#include<bits/stdc++.h>
#define ll long long
using namespace std;
const int N=5e5+5;
int n,m,a[N],b[N],k,lst[N],cnt,id[N<<2];
ll res,ans[N];
array<int,3>val[N];
vector<array<int,3> >v[N<<2];
vector<array<int,4> >q[N],Q;
struct P{
	int x,y;
	P operator-(P a){return {x-a.x,y-a.y};}
	ll operator*(P a){return 1ll*x*a.y-1ll*y*a.x;} 
	ll calc(){return 1ll*k*x+y;}
};
vector<P>s[N<<2];
void build(int p,int l,int r){
	id[p]=0;
	if(l==r){s[p]={{val[l][1],val[l][2]}};return ;}
	int mid=(l+r)/2;
	build(p<<1,l,mid);
	build(p<<1|1,mid+1,r);
	s[p].resize(s[p<<1].size()+s[p<<1|1].size());
	merge(s[p<<1].begin(),s[p<<1].end(),s[p<<1|1].begin(),s[p<<1|1].end(),s[p].begin(),
	[](P x,P y){return x.x^y.x?x.x<y.x:x.y<y.y;});
	int top=-1;
	for(auto i:s[p]){
		while(top>=1&&(s[p][top]-s[p][top-1])*(i-s[p][top-1])>=0) top--;
		s[p][++top]=i;
	}
	s[p].resize(top+1);
}
void query(int p,int l,int r,int lx,int rx){
	if(val[l][0]>rx||val[r][0]<lx) return ;
	if(val[l][0]>=lx&&val[r][0]<=rx){
		while(id[p]<s[p].size()-1){
			if(s[p][id[p]].calc()<=s[p][id[p]+1].calc()) id[p]++;
			else break;
		}
		res=max(res,s[p][id[p]].calc());
		return ;
	}
	int mid=(l+r)/2;
	query(p<<1,l,mid,lx,rx);
	query(p<<1|1,mid+1,r,lx,rx);
}
namespace out{
	void modify(int p,int l,int r,int lx,int rx,int i){
		if(l>=lx&&r<=rx) return v[p].push_back({i,a[i],b[i]});
		int mid=(l+r)/2;
		if(lx<=mid) modify(p<<1,l,mid,lx,rx,i);
		if(rx>mid) modify(p<<1|1,mid+1,r,lx,rx,i);
	}
	void dfs(int p,int l,int r){
		int t=0,mid=(l+r)/2;
		for(auto i:v[p]) val[++t]=i;
		if(t){
			sort(val+1,val+1+t),build(1,1,t);
			Q.clear();
			for(int i=l;i<=r;i++)
				for(auto j:q[i]) Q.push_back(j);
			sort(Q.begin(),Q.end());
			for(auto i:Q)
				k=i[0],res=0,query(1,1,t,i[1],i[2]),ans[i[3]]=max(ans[i[3]],res);
		}
		if(l<r) dfs(p<<1,l,mid),dfs(p<<1|1,mid+1,r);
	}
}
