int mn[N<<2];
void upd(int u,int l,int r,int x,int y){
	if(l==r){mn[u]=y;return;}int mid=(l+r)>>1;
	x<=mid?upd(u<<1,l,mid,x,y):upd(u<<1|1,mid+1,r,x,y);
	mn[u]=min(mn[u<<1],mn[u<<1|1]);
}
int ask(int u,int l,int r,int x,int y){
	if(x<=l&&r<=y)return mn[u];int mid=(l+r>>1);
	if(mid<x)return ask(u<<1|1,mid+1,r,x,y);
	if(mid>=y)return ask(u<<1,l,mid,x,y);
	return min(ask(u<<1,l,mid,x,y),ask(u<<1|1,mid+1,r,x,y));
}
