void update(int j,vector<int>&a) {
    int bit=j<26?2:j<52?1:0;
    for(int k=0; k<=7; k++)for(int w=0; w<=7; w++)if((w|1<<bit)==k)dp[now][j][k]=(dp[now][j][k]+sub(a[w],dp[pre][j][w]))%mod;
}
