        memset(dp[now],0,sizeof dp[now]);
        for(int j = 0; j <= 62; j++)for(int k = 0; k <= 7; k++)a[k] = (a[k] + dp[pre][j][k]) % mod;
        if (s[i]=='?')for(int j=0; j<62; j++)update(j,a);
        else if(islower(s[i]))update(s[i]-'a',a),update(s[i]-'a' + 26,a);
        else if(isupper(s[i]))update(s[i]-'A'+26,a);
