	vector<vec> a(n);
	for (vec &p : a) {
		cin >> p;
	}
	auto inside = [&](vec p) {
		for (int i = 0; i < n; i++) {
			if (C(a[i] - p, a[(i + 1) % n] - p) <= 0) return 0;
		}
		return 1;
	};
	while (q--) {
		vec A, B, O;
		db r;
		cin >> A >> B, O = (A + B) / db(2), r = abs(O - A);
		db d = 1e18;
		if (inside(O)) {
			d = 0;
		} else {
			for (int i = 0; i < n; i++) {
				d = min(d, dist(O, a[i], a[(i + 1) % n]));
