int pw(int x,int y){
	int z=1;
	x%=P;
	for(;y>0;y>>=1){
		if(y&1)z=z*x%P;
		x=x*x%P;
	}
	return z;
}
int id(int x){
	return x<N?x:N+n/x;
}
void getsp(){
	for(int i=1;p[i]*p[i]<=n;i++)
		for(int j=n;j>=p[i]*p[i];j=n/(n/j+1))
			sp[id(j)]-=sp[id(j/p[i])]-sp[p[i-1]];
}
int f(int x){
	if(x<=3)return pw(x,x-2);
	int m=sp[id(x)]-sp[id(x/2)]+2;
	return (x-m+1)%P*pw(x,m-2)%P;
}
