#include <bits/stdc++.h>
using namespace std;
typedef long long LL;

struct Block {
	int n, B;
	vector<LL> sm1, sm2;
	void init(int len) {
		B = sqrt(len); n = len;
		sm1 = vector<LL>(n + 3, 0); sm2 = vector<LL>(B + 3, 0);
	}
	void add(int x, LL v) {
		sm1[x] += v; sm2[x / B] += v;
	}
	LL query(int x) {
		int bl = x / B; LL sm = 0;
		for (int i = 0; i < bl; i++) sm += sm2[i];
		for (int i = B * bl; i <= x; i++) sm += sm1[i];
		return sm;
	}
} t1, t2;

LL qry(int l, int r) {
	return (t1.query(r) * (r + 1) - t2.query(r)) - (t1.query(l - 1) * l - t2.query(l - 1));
}

int n, q;
LL a[300005], d[300005];
vector<pair<int, int> > now;

void mdf(int l, int r, LL v) {
	d[r + 1] -= v, d[l] += v;
	t1.add(l, v); t1.add(r + 1, -v);
	t2.add(l, v * l); t2.add(r + 1, -v * (r + 1));
}

void addp(int L, int R) {
	int pl = L, pr = R;
	for (auto inv : now) {
		int l = inv.first, r = inv.second;
		if (l <= L && r + 1 >= L) pl = l;
		if (l - 1 <= R && r >= R) pr = r;
	}
	vector<pair<int, int> > vl, vr;
	for (auto inv : now) {
		int l = inv.first, r = inv.second;
		if (r < pl) vl.push_back(inv);
		if (l > pr) vr.push_back(inv);
	}
	vl.push_back({pl, pr}); a[pr] = qry(pr, pr);
	for (auto inv : vr) vl.push_back(inv);
	now.swap(vl);
	vector<pair<int, int> >().swap(vl);
	vector<pair<int, int> >().swap(vr);
}
void split(int x) {
	vector<pair<int, int> > vl, vr;
	for (auto inv : now) {
		int l = inv.first, r = inv.second;
		if (r < x) vl.push_back(inv);
		else if (l > x) vr.push_back(inv);
		else {
			if (l < x) vl.push_back({l, x - 1}), a[x - 1] = qry(x - 1, x - 1);
			if (r > x) vr.push_back({x + 1, r});
		}
	}
	for (auto inv : vr) vl.push_back(inv);
	now.swap(vl);
	vector<pair<int, int> >().swap(vl);
	vector<pair<int, int> >().swap(vr);
}

int main() {
	scanf("%d %d", &n, &q);
	for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
	t1.init(n + 1), t2.init(n + 1);
	for (int i = 1, l = 0; i <= n; i++) {
		if (!a[i - 1] && a[i]) l = i;
		if (a[i] && !a[i + 1]) now.push_back({l, i});
		d[i] = a[i] - a[i - 1];
		t1.add(i, d[i]), t2.add(i, 1ll * i * d[i]);
	}
	for (int _ = 1, op, l, r, v; _ <= q; _++) {
		scanf("%d", &op);
		if (op == 1) {
			scanf("%d %d", &l, &v);
			LL tmp = qry(l, l); mdf(l, l, v - tmp); a[l] = v;
			if (v) addp(l, l);
			else split(l);
		}
		if (op == 2) {
			scanf("%d %d %d", &l, &r, &v);
			mdf(l, r, v);
			a[r] = qry(r, r); addp(l, r);
		}
		if (op == 3) {
			for (auto inv : now) {
				l = inv.first, r = inv.second;
				mdf(l, r, 1); a[r]++;
			}
		}
		if (op == 4) {
			for (auto inv : now) {
				l = inv.first, r = inv.second;
				mdf(l, r, r - l + 1); a[r] += r - l + 1;
			}
		}
		if (op == 5) {
			scanf("%d %d", &l, &r);
			printf("%lld\n", qry(l, r));
		}
		vector<pair<int, int> > tmp;
		for (auto inv : now) {
			l = inv.first, r = inv.second;
			if (r != n) {
				a[r - 1] = a[r] - d[r];
				mdf(r, r, -a[r]); a[r] = 0; --r;
			}
			if (l <= r) tmp.push_back({l, r}); 
		}
		now.swap(tmp); vector<pair<int, int> >().swap(tmp);
	}
	return 0;
}

