#include<bits/stdc++.h>
using namespace std;
using db = __int128;
using T = db;
struct P {
  T x, y, z;
  explicit P(T x = 0, T y = 0, T z = 0) : x(x), y(y), z(z) {}
  T dot(P p) { return x * p.x + y * p.y + z * p.z; }
  P cross(P p) { return P(y * p.z - z * p.y, z * p.x - x * p.z, x * p.y - y * p.x); }
  P operator-(P p) { return P(x - p.x, y - p.y, z - p.z); }
};
vector<tuple<int, int, int>> hull(vector<P> p, T eps = 1e-9) {
  vector<tuple<int, int, int>> res;
  if(p.size() < 3)
    return res;
  res.emplace_back(0, 1, 2);
  res.emplace_back(0, 2, 1);
  for (int i = 3; i < p.size(); i += 1) {
    vector<tuple<int, int, int>> nxt;
    set<pair<int, int>> edge;
    for (auto [a, b, c] : res) {
      T prod = (p[b] - p[a]).cross(p[c] - p[a]).dot(p[i] - p[a]);
      if (prod > 0) {
        edge.emplace(a, b);
        edge.emplace(b, c);
        edge.emplace(c, a);
      } else
        nxt.emplace_back(a, b, c);
    }
    for (auto [x, y] : edge) {
      if (edge.find({y, x})!=edge.end()) continue;
      nxt.emplace_back(x, y, i);
    }
    res.swap(nxt);
  }
  return res;
}
db volume(vector<P> p, vector<tuple<int, int, int>> f) {
  db res = 0;
  for (auto [a, b, c] : f) res += p[a].cross(p[b]).dot(p[c]);
  return  res;
}

void output(db x) {
    if(x < 10) {
        cout << (int)x;
        return;
    }
    output(x / 10);
    cout << (int) (x % 10);
}

int main() {
    int T;
    cin >> T;
    while(T--) {
        int n;
        cin >> n;
        vector<P> v(n);
        for(auto &[x, y, z] : v) {
            long long a, b, c;
            cin >> a >> b >> c;
            x = a, y = b, z = c;
        }
        __int128 ans = 0;
        while(v.size() > 3) {
            random_shuffle(v.begin(), v.end());
            auto h = hull(v);
            ans += volume(v, h);
            vector<int> use(v.size());
            for(auto [x, y, z] : h)
                use[x] = use[y] = use[z] = 1;
            vector<P> nv;
            for(int i = 0; i < v.size(); i += 1)
                if(!use[i])
                    nv.push_back(v[i]);
            v.swap(nv);
        }

        output(ans);
        cout << "\n";
    }
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int N = 35, M = 305, mod = 998244353;
int F[N][M][M][2], G[N][M][M][2], fac[M], inv[M], a[N], ans[M];
int qpow(int x, int y)
{
	int ans = 1;
	while(y)
	{
		if(y & 1)
			ans = (ll)ans * x % mod;
		x = (ll)x * x % mod;
		y >>= 1;
	}
	return ans;
}
void prep(int n)
{
	int i;
	fac[0] = 1;
	for(i = 1; i <= n; i++)
		fac[i] = (ll)fac[i - 1] * i % mod;
	inv[n] = qpow(fac[n], mod - 2);
	for(i = n; i >= 1; i--)
		inv[i - 1] = (ll)inv[i] * i % mod;
}

int main()
{
	prep(300);
	int n, c, i, j, k, l, m, s = 0, r;
	scanf("%d%d", &n, &c);
	F[0][0][0][0] = 1;
	for(i = 1; i <= n; i++)
		scanf("%d", a + i);
	r = qpow(n, mod - 2);
	for(i = 1; i <= n; i++)
	{
		memset(G, 0, sizeof(G));
		for(j = 0; j < i; j++)
			for(k = 0; k <= s; k++)
				for(l = 0; l <= s; l++)
					if(F[j][k][l][0] || F[j][k][l][1])
					{
						G[j + 1][k][l + a[i]][0] = (G[j + 1][k][l + a[i]][0] + F[j][k][l][0]) % mod;
						G[j + 1][k][l + a[i]][1] = (G[j + 1][k][l + a[i]][1] + F[j][k][l][1]) % mod;
						if(i > c)
							for(m = 0; m < a[i]; m++)
							{
								G[j][k + m][l + m][0] = (G[j][k + m][l + m][0] + (ll)F[j][k][l][0] * inv[m]) % mod;
								G[j][k + m][l + m][1] = (G[j][k + m][l + m][1] + (ll)F[j][k][l][1] * inv[m]) % mod;
							}
						for(m = 0; m < a[i]; m++)
						{
							G[j][k + m][l + a[i]][0] = (G[j][k + m][l + a[i]][0] + (ll)F[j][k][l][0] * (mod - inv[m])) % mod;
							G[j][k + m][l + a[i]][1] = (G[j][k + m][l + a[i]][1] + (ll)F[j][k][l][1] * (mod - inv[m])) % mod;
						}
						if(i <= c)
							G[j][k + a[i] - 1][l + a[i]][1] = (G[j][k + a[i] - 1][l + a[i]][1] + (ll)F[j][k][l][0] * inv[a[i] - 1] % mod * r) % mod;
					}
		s += a[i];
		memcpy(F, G, sizeof(F));
	}
	for(i = 0; i <= n; i ++)
		for(j = 0; j <= s; j++)
			for(k = 0; k <= s; k++)
				if(F[i][j][k][1])
					ans[k] = (ans[k] + (ll)F[i][j][k][1] * fac[j] % mod * qpow(r, j) % mod * qpow((1 + (ll)(mod - i) * r) % mod, mod - j - 2)) % mod;
	for(i = 1; i <= s; i++)
	{
		ans[i] = (ans[i - 1] + ans[i]) % mod;
		printf("%d ", ans[i]);
	}
	printf("\n");
	return 0;
}

#include<bits/stdc++.h>
