	tag[x]+=1ll*val*cnt[y],tag[y]+=1ll*val*cnt[x];
	if(Q[x].size()<Q[y].size())swap(x,y);
	for(int k:Q[y])Ans[k]+=tag[y]-tag[x],Q[x]+=k;
