}
void solveFinal(int T,vector<Edge> &G)
{
	vector<int> V;
	auto ins=[&](int x){if(!ex[x])ex[x]=1,V+=x;};
	sort(G.begin(),G.end());
	for(Edge e:G)ins(e.x),ins(e.y);
	for(int u:V)fa[u]=u,cnt[u]=0,tag[u]=0,ex[u]=0,vector<int>().swap(Q[u]);
	for(int u:A[T])cnt[u]++;
	for(Qry e:B[T])Q[e.x]+=e.id;
	for(Edge e:G)merge(e.x,e.y,e.c);
	for(int u:V)if(u==fa[u])for(int k:Q[u])Ans[k]+=tag[u];
}
void solve(vector<Edge> &G,int l,int r,int p)
{
	vector<int> V;vector<Edge> G0;
	auto ins=[&](int x){if(!ex[x])ex[x]=1,V+=x;};
	for(int i=l;i<=r;i++)for(int u:A[i])ins(u),vis[u]=1;
	for(int i=l;i<=r;i++)for(Qry e:B[i])ins(e.x),vis[e.x]=1;
	for(int u:a[p])ins(u),vis[u]=1;
	for(Edge e:G)ins(e.x),ins(e.y),g[e.x]+={e.y,e.c},g[e.y]+={e.x,e.c};
	for(Edge e:s[p])ins(e.x),ins(e.y),g[e.x]+={e.y,e.c},g[e.y]+={e.x,e.c};
	for(int u:V)if(!t[u]&&vis[u])dfs0(u);
	for(int u:V)vector<E>().swap(g[u]),ex[u]=vis[u]=t[u]=0;
	G0.swap(edgeSet);
	if(l==r)solveFinal(l,G0);
	else{dmid;solve(G0,lson),solve(G0,rson);}
}

