ll qpow(ll a,int b)
{
	ll ans=1;
	while(b)
	{
		if(b&1)ans=ans*a%mod;
		a=a*a%mod;b>>=1;
	}
	return ans;
}
ll sol(int x,int y,int a,int b)
{
	if(x==y)return a*qpow(a+b,mod-2)%mod;
	bool fl=0;if(x>y){swap(x,y);swap(a,b);fl=1;}
	int k=(y-1)/x;ll ans=qpow(a*qpow(a+b,mod-2)%mod,k)*sol(x,y-k*x,a,b)%mod;
	return fl?(mod+1-ans)%mod:ans;
}

