vector<int> solve(int l,int r,int L,int R,int u){
	int v=min(R-L+1,r-l+1);
	vector<int> z;
	z.clear();
	z.resize(v+1);
	if(l>r||L>R){
		z[0]=1;
		return z;
	}
	if(u<0){
		for(int i=0;i<=v;i++) z[i]=calc(r-l+1,R-L+1,i);
		return z;
	}
	int p=r;
	for(int i=r;i>=l;i--){
		if(a[i]>>u&1) p=i-1; 
	}
	int q=R;
	for(int i=R;i>=L;i--){
		if(b[i]>>u&1) q=i-1;
	}
	if(k>>u&1){
		vector<int> x=solve(l,p,q+1,R,u-1);
		vector<int> y=solve(p+1,r,L,q,u-1);
		for(int i=0;i<x.size();i++){
			for(int j=0;j<y.size();j++) z[i+j]=(z[i+j]+x[i]*y[j])%mod;
		}
		return z;
	}
	vector<int> x=solve(l,p,L,q,u-1);
	vector<int> y=solve(p+1,r,q+1,R,u-1);
	for(int i=0;i<x.size();i++){
		for(int j=0;j<y.size();j++){
			for(int a=0;a<=min(p-l+1-i,R-q-j);a++){
				for(int b=0;b<=min(q-L+1-i,r-p-j);b++) z[i+j+a+b]=(z[i+j+a+b]+x[i]*y[j]%mod*calc(p-l+1-i,R-q-j,a)%mod*calc(q-L+1-i,r-p-j,b))%mod;
			}
		}
	}
	return z;
}
