void dfs(ll u,ll fa){
	ll sum=0;
	for(auto v:g[u]){
		if(v==fa)
			continue;
		dfs(v,u);
		sum+=dp[v][0];
	}
	ll up=sum;
	ll down=sum;
	for(auto it:g[u]){
		if(it==fa)
			continue;
		up=max(up,sum-dp[it][0]+dp[it][1]+a[it]-a[u]);
		down=max(down,sum-dp[it][0]+dp[it][2]+a[u]-a[it]);
	}
	dp[u][0]=up+down-sum;
	dp[u][1]=up;
	dp[u][2]=down;
}

