#include <bits/stdc++.h> // Common competitive programming header
using namespace std;     // Use standard namespace

// --- Type Aliases ---
using Move = tuple<char, int, int>;       // (type, x, rotation)
using Point = pair<int, int>;             // (x, y)
using ColHash = uint32_t;                 // Type for hashed column heights
using Heights = vector<int>;              // Type for vector<int> representing column heights

// --- Macros (replicated from original code for CP style) ---
#define F(i, a, b) for (int i = (a), iee = (b); i <= iee; i++) // For loop: i from a to b (inclusive)
#define FO(i, a, b) F(i, a, (b) - 1)                           // For loop: i from a to b (exclusive)
#define eb emplace_back                                        // Short for vector::emplace_back
#define V vector                                               // Short for std::vector
#define BE(x) begin(x), end(x)                                 // Short for std::begin(x), std::end(x)
#define concat(a, b) (a).insert(end(a), BE(b))                 // Concatenate vector b to vector a

// --- Tetromino Shape Definition ---
struct Mino {
    Point blks[4];    // Block coordinates
    int w;            // Width
    int colLow[4];    // Lowest block's relative Y for each column
    int colCnt[4];    // Number of blocks in each column
    bool flat;        // Is flat-bottomed
    Move op;          // Move details (type, x_offset, rotation)
};

// Global map for tetromino definitions: Key: {type_char, rotation_index}
map<Point, Mino> minoDefs;

// --- Tetromino Initialization ---
void initMinos() {
    auto defineMino = [&](char typeChar, int n, uint16_t mask) {
        int offset = -((n - 1) / 2); // Center offset
        Mino m;
        int cnt = 0;
        FO(r, 0, n) FO(c, 0, n) {
            if (mask & (1 << (n * n - 1 - (r * n + c)))) { // Correct bitmask indexing
                m.blks[cnt++] = {c + offset, r};
            }
        }

        F(k, 0, 3) { // 4 rotations
            std::sort(m.blks, m.blks + 4, std::greater<Point>());
            int minX = m.blks[3].first;

            m.w = m.blks[0].first - minX + 1;
            FO(i, 0, m.w) m.colLow[i] = m.colCnt[i] = 0;

            for (auto [x, y] : m.blks) {
                int colIdx = x - minX;
                m.colLow[colIdx] = max(m.colLow[colIdx], y);
                m.colCnt[colIdx]++;
            }

            m.flat = true;
            FO(i, 1, m.w) {
                if (m.colLow[i] -= m.colLow[0]) m.flat = false;
            }
            // m.colLow[0] is effectively 0 after normalization

            m.op = {typeChar, -minX, k};
            minoDefs[{typeChar, k}] = m;

            // Rotate blocks for next iteration
            F(i, 0, 3) {
                auto [old_x, old_y] = m.blks[i];
                m.blks[i] = {n - 1 - old_y + offset, old_x - offset};
            }
        }
    };

    // Define all 7 tetromino types, including 'J' twice as per original code
    defineMino('I', 4, 0b0000'1111'0000'0000);
    defineMino('J', 3, 0b100'111'000);
    defineMino('L', 3, 0b001'111'000);
    defineMino('J', 3, 0b100'111'000); // Original code: 'J' defined again
    defineMino('O', 2, 0b11'11);
    defineMino('S', 3, 0b011'110'000);
    defineMino('Z', 3, 0b110'011'000);
    defineMino('T', 3, 0b010'111'000);
}

// --- Global Game State & Config ---
const int MAXW = 200, MAXH = 2020; // Max dimensions + stack limit
int W, H_grid; // Current grid width and height (renamed H to H_grid)
char P_grid[MAXH][MAXW]; // Target pattern grid (renamed pattern to P_grid)

V<Move> resMoves; // Final sequence of moves (renamed res to resMoves)

// Vars for column groups (for `solveRow` function, formerly `foo`)
int grpL[MAXW], grpR[MAXW], grpW[MAXW], nGrp; // Group left/right/width, number of groups
int grpInitH[MAXW]; // Initial heights for columns in a group (original 'a')
int grpTargetH[MAXW]; // Target heights for columns in a group (original 's')
int grpReqBlk[MAXW]; // Required block count per group (original 'c')

// --- Helper Macros for column height vectors (replicated from original code) ---
#define zip(a) accumulate(BE(a), 0, [](ColHash z, int x) { return z << 6 | x; })
#define getmn(a) *min_element(BE(a))
#define getmx(a) *max_element(BE(a))

// --- Memoization Table for `solveGroup` ---
static map<tuple<int, ColHash, int>, map<ColHash, pair<ColHash, Move>>> mem;

// --- BFS `solveGroup` for a Single Column Group ---
optional<V<Move>> solveGroup(Heights s, Heights t, int offset, int typ) {
    int curGrpW = s.size();
    ColHash zs = zip(s); // Hashed initial state

    auto key = make_tuple(curGrpW, zs, typ);
    auto &vis = mem[key]; // Reference to the specific memoization map

    if (vis.empty()) {
        const int MAXD = 11; // Max relative height for a column, original MAXD
        queue<pair<ColHash, Heights>> Q;

        vis[zs] = {-1u, {}}, Q.emplace(zs, s); // -1u indicates starting node
        while (!Q.empty()) {
            auto [ha, a] = Q.front(); Q.pop();

            for (auto [_, mino] : minoDefs) F(i, 0, curGrpW - mino.w) { // Iterate placements
                bool ok = true;
                FO(j, 1, mino.w) if (a[i + j] - a[i] + mino.colLow[j]) { ok = false; break; }
                if (!ok) continue; // Hole check

                if (mino.flat && a[i] == typ * getmn(a)) continue; // Flat-bottom rule

                auto b = a; // Next state
                FO(j, 0, mino.w) b[i + j] += mino.colCnt[j];

                if (getmx(b) > MAXD) continue; // Height limit check

                ColHash hb = zip(b); // Hashed next state
                if (vis.find(hb) == vis.end()) {
                    auto [tt, tx, td] = mino.op;
                    vis[hb] = {ha, {tt, tx + i, td}};
                    Q.emplace(hb, b);
                }
            }
        }
    }

    ColHash x = zip(t); // Hashed target state
    if (vis.find(x) == vis.end()) return nullopt; // Target not reachable

    V<Move> ret;
    while (x != zs) { // Reconstruct path
        auto [y, op] = vis[x];
        auto [tt, xx, td] = op;
        ret.eb(tt, xx + offset, td), x = y; // Add move, adjust x with global offset
    }
    reverse(BE(ret));
    return ret;
}

// --- Main Row Reconstruction Logic (formerly `foo` function) ---
void solveRow() {
    // Calc grpReqBlk & total sum
    F(i, 1, W) grpInitH[i] = (1 < i && i < W); // 'a' in original: initial platform gaps

    F(i, 1, nGrp) { // 'c' in original: total blocks needed for each group
        grpReqBlk[i] = 0;
        F(j, grpL[i], grpR[i]) grpReqBlk[i] += grpTargetH[j]; // grpTargetH includes pattern data
    }
    grpReqBlk[1]++, grpReqBlk[nGrp]++; // Adjust first and last group counts

    int sum = 0;
    F(i, 1, nGrp) sum += grpReqBlk[i];

    // Adjust for 'mod 4'
    int dl = W * (4 - sum % 4) % 4, curMod4Acc = 0; // 'dl' & 't' in original
    sum += dl * W;

    F(i, 1, W) grpTargetH[i] += 1 + dl;
    F(i, 1, nGrp) grpReqBlk[i] += dl * grpW[i];

    // Place minos spanning 2 groups to balance modulo 4
    F(i, 1, nGrp) {
        (curMod4Acc += grpReqBlk[i]) %= 4;
        if (curMod4Acc) {
            grpInitH[grpR[i]] += curMod4Acc, grpInitH[grpR[i] + 1] += 4 - curMod4Acc;
            if (curMod4Acc == 1) resMoves.eb('J', grpR[i] + 1, 3);
            if (curMod4Acc == 2) resMoves.eb('O', grpR[i], 0);
            if (curMod4Acc == 3) resMoves.eb('L', grpR[i], 1);
        }
    }

    // Loop for base target height ('L' in original)
    for (int L = 1 + dl; L <= 100; L += 4) {
        optional<V<Move>> accGrpSol = V<Move>();
        
        F(i, 1, nGrp) {
            // Original: solve({a + l[i], a + r[i] + 1}, {s + l[i], s + r[i] + 1}, l[i], i == num);
            Heights curGrpInitH(grpInitH + grpL[i], grpInitH + grpR[i] + 1);
            Heights curGrpTargetH(grpTargetH + grpL[i], grpTargetH + grpR[i] + 1);

            auto grpSol = solveGroup(curGrpInitH, curGrpTargetH, grpL[i], (i == nGrp));

            if (!grpSol) { accGrpSol.reset(); break; }
            concat(*accGrpSol, *grpSol);
        }

        if (accGrpSol) {
            concat(resMoves, *accGrpSol);
            break;
        }

        F(i, 1, W) grpTargetH[i] += 4;
    }
}

// --- Main Function ---
int main() {
    std::ios_base::sync_with_stdio(false); // Fast I/O
    std::cin.tie(NULL);

    initMinos();

    int T_cases;
    for (cin >> T_cases; T_cases; T_cases--) { // Original test cases loop
        resMoves.clear();
        nGrp = 0;

        cin >> H_grid >> W;

        int prevBlkCnt = 0;
        bool noSol = false;
        F(i, 1, H_grid) {
            int currBlkCnt = 0;
            cin >> P_grid[i];
            FO(j, 0, W) currBlkCnt += (P_grid[i][j] == '#');
            
            // Original `no_solution` condition from latest provided code
            if (currBlkCnt == W || (currBlkCnt == 0 && prevBlkCnt > 0)) {
                noSol = true;
            }
            prevBlkCnt = currBlkCnt;
        }

        if (noSol) {
            cout << "-1\n";
            continue;
        }

        // Divide groups (hardcoded from original code)
        grpW[++nGrp] = 3;
        F(i, 1, W / 2 - 3) grpW[++nGrp] = 2;
        grpW[++nGrp] = 4;
        if (W == 5) grpW[nGrp = 1] = 5; // Special case for W=5
        
        // Calculate start and end columns for each group
        F(i, 1, nGrp) grpL[i] = grpR[i - 1] + 1, grpR[i] = grpL[i] + grpW[i] - 1;

        // Solve row by row, from bottom to top (H_grid down to 1)
        int platPivotCol = 2; // Original 'p'
        for (int i = H_grid; i >= 1; i--) { // Exact original loop for decrementing
            // Init grpTargetH for current row from pattern
            F(j, 1, W) grpTargetH[j] = (P_grid[i][j - 1] == '#');

            // Make platform
            resMoves.eb('T', platPivotCol, 0);
            for (int k = platPivotCol - 2; k >= 2; k -= 2) resMoves.eb('S', k, 0);
            for (int k = platPivotCol + 2; k <= W; k += 2) resMoves.eb('Z', k, 0);

            // Update platPivotCol based on target pattern
            F(j, 1, W) if (grpTargetH[j]) platPivotCol = j;
            platPivotCol = max(2, platPivotCol / 2 * 2);

            solveRow(); // Main logic to fill the current row
        }

        cout << resMoves.size() << '\n';
        for (auto [t, x, d]: resMoves) // Original output loop
            cout << t << ' ' << x << ' ' << d << '\n';
    }
    return 0;
}

