int qpow(int a,int b)
{
	int c=1;
	while(b)
	{
		if(b&1)c=c*a%p;
		a=a*a%p;
		b/=2;
	}
	return c;
}
int c(int n,int m)
{
	if(m<0||m>n)return 0;
	return fac[n]*ifac[m]%p*ifac[n-m]%p;
}
int cal(int*a,int kk)
{
	int ans=0;
	for(int i=a[1]-m-kk;i<=a[n]+m;i++)
	{
		int t=1;
		for(int j=1;j<=n;j++)
		{
			int s=0;
			for(int k=i;k<=i+kk;k++)if(!((m+k-a[j])&1))s+=c(m,(m+k-a[j])/2);
			t=t*(s%p)%p;
		}
		ans+=t;
	}
	return ans%p;
}
