const int N=1<<18,p=998244353;
using namespace std;
int L,sw[N],a[N],b[N],w[N];
int pw(int a,int b)
{
	int rs=1;
	for(;b;b/=2,a=1ll*a*a%p)
		if(b&1)rs=1ll*rs*a%p;
	return rs;
}
void dft(int *a)
{
	up(i,0,L-1)if(i<sw[i])swap(a[i],a[sw[i]]);
	for(int i=1;i<L;i*=2)
		for(int j=0;j<L;j+=i)
			up(k,0,i-1){
				int x=a[j],y=1ll*a[j+i]*w[L/i/2*k]%p;
				a[j]=(x+y)%p,a[j+i]=(x+p-y)%p,++j;
			}
}
void idft(int *a)
{
	int ni=p-(p-1)/L;
	up(i,0,L-1)a[i]=1ll*a[i]*ni%p;
	dft(a);
	up(i,1,L/2-1)swap(a[i],a[L-i]);
}
void mul(int n,int m,int *a,int *b){
	L=1;
	while(L<=n+m)L*=2;
	fill(a+n+1,a+L,0),
	fill(b+m+1,b+L,0);
	w[0]=1,w[1]=pw(3,(p-1)/L);
	up(i,1,L-1)
		w[i]=1ll*w[i-1]*w[1]%p,
		sw[i]=(i&1)*L/2|sw[i/2]/2;
	dft(a),dft(b);
	up(i,0,L-1)a[i]=1ll*a[i]*b[i]%p;
	idft(a);
}
