using namespace std;
#define N 600005
#define ls u<<1
#define rs u<<1|1
int n,m;
int a[N],l[N],r[N],c[N];
struct node{//c 是通行证
	int mx1,c1,mx2,c2;
	void apply(int x,int y){
		if(y==c1)mx1=max(mx1,x);
		else if(x>mx1){
			mx2=mx1,c2=c1;
			mx1=x,c1=y;
		}
		else if(y==c2)mx2=max(mx2,x);
		else if(x>mx2){
			mx2=x,c2=y;
		}
	}
};
node operator + (const node &x,const node &y){
	node ans=x;
	ans.apply(y.mx1,y.c1);
	ans.apply(y.mx2,y.c2);
	return ans;
}
node tr[N*4],tag[N*4];
void pushtag(int u,node t){
	tag[u]=tag[u]+t;
	int c1=tr[u].c1,c2=tr[u].c2;
	if(c1&&t.c1)tr[u].apply(t.mx1+(c1!=t.c1),c1);
	if(c2&&t.c1)tr[u].apply(t.mx1+(c2!=t.c1),c2);
	if(c1&&t.c2)tr[u].apply(t.mx2+(c1!=t.c2),c1);
	if(c2&&t.c2)tr[u].apply(t.mx2+(c2!=t.c2),c2);
}
void push(int u){
	if(!tag[u].c1)return;
	pushtag(ls,tag[u]);
	pushtag(rs,tag[u]);
	tag[u]={0,0,0,0};
}
void build(int u,int l,int r){
	tag[u]={0,0,0,0};
	if(l==r){
		if(::l[l]==1){
			tr[u]={1,c[l],0,0};
		}
		else
			tr[u]={0,0,0,0};
		return;
	}
	int m=(l+r)>>1;
	build(ls,l,m),build(rs,m+1,r);
	tr[u]=tr[ls]+tr[rs];
}
node qry(int u,int l,int r,int L,int R){
	if(L<=l&&r<=R)return tr[u];
	int m=(l+r)>>1;push(u);
	if(m>=L&&m<R)return qry(ls,l,m,L,R)+qry(rs,m+1,r,L,R);
	else if(m>=L)return qry(ls,l,m,L,R);
	else return qry(rs,m+1,r,L,R);
}
void upd(int u,int l,int r,int L,int R,const node &x){
	if(L<=l&&r<=R)return pushtag(u,x);
	int m=(l+r)>>1;push(u);
	if(m>=L)upd(ls,l,m,L,R,x);
	if(m<R) upd(rs,m+1,r,L,R,x);
	tr[u]=tr[ls]+tr[rs];
}
void upd(int u,int l,int r,int x,const node &y){
	if(l==r){
		tr[u]=y;
		return;
	}
	int m=(l+r)>>1;push(u);
	if(m>=x)upd(ls,l,m,x,y);
	else upd(rs,m+1,r,x,y);
	tr[u]=tr[ls]+tr[rs];
}
void output(int u,int l,int r){
	if(l==r){
		printf("%d ",tr[u].mx1);
		return;
	}
	int m=(l+r)>>1;
	output(ls,l,m),output(rs,m+1,r);
}
