bool spfa()
{
	int i,u,v,hd,tl;
	static int q[N*N];
	memset(d,0x3f,sizeof(d));
	memcpy(cur,head,sizeof(cur));
	d[q[hd=tl=1]=S]=0;
	while(hd<=tl)
	{
		inq[u=q[hd++]]=0;
		for(i=head[u];i;i=e[i].nxt)
			if(e[i].w&&d[v=e[i].v]>d[u]+e[i].c)
			{
				d[v]=d[u]+e[i].c;
				if(!inq[v])inq[q[++tl]=v]=1;
			}
	}
	return d[T]!=inf;
}
int dfs(int u,int fw)
{
	int v,k,sm=0;
	if(u==T)return fw;inq[u]=1;
	for(int& i=cur[u];i;i=e[i].nxt)
		if(e[i].w&&d[v=e[i].v]==d[u]+e[i].c&&!inq[v]&&(k=dfs(v,min(e[i].w,fw-sm))))
		{
			e[i].w-=k;e[i^1].w+=k;sm+=k;ans+=1ll*k*e[i].c;
			if(sm==fw)break;
		}
	inq[u]=0;return sm;
}

