int query(int xa,int xb,int xc,int xd,int l,int r,int flg)
{
	int t;
	if(flg==3)return 3;
	if(flg==0){
		if(da+ta.c[xa]+td.c[xd]<=ca&&db+tb.c[xb]+td.c[xd]<=cb&&
		da+ta.c[xa]+db+tb.c[xb]+dc+tc.c[xc]+td.c[xd]<=ca+cb){
