			if(db+tb.c[xb]+td.c[xd]>cb){
				t=min(ta.c[xa],min(ca-da,ca+cb-da-db-dc));
				cst+=l*t;da+=t;
				t=min(tb.c[xb],min(cb-db,ca+cb-da-db-dc));
				cst+=l*t;db+=t;
				t=min(td.c[xd],min(min(ca-da,cb-db),ca+cb-da-db-dc));
				cst+=l*t;da+=t;db+=t;dc-=t;
				t=min(tc.c[xc],ca+cb-da-db-dc);
				cst+=l*t;dc+=t;
				return 2;
			}
			else{
				t=min(ta.c[xa],min(ca-da,ca+cb-da-db-dc));
				cst+=l*t;da+=t;
				t=min(tb.c[xb],min(cb-db,ca+cb-da-db-dc));
				cst+=l*t;db+=t;
				t=min(td.c[xd],min(min(ca-da,cb-db),ca+cb-da-db-dc));
				cst+=l*t;da+=t;db+=t;dc-=t;
				t=min(tc.c[xc],ca+cb-da-db-dc);
				cst+=l*t;dc+=t;
				return 1;
			}
		}
	}
	if(flg==1){
		if(tb.c[xb]+tc.c[xc]<=ca+cb-da-db-dc){
			cst+=tb.s[xb]+tc.s[xc];
			db+=tb.c[xb]+tc.c[xc];
