		if(min(ca,da)+min(cb,db)+dc>=ca+cb) ans=min(ans,bse+cst);
		if(i<vc.size()){
			bse+=vc[i].second;
			td.update(1,0,len,vc[i].first-vc[i].second,1);
			tc.update(1,0,len,vc[i].second,-1);
		}
	}
	return ans;
}
