#include <bits/stdc++.h>

using i64 = long long;

const i64 inf = 1e18;

struct Node {
    Node *l{}, *r{};
    int sum = 0;
};
void build(Node *&u, int l, int r) {
    u = new Node{};
    if (r - l == 1) {
        return;
    }
    int m = (l + r) / 2;
    build(u->l, l, m);
    build(u->r, m, r);
}
void modify(Node *&u, int l, int r, int p) {
    u = new Node{*u};
    u->sum += 1;
    if (r - l == 1) {
        return;
    }
    int m = (l + r) / 2;
    if (p < m) {
        modify(u->l, l, m, p);
    } else {
        modify(u->r, m, r, p);
    }
}
int query(Node *u, Node *v, int l, int r, int ql, int qr) {
    if (r <= ql || qr <= l) {
        return 0;
    }
    if (ql <= l && r <= qr) {
        return v->sum - u->sum;
    }
    int m = (l + r) / 2;
    return query(u->l, v->l, l, m, ql, qr) + query(u->r, v->r, m, r, ql, qr);
}

void solve() {
    int n, m;
    std::cin >> n >> m;

    std::vector<int> p(n), ip(n + 1), q(n), iq(n + 1);
    for (int i = 0; i < n; ++i) {
        std::cin >> p[i];
        ip[p[i]] = i;
    }
    for (int i = 0; i < n; ++i) {
        std::cin >> q[i];
        iq[q[i]] = i;
    }

    std::vector<int> a(n + 1);
    for (int i = 0; i < n; ++i) {
        a[p[i]] = q[i];
    }

    std::vector<Node *> root(n + 1);
    build(root[0], 0, n);
    for (int i = 1; i <= n; ++i) {
        modify(root[i] = root[i - 1], 0, n, a[i] - 1);
    }

    while (m--) {
        i64 A, B, X, Y;
        std::cin >> A >> B >> X >> Y;
        if (n == 1) {
            std::cout << "0\n";
            continue;
        }

        std::vector<int> pos;
        if (A <= n) {
            pos.push_back(ip[A]);
        }
        if (B <= n) {
            pos.push_back(iq[B]);
        }
        i64 t = std::sqrt(A);
        if (t * t == A) {
            pos.push_back(ip[t]);
        }
        t = std::sqrt(B);
        if (t * t == B) {
            pos.push_back(iq[t]);
        }
        std::sort(pos.begin(), pos.end());
        pos.erase(std::unique(pos.begin(), pos.end()), pos.end());
        const int k = int(pos.size());

        int Al = std::floor(std::sqrt(A)), Ar = std::min<i64>(A - 1, n);
        int Bl = std::floor(std::sqrt(B)), Br = std::min<i64>(B - 1, n);

        int curx = std::min<i64>(A - 1, n), cury = std::min<i64>(B - 1, n);
        std::array<int, 4> cnt{};
        cnt[3] = query(root[Al], root[Ar], 0, n, Bl, Br);
        cnt[1] = query(root[Al], root[Ar], 0, n, 0, n) - cnt[3];
        cnt[2] = query(root[0], root[n], 0, n, Bl, Br) - cnt[3];
        for (auto i : pos) {
            cnt[(Al < p[i] && p[i] <= Ar) | (Bl < q[i] && q[i] <= Br) << 1] -= 1;
            curx -= p[i] < A;
            cury -= q[i] < B;
        }

        i64 ans = inf;
        for (int s = 0; s < 1 << (2 * k); ++s) {
            i64 sum = 0;
            int cx = curx - n / 2, cy = cury - n / 2, ex = 0, ey = 0;
            for (int i = 0; i < k; ++i) {
                i64 np = p[pos[i]], nq = q[pos[i]];
                int t = s >> (2 * i) & 3;
                if (t & 1) {
                    np *= np;
                }
                if (t & 2) {
                    nq *= nq;
                }
                sum += t == 3 ? Y : t > 0 ? X : 0;
                ex += np == A;
                ey += nq == B;
                cx += np < A;
                cy += nq < B;
            }
            if (ex == 0 || ey == 0) {
                continue;
            }
            for (int i = 0; i <= (ex == 2); ++i) {
                for (int j = 0; j <= (ey == 2); ++j) {
                    int l = std::max(0, cx + i + cy + j - cnt[1] - cnt[2] - cnt[3]);
                    int r = std::min({cnt[3], cx + i, cy + j});
                    if (cx + i <= cnt[1] + cnt[3] && cy + j <= cnt[2] + cnt[3] && l <= r) {
                        ans = std::min(ans, sum + l * Y + (cx + i + cy + j - 2 * l) * X);
                        ans = std::min(ans, sum + r * Y + (cx + i + cy + j - 2 * r) * X);
                    }
                }
            }
        }

        std::cout << (ans == inf ? -1 : ans) << "\n";
    }
}

int main() {
    std::cin.tie(nullptr)->sync_with_stdio(false);

    int t;
    std::cin >> t;

    while (t--) {
        solve();
    }

    return 0;
}

