const int inv2=(mod+1)/2,inv6=(mod+1)/6;
int C(int a,int b){
    if(a>=mod)a-=mod;
    if(b==0)return 1;
    if(b==1)return a;
    if(b==2)return 1ll*a*(a-1)%mod*inv2%mod;
    if(b==3)return 1ll*a*(a-1)%mod*(a-2)%mod*inv6%mod;
    return 0;
}
int M(int x){if(x>=mod)x-=mod;return x;}
void ad(int &x,int y){x+=y;if(x>=mod)x-=mod;}
