			if(A[i][j]!=A[j][i]||(i==j&&A[i][j])) return 0;
	for(int i=1;i<=n;i++)
		for(int j=0;j<3;j++) bel[i][j]=0;
	for(int i=1;i<=n;i++)
		for(int j=0;j<3;j++)
			if(!bel[i][j]) dfs(i,i,j);
	for(int i=1;i<=n;i++)
		for(int j=0;j<3;j++)
			vec[bel[i][j]][j].push_back(i);
	for(int i=1;i<=n;i++)
		for(int j=0;j<3;j++)
			for(int u:vec[i][j])
				for(int v:vec[i][j])
					if(u!=v&&A[u][v]<=j) return 0;
	tot=0;
	for(int i=1;i<=n;i++){
		int s3=vec[i][2].size();
		if(!s3) continue;
		if(s3<=3) ve[bel[i][1]].push_back(mp(i,(s3==1)?i:-1));
		else{
			for(int j=1;j<s3;j++) ans[++tot]=mp(vec[i][2][j-1],vec[i][2][j]);
			for(int j=2;j<s3;j++) ans[++tot]=mp(vec[i][2][0],vec[i][2][j]);
			ve[bel[i][1]].push_back(mp(vec[i][2][1],vec[i][2][s3-1]));
		}
	}
	for(int i=1;i<=n;i++){
		int sv=ve[i].size();
		if(!sv) continue;
		PR u=mp(-1,-1),v=mp(-1,-1);
		for(PR x:ve[i]){
			if(x.se==-1) continue;
			if(u.fi==-1) u=x;
			else if(v.fi==-1) v=x;
		}
		if(sv==1){
			if(u.fi!=u.se) ans[++tot]=u;
			else if(u.se==-1) return 0;
		}
		else{
			if(v.fi==-1) return 0;
			PR U=u,V=v;
			for(PR x:ve[i]){
				if(x==U||x==V) continue;
				if(x.se==-1){
					ans[++tot]=mp(u.fi,vec[x.fi][2][0]);
					u.fi=vec[x.fi][2][0];
					ans[++tot]=mp(u.se,vec[x.fi][2][1]);
					ans[++tot]=mp(vec[x.fi][2][0],vec[x.fi][2][1]);
					int s3=vec[x.fi][2].size();
					if(s3<=2) u.se=vec[x.fi][2][1];
					else{
						ans[++tot]=mp(vec[x.fi][2][1],(u.se=vec[x.fi][2][2]));
						ans[++tot]=mp(vec[x.fi][2][0],vec[x.fi][2][2]);
					}
				}
				else{
					ans[++tot]=mp(u.se,x.fi);
					u.se=x.se;
				}
			}
			ans[++tot]=mp(u.fi,v.fi);
			ans[++tot]=mp(u.se,v.se);
		}
	}
	for(int i=1;i<=n;i++)
		if(bel[i][1]==i&&bel[i][0]!=i) ans[++tot]=mp(i,bel[i][0]);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=n;j++) bl[i][j]=(i==j);
	for(int i=1;i<=tot;i++)
		if(bl[ans[i].fi][ans[i].se]) return 0;
		else bl[ans[i].fi][ans[i].se]=bl[ans[i].se][ans[i].fi]=1;
	printf("Yes\n%d\n",tot);
	for(int i=1;i<=tot;i++) printf("%d %d\n",ans[i].fi,ans[i].se);
	return 1;
}
