void build(int x,int l,int r)
{
	g[x].clear();
	if(l==r) return ;
	int mid=(l+r)>>1;
	build(x<<1,l,mid),build(x<<1|1,mid+1,r);
}
void upd(int x,int l,int r,int L,int R,pair<int,int> v)
{
	if(L<=l&&r<=R) g[x].emplace_back(v);
	else
	{
		int mid=(l+r)>>1;
		if(L<=mid) upd(x<<1,l,mid,L,R,v);
		if(mid+1<=R) upd(x<<1|1,mid+1,r,L,R,v); 
	}
}
struct DSU
{
	int fa[N],siz[N];
	stack<int> s;
	void build(int m){s=stack<int>{};for(int i=1;i<=m;i++) fa[i]=i,siz[i]=1;}
	int find(int x)
	{
		if(fa[x]==x) return x;
		return find(fa[x]);
	}
	bool merge(int x,int y)
	{
		x=find(x),y=find(y);
		if(x==y) return 0;
		if(siz[x]<siz[y]) swap(x,y);
		siz[x]+=siz[y],fa[y]=x,s.push(y);
		return 1;
	}
	void undo(int tmp)
	{
		while(s.size()>tmp)
		{
			int y=s.top();s.pop();
			siz[fa[y]]-=siz[y],fa[y]=y;
		}
	}
}dsu;
