#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
ll fp(ll a,ll k,ll p)
{
    a%=p;
    if(k<0)
    {
        if(a==0)throw "divided by zero";
        a=fp(a,p-2,p),k=-k;
    }
    ll res=1;
    while(k)
    {
        if(k&1)res=res*a%p;
        a=a*a%p;
        k>>=1;
    }
    return res;
}
const int MAXH=2;
const ll Mod[MAXH]={998244353,1000000007};
array<ll,MAXH> read()
{
    static const int MAXL=4005;
    static char buf[MAXL];
    scanf("%s",buf);
    array<ll,MAXH> res{};
    for(int i=0; buf[i]; i++)
        for(int j=0; j<MAXH; j++)
            res[j]=(10*res[j]+buf[i]-'0')%Mod[j];
    return res;
}
array<ll,MAXH> query(ll a,ll b,ll c)
{
    printf("? %lld %lld %lld\n",a,b,c);
    fflush(stdout);
    auto r=read(),s=read();
    for(int j=0; j<MAXH; j++)
        r[j]=r[j]*fp(s[j],-1,Mod[j])%Mod[j];
    return r;
}
int sgn(ll x)
{
    if(x<0)return -1;
    if(x>0)return 1;
    return 0;
}
struct Point
{
    ll x,y;
    int id;
    explicit Point(ll _x=0,ll _y=0,int _id=0):x(_x),y(_y),id(_id) {}
    Point operator - (const Point& t)const
    {
        return Point(x-t.x,y-t.y,id);
    }
    ll operator * (const Point& t)const
    {
        return x*t.y-y*t.x;
    }
    ll operator ^ (const Point& t)const
    {
        return x*t.x+y*t.y;
    }
    bool operator < (const Point& t)const
    {
        return x==t.x ? y<t.y : x<t.x;
    }
    bool operator == (const Point& t)const
    {
        return x==t.x && y==t.y;
    }
};
array<ll,MAXH> cal(const array<Point,3>& tpoly,ll a,ll b,ll c)
{
    int n=tpoly.size();
    array<Point,3> poly;
    for(int i=0; i<n; i++)
    {
        poly[i].x=tpoly[i]*Point(-b,a);
        poly[i].y=tpoly[i]^Point(-b,a);
    }
    ll x=-c;
    array<ll,MAXH> res{};
    for(int i=0; i<n; i++)
    {
        int sl=sgn(x-poly[i].x),sr=sgn(x-poly[(i+1)%n].x);
        if(sl*sr==0)throw "through vertex";
        int s=sgn(sr-sl);
        if(s==0)continue;
        for(int j=0; j<MAXH; j++)
        {
            ll cur=(poly[(i+1)%n].y-poly[i].y)%Mod[j];
            cur=cur*fp(poly[(i+1)%n].x-poly[i].x,-1,Mod[j])%Mod[j];
            cur=((x-poly[i].x)%Mod[j]*cur+poly[i].y)%Mod[j];
            res[j]=((res[j]+cur*s)%Mod[j]+Mod[j])%Mod[j];
        }
    }
    return res;
}
vector<Point> prepare(const vector<Point>& p,int i,int n)
{
    vector<Point> can;
    for(int j=i+1; j<n; j++)
        can.push_back(p[j]);
    sort(can.begin(),can.end(),[o=p[i]](const Point& lhs,const Point& rhs)
    {
        return (lhs-o)*(rhs-o)==0 ? ((lhs-o)^(lhs-o))<((rhs-o)^(rhs-o)) : (lhs-o)*(rhs-o)>0;
    });
    vector<Point> res;
    for(int j=0,k=0; j<(int)can.size(); j=k)
    {
        while(k<(int)can.size() && (can[j]-p[i])*(can[k]-p[i])==0)k++;
        res.push_back(can[j]);
    }
    return res;
}
struct ArrayHasher
{
    size_t operator()(const array<ll, MAXH>& a) const
    {
        size_t h = 0;
        for (auto e : a)
            h ^= hash<ll>{}(e) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
int solve()
{
    int n;
    scanf("%d",&n);
    vector<Point> p(n);
    for(int i=0; i<n; i++)
        scanf("%lld%lld",&p[i].x,&p[i].y);
    sort(p.begin(),p.end());
    for(int i=0; i<n; i++)
        p[i].id=i;
    vector<int> pre(n,-1),nxt(n,-1);
    vector<array<Point,3>> tri;
    for(int i=0; i<n-2; i++)
    {
        ll a=rng()%900'000'000'000'000+3'000,b=2,c=-(a*p[i].x+b*p[i].y+1);
        array<ll,MAXH> cut{},cof{};
        unordered_map<array<ll,MAXH>,array<Point,3>,ArrayHasher> mp;
        try
        {
            for(int j=0; j<MAXH; j++)
            {
                ll cur=(a%Mod[j])*(a%Mod[j])+(b%Mod[j])*(b%Mod[j]);
                cof[j]=fp(cur,-1,Mod[j]);
            }
            for(auto& t : tri)
            {
                auto r=cal(t,a,b,c);
                for(int j=0; j<MAXH; j++)
                    cut[j]=(cut[j]+r[j])%Mod[j];
            }
            vector<Point> can=prepare(p,i,n),lef,rig;
            if(pre[i]<0)lef=can;
            else lef.push_back(p[pre[i]]);
            if(nxt[i]<0)rig=can;
            else rig.push_back(p[nxt[i]]);
            for(auto& x : lef)
                for(auto& y : rig)
                {
                    if(x==y)continue;
                    array<Point,3> t{p[i],y,x};
                    auto r=cal(t,a,b,c);
                    for(int j=0; j<MAXH; j++)
                        r[j]=r[j]*cof[j]%Mod[j];
                    if(!mp.emplace(r,t).second)throw "duplicate";
                }
        }
        catch(...)
        {
            --i;
            continue;
        }
        auto res=query(a,b,c);
        for(int j=0; j<MAXH; j++)
            res[j]=(res[j]-cut[j]*cof[j]%Mod[j]+Mod[j])%Mod[j];
        auto itr=mp.find(res);
        assert(itr!=mp.end());
        pre[itr->second[1].id]=itr->second[2].id;
        nxt[itr->second[2].id]=itr->second[1].id;
        tri.push_back(itr->second);
    }
    reverse(tri.begin(),tri.end());
    vector<Point> res;
    for(auto& t : tri)
    {
        if(res.empty())
        {
            for(int j=0; j<3; j++)
                res.push_back(t[j]);
            continue;
        }
        for(size_t j=0; j<res.size(); j++)
            if(res[j]==t[2] && res[(j+1)%res.size()]==t[1])
            {
                res.insert(res.begin()+j+1,t[0]);
                break;
            }
    }
    printf("!\n");
    for(int i=0; i<n; i++)
        printf("%lld %lld\n",res[i].x,res[i].y);
    fflush(stdout);
    return 0;
}
int main()
{
    int T;
    scanf("%d",&T);
    while(T--)solve();
    return 0;
}

