int chk(int x1,int y1,int x2,int y2,int w)
{
	int s=0;
	for(auto k:{w,0})
		s+=sm[x2][y2][k]-sm[x1-1][y2][k]-sm[x2][y1-1][k]+sm[x1-1][y1-1][k];
	return s==(x2-x1+1)*(y2-y1+1);
}
ll sol(int n,int m)
{
	int i,j,k;
