		for(j=1;j<=m;++j)
			for(k=0;k<=4;++k)
				sm[i][j][k]=sm[i-1][j][k]+sm[i][j-1][k]-sm[i-1][j-1][k]+(a[i][j]==k);
	for(i=0;i<=n+1;++i)
		for(j=0;j<=m+1;++j)
			for(k=0;k<4;++k)
				f[i][j][k]=1;
	for(i=1;i<=n;++i)
	{
		for(j=1;j<=m;++j)
			f[i][j][0]=(f[i-1][j][0]*chk(i,1,i,j,4)+f[i][j-1][0]*chk(1,j,i,j,1))%mod;
		for(j=m;j;--j)
			f[i][j][1]=(f[i-1][j][1]*chk(i,j,i,m,3)+f[i][j+1][1]*chk(1,j,i,j,1))%mod;
	}
	for(i=n;i;--i)
	{
		for(j=1;j<=m;++j)
			f[i][j][2]=(f[i+1][j][2]*chk(i,1,i,j,4)+f[i][j-1][2]*chk(i,j,n,j,2))%mod;
		for(j=m;j;--j)
			f[i][j][3]=(f[i+1][j][3]*chk(i,j,i,m,3)+f[i][j+1][3]*chk(i,j,n,j,2))%mod;
	}
	ll nw=1,ans=0;
	for(j=1;j<=m;++j)
	{
		int ct=0;
		for(i=0;i<=n;++i)
			ct+=chk(1,j,i,j,1)&&chk(i+1,j,n,j,2);
		nw=nw*ct%mod;
		if(j!=m)
			for(i=1;i<=n;++i)
				(ans+=nw*f[i-1][j+1][1]%mod*f[i+1][j+2][3]*chk(i,j+1,i,m,3)*chk(i+1,j+1,n,j+1,2))%=mod;
		else ans+=nw;
		ll sm=0;
		if(j<m)
		{
			for(i=1;i<=n;++i)
			{
				ll w=f[i-1][j][0]*f[i+1][j-1][2]*chk(i,1,i,j,4)*chk(i+1,j,n,j,2)%mod;
				(nw+=w)%=mod;(sm+=w)%=mod;(ans+=sm*f[i][j+2][1]%mod*f[i+2][j+1][3]*chk(i+1,j+1,i+1,m,3)*chk(1,j+1,i,j+1,1))%=mod;
			}
			sm=0;
			for(i=1;i<=n;++i)
			{
				(ans+=sm*f[i][j-1][0]%mod*f[i+2][j][2]*chk(i+1,1,i+1,j,4)*chk(1,j,i,j,1))%=mod;
				(sm+=f[i-1][j+1][1]*f[i+1][j+2][3]*chk(i,j+1,i,m,3)*chk(i+1,j+1,n,j+1,2))%=mod;
			}
		}
	}
	return ans;
}

