		while((u^rec[j])>(u^rec[(j+3)&3]))j=(j+3)&3;
		tmp=cut(tmp,p[i]-rec[j],u);
	}
}
bool chk(ld w,ld h){
	poly tmp={pt(-V,-V),pt(V,-V),pt(V,V),pt(-V,V)};
	poly rec={pt(0,0),pt(w,0),pt(w,h),pt(0,h)};
	add(p,rec,tmp),add(q,rec,tmp);
	return !tmp.empty();
}
void solve(){
	cin>>lens[0]>>lens[1]>>lens[2]>>lens[3];
	cin>>wall[0]>>wall[1]>>wall[2]>>wall[3];
	ld w=sqrtl((lens[1]-lens[0])*(lens[1]-lens[0]));
	ld h=sqrtl((lens[2]-lens[1])*(lens[2]-lens[1]));
	p3 a=wall[0],b=wall[1],c=wall[2];
	p3 e1=(b-a)/sqrtl((b-a)*(b-a));
	p3 e3=((b-a)^(c-a))/crs(b-a,c-a);
	p3 e2=e3^e1;
	p.clear();
	q.clear();
	for(p3 d:wall){
		d-=a;
		p.pb(pt(d*e1,d*e2));
	}
	for(p3 &d:lens){
		d-=a;
		d=p3(d*e1,d*e2,d*e3);
	}
	pos=O3-a;
	pos=p3(pos*e1,pos*e2,pos*e3);
	for(p3 d:lens){
		auto [x1,y1,z1]=pos;
		auto [x2,y2,z2]=d;
		q.pb(pt(x1-z1/(z2-z1)*(x2-x1),y1-z1/(z2-z1)*(y2-y1)));
	}
	if(area(p)<0)reverse(p.begin(),p.end());
	if(area(q)<0)reverse(q.begin(),q.end());
	ld l=0,r=V;
	for(int _=0;_<=B;_++){
		ld mid=(l+r)/2;
		if(chk(mid,mid*h/w))l=mid;
		else r=mid;
	}
	cout<<fixed<<setprecision(20)<<l*l*h/w<<'\n';
}
