int a[N],pos[lgN][N],Prt[lgN][N],id[lgN][N],pl[N<<2],pr[N<<2],c[lgN],Vrt[N],n;
inline void Insert(int x,int L,int R,int p,int i){
	idx[x].push_back(i);
	if(L==R) return ;
	int mid=L+R>>1;
	if(p<=mid) Insert(x<<1,L,mid,p,i);
	else Insert(x<<1|1,mid+1,R,p,i);
}
inline void Split(int x,int L,int R,int d,int i){
	if(R<a[i]) return ;
	if(L>=a[i]) return itv[i].push_back({x,L,R,d});
	int mid=L+R>>1;
	Split(x<<1,L,mid,d+1,i);
	Split(x<<1|1,mid+1,R,d+1,i);
}
inline void GetPos(int x,int L,int R,int d){
	if(L<R){
		int mid=L+R>>1;
		GetPos(x<<1,L,mid,d+1);
		GetPos(x<<1|1,mid+1,R,d+1);
	}

	T.Build(1,L,R),T.Push(1,-L);
	for(int i:idx[x]){
		Q.q[a[i]].push(i),Q.Update(a[i]);
		T.Modify(1,L,R,a[i],R,-1);
		if(T.tr[1].mn<0){
			int j=T.Find(1,L,R);
			int x=Q.Query(1,1,n,L,j);
			Q.q[a[x]].pop();
			Q.Update(a[x]);
			T.Modify(1,L,R,a[x],R,1);
			pos[d][i]=x;
		}else pos[d][i]=-1;
		pg[x].push_back({pos[d][i],i});
	}
	for(int i:idx[x]) while(Q.q[a[i]].size()) Q.q[a[i]].pop();
	pg[x].push_back({INT_MAX,0});
	sort(pg[x].begin(),pg[x].end(),greater<>());
	for(int i=1;i<pg[x].size();i++){
		Prt[d][pg[x][i][1]]=Prt[d][pg[x][i-1][1]];
		DS3::Modify(Prt[d][pg[x][i][1]],1,n,pg[x][i][1],1);
	}

	vector<int> tmp;
	for(int i:idx[x]) if(~pos[d][i]) tmp.push_back(pos[d][i]);
	sort(tmp.begin(),tmp.end());
	tmp.erase(unique(tmp.begin(),tmp.end()),tmp.end());
	pl[x]=c[d]+1;
	for(int i:tmp) id[d][++c[d]]=i;
	pr[x]=c[d];
}

struct DS4{
	ll tr[N];
	inline void Add(int x,ll k){while(x<=n) tr[x]+=k,x+=x&-x;}
	inline ll Ask(int x){ll sum=0;while(x) sum+=tr[x],x&=x-1;return sum;}
	inline ll Ask(int l,int r){return Ask(r)-Ask(l-1);}
}Ti[lgN],Tp[lgN],Ta;

ll ans;
vector<array<int,2>> ins[N],ers[N];
inline void InsP(int x,int L,int R,int d,int i){
	if(~pos[d][i]){
		int p=lower_bound(id[d]+pl[x],id[d]+pr[x]+1,pos[d][i])-id[d];
		ans+=Ti[d].Ask(pl[x],p);
		Tp[d].Add(p,1);
	}
	if(L==R) return ;
	int mid=L+R>>1;
	if(a[i]<=mid) InsP(x<<1,L,mid,d+1,i);
	else InsP(x<<1|1,mid+1,R,d+1,i);
}
inline void InsI(int x,int L,int R,int d,int i,ll w){
	int p=lower_bound(id[d]+pl[x],id[d]+pr[x]+1,i)-id[d];
	ans+=w*(Tp[d].Ask(p,pr[x])-(L<=a[i]&&a[i]<=R&&pos[d][i]<=i));
	ans+=w*-L;
	if(L-1>0) Ta.Add(L-1,w);
	if(p<=pr[x]) Ti[d].Add(p,w);
}

signed main(){
	cin.tie(0),cout.tie(0);
	ios::sync_with_stdio(0);

	cin>>n;
	for(int i=1;i<=n;i++) cin>>a[i];

	for(int i=1;i<=n;i++) ia[a[i]].push_back(i);
	for(int i=1;i<=n;i++){
		Vrt[i]=Vrt[i-1];
		for(int j:ia[i]) DS3::Modify(Vrt[i],1,n,j,1);
	}

	for(int i=1;i<=n;i++){
		Insert(1,1,n,a[i],i);
		Split(1,1,n,0,i);
	}

	Q.Build(1,1,n);
	GetPos(1,1,n,0);
	for(int i=1;i<=n;i++){
		auto Tick=[&](int p,int j){
			int x1=itv[i][p][0],l1=itv[i][p][1],d1=itv[i][p][3];
			int p1=(*--upper_bound(pg[x1].begin(),pg[x1].end(),array<int,2>({i,0}),greater<>()))[1];
			ll s1=-l1-DS3::Query(Vrt[l1-1],1,n,1,i)-DS3::Query(Prt[d1][p1],1,n,1,i);
			
			int x2=itv[i][j][0],l2=itv[i][j][1],d2=itv[i][j][3];
			int p2=(*--upper_bound(pg[x2].begin(),pg[x2].end(),array<int,2>({i,0}),greater<>()))[1];
			ll s2=-l2-DS3::Query(Vrt[l2-1],1,n,1,i)-DS3::Query(Prt[d2][p2],1,n,1,i);
			
			return DS3::Find(Vrt[l1-1],Prt[d1][p1],Vrt[l2-1],Prt[d2][p2],1,n,i+1,s1,s2);
		};
		vector<int> p={0},t={i};
		for(int j=1;j<itv[i].size();j++){
			while(true){
				int k=Tick(p.back(),j);
				if(k<t.back()){
					p.pop_back();
					t.pop_back();
				}else{
					t.push_back(k);
					break ;
				}
			}
			p.push_back(j);
		}
		for(int j=0;j<p.size();j++){
			ins[t[j]].push_back({i,p[j]});
			if(j+1<p.size()) ers[t[j+1]].push_back({i,p[j]});
		}
	}

	vector<ll> res;
	for(int k=1;k<=n;k++){
		InsP(1,1,n,0,k);
		ans+=Ta.Ask(a[k],n);
		ans+=a[k];
		for(auto p:ers[k]){
			int i=p[0],j=p[1];
			InsI(itv[i][j][0],itv[i][j][1],itv[i][j][2],itv[i][j][3],i,-1);
			ans-=DS3::Query(Vrt[itv[i][j][1]-1],1,n,i+1,k);
		}
		for(auto p:ins[k]){
			int i=p[0],j=p[1];
			InsI(itv[i][j][0],itv[i][j][1],itv[i][j][2],itv[i][j][3],i,1);
			ans+=DS3::Query(Vrt[itv[i][j][1]-1],1,n,i+1,k);
		}
		Ta.Add(a[k],-1);
		res.push_back(ans);
	}

	for(ll x:res) cout<<x<<' ';cout<<endl;

	return 0;
}

