#define N 100005

using namespace std;

char st[N];
int n,cnt,q[N];
bool chk(int x,int y,int m)
{
	int i,ct=0;cnt=0;
	for(i=x;i<=y;++i)
		if(st[i]=='?')
		{
			q[++cnt]=ct;
			ct=0;
		}
		else
			++ct;
	q[++cnt]=ct;
	for(i=1;i<cnt;++i)
	{
		if(q[i]+q[i+1]+1>=m)return 1;
		if(i<=n-2&&q[i]+q[i+1]+q[i+2]+2>=m){q[i+2]+=q[i+1]+1;++i;}
	}
	return q[cnt]>=m;
}
int sol(int x,int y)
{
	if(x>y)return 0;
	int l=1,r=y-x+1,ans=0;
	while(l<=r)
	{
		int m=(l+r)>>1;
		if(chk(x,y,m))l=(ans=m)+1;
		else r=m-1;
	}
	return ans;
}

