		for(i=1;i<=n;++i)
			if(st[i]=='1')
			{
				ans=max(ans,sol(lst+1,i-1));
				lst=i;
			}
		ans=max(ans,sol(lst+1,n));
		cout<<ans<<endl;
	}
	return 0;
}

