	#define mid ((l+r)>>1)
	#define ls u<<1
	#define rs u<<1|1
	void upd(bool o,int u,int l,int r,int x,int v){
		if(l==r){t[o][u]=v;return;}
		x<=mid?upd(o,ls,l,mid,x,v):upd(o,rs,mid+1,r,x,v);
		t[o][u]=max(t[o][ls],t[o][rs]);
		mx[u]=max(mx[ls],mx[rs]);
		if(t[0][ls]&&t[1][rs]) mx[u]=max(mx[u],t[0][ls]+t[1][rs]); 
	}
