		s[i][1][y].insert({v,id});
		s[i][0][z].insert({v,id});
		t[i].upd(1,1,0,(1<<i+1)-1,y,(*s[i][1][y].rbegin()).first);
		t[i].upd(0,1,0,(1<<i+1)-1,z,(*s[i][0][z].rbegin()).first);
	}
