    {
        int x=a[n-1]-1,y=n-1-a[n-1];
        mk(x,2);mk(1,x+y);mk(y,1);mk(1,y+1);mk(1,x+1);
        return;
    }
    if(a[n]==n)return;
    mk(1,1);mk(n-2,1);mk(2,n-3);mk(n-3,1);mk(1,n-2);
