void trhs(int x,int fa){
	hs[x]=1;
	for(int y:g[x]) if(y!=fa&&!incir[y]){
		trhs(y,x);
		hs[x]+=shift(hs[y]);
	}
}

void getcir(int x,int fa){
	v[x]=1;
	for(int y:g[x]) if(y^fa){
		if(v[y]){
			incir[x]=1;
			cir_tail=y;
			cir.push_back(x);
			return ;
		}
		getcir(y,x);
		if(incir[y]&&!shudwn){
			incir[x]=1;
			cir.push_back(x);
			if(x==cir_tail) shudwn=1;
			return ;
		}
	}
}

