struct frac{
	ll p,q;
	frac() {p=0,q=1;}
	frac(ll p_,ll q_) {ll g=__gcd(p_,q_);p=p_/g,q=q_/g;}
	bool operator<=(frac k)const {return (__int128)p*k.q<=(__int128)k.p*q;}
	frac operator+(frac k)const {return frac(p*k.q+q*k.p,q*k.q);}
	frac operator*(frac k)const {return frac(p*k.p,q*k.q);}
}pos[N];

bool chk(int x,int y){
	if(!y) return 0;
	ll p=1ll*(a[y]-a[x])*W,q=b[x]-a[x]-b[y]+a[y];
	if(q<0) p=-p,q=-q;
	if(p<=0||!q) return 0;
	return frac(p,q)<=pos[y];
}

void work(int x,int y){
	ll p=1ll*(a[y]-a[x])*W,q=b[x]-a[x]-b[y]+a[y];
	if(q<0) p=-p,q=-q;
	frac X=frac(p,q),Y=frac(b[x]-a[x],W)*X+frac(a[x],1);
	pos[x]=X;
	printf("(%lld/%lld,%lld/%lld)\n",X.p,X.q,Y.p,Y.q);
}

