void pushup(int rt){
	t[rt]=GCD(t[rt<<1],t[rt<<1|1]);
}
void build(int l=1,int r=k,int rt=1){
	if(l==r)return void(t[rt]=d[pos[l]]-d[pos[l-1]]);
	int mid=(l+r)>>1;build(l,mid,rt<<1);build(mid+1,r,rt<<1|1);pushup(rt);
}
void update(int x,int y,int l=1,int r=k,int rt=1){
	if(l==r)return t[rt]+=y,void();int mid=(l+r)>>1;
	x<=mid?update(x,y,l,mid,rt<<1):update(x,y,mid+1,r,rt<<1|1);pushup(rt);
}
ll query(){return abs(t[1]);}
ll sum,ans=1e18;
