#include<bits/stdc++.h>
using namespace std;

const int N = 2005;
typedef long double db;
typedef long long LL;
typedef __int128 LLL;
const db PI = acosl(-1);

//a > 0, b > 0
LLL exgcd(LLL n, LLL a, LLL b, LLL c){
    LLL res = (b / c) * (n + 1) + (a / c) * n * (n + 1) / 2;
    a %= c, b %= c;
    if(!a)return res + (b / c) * (n + 1);
    LLL m = (a * n + b) / c;
    return res + m * n - exgcd(m - 1, c, c - b - 1, a);

    // if(a < 0)a += c, res -= (a / c) * n * (n + 1) / 2;
}

LLL nexgcd(LLL n, LLL a, LLL b, LLL c){
    LLL res = (b / c) * (n + 1) + (a / c) * n * (n + 1) / 2;

    a %= c, b %= c;
    if(a < 0)a += c, res -= n * (n + 1) / 2;
    if(b < 0)b += c, res -= n + 1;

    return res + exgcd(n, a, b, c);
}

LLL floor_sum(LLL a, LLL b, LLL c, LLL l, LLL r){
    return nexgcd(r, a, b, c) - nexgcd(l - 1, a, b, c);
}

const LL W = 1e9, V = W * W + W + 1;

struct Point{
    LL x, y;

    inline Point operator- (const Point &w){ return {x - w.x, y - w.y}; }
    inline LL operator* (const Point &w){ return x * w.y - y * w.x;}
    inline LL operator& (const Point &w){ return x * w.x + y * w.y;}

    inline db ang(){return atan2(y, x);}

}p[N];

db ang[N], ang2[N];
LL tmp[N];


bool in(Point x, Point k, LL lim){
    return x.x <= lim && (LLL)x.x * k.y >= (LLL)x.y * k.x;
}

LLL divx(LLL a, LLL b){
    if(a > 0)return a / b;
    return (a - b + 1) / b;
}

LL gclamp(LLL k){
    return max(min(k, (LLL)V), (LLL)-V);
}

void clamp(LL &l, LL &r, LLL k, LLL b){
    if(k == 0){
        if(b < 0)l = 1, r = 0;
    }
    else if(k > 0){
        LLL t = divx(b, k);
        r = min(r, gclamp(t));
    }
    else {
        LLL t = divx((-b) + (-k) - 1, -k);
        l = max(l, gclamp(t));
    }
}

LL seg(Point u, Point v, Point k, LL lim){
    if(u.x > v.x)swap(u, v);
    LL d = __gcd(abs(u.x - v.x), abs(u.y - v.y));
    LL l = 1, r = d - 1;

    LLL dx = (v.x - u.x) / d, dy  = (v.y - u.y) / d;
    
    clamp(l, r, dx, lim - u.x);
    clamp(l, r, k.x * dy - dx * k.y, (LLL)u.x * k.y - (LLL)k.x * u.y);

    return max(0ll, r - l + 1);
}

pair<LL, db> calc(Point u, Point v, int id, Point k, LL lim){
    LL res1 = 0; db res2 = 0;
    if(u.x == v.x)return {res1, res2};
    if(u.x > v.x)swap(u, v);

    LL l = u.x + 1, r = min(lim, v.x - 1);
    LL a = v.y - u.y, c = v.x - u.x, b = u.y * c - u.x * a - 1;
    clamp(l, r, (LLL)k.x * a - (LLL)k.y * c, -(LLL)b * k.x);
    if(l <= r)res1 += 2 * floor_sum(a, b, c, l, r);

    l = u.x + 1, r = min(lim, v.x - 1);
    clamp(l, r, (LLL)k.y * c - (LLL)k.x * a, (LLL)b * k.x - 1);
    a = k.y, b = 0, c = k.x;
    if(l <= r)res1 += 2 * floor_sum(a, b, c, l, r);
    
    res1 += seg({u.x, 0}, u, k, lim);
    res1 += seg({v.x, 0}, v, k, lim);
    res1 += tmp[id];

    if(in(u, k, lim))res2 += ang[id];
    if(in(v, k, lim))res2 += 1 - ang[id];

    // printf("%lld %Lf\n", res1, res2);

    return {res1, res2};
}

int n;

LL solve(Point k, LL lim){
    LL res1 = 0; db res2 = 0;

    for(int i = 1; i <= n; i ++){
        Point u = p[i], v = p[i % n + 1];
        tmp[i] = seg(u, v, k, lim);
        if(u.x == v.x)continue;
        auto tt = calc(u, v, i, k, lim);
        if(u.x < v.x)res1 -= tt.first, res2 -= tt.second;
        else res1 += tt.first, res2 += tt.second;
    }

    for(int i = 1; i <= n; i ++){
        if(in(p[i], k, lim))res2 += ang2[i];
        res1 += tmp[i];
    }

    return (res1 + llroundl(res2)) / 2;
}

Point getp(LL x){
    if(x <= V)return {V, x};
    else return {2 * V - x, V};
} 

void solve(){

    LL k;
    scanf("%d%lld", &n, &k);

    for(int i = 1; i <= n; i ++)scanf("%lld%lld", &p[i].x, &p[i].y);
    
    for(int i = 1; i <= n; i ++){
        Point u = p[i] - p[(i == 1) ? n : i - 1], v = p[i] - p[i % n + 1];
        ang2[i] = atan2(u * v, u & v);
        if(ang2[i] < 0)ang2[i] += 2 * PI;
        ang2[i] /= PI;

        u = p[i], v = p[i % n + 1];
        if(u.x > v.x)swap(u, v);
        if(u.x == v.x)ang[i] = 0;
        else ang[i] = ((v - u).ang() + PI / 2) / PI;
    }

    // printf("%lld\n", solve(getp(2 * V - W), W));
    // return ;


    LL l = 0, r = 2 * V;
    while(l < r){
        LL mid = (l + r) >> 1;
        auto t = getp(mid);
        if(solve(t, W) >= k)r = mid;
        else l = mid + 1;
    }

    auto t1 = getp(l), t2 = getp(l - 1);
    k -= solve(t2, W);

    l = 0, r = W;
    while(l < r){
        LL mid = (l + r) >> 1;
        if(solve(t1, mid) - solve(t2, mid) >= k)r = mid;
