	int f=0;
	//cout<<l<<" "<<r<<endl;
	//for(i=1;i<=n;i++) cout<<a[i]<<" ";
	//cout<<endl;
	if(mv-l<=r-mv) {//左边较短
		for(i=l;i<=mv;i++) 
			if(a[i]<=mv) vis[a[i]]=1;
		if(vis[mv]&&a[mid]!=mv) f=1;
		for(i=l;i<=mv;i++) 
			if(!vis[i]) np.push_back(pos[i]);
			else vis[i]=0;
		sort(np.begin(),np.end());
		for(i=l;i<=mv;i++)
			if(a[i]>mv) {
				ans++,swap(a[i],a[np.back()]);
				swap(pos[a[i]],pos[a[np.back()]]);
				np.pop_back();
			}
		//cout<<"l:"<<ans<<endl;
		work(l,mv-f),work(mv-f+1,r);
	} else {
		for(i=mv;i<=r;i++) 
			if(a[i]>=mv) vis[a[i]]=1;
		if(a[mv]!=mv&&vis[mv]) f=1;
		//cout<<f<<endl;
		for(i=mv;i<=r;i++) 
			if(!vis[i]) np.push_back(pos[i]);
