int calc(vector <pair <int, int> > f, int k){
	auto cs = [&](int x){ int ans = 2e18; for(auto i: f) ans = min(ans, i.second * x + i.first); return ans;};
	int now = 0, ans = 0;
	while(now <= k){
		int c = cs(now), d = cs(now + 1) - c;
		int L = now + 1, R = k;
		while(L < R){
			int mid = L + R + 1 >> 1;
			if(cs(mid) - c == (mid - now) * d) L = mid;
			else R = mid - 1;
		}
		(ans += c % mod * (R - now + 1) + d * ((R - now + 1) * (R - now) / 2 % mod)) %= mod;
		now = R + 1;
	}
	return ans;
}
