ll K[N],B[N],val[N],ans;
vector<pair<int,int> >v[N];
void push(int p){
	sz[p]=sz[lc[p]]+sz[rc[p]]+1;
}
void upd(int p,ll k,ll b){
	K[p]+=k,B[p]+=b,val[p]+=1ll*k*(sz[lc[p]]+1)+b;
}
void down(int p){
	upd(lc[p],K[p],B[p]),upd(rc[p],K[p],B[p]+K[p]*(sz[lc[p]]+1));
	K[p]=B[p]=0;
}
void split(int p,int &x,int &y,ll k){
	if(!p){x=y=0;return ;}
	down(p);
	if(val[p]>=k) x=p,split(rc[p],rc[x],y,k);
	else y=p,split(lc[p],x,lc[y],k);
	push(p);
}
int merge(int x,int y){
	if(!x||!y) return x|y;
	if(rd[x]<rd[y]) swap(x,y);
	int u,v;
	down(x),split(y,u,v,val[x]);
	return lc[x]=merge(lc[x],u),rc[x]=merge(rc[x],v),push(x),x;
}
void dfs(int x,int fa){
	rt[x]=x,sz[x]=1,rd[x]=rand();
	for(auto p:v[x]){
		int y=p.first,z=p.second;
		if(y!=fa) dfs(y,x),upd(rt[y],-2*z,z*(k+1)),rt[x]=merge(rt[x],rt[y]);
	}
}
void dfs2(int p,int k){
	if(p){
		if(sz[lc[p]]+1<=k) ans+=val[p];
		down(p);
		dfs2(lc[p],k),dfs2(rc[p],k-sz[lc[p]]-1);
	}
}
