#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
constexpr ll mod=1e9+7;
ll qpow(ll a){
	ll ans=1;int b=mod-2;
	while(b){
		if(b&1) ans=ans*a%mod;
		a=a*a%mod,b>>=1;
	}
	return ans;
}
unordered_map<int,unordered_map<int,ll>> dp;
void dfs(int n){
	if(dp.count(n)) return;
	int k=1<<__lg(n),L=k/2-1+min(n-k+1,k/2),R=n-1-L;
	dfs(L),dfs(R);
	dp[n][n]=dp[L][0]%mod*dp[R][0]%mod;dp[n][0]=dp[n][n]*qpow(n)%mod;
	for(auto [x,y]:dp[L])if(x)dp[n][x]=qpow(n-x)*y%mod*dp[R][0]%mod;
	for(auto [x,y]:dp[R])if(x)dp[n][x]=(dp[n][x]+qpow(n-x)*y%mod*dp[L][0]%mod)%mod;
}
inline void solve(){
	int n;cin>>n;
	dfs(n);
	ll ans=0;
	for(auto [x,y]:dp[n]) if(x)ans+=y;
	cout<<ans%mod*qpow(n)%mod<<'\n';
}
int main(){
	int t;cin>>t;
	dp[0][0]=1;
	dp[1][0]=dp[1][1]=1;
	while(t--) solve();
}

