void solve(){
	int n,m;
	cin>>n>>m;
	int la=0,lb=0;
	vector<array<int,2>>a(n),b(m),c;
	for(auto &[x,y]:a){
		cin>>x>>y;
		la+=y-x;
		c.push_back({x,0});
		c.push_back({y,0});
	}
	for(auto &[x,y]:b){
		cin>>x>>y;
		lb+=y-x;
		c.push_back({x,1});
		c.push_back({y,1});
	}
	sort(c.begin(),c.end());
	c.push_back({0,0});
	double res=0,sa=0,sb=0,pa=0,pb=0;
	int fa=0,fb=0;
	for(int i=0;i<c.size()-1;++i){
		auto PA=[&](int len){
			if(la==0) return 1.0L/n;
			else return 1.0L*len/la;
		};
		auto PB=[&](int len){
			if(lb==0) return 1.0L/m;
			else return 1.0L*len/lb;
		};
		if(c[i][1]==0) fa^=1;
		else fb^=1;
		int len=c[i+1][0]-c[i][0];
		double mid=(c[i+1][0]+c[i][0])/2.0L;
		if(fa && fb) res+=1.0L/3.0L*len*PA(len)*PB(len);
		if(fa) res+=PA(len)*(pb*mid-sb);
		if(fb) res+=PB(len)*(pa*mid-sa);
		if(fa) sa+=mid*PA(len),pa+=PA(len);
		if(fb) sb+=mid*PB(len),pb+=PB(len);
	}
	cout<<fixed<<setprecision(15)<<res<<"\n";
}

