const int N=1e5+10,V=1e5;
template<const int M>
struct SGT{
	int cnt[N<<2];
	ll t[N<<2][M];
	void pushup(int rt){
		for(int i=0;i<M;i++){
			t[rt][i]=t[rt<<1][i]+t[rt<<1|1][(M-cnt[rt<<1]%M+i)%M];
		}
		cnt[rt]=cnt[rt<<1]+cnt[rt<<1|1];
	}
	void update(int x,int y,int l=1,int r=V,int rt=1){
		if(l==r){
			cnt[rt]+=y;
			for(int i=0;i<M;i++)t[rt][i]=1ll*(cnt[rt]/M+(i<cnt[rt]%M))*x;
			return;
		}
		int mid=(l+r)>>1;
		if(x<=mid)update(x,y,l,mid,rt<<1);
		else update(x,y,mid+1,r,rt<<1|1);
		pushup(rt);
	}
	int count()const{
		return cnt[1];
	}
	ll operator [] (const int &x)const{
		return t[1][x];
	}
};
