			ntt(coef,1<<bt,0);
			for(int i=0;i<(1<<bt);++i) coef[i]=coef[i]*1ll*z[i]%MOD;
			maintain(coef);
		}
		for(int i=0;i<(1<<bt);++i) z[i]=z[i]*1ll*z[i]%MOD;
	}
	for(int X0,Y0,X1,Y1;q--;){
