}

Mat val(int x){
  Mat c=zero;
  c.a[m<<1][m<<1]=1;
  for(int i=0;i<m;i++){
	int dw=qpow(D[x][i]);
	add(c.a[i+m][i+m],dw);
	del(c.a[(i-1+m)%m+m][i+m],mul(dw,L[x][i]));
	del(c.a[(i+1+m)%m+m][i+m],mul(dw,R[x][i]));
	del(c.a[i][i+m],mul(U[x][i],dw));
	del(c.a[m<<1][i+m],dw);
	add(c.a[i+m][i],1);
  }
  return c;
}

void pu(int p){tr[p]=tr[lc]*tr[rc];}

void build(int l,int r,int p){
  if(l==r) return tr[p]=val(l),void();
  build(lson),build(rson),pu(p);
}

void upd(int l,int r,int p,int x){
  if(l==r) return tr[p]=val(l),void();
  (x<=mid)?upd(lson,x):upd(rson,x);pu(p);
}

Mat qry(int l,int r,int p,int x,int y){
  if(x>y) return e;
  if(x<=l&&y>=r) return tr[p];
  if(y<=mid) return qry(lson,x,y);
  if(x>mid) return qry(rson,x,y);
  return qry(lson,x,y)*qry(rson,x,y);
}

void Gauss(){
  for(int i=0;i<(m<<1);i++){
	if(!G[i][i])
	  for(int j=i+1;j<(m<<1);j++)
	    if(G[j][i]){swap(i,j);break;}
	int inv=qpow(G[i][i]);
	for(int j=i+1;j<(m<<1);j++){
	  int nw=mul(G[j][i],inv);
	  for(int k=i;k<=(m<<1);k++) del(G[j][k],mul(G[i][k],nw));
	}
  }
  for(int i=(m<<1)-1;i>=0;i--){
	X[i]=G[i][m<<1];
	for(int j=i+1;j<(m<<1);j++) del(X[i],mul(X[j],G[i][j]));
	X[i]=mul(X[i],qpow(G[i][i]));
  }
}

