int n,k,B,a[N],fa[N],dis[N],op[N],to[N],L[N],R[N],bel[N],ans;
int find(int x){return fa[x]==x?x:fa[x]=find(fa[x]);}
void make(int x){
	for(int i=R[x];i>=L[x];i--){
		int w=op[i]?min(i+k,n+1):i+1;
		if(w>R[x])to[i]=w,dis[i]=op[i];
		else to[i]=to[w],dis[i]=dis[w]+op[i];
	}
}
void update(int l,int r){
	for(int i=find(l);i<=r;i=find(i+1))op[i]=1,make(bel[i]);
	for(int i=find(l);i<=r;i=find(i))fa[i]=i+1;
}
void solve(){
	scanf("%d%d",&n,&k);B=sqrt(n);
	for(int i=1;i<=n;i++)scanf("%d",&a[i]),op[i]=0;
	for(int i=1,x;i<=n;i++){
		x=bel[i]=(i-1)/B+1;
		if(!L[x])L[x]=i;R[x]=i;
	}for(int i=1;i<=n+1;i++)fa[i]=i;
	for(int i=1;i<=bel[n];i++)make(i);
	for(int i=1;i<=n;i++){
		update(max(a[i]-k+1,1),a[i]);ans=0;
		for(int u=1;u<=n;u=to[u])ans+=dis[u];
		printf("%d ",ans);
	}puts("");
}
