int build(int l,int r){
	int p=0;
	if(l==r){
		int u=++tot;
		val[u]=a[l];
		return u;
	}
	int c1=-1,c2=-1,c3=-1;
	if(a[l]=='!'){
		int u=++tot;
		val[u]=a[l];
		son[tot][0]=build(l+1,r);
		return u;
	}
	for(int i=l;i<=r;i++){
		if(a[i]=='(')p++;
		if(a[i]==')')p--;
		if(a[i]=='&')if(!p)c1=i;
		if(a[i]=='^')if(!p)c2=i;
		if(a[i]=='|')if(!p)c3=i;
	}
	if(c2==-1)c2=c3;
	if(c1==-1)c1=c2;
	if(c1==-1){
		return build(l+1,r-1);
	}
	else{
		int u=++tot;
		val[u]=a[c1];
		son[u][0]=build(l,c1-1);
		son[u][1]=build(c1+1,r);
		return u;
	}
}
