		}
		if(!fsy.init(a[1], a[2])) {
			puts("1");
			continue;
		}
		db l = 0, r = a[0].x;
		ry = a[0].y;
		for(auto & x : a) {
			r = std::max(r, x.x);
			ry = std::max(ry, x.y);
		}
		printf("%.12Lf\n", findmax(l, r, [&](db x) { return findmax(0, ry, [&](db y) { return g(x, y); });}));
	}

}

