int work()
{
	int tot=0;
	auto E=e;
	e.assign(ls+1,vector<array<int,2>>());
	for(int i=1; i<=n; i++)
	{
		if(tot+E[i].size()*(E[i].size()-1)/2>=ls) return ls;
		for(auto [_,x]:E[i])
		{
			for(auto [_,y]:E[i])
			{
				if(x<y)
				{
					e[x].push_back({y,++tot});
					e[y].push_back({x,tot});
				}
			}
		}
	}
	return tot;
}
vector<bool> vis;
int dfs(int u)
{
	vis[u]=1;
	int res=1;
	for(auto [v,_]:e[u])
	{
		if(vis[v]) continue;
		res+=dfs(v);
	}
	return res;
}
