		e[x].push_back({y,i});
		e[y].push_back({x,i});
	}
	if(m>n)
	{
		cout<<n<<"\n";
		return;
	}
	int t=min(k,10ll);
	ls=m;
	for(int i=1; i<=t; i++)
	{
		m=work();
		if(m>=ls)
		{
			cout<<ls<<"\n";
			return;
		}
		n=ls;
		ls=m;
	}
	k-=t;
	
	
