#define pr pair<int,int>
#define mod 1000000007

typedef long long ll;

using namespace std;

int H,W,h[4],w[4];

ll calc()
{
	ll ans=0;
	int s[4];
	for(s[1]=0;s[1]<3;++s[1])
		for(s[2]=0;s[2]<3;++s[2])
			for(s[3]=0;s[3]<3;++s[3])
			{
				int ct=0,ps=0,U=0,D=0;
				for(int i=1;i<=3;++i)
					if(s[i]==0)U=max(U,w[i]);
					else if(s[i]==2)D=max(D,w[i]);
					else{++ct;ps=i;}
				if(U==0||D==0)continue;
				if(ct==0)
				{
					if(U+D>=W)++ans;
				}
				else
				{
					if(U+D>=W){ans+=W-w[ps]-1;}
					else
					{
						int L=max(2,W-D-w[ps]+1),R=min(W-w[ps],U+1);
						ans+=max(0,R-L+1);
					}
				}
			}
	return ans%mod;
}
int sol()
{
	int i;
	ll ans=0;
	cin>>H>>W;
	for(i=1;i<=3;++i)
		cin>>h[i]>>w[i];
	if(h[1]!=H&&h[2]!=H&&h[3]!=H)
	{
		swap(H,W);
		for(i=1;i<=3;++i)
			swap(h[i],w[i]);
	}
	if(pr{h[1],w[1]}<pr{h[2],w[2]}){swap(h[1],h[2]);swap(w[1],w[2]);}
	if(pr{h[2],w[2]}<pr{h[3],w[3]}){swap(h[2],h[3]);swap(w[2],w[3]);}
	if(pr{h[1],w[1]}<pr{h[2],w[2]}){swap(h[1],h[2]);swap(w[1],w[2]);}
	if(h[1]<H)return 0;
	if(h[1]==H&&w[1]==W)return 1ll*(H-h[2]+1)*(W-w[2]+1)%mod*(H-h[3]+1)%mod*(W-w[3]+1)%mod;
	if(h[2]==H&&h[3]==H)return calc();
	if(w[2]==W&&w[3]==W&&h[2]+h[3]>=H)ans+=2ll*(W-w[1]-1);
	if(h[2]==H)
	{
		if(w[1]+w[2]>=W)(ans+=2ll*(H-h[3]+1)*(W-w[3]+1))%=mod;
	}
	else
	{
		if(w[1]+w[2]>=W&&w[1]+w[3]>=W&&h[2]+h[3]>=H)ans+=4;
	}
	return ans%mod;
}

