	int cnt[MAXN*64],ls[MAXN*64],rs[MAXN*64],tot;
	ll sum[MAXN*64];
	void ins(int u,int op,int l,int r,int &p) {
		if(!p) p=++tot;
		cnt[p]+=op,sum[p]+=op*u;
		if(l==r) return ;
		int mid=(l+r)>>1;
		u<=mid?ins(u,op,l,mid,ls[p]):ins(u,op,mid+1,r,rs[p]);
	}
