int solve(int a,int b,int x,ll al,ll ar,ll bl,ll br){
	al=max(al,pw[a-1]),ar=min(ar,pw[a]);
	bl=max(bl,0ll),br=min(br,pw[b]);
	if(al>=ar||bl>=br)return 0;
	bool flag=al==pw[a-1]&&ar==pw[a]&&bl==0&&br==pw[b];
	if(flag&&~his[a][b][x])return his[a][b][x];
	int res1=solve1(a,b,x,al,ar,bl,br);
	int res2=solve2(a,b,x,al,ar,bl,br);
	// debug("solve",a,b,x,al,ar,bl,br,res1,res2);
	if(flag)his[a][b][x]=(res1+res2)%mod;
	return (res1+res2)%mod;
}
int work(ll lim){
	ll ans=0;
	for(int a=1;a+2<N;a++){
		for(int b=1;a+b+1<N;b++){
			for(int x=0;x<=9;x++){
				int c=lim/pw[b]%10;
				if(x<c){
					ans+=solve(a,b,x,0,lim/pw[b+1]+1,0,pw[b]);
				}else if(x==c){
					ans+=solve(a,b,x,0,lim/pw[b+1],0,pw[b]);
					ans+=solve(a,b,x,lim/pw[b+1],lim/pw[b+1]+1,0,lim%pw[b]+1);
				}else{
					ans+=solve(a,b,x,0,lim/pw[b+1],0,pw[b]);
				}
			}
		}
	}
	ans%=mod;
	// debug("work",lim,ans);
	return ans%mod;
}
