	inline friend info operator+(const info&x,const info&y) {
		return {x.f&y.f,(x.f&y.g)|(x.g&y.f)};
	}
};
int stk[105],tp,L[MAXN<<2],R[MAXN<<2];
struct SegmentTree {
	bool ty[MAXN<<2];
	ull tg[MAXN<<2];
	info tr[MAXN<<2];
	void psu(int p) {
		tr[p]=tr[p<<1]+tr[p<<1|1];
	}
	void adt(int p,ull k) {
		tr[p].f&=U^k;
		tr[p].g=ty[p]?(U^tr[p].f):(tr[p].g&(U^k));
		tg[p]|=k;
	}
	void psd(int p) { adt(p<<1,tg[p]),adt(p<<1|1,tg[p]),tg[p]=0; }
	void init(int l=1,int r=n,int p=1) {
		L[p]=l,R[p]=r;
		if(l==r) {
			ty[p]=1,tr[p]={a[l],U^a[l]};
			return ;
		}
		int mid=(l+r)>>1;
		init(l,mid,p<<1);
		init(mid+1,r,p<<1|1);
		psu(p);
	}
	void set(int u,ull k,int l=1,int r=n,int p=1) {
		if(l==r) return tr[p]={k,U^k},void();
		int mid=(l+r)>>1; psd(p);
		u<=mid?set(u,k,l,mid,p<<1):set(u,k,mid+1,r,p<<1|1);
		psu(p);
	}
	void upd(int ul,int ur,ull k,int l=1,int r=n,int p=1) {
		if(ul<=l&&r<=ur) return adt(p,k);
		int mid=(l+r)>>1; psd(p);
		if(ul<=mid) upd(ul,ur,k,l,mid,p<<1);
		if(mid<ur) upd(ul,ur,k,mid+1,r,p<<1|1);
		psu(p);
	}
	info qry(int ul,int ur,int l=1,int r=n,int p=1) {
		if(ul<=l&&r<=ur) return stk[++tp]=p,tr[p];
		int mid=(l+r)>>1; psd(p);
		if(ur<=mid) return qry(ul,ur,l,mid,p<<1);
		if(mid<ul) return qry(ul,ur,mid+1,r,p<<1|1);
		return qry(ul,ur,l,mid,p<<1)+qry(ul,ur,mid+1,r,p<<1|1);
	}
	ull qpos(int k,int l,int r,int p) {
		if(l==r) return tr[p].g;
		int mid=(l+r)>>1; psd(p);
		if(tr[p<<1].g>>k&1) return qpos(k,l,mid,p<<1);
		return qpos(k,mid+1,r,p<<1|1);
	}
}	T;
