void up(int rt){tr[rt]=tr[rs[rt]]*tr[ls[rt]];sz[rt]=sz[ls[rt]]+sz[rs[rt]];}
void updt(int a,mat b,int l,int r,int& rt)
{
	if(!rt)rt=++cnt;
	if(l==r)
	{
