void mrg(int l,int r,int& rt,int rt0)
{
	if(!rt||!rt0){rt=max(rt,rt0);return;}if(l==r){q[++tl]=l;return;}
	int m=(l+r)>>1;mrg(lson,ls[rt0]);mrg(rson,rs[rt0]);up(rt);
