}



vi prv;
void go(int u) {
    if (u == -1) return;
    for(auto &v : g[u]) {
        if (prv[v] == -1) {
            prv[v] = u;
            go(mt[v]);
        }
    }
}

vi val;
void go_val(int u, int x) {
    if (u == -1) return;
    for(auto &v : g[u]) {
        if (val[v] == -1) {
            val[v] = x;
            go_val(mt[v], x);
        }
    }
}


ll ans[4];
int cnt[4];

vi order, cost, rem;
void rec(int mask, int e, ll dmg, int from, int depth=0) {
    bool ok = ckmax(ans[e], dmg);
    mask |= (1 << e);
    if (mask == 15) return;

    if (__builtin_popcount(mask^15) == 1) {
        // okay we need only one change
        int target = __builtin_ctz(mask^15);
        // e + e_in - e_out == target
        rep(e_out, 4) {
            val.assign(mt.size(), -1);

            int e_in = (target + e_out + 4 - e) % 4;

            for(int ptr = (int)order.size() - 1; ptr >= from; --ptr) {
                int i = order[ptr];
                if (mt[i] == -1) continue;
                if (rem[i] != e_out) continue;

                if (val[i] == -1) {
                    val[i] = cost[i];
                    go_val(mt[i], val[i]);
                }
            }


            for(int ptr = from; ptr < order.size(); ++ptr) {
                int i = order[ptr];
                if (mt[i] != -1) continue;
                if (rem[i] != e_in) continue;

                if (val[i] != -1) {
                    ckmax(ans[target], dmg + cost[i] - val[i]);
                }
            }
        }
        return;
    }
    assert(depth < 2);

    auto save = mt;
    vi was_prv(mt.size(), -1);
    for(int ptr = from; ptr < order.size(); ++ptr) {
        int i = order[ptr];
        if (mt[i] == -1) continue;

        was_prv.assign(mt.size(), -1);
        swap(prv, was_prv);
        prv[i] = -2;
        go(mt[i]);

        int was_mask = mask;

        for(int ptr2 = ptr + 1; ptr2 < order.size() && mask != 15; ++ptr2) {
            int j = order[ptr2];
            if (mt[j] != -1 || prv[j] == -1) continue;
            int e2 = (e - rem[i] + rem[j] + 4) % 4;
            if ((1 << e2) & mask) continue;
            {
                int v = j;
                while (v != i) {
                    mt[v] = prv[v];
                    int u = mt[v];
                    swap(v, mt[u]);
                }
                mt[v] = -1;
            }
            rec(mask, e2, dmg - cost[i] + cost[j], ptr+1, depth+1);
            mask |= (1 << e2);
            {
                int v = j;
                int u = -1;
                while (v != i) {
                    swap(u, mt[v]);
                    v = save[u];
                    mt[u] = v;
                }
                mt[v] = u;
            }
        }
        swap(prv, was_prv);
        mask = was_mask;
    }
}

void solve() {
    cin >> n >> m;
    const int R = n + m;
    L = n * m;
    g.resize(L + R);
    cost.resize(L);
    rem.resize(L);

    rep(i, n) {
        rep(j, m) {
            int v = i * m + j;
            add_edge(v, L+i);
            add_edge(v, L+n+j);
            cin >> cost[v];
        }
    }
    rep(i, n) {
        rep(j, m) {
            int v = i * m + j;
            cin >> rem[v];
        }
    }
    mt.resize(L + R, -1);
    used.resize(L+R,-1);

    order.resize(L);
    iota(all(order), 0);
    sort(all(order), [&] (const int &i, const int &j) { return cost[i] > cost[j]; });

    ll dmg = 0;
    int e = 0;
    for(auto &i : order) {
        if (kuhn(i)) {
            T++;
            e = (e + rem[i]) % 4;
            dmg += cost[i];
        }
    }
    rep(i, 4) ans[i] = -INF;
    rec(0, e, dmg, 0);
    rep(i, 4) {
        cout << max(ans[i], -1ll) << '\n';
    }
}

