void dfs(int u)
{
	int i,v;sz[u]=1;sn[u]=0;
	for(i=head[u];i;i=e[i].nxt)
	{
		dfs(v=e[i].v);sz[u]+=sz[v];
		if(sz[sn[u]]<sz[v])sn[u]=v;
	}
}
void dfs2(int u,int s)
{
	int i,v;
	fm[dfn[u]=++cnt]=u;tp[u]=s;
	if(sn[u]){dfs2(sn[u],s);fa[sn[u]]=u;}
	for(i=head[u];i;i=e[i].nxt)
		if((v=e[i].v)!=sn[u])
			{fa[v]=u;dfs2(v,v);}
}
void up(int rt){tr[rt]=tr[rt<<1]+tr[rt<<1|1];}
void down(int rt){tr[rt<<1].upd(tr[rt]);tr[rt<<1|1].upd(tr[rt]);tr[rt].dl=0;tr[rt].in=inf;}
void mk(int l,int r,int rt)
{
	if(l==r){tr[rt]={0,c[fm[l]],c[fm[l]],0,inf};return;}
	int m=(l+r)>>1;mk(lson);mk(rson);up(rt);
}
void dl(int a,int b,ll c,int l,int r,int rt)
{
	if(a<=l&&r<=b)
	{
		tr[rt].upd({0,0,0,c,inf});
		return;
	}
	down(rt);
	int m=(l+r)>>1;
	if(a<=m)dl(a,b,c,lson);
	if(b>m)dl(a,b,c,rson);
	up(rt);
}
void dl(int u,ll w)
{
	while(u)
	{
		dl(dfn[tp[u]],dfn[u],w,1,n,1);
		u=fa[tp[u]];
	}
}

