    for (int i = 0; i < k; ++i) adv(ti, tj, i);
    jump[0][i * m + j] = ti * m + tj;
  }
  for (int l = 0; l < L - 1; ++l)
  for (int i = 0; i < n * m; ++i) jump[l + 1][i] = jump[l][jump[l][i]];
  solve(all, 0, L - 1);
  sort(merges.begin(), merges.end());
