using namespace std;

const int N = __builtin_pow(3, 9), i3 = -1u / 3 * 2 + 1;

using B = array<array<int, 3>, 3>;

bool chk(B g) {
  auto chk = [&](int a, int b, int c, int d) { return g[a][b] == g[a + c][b + d] && g[a][b] == g[a - c][b - d]; };
  return !(g[1][1] && (chk(1, 1, 0, 1) || chk(1, 1, 1, 1) || chk(1, 1, 1, -1) || chk(1, 1, 1, 0)) ||
      g[0][0] && (chk(0, 1, 0, 1) || chk(1, 0, 1, 0)) ||
      g[2][2] && (chk(2, 1, 0, 1) || chk(1, 2, 1, 0)));
}

struct ns {
  int n, s;

  int lo() { return 2 * n - s; }
  int hi() { return 2 * n + s; }
  ns operator-() { return {-n, s}; }
  ns operator+(ns oth) { return {n + oth.n, s ^ oth.s}; }
};

ns val[N];

void eval(B& g, int id) {
  int l = -1 << 30, r = 1 << 30;
  for (int p = N; auto& x: g) for (auto& x: x) if (p *= i3, !x) {
    x = 1;
    if (chk(g)) l = max(l, val[id + p].lo());
    x = -1;
    if (chk(g)) r = min(r, val[id - p].hi());
    x = 0;
  }
  if (l == r) val[id] = {l / 2, ~l & 1};
  else if (l < 0 && r > 0) val[id] = {};
  else if (l + 1 >> 11 != r - 1 >> 11) val[id] = {l < 0? r - 1 >> 1 & -1 << 10: l + 2048 >> 1 & -1 << 10};
  else {
    int b = 1 << 31 - __builtin_clz(l ^ r - 1);
    val[id] = {(l & -b | b) >> 1};
  }
  val[N - 1 - id] = -val[id];
}

void gen(B g, int i, int id) {
  if (i == 9) return eval(g, id);
  g[i / 3][i % 3] = 1;
  if (chk(g)) gen(g, i + 1, id * 3 + 2);
  g[i / 3][i % 3] = -1;
  if (chk(g) && id != N - 1 >> 1) gen(g, i + 1, id * 3);
  g[i / 3][i % 3] = 0;
  gen(g, i + 1, id * 3 + 1);
}

