using namespace std;

using fp = double;
using pt = array<fp, 2>;
struct ept: pt { int i; };

pt operator-(pt a, pt b) { return {a[0] - b[0], a[1] - b[1]}; }
pt operator+(pt a, pt b) { return {a[0] + b[0], a[1] + b[1]}; }
fp operator&(pt a, pt b) { return a[0] * b[0] + a[1] * b[1]; }
fp operator^(pt a, pt b) { return a[0] * b[1] - a[1] * b[0]; }
pt operator*(fp a, pt b) { return {a * b[0], a * b[1]}; }
pt rot(pt a) { return {-a[1], a[0]}; }
pt flip(pt a, pt b, pt c) { return a + 2 * (a - b ^ c - b) / (c - b & c - b) * rot(c - b); }
bool lis(pt a, pt b, pt c, pt d) { auto x = c - a ^ b - a, y = d - a ^ b - a; return x * y <= 0 || min(abs(x), abs(y)) * min(abs(x), abs(y)) / (b - a & b - a) < 1e-18; }
pt l2s(pt a, pt b, pt c, pt d) { pt t = a + (c - a ^ d - c) / (b - a ^ d - c) * (b - a); return (t - c & d - c) > (d - c & d - c)? d: (t - c & d - c) < 0? c: t; }

array<pt, 2> flip(vector<ept>& v, int i) {
  array<pt, 2> e{v[i], v[(i + 1) % v.size()]};
  for (auto& p: v) (pt&)p = flip(p, e[0], e[1]);
  return e;
}

int main() {
  int n; cin >> n;
  vector<ept> v(n), u;
  vector<array<pt, 2>> g;
  vector<pt> c, l, r;
  vector<int> ord(n);
  for (int i = 0; i < n; ++i) cin >> v[i][0] >> v[i][1], v[i].i = ord[i] = i;
  vector<fp> ans(n + 1);
  do {
    int mink = n - 1;
    while (mink && ord[mink] > ord[mink - 1]) --mink;
    u = v, g = {};
    for (int k = 0; ; ++k) {
      if (k >= mink) {
        c.assign(v.begin(), v.end());
        for (auto g: g)
        for (auto g: g) c.push_back(g);
        c.insert(c.end(), u.begin(), u.end());
        for (auto& a: c)
        for (auto& b: c) if (&b < &a) {
          bool ok = 1;
          for (auto& [c, d]: g) if (!lis(a, b, c, d)) { ok = 0; break; }
          if (!ok) continue;
          l = {}, r = {};
          for (pt d = v.back(); pt c: v) {
            if (lis(a, b, c, d)) l.push_back(l2s(a, b, c, d));
            d = c;
          }
          for (pt d = u.back(); pt c: u) {
            if (lis(a, b, c, d)) r.push_back(l2s(a, b, c, d));
            d = c;
          }
          for (auto a: l)
          for (auto b: r) ans[k] = max(ans[k], a - b & a - b);
        }
      }
      if (k == n) break;
      g.push_back(flip(u, ord[k]));
    }
  } while (next_permutation(ord.begin(), ord.end()));
  cout.precision(20);
  for (fp y{}; auto x: ans) cout << fixed << __builtin_sqrt(y = max(x, y)) << '\n';
}

