int main() {
  cin.tie(0)->sync_with_stdio(0);
  for (int tc = (cin >> tc, tc); tc--; ) {
    int n;
    int64_t p, s{}, cc{};
    cin >> n >> p;
    vector<array<int64_t, 4>> v(n);
    unordered_map<int, int> pen;
    for (auto& [a, b, c, d]: v) {
      cin >> a >> b >> c >> d; b = 2 * b + a, a = 2 * a - 3;
      if (pen[b] == -1) a = 0;
      else if (d) { s += a * c + a * p * pen[b], pen[b] = -1, cc += a; }
      else ++pen[b], a = 0;
    }
    v.erase(remove_if(v.begin(), v.end(), [](auto& a) { return !a[0]; }), v.end());
    if (s >= 0) ++s;
    else for (s = -s; auto& [a, b, c, d]: v) a = -a;
    vector<pt> f(v.size());
    if (int64_t s = 0, c = 0; 1)
    for (int i = v.size(); i--; ) {
      s += v[i][0] * v[i][2];
      c += v[i][0];
      f[i] = {v[i][2], v[i][2] * c - s};
    }
    f.erase(unique(f.begin(), f.end()), f.end());
    pt ans{(int64_t)1e18};
    if (!cc)
    for (int it: {1, 0}) {
      reverse(f.begin(), f.end());
      for (auto& p: f) p = pt{} - p;
      int sz{};
      for (int i = 0; i < f.size(); ++i) {
        while (sz && stv[sz - 1] >= f[i][1]) --sz;
        stv[sz] = f[i][1], sti[sz++] = i;
        int j = upper_bound(stv, stv + sz, f[i][1] - s) - stv - 1;
        if (!~j) continue;
        j = sti[j];
        if (f[i][1] <= f[i - 1][1]) continue;
        int64_t slack = f[i][1] - s - f[j][1], spi = i + 1 < f.size()? slope(f[i + 1] - f[i]): 0, smi = slope(f[i] - f[i - 1]), spj = slope(f[j + 1] - f[j]), dxmi = f[i][0] - f[i - 1][0], dxpj = f[j + 1][0] - f[j][0], dx = f[i][0] - f[j][0];
        ans = min(ans, {dx, it? -f[i][0]: f[j][0]});
        if (it && i + 1 < f.size() && spj > spi && spi > 0) {
          int64_t dl = min(dxpj, slack / spj), d = min({f[i + 1][0] - f[i][0], dxpj - dl, (slack - dl * spj) / (spj - spi)});
          ans = min(ans, {dx - dl, -f[i][0] - d});
        }
        if (!it && spj >= smi) {
          int64_t dr = min(dxmi, slack / smi);
          ans = min(ans, {dx - dr, f[j][0]});
        }
        if (!it && spj < smi) {
          int64_t dl = min(dxpj, slack / spj), d = min({dl, dxmi, (slack - dl * spj) / (smi - spj)});
          ans = min(ans, {dx - dl, f[j][0] + dl - d});
        }
        if (it && spj <= smi) {
          int64_t dl = min(dxpj, slack / spj);
          ans = min(ans, {dx - dl, -f[i][0]});
        }
        if (it && spj > smi) {
          int64_t dr = min(dxmi, slack / smi), d = min({dr, dxpj, (slack - dr * smi) / (spj - smi)});
          ans = min(ans, {dx - dr, -f[i][0] + dr - d});
        }
      }
    }
    if (ans[0] == 1e18) cout << "-1\n";
    else cout << ans[1] << ' ' << ans[0] + ans[1] << '\n';
  }
}

