int qmi(int a,int k)
{
    int res=1%mod2;
    while(k)
    {
        if(k&1) res=res*a%mod2;
        a=a*a%mod2;
        k>>=1;
    }
    return res%mod2;
}
const int gi=qmi(g,mod2-2);
void ntt(int* a,int inv)
{
