int C2(long long x,int k){
	int cj=id[k];
	for(int i=1;i<=k;++i)cj=(x-i+1+mod)%mod*cj%mod;
	return cj;
}
int CC(int n,int m){
	if(m==-1)return (n==-1);
	if(n<0||m<0||n<m)return 0;
	return 1ll*di[n]*id[m]%mod*id[n-m]%mod;
}
