		for(int i=0;i<=n;++i){
			if(i%2==0)hh=(hh+1ll*CC(n,i)*CC(h-i*(k+1)+n-1,n-1))%mod;
			else hh=(hh-1ll*CC(n,i)*CC(h-i*(k+1)+n-1,n-1))%mod;
		}
		hh=(hh+mod)%mod;
		ans=(ans-hh+mod)%mod;
	}
