	int head[4005],cnt,T,dis[4005],cur[4005];
	queue<int> q;
	inline void add(int x,int y,int f){
		d[cnt]=edge{head[x],y,f},head[x]=cnt++;
		d[cnt]=edge{head[y],x,f},head[y]=cnt++;
	}
	inline void init(){
		T=2*n+1,cnt=0;
		for(int i=0;i<=T;i++) head[i]=-1;
		for(int i=1;i<=n;i++) add(0,i,0);
		for(int i=1;i<=n;i++) add(i+n,T,0);
	}
	inline void reset(int p,int q){
		for(int i=0;i<n;i++) d[i<<1].flow=p,d[i<<1|1].flow=0,d[(i+n)<<1].flow=q,d[(i+n)<<1|1].flow=0;
		for(int i=n<<2;i<cnt;i+=2) d[i].flow=inf,d[i|1].flow=0;
	}
	inline bool bfs(){
		for(int i=0;i<=T;i++) dis[i]=-1,cur[i]=head[i];
		dis[T]=0,q.emplace(T);
		while(!q.empty()){
			int v=q.front();
			q.pop();
			for(int i=head[v];~i;i=d[i].ne) if(d[i^1].flow&&dis[d[i].to]==-1) dis[d[i].to]=dis[v]+1,q.emplace(d[i].to);
		}
		return ~dis[0];
	}
	int getflow(int v,int inflow){
		if(v==T) return inflow;
		int outflow=0,tmp;
		while(1){
			while(~cur[v]&&(!d[cur[v]].flow||dis[d[cur[v]].to]!=dis[v]-1)) cur[v]=d[cur[v]].ne;
			if(cur[v]==-1) return outflow;
			tmp=getflow(d[cur[v]].to,min(inflow-outflow,d[cur[v]].flow));
			d[cur[v]].flow-=tmp,d[cur[v]^1].flow+=tmp,outflow+=tmp;
			if(inflow==outflow) return inflow;
			cur[v]=d[cur[v]].ne;
		}
	}
	inline node work(int p,int q){
		reset(p,q);
		int res=0,cntl=0,cntr=0;
		while(bfs()) res+=getflow(0,inf);
		for(int i=1;i<=n;i++) cntl+=dis[i]==-1,cntr+=dis[i+n]==-1;
		return node{cntl,cntr};
	}
}
inline void solve(node l,node r){
	node tmp=network::work(r.y-l.y,r.x-l.x);
