#include<bits/stdc++.h>
using std::cin, std::cout;
int n, q;
struct func {
	int v, off;
	int at(int p) const { return p * v + off; }
};
const int N = 300005;
func m[N << 2];
int t[N << 2];
int min0[N << 2];
int min1[N << 2];
int max0[N << 2];
int max1[N << 2];
int max[N << 2];

void put(int x, func v, int l, int r) {
	m[x] = v;
	t[x] = 1;
	std::tie(min0[x], max0[x]) = std::minmax(v.at(l) - l, v.at(r) - r);
	std::tie(min1[x], max1[x]) = std::minmax(v.at(l) + l, v.at(r) + r);
	max[x] = std::max(v.at(l), v.at(r));
}
void update(int x) {
	min0[x] = std::min(min0[x << 1], min0[x << 1 | 1]);
	min1[x] = std::min(min1[x << 1], min1[x << 1 | 1]);
	max0[x] = std::max(max0[x << 1], max0[x << 1 | 1]);
	max1[x] = std::max(max1[x << 1], max1[x << 1 | 1]);
	max[x] = std::max(max[x << 1], max[x << 1 | 1]);
}
void down(int x, int l, int r) {
	if(t[x]) {
		int mid = (l + r) >> 1;
		put(x << 1, m[x], l, mid);
		put(x << 1 | 1, m[x], mid + 1, r);
		t[x] = 0;
	}
}
void apply(int ql, int qr, func v, int cur = 1, int l = 1, int r = n) {
	if(ql <= l && r <= qr) {
		// off vs a[p] - pos * v
		int min = v.v == 1 ? min0[cur] : min1[cur];
		int max = v.v == 1 ? max0[cur] : max1[cur];
		if(v.off <= min) return put(cur, v, l, r);
		if(v.off >= max) return ;
	}
	int mid = (l + r) >> 1;
	down(cur, l, r);
	if(ql <= mid) apply(ql, qr, v, cur << 1, l, mid);
	if(mid < qr) apply(ql, qr, v, cur << 1 | 1, mid + 1, r);
	update(cur);
}
int query(int ql, int qr, int cur = 1, int l = 1, int r = n) {
	if(ql <= l && r <= qr) {
		return max[cur];
	}
	int mid = (l + r) >> 1, ans = 0;
	down(cur, l, r);
	if(ql <= mid) ans = std::max(ans, query(ql, qr, cur << 1, l, mid));
	if(mid < qr) ans = std::max(ans, query(ql, qr, cur << 1 | 1, mid + 1, r));
	return ans;
}


int main() {
	std::ios::sync_with_stdio(false), cin.tie(0);
	cin >> n >> q;
	put(1, {0, int(1e9)}, 1, n);
	for(int i = 1;i <= q;++i) {
		int op, d, x, l, r;
		cin >> op;
		if(op == 1) {
			cin >> d >> x;
			if(d == 0) {
				apply(1, x, {-1, x});
			} else {
				apply(x, n, {1, -x});
			}
		} else {
			cin >> l >> r;
			int ans = query(l, r);
			if(ans > n) {
				ans = -1;
			}
			cout << ans << '\n';
		}
	}
}

