#include<bits/stdc++.h>
using namespace std;
#define PDI pair<double, int>

const int N = 310, M = 2 * N;
int n;
double f[N], g[N], ans;
struct tree
{
	int n, s;
	double dp[N], dp_f[N], dp_g[N], dp_ff[N], dp_gg[N];
	//level,probability and steps of reaching 1,probability and steps of reaching i(without 1)

	int h[N], ne[M], e[M], idx;
	void add(int a, int b)
	{
		e[++idx] = b, ne[idx] = h[a], h[a] = idx;
	}

	double f[N], g1[N], g2[N];//probability upward,steps upward,steps restart
	void dfs(int x, int fa)
	{
		f[x] = g1[x] = g2[x] = 0;
		if(dp[x] >= 0) return;

		int deg = 1;
		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa) dfs(e[i], x), deg++;
		if(!fa) return;

		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa)
			{
				f[x] += f[e[i]];
				g1[x] += f[e[i]] + g1[e[i]];
				g2[x] += 1 - f[e[i]] + g2[e[i]];
			}
		f[x] = 1 / (deg - f[x]);
		g2[x] = (g2[x] + g1[x] * (1 - f[x])) * f[x];
		g1[x] = (1 + g1[x] * f[x]) * f[x];
	}

	double maxn, ff, gg1, gg2;
	int maxid;
	void dfs1(int x, int fa, double f0, double g01, double g02)
	{
		if(dp[x] >= 0) return;
		if(fa)
		{
			g01 = g01 * f[x] + g1[x] * f0;
			g02 = g02 * f[x] + g1[x] * (1 - f0) + g2[x];
			f0 *= f[x];
		}

		double res = (g01 + g02) / f0;
		if(res > maxn) maxn = res, maxid = x;
		if(x == s) ff = f0, gg1 = g01, gg2 = g02;
		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa) dfs1(e[i], x, f0, g01, g02);
	}

	vector<int> rk;
	void init()
	{
		scanf("%d%d", &n, &s);
		for(int i = 1, a, b; i < n; i++)
			scanf("%d%d", &a, &b), add(a, b), add(b, a);

		for(int i = 1; i <= n; i++) dp[i] = -1;
		for(int i = 1; i < n; i++)
		{
			dfs(1, 0);
			maxn = -1, ff = gg1 = 0;
			dfs1(1, 0, 1, 0, 0);
			int rt = maxid;
			dp[rt] = maxn, dp_f[rt] = ff, dp_g[rt] = gg1;
			rk.push_back(rt);

			dfs(1, 0);
			ff = gg2 = 0;
			dfs1(1, 0, 1, 0, 0);
			dp_ff[rt] = 1 - ff, dp_gg[rt] = gg2;
		}
		// for(int i : rk) cout << i << ' ' << dp_f[i] << ' ' << dp_g[i] << ' ' << dp_ff[i] << ' ' << dp_gg[i] << endl;
	}
}tr[N];

