#include <bits/stdc++.h>

using i64 = long long;

void solve() {
	int n;
	std::cin >> n;

	std::string s;
	std::cin >> s;

	std::vector<std::vector<int>> adj(n);
	for (int i = 1; i < n; ++ i) {
		int u, v;
		std::cin >> u >> v;
		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	std::vector<std::set<std::array<int, 2>>> S(n);
	std::vector<int> c(n), val(n), ans(n, -1);

	auto dfs = [&](auto &self, int x, int p) -> void {
		if (x) {
			c[x] = c[p];
			val[x] = val[p];
		}
		if (s[x] == '0') {
			c[x]++;
			val[x]--;
		} else {
			c[x]--;
			val[x] += 3;
		}
		S[x].insert({c[x], val[x]});

		auto merge = [&](int y) -> void {
			if (S[x].size() < S[y].size()) {
				std::swap(S[x], S[y]);
			}
			for (auto [curc, curv] : S[y]) {
				auto it = S[x].lower_bound({c[x] + (x == 0 ? 0 : c[p]) - curc, -(1 << 30)});
				if (it != S[x].end()) {
					ans[x] = std::max(ans[x], (*it)[1] + curv - val[x] - (x == 0 ? 0 : val[p]));
				}
			}
			for (auto [curc, curv] : S[y]) {
				auto it = S[x].lower_bound({curc, -(1 << 30)});
				if (it != S[x].end() && (*it)[1] >= curv) {
					continue;
				} else {
					S[x].insert({curc, curv});	
				}
				it = S[x].lower_bound({curc, curv});
				while (it != S[x].begin() && (*prev(it))[1] <= curv) {
					S[x].erase(prev(it));
				}
			}
		};

		for (auto y : adj[x]) {
			if (y == p) {
				continue;
			}
			self(self, y, x);
			merge(y);
			S[y].clear();
		}
	};

	dfs(dfs, 0, -1);
	S[0].clear();
	c[0] = val[0] = 0;
	for (int i = 0; i < n; ++ i) {
		s[i] = '0' + '1' - s[i];
	}
	dfs(dfs, 0, -1);

	for (int i = 0; i < n; ++ i) {
		std::cout << ans[i] << '\n';
	}
}

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);

	int T;
	std::cin >> T;

	while (T --) {
		solve();
	}

	return 0;
}

