ll ksm(ll x,int b){
    ll s=1;
    while(b){
        if(b&1)
            s=s*x%M;
        b>>=1;
        x=x*x%M;
    }
    return s;
}
void NTT(ll *A,int L,int t){
    int i,j,k,x,y;
    ll w,w0;
    for(i=0;i<L;i++)
        if(R[i]>i)
            swap(A[i],A[R[i]]);
    for(i=1;i<L;i<<=1){
        w0=ksm(t==1?M0:M1,(M-1)/i/2);
        for(j=0;j<L;j+=i<<1){
            w=1;
            for(k=0;k<i;k++,w=w*w0%M){
                x=A[j+k];y=A[j+i+k]*w%M;
                A[j+k]=(x+y)%M;
                A[j+i+k]=(x-y)%M;
            }
        }
    }
    if(t==1)return;
    x=ksm(L,M-2);
    for(i=0;i<L;i++)
        A[i]=A[i]*x%M;
}
