    int h=d[i];pushdown(i);
    if(u<=mn[i<<1]&&v>=mx[i<<1])return (ull)u*v*(h+1>>1)+sol(i<<1|1,u,v);
    if(u>mn[i<<1]&&v<mx[i<<1])return sol(i<<1,u,v)+cf[i];
    if(u<=mn[i<<1]&&v<mx[i<<1])return (ull)u*sol_mx(i<<1,v)+sol(i<<1|1,u,mx[i<<1]);
    return (ull)v*sol_mn(i<<1,u)+sol(i<<1|1,mn[i<<1],v);
