int qmi(int a,int k,int p){
    int res=1;
    while(k){
        if(k&1) res=res*a%p;
        a=a*a%p;
        k>>=1;
    }
    return res;
}
void NTT(poly &A,int len,int sgn){
    for(int i=0;i<len;i++) if(i<r[i]) swap(A[i],A[r[i]]);
    for(int mid=1;mid<len;mid<<=1){
        int Wn=qmi((sgn==1)?G:Gi,(mod-1)/mid/2,mod);
        for(int siz=mid<<1,i=0;i<len;i+=siz){
            for(int j=0,I=1;j<mid;j++,I=I*Wn%mod){
                int p=A[j+i],q=I*A[j+i+mid];
                A[j+i]=(p+q)%mod;
                A[j+i+mid]=(p-q+mod)%mod;
            }
        }
    }
    if(sgn==-1) for(int i=0,inv=qmi(len,mod-2,mod);i<len;i++) A[i]=A[i]*inv%mod;
}
poly &operator+=(poly &A,const poly &B){
    A.resize(max(A.size(),B.size()));
    for(int i=0;i<A.size()&&i<B.size();i++) A[i]=(A[i]+B[i])%mod;
    return A;
}
poly operator*(poly A,poly B){
    if(!A.size()||!B.size()){
        return {};
    }
    int n=A.size()+B.size();
    int len=1;
    while(len<n) len<<=1;
    A.resize(len),B.resize(len);
    for(int i=1;i<len;i++) r[i]=(r[i>>1]>>1)|((i&1)?(len>>1):0);
    NTT(A,len,1),NTT(B,len,1);
    for(int i=0;i<len;i++) A[i]=A[i]*B[i]%mod;
    NTT(A,len,-1);
    while(A.size()&&!A.back()) A.pop_back();
    return A;
}
poly operator*(poly A,int b){
    for(int i=0;i<A.size();i++) A[i]=A[i]*b%mod;
    return A;
}
Node solve(int l,int r){
    if(l==r){
        Node cur={};
