int chk(int x,int y)
{
	int p[3]={0,1,2};
	if(ct[0]+ct[1]+ct[2]==0)return x!=y;
	sort(p,p+3,[](int x,int y){return ct[x]<ct[y];});
	int w=ct[p[0]]+ct[p[1]]+1-ct[p[2]];
	if(w<0)return 0;
	if(w==0)return x!=p[2]&&y!=p[2];
	if(ct[p[0]]==0)return (x!=p[1]&&y!=p[2])||(x!=p[2]&&y!=p[1]);
	if(w==1)return x!=p[2]||y!=p[2];
	return 1;
}
