void gt(int x,int y)
{
	for(int i=0;i<3;++i)
		if(y!=i&&ct[i])
		{
			--ct[i];
			if(chk(x,i))
			{gt(x,i);o.push_back(i);return;}
			++ct[i];
		}
	return;
}

