int n,top,stk[N];
poly p;
ld ans=inf;

ld convexchecker(poly &p){
	sort(p.begin(),p.end());
	p.erase(unique(p.begin(),p.end()),p.end());
	int n=(int)p.size();
	poly q;
	stk[top=1]=0;
	for(int i=1;i<n;i++){
		while(top>1&&((p[i]-p[stk[top]])^(p[stk[top]]-p[stk[top-1]]))>0)top--;
		stk[++top]=i;
	}
	for(int i=1;i<=top;i++)
		q.pb(p[stk[i]]);
	stk[top=1]=0;
	for(int i=1;i<n;i++){
		while(top>1&&((p[i]-p[stk[top]])^(p[stk[top]]-p[stk[top-1]]))<0)top--;
		stk[++top]=i;
	}
	for(int i=top-1;i>1;i--)
		q.pb(p[stk[i]]);
	if(p.size()^q.size())return 2e50;
	ld res=0;
	for(int i=0;i<n;i++)
		res+=q[i]^q[(i+1)%n];
	return res;
}

