#define mid (l+r)/2
void add(int &u,int v,int l,int r,int p,int val)
{
	u=++tot;t[u]=t[v];
	t[u].sum+=val;
	if(l==r)
		return;
	if(p<=mid)add(t[u].ls,t[v].ls,l,mid,p,val);
	else add(t[u].rs,t[v].rs,mid+1,r,p,val);
}
void merge(int &u,int v)
{
	if(!v)return;
	if(!u)
	{
		u=v; 
		return;
	}
	int x=++tot;
	t[x]=t[u]; 
	t[x].sum+=t[v].sum;
	merge(t[x].ls,t[v].ls);
	merge(t[x].rs,t[v].rs);
	u=x;
}
int qry(int u,int v,int l,int r)
{
	if(l==r)return l;
	int x=t[t[u].ls].sum-t[t[v].ls].sum;
	if(x>=k2)return qry(t[u].ls,t[v].ls,l,mid);
	else 
	{
		k2-=x;
		return qry(t[u].rs,t[v].rs,mid+1,r);
	}
}
