int ksm(int a,int b=p-2){
	int ans=1;
	for(;b;b>>=1,a=a*a%p) if(b&1) ans=ans*a%p;
	return ans;
}
void NTT(int *a,int len,int tp){
	for(int i=0;i<len;i++) if(i<r[i]) swap(a[i],a[r[i]]);
	for(int mid=1,c=1;mid<len;mid<<=1,c++){
		int wn=(tp?yy[c]:nyy[c]);
		for(int j=0,R=mid<<1;j<len;j+=R){
			for(int k=0,w=1;k<mid;k++,w=w*wn%p){
				int x=a[j+k],y=a[j+k+mid]*w%p;
				a[j+k]=(x+y)%p;
				a[j+k+mid]=(x+p-y)%p;
			}
		}
	}
	if(tp) return;
	int iv=ksm(len);
	for(int i=0;i<len;i++) a[i]=a[i]*iv%p;
}
int h[N];
void invv(int *f,int *g,int len){
	if(len==1) return g[0]=ksm(f[0]),void();
	invv(f,g,(len+1)>>1);
	int m=len<<1;
	int limit,l;
	for(limit=1,l=0;limit<m;limit<<=1,l++);
	for(int i=1;i<limit;i++) r[i]=(r[i>>1]>>1)|((i&1)<<(l-1));
	for(int i=0;i<len;i++) h[i]=f[i];
	for(int i=len;i<limit;i++) h[i]=0;
	NTT(h,limit,1),NTT(g,limit,1);
	for(int i=0;i<limit;i++) g[i]=(2-h[i]*g[i]%p+p)%p*g[i]%p;
	NTT(g,limit,0);
	for(int i=len;i<limit;i++) g[i]=0;
}
void mul(int *f,int *g,int n,int m){
	int limit,l;
	for(limit=1,l=0;limit<n+m;limit<<=1,l++);
	for(int i=1;i<limit;i++) r[i]=(r[i>>1]>>1)|((i&1)<<(l-1));
	NTT(f,limit,1),NTT(g,limit,1);
	for(int i=0;i<limit;i++) f[i]=f[i]*g[i]%p;
	NTT(f,limit,0),NTT(g,limit,0);
}
