using namespace std;
typedef long long ll;

constexpr int D = 14; // (n/14) x 14 grid

array<int, 2> edge[4040];
int col[4040], chk[4040];
int cnt_eq[1616], cnt_col[1616], cnt_v[1616];

vector<array<int, 3>> operator + (const vector<array<int, 3>> &A, const vector<array<int, 3>> &B){
    vector<array<int, 3>> ret = A;
    ret.insert(ret.end(), B.begin(), B.end());
    return ret;
}

vector<array<int, 3>> rev(vector<array<int, 3>> A){
    reverse(A.begin(), A.end());
    return A;
}

void go(vector<array<int, 3>> &A, char axis, int val, char op){
    assert(!A.empty());
    A.push_back(A.back());

    int idx = axis - 'x';
    if (op=='+') A.back()[idx] += val;
    else A.back()[idx] = val;
}

vector<array<int, 3>> pull(int v, int z){
    vector<array<int, 3>> ret = {{(v/D + 1) * 3, (v%D + 1) * 5, 0}};
    cnt_v[v]++;

    if (cnt_v[v]==2) go(ret, 'y', 1, '+');
    if (cnt_v[v]==3) go(ret, 'y', -1, '+');
    if (cnt_v[v]==4){go(ret, 'x', 1, '+'); go(ret, 'y', 2, '+'); go(ret, 'x', -1, '+');}
    if (cnt_v[v]==5){go(ret, 'x', -1, '+'); go(ret, 'y', -2, '+'); go(ret, 'x', 1, '+');}

    go(ret, 'z', z, '+');
    return ret;
}

vector<array<int, 3>> connect(int e){
    auto [u, v] = edge[e];

    if (u/D == v/D){
        int z = ++cnt_eq[u/D];
        auto A = pull(u, z), B = pull(v, z);

        go(A, 'x', 1, '+');
        go(B, 'x', 1, '+');

        return A + rev(B);
    }

    fill(chk+1, chk+D*10, 0);
    for (int i=1;i<e;i++){
        auto [u2, v2] = edge[i];
        if (u2/D == u/D || u2/D == v/D || v2/D == u/D || v2/D == v/D){
            chk[col[i]] = 1;
        }
    }

    for (int i=1;i<=D*10;i++) if (!chk[i]){
        col[e] = i;
        cnt_col[i]++;
        break;
    }

    assert(col[e]);

    int y = (D+1)*5 + cnt_col[col[e]];
    int z = col[e] * 2 - 1;
    auto A = pull(u, z), B = pull(v, z);

    go(A, 'x', -1, '+'); 
    go(A, 'y', y, '=');
    go(A, 'z', 1, '+');

    go(B, 'x', -1, '+'); 
    go(B, 'y', y, '=');
    go(B, 'z', 1, '+');

    return A + rev(B);
}

