	node res{};
	rep(k,0,2){
		res.to[k]=a.to[b.to[k]];
		res.sum[k]=(a.sum[b.to[k]]+b.sum[k]*a.pw)%mod;
	}
	res.pw=a.pw*b.pw%mod;
	return res;
}
