#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll inf=4e18;
const ll N=2e9;
struct LCC{
	ll k[5000005],b[5000005];
	int c[5000005][2],t[5000005],tot,totp,rt;
	ll calc(int i,ll x) {
		if(!i)return inf;
		return k[i]*x+b[i];
	}
	void Modify(int &p,ll l,ll r,ll z) {
		if(!p)p=++totp;
		if(calc(t[p],l)<=calc(z,l)&&calc(t[p],r)<=calc(z,r))return ;
		if(calc(t[p],l)>=calc(z,l)&&calc(t[p],r)>=calc(z,r)) {
			t[p]=z;
			return ;
		}
		ll mid=(l+r)/2;
		if(k[t[p]]>k[z]) {
			if(calc(t[p],mid)>calc(z,mid))Modify(c[p][0],l,mid,t[p]),t[p]=z;
			else Modify(c[p][1],mid+1,r,z);
		} else {
			if(calc(t[p],mid)>calc(z,mid))Modify(c[p][1],mid+1,r,t[p]),t[p]=z;
			else Modify(c[p][0],l,mid,z);
		}
	}
	ll Getans(int p,ll l,ll r,ll x) {
		if(!t[p])return inf;
		ll ret=calc(t[p],x);
		if(l==r)return ret;
		ll mid=(l+r)/2;
		if(x<=mid)ret=min(ret,Getans(c[p][0],l,mid,x));
		else ret=min(ret,Getans(c[p][1],mid+1,r,x));
		return ret;
	}
	void clear(){
		tot=0;
		for(int i=1;i<=totp;i++)t[i]=c[i][0]=c[i][1]=0;
		totp=rt=0;
	}
	void insert(ll kk,ll bb){
		++tot;
		k[tot]=kk,b[tot]=bb;
		Modify(rt,1,N,tot);
	}
	ll get(ll x){
		return Getans(rt,1,N,x);
	}
}lcc;
int n,m,q,a[100005],b[100005],ra[100005],rb[100005];
ll f[100005];
ll ans[100005],qu[100005];
int st[100005],quids[100005];
void Solve(){
	// case 1: left to m
	lcc.clear();
	for(int i=1;i<=m;i++)if(a[i]<=a[m])lcc.insert(b[i],-1ll*a[i]*b[i]);
	for(int i=1;i<=q;i++)if(qu[i]>a[m])ans[i]=min(ans[i],lcc.get(2*qu[i]-a[m]));
	//cout<<ans[1]<<'\n';

	// case 2: between m and query pos
	lcc.clear();
	map<int,int> mnb;
	for(int i=1;i<=m;i++)
		if(a[i]>=a[m]){
			if(!mnb.count(a[i])){
				mnb[a[i]]=b[i];
			}
			else mnb[a[i]]=min(mnb[a[i]],b[i]);
		}
	int tot=0;
	for(auto [x,y]:mnb)ra[++tot]=x,rb[tot]=y;
	assert(ra[1]==a[m]);
	f[1]=0;
	lcc.insert(-a[m],f[1]);
	for(int i=2;i<=tot;i++){
		f[i]=lcc.get(rb[i])+1ll*rb[i]*ra[i];
		lcc.insert(-ra[i],f[i]);
		//cout<<i<<' '<<ra[i]<<' '<<rb[i]<<' '<<f[i]<<'\n';
	}
	lcc.clear();
	int rq=0;
	//cout<<a[m]<<' '<<qu[1]<<' '<<rq<<'\n';
	for(int i=1;i<=q;i++)if(qu[i]>a[m])quids[++rq]=i;
	sort(quids+1,quids+rq+1,[](int x,int y){return qu[x]<qu[y];});
	for(int i=1,o=1;i<=rq;i++){
		while(o<=tot&&ra[o]<=qu[quids[i]]){
			lcc.insert(rb[o],f[o]-2ll*ra[o]*rb[o]);
			o++;
		}
		ans[quids[i]]=min(ans[quids[i]],lcc.get(2*qu[quids[i]]));
	}
	//cout<<ans[1]<<'\n';

	// case 3: right to pos
	ll mn=inf;
	for(int i=rq,o=tot;i>=1;i--){
		//cout<<qu[quids[i]]<<' '<<ra[o]<<'\n';
		while(o>=1&&ra[o]>=qu[quids[i]]){
			mn=min(mn,f[o]);
			o--;
		}
		ans[quids[i]]=min(ans[quids[i]],mn);
	}
	//cout<<ans[1]<<'\n';
}
int main(){
	scanf("%d%d%d",&n,&m,&q);
	for(int i=1;i<=m;i++)scanf("%d%d",&a[i],&b[i]);
	for(int i=1;i<=q;i++){
		scanf("%lld",&qu[i]);
		ans[i]=1ll*abs(qu[i]-a[m])*b[m];
	}
	Solve();
	//return 0;
	for(int i=1;i<=m;i++)a[i]=n-a[i]+1;
	for(int i=1;i<=q;i++)qu[i]=n-qu[i]+1;
	Solve();
	for(int i=1;i<=q;i++)cout<<ans[i]<<'\n';
}

