using namespace std;
typedef long long ll;
const double eps=1e-9;
ll Calc(int n,ll v){
	ll ans=0;
	if(v%100==0){
		v/=100;
		for(int i=0;i*i<=v;i++){
			int u=v-i*i;
			int j=round(sqrt(u));
			if(i>j)continue;
			if(j*j==u){
				if(i+j<n)return -1;
			}
		}
		v*=100;
	}
	// 1. centered at a point
	// 1.1 upper is ---
	for(int i=1;i<=n&&200ll*i*i<=v;i++){
		int j=ceil(sqrt(v/200.0-i*i));
		ans+=max(n-2*max(i,j)+1,0)*max(n-2*max(i,j)+1,0);
	}
	// 1.2 upper is |
	for(int i=0;i<=n&&200ll*i*i<v;i++){
		int j=ceil(sqrt(v/200.0-i*i));
		if(200ll*i*i+200ll*j*j==v)continue;
		ans+=max(n-2*max(i,j)+1,0)*max(n-2*max(i,j)+1,0);
	}
	// 2. centered at (.5, .5)
	// 2.1 --- and 2.2 |
	for(int i=0;i<=n&&200ll*(i+0.5)*(i+0.5)<=v;i++){
		int j=ceil(sqrt(v/200.0-(i+0.5)*(i+0.5))-0.5);
		ans+=max(n-2*max(i,j),0)*max(n-2*max(i,j),0);
		if(fabs((i+0.5)*(i+0.5)+(j+0.5)*(j+0.5)-v/200.0)>eps&&fabs((i+0.5)*(i+0.5)-v/200.0)>eps){
			ans+=max(n-2*max(i,j),0)*max(n-2*max(i,j),0);
		}
	}
	return ans;
}
