				dis[v]=dis[u]+w;
				if(!vis[v])q.emplace(-dis[v],v);
			}
		}
	}
}
void dijk2(int s,loli *dis){
	memset(vis+1,0,sizeof(int)*n);
	for(int i=1;i<=n;i++)dis[i]=inf;
	q.emplace(dis[s]=0,s);
	for(int v:g[s])q.emplace(dis[v]=0,v);
	while(!q.empty()){
		int u=q.top().se;q.pop();
		if(vis[u])continue;else vis[u]=1;
		for(int v:g[u]){
			loli w=sqr(h[u]-h[v]);
			if(dis[v]>dis[u]+w){
				dis[v]=dis[u]+w;
				if(!vis[v])q.emplace(-dis[v],v);
			}
		}
	}
}
