}t[N*12];
int n,q,rt[4],x,y,tot;
ull pw1[N],pw2[N];
char s1[N],s2[N],s3[N];
void up(int i){
    int l=t[i].ls, r=t[i].rs;
    t[i].h1=add1(t[l].h1*pw1[t[r].len]%Mod1,t[r].h1);
    t[i].h2=add2(t[l].h2*pw2[t[r].len]%Mod2,t[r].h2);
}
void build(char s[],int l,int r,int &i){
    if(!i) i=++tot;
    if(l==r) return t[i]={(ull)s[l]-'a',(ull)s[l]-'a',0,0,1}, void();
    t[i].len=r-l+1;
    build(s,l,mid,t[i].ls), build(s,mid+1,r,t[i].rs);
    up(i);
}
int cmp(int p,int q,int l,int r,int x,int y){
    if(p<=l&&r<=q){
        if(l==r) return t[x].h1>t[y].h1?1:(t[x].h1<t[y].h1?-1:0);
        if(t[t[x].ls].h1==t[t[y].ls].h1&&t[t[x].ls].h2==t[t[y].ls].h2) return cmp(p,q,mid+1,r,t[x].rs,t[y].rs);
        return cmp(p,q,l,mid,t[x].ls,t[y].ls);
    }
    int res=0;
    if(p<=mid) res=cmp(p,q,l,mid,t[x].ls,t[y].ls);
    if(res==0&&q>mid) res=cmp(p,q,mid+1,r,t[x].rs,t[y].rs);
    return res; 
}
void swp(int p,int q,int l,int r,int &x,int &y){
    if(p<=l&&r<=q) return swap(x,y), void();
    if(p<=mid) swp(p,q,l,mid,t[x].ls,t[y].ls);
    if(q>mid) swp(p,q,mid+1,r,t[x].rs,t[y].rs);
    up(x), up(y);
}
