	void init(int x){for(x+=n+1;x<=2*n+2;x+=x&-x)d[x]=inf;}
	void upd(int x,int y){for(x+=n+1;x<=2*n+2;x+=x&-x)d[x]=min(d[x],y);}
	int ask(int x){int y=inf;for(x+=n+1;x;x-=x&-x)y=min(y,d[x]);return y;}
}tr;
struct node{
	int y,z,w;
	friend bool operator<(const node&t1,const node&t2){
		if(t1.y!=t2.y)return t1.y<t2.y;
		return t1.z<t2.z;
	}
};
vector<node>v[N];
void CDQ(int l,int r){
	if(l==r)return;
	int d=(l+r)/2;
	map<int,vector<node>>mp;
	for(int i=l;i<=d;i++)for(auto[y,z,w]:v[i])mp[y].emplace_back(1,z,w);
	for(int i=d+1;i<=r;i++)for(auto[y,z,w]:v[i])mp[y].emplace_back(0,z,w);
	for(auto&[y,it]:mp){
		sort(all(it));
		// cerr<<"now "<<y<<'\n';
		for(auto[id,z,w]:it){
			// cerr<<id<<' '<<z<<' '<<w<<'\n';
			if(id)tr.upd(z,w);
			else ans=max(ans,w-tr.ask(z-1));
		}
	}
	// cerr<<"========\n";
	// cerr<<"ans "<<ans<<'\n';
	for(int i=l;i<=d;i++)for(auto[y,z,w]:v[i])tr.init(z);
	CDQ(l,d);CDQ(d+1,r);
}
int solve(int x,int y1,int y2,int y3){
	for(int i=0;i<=2*n+2;i++)v[i].clear();
	v[n+1].emplace_back(0,0,0);
	for(int i=1;i<=n;i++){
		s1[i]=s1[i-1]+(a[i]==x)-(a[i]==y1);
		s2[i]=s2[i-1]+(a[i]==x)-(a[i]==y2);
		s3[i]=s3[i-1]+(a[i]==x)-(a[i]==y3);
		v[s1[i]+n+1].emplace_back(s2[i],s3[i],i);
	}
	ans=0;
	CDQ(0,2*n+2);
	return ans;
}
