                for (int di = 2; di >= 0; --di) {
                    for (int dj = 2; dj >= 0; --dj) {
                        if (secret[di][dj]) {
                            g[i+di][j+dj] = 1;
                            goto placed;
                        }
                    }
                }
                placed:;
            }
        }
        auto [status2, _] = ask(g);
        assert(status2);
    }
}

