void upd(int l,int r,int xx,int val,int ind){
    if(l==r){
        sum[ind]+=val;
        seg[ind]=sum[ind];
        sl[ind]=seg[ind],sr[ind]=seg[ind];
        return;
    }
    int mid=l+r>>1;

    if(xx<=mid) upd(l,mid,xx,val,ind*2);
    else upd(mid+1,r,xx,val,ind*2+1);
    sum[ind]=sum[ind*2]+sum[ind*2+1];
    sl[ind]=max(sl[ind*2],sum[ind*2]+sl[ind*2+1]);
    sr[ind]=max(sr[ind*2+1],sum[ind*2+1]+sr[ind*2]);
    seg[ind]=max({sr[ind*2]+sl[ind*2+1],seg[ind*2],seg[ind*2+1],sl[ind],sr[ind]});
}
int now_r, now_seg;
void val(int l,int r,int l1,int r1,int ind){
