    int mid=l+r>>1;
    if(r1<=mid) val(l,mid,l1,r1,ind*2);
    else if(l1>mid) val(mid+1,r,l1,r1,ind*2+1);
    else val(l,mid,l1,r1,ind*2),val(mid+1,r,l1,r1,ind*2+1);
}

