#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

constexpr ll INF = 1e18;

struct Seg{
	ll tree[1601600], lazy[1601600];
	int sz;

	void init(int n){
		sz = n;
		fill(tree, tree+sz*4, INF);
	}

	void propagate(int i, int l, int r){
		tree[i] += lazy[i];
		if (l!=r){
			lazy[i<<1] += lazy[i];
			lazy[i<<1|1] += lazy[i];
		}
		lazy[i] = 0;
	}

	void update(int i, int l, int r, int s, int e, ll x){
		propagate(i, l, r);
		if (r<s || e<l) return;
		if (s<=l && r<=e){
			lazy[i] += x;
			propagate(i, l, r);
			return;
		}

		int m = (l+r)>>1;
		update(i<<1, l, m, s, e, x);
		update(i<<1|1, m+1, r, s, e, x);
		tree[i] = min(tree[i<<1], tree[i<<1|1]);
	}

	void set(int i, int l, int r, int p, ll x){
		propagate(i, l, r);
		if (r<p || p<l) return;
		if (l==r){
			tree[i] = min(tree[i], x);
			return;
		}

		int m = (l+r)>>1;
		set(i<<1, l, m, p, x);
		set(i<<1|1, m+1, r, p, x);
		tree[i] = min(tree[i<<1], tree[i<<1|1]);
	}

	ll query(int i, int l, int r, int s, int e){
		propagate(i, l, r);
		if (r<s || e<l) return INF;
		if (s<=l && r<=e) return tree[i];

		int m = (l+r)>>1;
		return min(query(i<<1, l, m, s, e), query(i<<1|1, m+1, r, s, e));
	}

	void update(int l, int r, ll x){
		update(1, 1, sz, l, r, x);
	}

	void set(int p, ll x){
		set(1, 1, sz, p, x);
	}

	ll query(int l, int r){
		return query(1, 1, sz, l, r);
	}
}tree;

int a[200200];
ll sum[200200], dp[200200][2];

int main(){
	int n, d, s, f, w;
	scanf("%d %d %d %d %d", &n, &d, &s, &f, &w);

	for (int i=1;i<=n;i++) scanf("%d", a+i);

	vector<ll> C;
	for (int i=1;i<=n;i++){
		sum[i] = sum[i-1] + a[i];
		C.push_back(sum[i-1]-(ll)d*i);
		C.push_back(sum[i]-(ll)d*i);
	}

	sort(C.begin(), C.end());
	C.erase(unique(C.begin(), C.end()), C.end());

	auto getidx = [&](ll x){
		return upper_bound(C.begin(), C.end(), x) - C.begin(); 
	};

	tree.init(C.size());
	tree.set(getidx(-d), 0);

	for (int i=1;i<n;i++){
		dp[i+1][0] = tree.query(1, getidx(sum[i]-(ll)d*i-1)) + f;
		dp[i+1][1] = tree.query(1, getidx(sum[i+1]-(ll)d*i-1)) + f + w*2;

		tree.update(1, C.size(), s);
		tree.update(getidx(sum[i]-(ll)d*(i+1))+1, C.size(), w*2);

		tree.set(getidx(sum[i]-(ll)d*(i+1)), dp[i+1][0]);
