#define mod 998244353

using namespace std;
const int inv2 = (mod + 1) / 2;
int n, P[2][M], pw[M], L[M], R[M], stk[M], top, ans, pre[M];
void get(int op)
{
	for(int i = 1; i <= n; i++)
	{
		// cout << L[i] << " " << R[i] << endl;
		if(L[i] == -1 || R[i] == -1) continue;
		int l = pre[i - L[i] + 1];
		if(L[i] == 1) l = (l + pw[i - L[i] + 1]) % mod;
		else l = (l + pw[i - L[i] + 2]) % mod;
		int r = pre[R[i] - i + 1];
		if(R[i] == n) r = (r + pw[R[i] - i + 1]) % mod;
		else r = (r + pw[R[i] - i + 2]) % mod;
		// cout << "ASD: " << l << " " << r << endl;
		ans = (ans + l * r * 2 % mod * P[0][i] % mod * op % mod) % mod;
		ans = (ans % mod + mod) % mod;
	}
}
void calc()
{
	P[0][0] = 1e18;
	stk[top = 1] = 0;
	for(int i = 1; i <= n; i++)
	{
		while(P[0][stk[top]] <= P[0][i]) top--;
		L[i] = stk[top] + 1;
		stk[++top] = i;
	}
	P[0][n + 1] = 1e18;
	stk[top = 1] = n + 1;
	for(int i = n; i >= 1; i--)
	{
		while(P[0][stk[top]] < P[0][i]) top--;
		R[i] = stk[top] - 1;
		stk[++top] = i;
	}
	get(1);
	stk[top = 1] = 1;
	for(int i = 1; i <= n; i++)
	{
		while(max(P[0][stk[top]], P[1][stk[top]]) <= P[0][i]) top--;
		if(P[0][i] >= P[1][i]) L[i] = stk[top] + 1;
		else L[i] = -1;
		stk[++top] = i;
	}
	stk[top = 1] = n + 1;
	for(int i = n; i >= 1; i--)
	{
		while(P[0][stk[top]] < P[0][i] && P[1][stk[top]] <= P[0][i]) top--;
		if(P[0][i] >= P[1][i]) R[i] = stk[top] - 1;
		else R[i] = -1;
		stk[++top] = i;
	}
	get(-1);
	P[0][0] = P[0][n + 1] = 0;
}
signed main()
{
	scanf("%lld", &n);
	pw[0] = 1;
	for(int i = 1; i <= n; i++) pw[i] = pw[i - 1] * inv2 % mod;
	for(int i = 2; i <= n; i++) pre[i] = (pre[i - 1] + pw[i]) % mod;
	for(int i = 1; i <= n; i++) scanf("%lld", &P[0][i]);
	for(int i = 1; i <= n; i++) scanf("%lld", &P[1][i]);
	calc();
	for(int i = 1; i <= n; i++) swap(P[0][i], P[1][i]);
	calc();
	printf("%lld\n", ans);
