#define N 200005
#define ll long long
#define mod 998244353
using namespace std;
int n,f[N];
int v[N],p[N],mu[N],cp;
void shai(int n){
	mu[1]=1;
	for(int i=2;i<=n;i++){
		if(!v[i]) v[i]=p[++cp]=i,mu[i]=-1;
		for(int j=1;j<=cp&&i*p[j]<=n;j++){
			if(v[i]<p[j]) break;
			v[i*p[j]]=p[j];
			if(i%p[j]==0) mu[i*p[j]]=0;
			else mu[i*p[j]]=-mu[i];
		}
	}
}
ll pw2[N],pw3[N];
ll gcd(ll a,ll b){
	return b?gcd(b,a%b):a;
}
ll calc(int k){
	ll ans=0;
	for(int j=1;j*k<=n;j++) ans=(ans+mu[j]*(pw2[f[j*k]]-1))%mod;
	ans=ans*ans%mod;
	for(int i=1;i*k<=n;i++){
		for(int j=1;j*i*k<=n;j++){
			if(gcd(i,j)>1) continue;
			for(int d=1;d*i*j*k<=n;d++)
				ans=(ans+mu[d*i]*mu[d*j]*(pw3[f[d*i*j*k]]*pw2[f[d*i*k]+f[d*j*k]-2*f[d*i*j*k]]-pw2[f[d*i*k]]*pw2[f[d*j*k]])%mod+mod)%mod;
		}
	}
	return ans;
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		int x;
		scanf("%d",&x);
		f[x]++;
	}
	for(int i=1;i<=n;i++)
		for(int j=i*2;j<=n;j+=i)
			f[i]+=f[j];
	shai(n);
	pw2[0]=pw3[0]=1;
	for(int i=1;i<=n;i++){
		pw2[i]=pw2[i-1]*2%mod;
		pw3[i]=pw3[i-1]*3%mod;
	}
	ll ans=0;
	for(int i=1;i<=n;i++) ans=(ans+i*calc(i))%mod;
	printf("%lld\n",ans);
	return 0;
}

