typedef long long ll;

vector<int> ans;
vector<pair<int, int>> edges;

void fuck(int cur, int x){
	edges.emplace_back(cur, cur+1);
	edges.emplace_back(cur, cur+2);

	for (int i=cur+2;i<=cur+x-2;i++){
		edges.emplace_back(i, cur+1);
		if (i < cur+x-2) edges.emplace_back(i, i+1);
	}

	edges.emplace_back(cur+1, cur+x-1);
}

bool build(int rem){
	if (rem % 2 == 1 && rem < 11) return false;
	if (rem == 0) return true;

	int x = sqrt(rem);
	x += 2;

	for (;x>=4;x--) if (rem >= x*x - 5){
		ans.push_back(x);
		if (build(rem - x*x + 5)) return true;
		ans.pop_back();
	}

	ans.push_back(1);
	if (build(rem - 2)) return true;
	return false;
}

