	int k;
	scanf("%d", &k);

	if (k % 2 == 1 && k < 11){
		printf("-1 -1\n");
		return 0;
	}

	assert(build(k));

	int cur = 1;
	for (auto &x:ans){
		if (x >= 4){
			fuck(cur, x);
			cur += x-1;
		}
		else{
			edges.emplace_back(cur, cur+1);
			cur += 1;
		}
	}

	printf("%d %d\n", cur, (int)edges.size());
	for (auto &[x, y]:edges) printf("%d %d\n", x, y);
}

