i64 f1(int, int);
i64 f2(int, int);

i64 f1(int l, int r) {
    assert(0 <= l && l <= r && r <= N);
    if (l == r)
        return 1;
    auto &ret = dp1[l][r];
    if (~ret)
        return ret;
    ret = f2(l + 1, r);
    return ret;
}

i64 f2(int l, int r) {
    assert(0 <= l && l <= r && r <= N);
    if (l == r)
        return 1;
    auto &ret = dp2[l][r];
    if (~ret)
        return ret;
    ret = 0;
    auto cnt = 0;
    for (auto i = l; i < r; ++i) {
        cnt += int(A[l] < A[i]);
        if (i + 1 == r || A[l] < A[i + 1]) {
            ret += f1(l, i + 1) * pow2[cnt] % MOD * f2(i + 1, r) % MOD;
            ret %= MOD;
        }
    }
    return ret;
}

