const int SZ = 202020;
const int INF = (int)1e9 + 10;
struct Seg {
	int tree[4 * SZ];
	void init() {
		fill(tree, tree + 4 * SZ, -INF);
	}
	void update(int a, int v, int l, int r, int x) {
		if (l + 1 == r) {
			tree[x] = v;
			return;
		}
		int m = (l + r) / 2;
		if (a < m) update(a, v, l, m, 2 * x);
		else update(a, v, m, r, 2 * x + 1);
		tree[x] = max(tree[2 * x], tree[2 * x + 1]);
	}
	int query(int a, int b, int l, int r, int x) {
		if (b <= l || a >= r) return -INF;
		if (a <= l && r <= b) return tree[x];
		int m = (l + r) / 2;
		return max(query(a, b, l, m, 2 * x), query(a, b, m, r, 2 * x + 1));
	}
} seg[2];

