ll get_dist(int i){
    return norm(a[i]-a[id[i]]);
}

bool inside(const point &p){
    int res=0;
    for(int i=1;i<=n;i++){
        point u=a[i],v=a[i%n+1];
        if(on_segment(p,u,v)||u==p)return true;
        ll cur=cross(v,p,u);
        if(imag(u)<imag(p)&&imag(p)<=imag(v)&&cur>0)res^=1;
        if(imag(u)>=imag(p)&&imag(p)>imag(v)&&cur<0)res^=1;
    }
    return res;
}

