template <typename T> bool chmin(T &a, const T &b) {
	if (a <= b) return false;
	a = b;
	return true;
}

template <typename T> bool chmax(T &a, const T &b) {
	if (a >= b) return false;
	a = b;
	return true;
}

template <typename T> T max(vector<T> &a){
	assert(!a.empty());
	T ret = a[0];
	for (int i=0; i<(int)a.size(); i++) chmax(ret, a[i]);
	return ret;
}

template <typename T> T min(vector<T> &a){
	assert(!a.empty());
	T ret = a[0];
	for (int i=0; i<(int)a.size(); i++) chmin(ret, a[i]);
	return ret;
}

template <typename T> T sum(vector<T> &a){
	T ret = 0;
	for (int i=0; i<(int)a.size(); i++) ret += a[i];
	return ret;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	
	ll n, s, c;
	cin >> n >> s >> c;
	vector<ll> a(n), l(n), r(n);
	rep(i,0,n) {
		cin >> a[i] >> l[i] >> r[i];
	}

	vector<pair<ll,ll>> far;
	far.push_back(pair(0, 1));
	far.push_back(pair(1, 1));
	rep(i,0,n) {
		rep(j,i + 1,n) {
			if ((l[i] - l[j]) + (r[i] - r[j]) != 0) {
				ll g = __gcd(abs(r[i] - r[j]), abs((l[i] - l[j]) + (r[i] - r[j])));
				ll si = (r[i] - r[j]) / g;
				ll bo = ((l[i] - l[j]) + (r[i] - r[j])) / g;
				if (bo < 0) {
					si *= -1;
					bo *= -1;
				}
				if (0 <= si && si <= bo) {
					far.push_back(pair(si, bo));
				}
			}
		}
	}

	sort(all(far), [](pair<ll,ll> a, pair<ll,ll> b) {
		return (__int128)a.first * b.second < (__int128)a.second * b.first;
	});

	far.erase(unique(all(far)),far.end());

	//for (auto [x,y]: far) cout << x << ' ' << y << endl;

	auto comp = [](pair<ll,ll> a, pair<ll,ll> b) -> bool {
		return (__int128)a.first * b.second < (__int128)a.second * b.first;
	};

	int ub = (int)far.size() - 1;
	int lb = 0;

