			p.emplace_back(pair(- (l[i] + r[i]) * x + r[i] * y, a[i]));
		}
		sort(all(p));

		ll rs = 0;
		ll ts = 0;
		rep(i,0,n) {
			rs += p[i].second * p[i].first;
			ts += p[i].second;
			ll v = rs - ts * p[i].first + s * p[i].first + c * s * (2 * x - y);
			//cout << v << ' ' << y  << endl;
			if ((__int128)ans.first * y < (__int128)ans.second * v) {
				ans = pair(v, y);
			}
		}

		return ans;
	};


	while (ub - lb > 3) {
		int t1 = (ub + ub + lb) / 3;
		int t2 = (ub + lb + lb) / 3;
		if (comp(check(far[t1]), check(far[t2]))) {
			ub = t1;
		} else {
			lb = t2;
		}
	}

	pair<ll,ll> ans = pair(0, 1);
	rep(i,lb,ub+1) {
		if (comp(ans, check(far[i]))) {
			ans = check(far[i]);
		}
		//cout << check(far[i]).first << ' ' << check(far[i]).second <<endl;
		//cout << ans.first << ' ' << ans.second <<endl;
	}
	

	ll si = ans.first;
	ll bo = 10000 * ans.second;
	ll g = __gcd(si, bo);
	si /= g;
	bo /= g;
	
	cout << si << ' ' << bo << endl;
	

}

