bool check_sqsum(ll x,ll y,ll z){
	// sqrt(x) + sqrt(y) == sqrt(z)
	// printf("checksum %lld %lld %lld\n",x,y,z);
	if(z<x+y) return false;
	// printf("check value: %lld\n",sq(z-x-y)-4ll*x*y);
	return sq(z-x-y)==4ll*x*y;
}


