			a[i]={sqrt(dist[i]),0,0};
			// printf("%d %d %d\n",dist[1],d1,dist[i]);
			// puts("linear pos");
		}else if(check_sqsum(dist[1],dist[i],d1)){
			a[i]={-sqrt(dist[i]),0,0};
			// puts("linear neg");
		}else if(!p){
			p=i;
			double c=((double)dist[i]+dist[1]-d1)/(2*sqrt((ll)dist[i]*dist[1]));
			assert(-1<=c&&c<=1);
			double s=sqrt(max((double)0,1-c*c));
			a[p]={c*sqrt(dist[i]),s*sqrt(dist[i]),0};
			// assert(abs(a[p][1]*a[1][0]-a[p][0]*a[1][1])<)
			// puts("first nonlinear");
		}else{
