			double s1=2*(a[p][0]-a[0][0]),t1=2*(a[p][1]-a[0][1]),u1=dist[i]-dp+dist[p];
			// printf("%Lf %Lf %Lf\n%Lf %Lf %Lf\n",s0,t0,u0,s1,t1,u1);
			// s0x+t0y=u0, s1x+t1y=u1
			// (t0*s1-t1*s0)y=(u0*s1-u1*s0)
			double y=(u0*s1-u1*s0)/(t0*s1-t1*s0);
			double x=(u0*t1-u1*t0)/(s0*t1-s1*t0);
