				// puts("first nonplanar");
				q=i; a[i]={x,y,z};
			}else{
				// puts("nonplanar");
				int dq=ask(q,i);
				double dpos=sq(a[q][0]-x)+sq(a[q][1]-y)+sq(a[q][2]-z);
				double dneg=sq(a[q][0]-x)+sq(a[q][1]-y)+sq(a[q][2]+z);
				if(abs(dneg-dq)<abs(dpos-dq)) z=-z,swap(dpos,dneg);
				// assert(abs(dpos-dq)<1e-10);
				a[i]={x,y,z};
			}
		}
		// printf("%Lf %Lf %Lf\n",a[i][0],a[i][1],a[i][2]);
	}
	for(int i=1;i<=n;i++){
