void solve()
{
    auto getans = [&] (int n, int m, vector<string> &a) -> bool
    {
        vector<vector<string>> base(4, vector<string>(2));
        base[0] = {"CC", "IP"};
        base[1] = {"IP", "CC"};
        
        base[2] = {"CI", "CP"};
        base[3] = {"PC", "CI"};

        for (int idx = 0; idx < 4; idx++) {
            int flag = 1;
            vector<string> ans = a;
            for (int i = 1; i <= n; i++) {
                int res = 1;
                for (int j = 1; j <= m; j++) {
                    char now = base[idx][i % 2][j % 2];
                    if (ans[i][j] == '?') ans[i][j] = now;
                    else res = res & (ans[i][j] == now);
                }
                if (res == 1)
                    continue;
                res = 1;
                for (int j = 1; j <= m; j++) {
                    ans[i][j] = a[i][j];
                    char now = base[idx][i % 2][(j % 2) ^ 1];
                    if (ans[i][j] == '?') ans[i][j] = now;
                    else res = res & (ans[i][j] == now);
                }
                if (res == 1)
                    continue;
                flag = 0;
            }
            if (flag) {
                a = ans;
                return true;
            }
        }
        return false;
    };

    int n, m;
    cin >> n >> m;
    vector<string> a(n + 1);

    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] = " " + a[i];
    }

    if (getans(n, m, a)) {
        cout << "yes\n";
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                cout << a[i][j];
            }
            cout << '\n';
        }
        return;
    }

    vector<string> b(m + 1, string(n + 1, ' '));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            b[j][i] = a[i][j];
        }
    } 

    if (getans(m, n, b)) {
        cout << "yes\n";
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                cout << b[j][i];
            }
            cout << '\n';
        }
        return;
    }
    cout << "no\n";
}

