namespace IAOI_lib{
  class dsu{
    private:
      vector<int> a,s;
    public:
      dsu(int n):a(n),s(n,1){
        iota(a.begin(),a.end(),0);
      }
      int leader(int x){
        return a[x]==x?x:a[x]=leader(a[x]);
      }
      int size(int x){
        return s[leader(x)];
      }
      void merge(int x,int y){
        x=leader(x),y=leader(y);
        if(x==y)return;
        if(s[x]>s[y])swap(x,y);
        s[y]+=s[x],a[x]=y;
      }
      bool same(int x,int y){
        return leader(x)==leader(y);
      }
      vector<vector<int> > groups(){
        vector<int> id(a.size(),-1);
        int c=0;
        for(int i=0;i<a.size();i++)
          if(i==leader(i))id[i]=c++;
        vector<vector<int> > v(c);
        for(int i=0;i<a.size();i++)
          v[id[leader(i)]].emplace_back(i);
        return v;
      }
  };
}
int main(){
  ios::sync_with_stdio(false);
  cin.tie(0); cout.tie(0);
  int t; cin>>t;
  while(t--){
    int n,N; cin>>n,N=n*3;
    vector<pii> r,nr;
    vector<tpi> inter;
    for(int i=0;i<n;i++){
      string s; cin>>s;
      switch(s[0]){
        case 'r':{
          int x,y; cin>>x>>y;
          r.emplace_back(x-1,y-1);
          break;
        }
        case 'n':{
          int x,y; cin>>x>>y;
          nr.emplace_back(x-1,y-1);
          break;
        }
        default:{
          int x,y,z; cin>>x>>y>>z;
          inter.emplace_back(x-1,y-1,z-1);
          break;
        }
      }
    }
    vector<vector<int> > g(N);
    for(int i=0;i<inter.size();i++){
      auto [x,y,z]=inter[i];
      g[x].emplace_back(i);
      g[y].emplace_back(i);
      g[z].emplace_back(i);
    }
    vector t(N,vector<bool>(N));
    auto bfs=[&](int s){
      queue<int> q;
      for(int i=0;i<N;i++)
        if(t[s][i])q.emplace(i);
      while(!q.empty()){
        int u=q.front(); q.pop();
        for(int p:g[u]){
          if(auto [x,y,z]=inter[p];u==x){
            if(!t[s][y])t[s][y]=true,q.emplace(y);
            if(!t[s][z])t[s][z]=true,q.emplace(z);
          }
          else if(t[s][u^y^z]&&!t[s][x])
            t[s][x]=true,q.emplace(x);
        }
      }
    };
    for(int s=0;s<N;s++)
      t[s][s]=true,bfs(s);
    IAOI_lib::dsu d(N);
    for(int u=0;u<N;u++)
      for(int v=u+1;v<N;v++)
        if(t[u][v]&&t[v][u])d.merge(u,v);
    for(auto &[x,y]:r)
      x=d.leader(x),y=d.leader(y);
    for(auto &[x,y]:nr)
      x=d.leader(x),y=d.leader(y);
    for(auto &[x,y,z]:inter)
      x=d.leader(x),y=d.leader(y),z=d.leader(z);
    for(auto &v:g)v.clear();
    for(int i=0;i<inter.size();i++){
      auto [x,y,z]=inter[i];
      g[x].emplace_back(i);
      g[y].emplace_back(i);
      g[z].emplace_back(i);
    }
    for(auto &v:t)fill(v.begin(),v.end(),false);
    bool f=true;
    for(int s=0;s<N&&f;s++)
      if(s==d.leader(s)){
        for(auto [x,y]:r)
          if(s==x)t[s][y]=true;
        bfs(s);
        for(auto [x,y]:nr)
          if(s==x)f&=!t[s][y];
      }
    auto topo=[&](vector<vector<bool> > &t){
      vector<int> d(N);
      for(int u=0;u<N;u++)
        for(int v=0;v<N;v++)
          if(t[u][v])d[v]++;
      queue<int> q;
      for(int u=0;u<N;u++)
        if(!d[u])q.emplace(u);
      while(!q.empty()){
        int u=q.front(); q.pop();
        for(int v=0;v<N;v++)
          if(t[u][v]&&!--d[v])q.emplace(v);
      }
      return count(d.begin(),d.end(),0)==N;
    };
    cout<<(f&&topo(t)?"yes\n":"no\n");
  }
  return 0;
}

