#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
  int n, m, k; cin >> m >> n >> k;
  int u, v; cin >> u >> v;
  vector<vector<pair<int, ll>>> g(n);
  for(int i = 0; i < m; i++) {
    int a, b; ll c; cin >> a >> b >> c;
    g[b].emplace_back(a, c);
  }
  set<tuple<int, int, int>> banned;
  for(int i = 0 ;i < k; i++) {
    int a, b, c; cin >> a >> b >> c;
    banned.emplace(c, b, a);
  }
  map<pair<int, int>, ll> dist;
  using P = pair<int, int>;
  using N = pair<ll, P>;
  priority_queue<N, vector<N>, greater<N>> pq;
  dist[{v, -1}] = 0LL;
  pq.emplace(N(0LL, P(v, -1)));
  while(!pq.empty()) {
    auto [d, p] = pq.top(); pq.pop();
    if(dist[p] < d) continue;
    auto [u, uu] = p;
    for(auto [v, c] : g[u]) {
      ll nd = d+c;
      if(banned.count({uu, u, v})) continue;
      P np = {v, u};
      if(dist.count(np) && dist[np] < nd) continue;
      dist[np] = nd;
      pq.emplace(nd, np);
    }
  }
  constexpr ll INF = 1e18;
  ll ans = INF;
  for(auto [p, d] : dist) {
    if(p.first == u) {
      if(ans > d) ans = d;
    }
  }
  if(ans == INF) cout << "-1\n";
  else cout << ans << '\n';
}

