inline void pushtag(int p,int c)
{
	tag[p]+=c;
	if(num[p]) hs[p]-=sum[num[p]-1]*c;
}
inline void pushdown(int p)
{
	if(!tag[p]) return;
	pushtag(p<<1,tag[p]);pushtag(p<<1|1,tag[p]);
	tag[p]=0;
}
inline void pushup(int p)
{
	hs[p]=hs[p<<1]*pw[num[p<<1|1]]+hs[p<<1|1];
	num[p]=num[p<<1]+num[p<<1|1];
}
void upd(int k,int c,int s=1,int t=n,int p=1)
{
	if(s==t)
	{
		hs[p]=c;
		num[p]=(c>0);
		return;
	}
	int m=s+t>>1;
	pushdown(p);
	if(k<=m) upd(k,c,s,m,p<<1);
	else upd(k,c,m+1,t,p<<1|1);
	pushup(p);
}
