int match(int st) {
  int mn, mx;

  if (s[st] == t[0])
    mn = mx = st;
  else if (st + 1 < N and s[st + 1] == t[0])
    mn = mx = st + 1;
  else
    return -1;

  int mnp, mxp;
  for (char x : t) {
    mnp = inf, mxp = 0;

    if (x == s[mx] or (st < mx and x == s[mx - 1])) {
      mnp = mx;
      mxp = mx;
    }
    if (mx + 1 < N and x == s[mx + 1]) {
      mnp = min(mnp, mx + 1);
      mxp = mx + 1;
    }

    if (mn < mx) {
      if (mn + 1 < N and x == s[mn + 1]) mnp = mn + 1;
      if (x == s[mn] or (st < mn and x == s[mn - 1])) mnp = mn;
    }

    if (mnp == inf) return -1;

    mn = mnp, mx = mxp;
  }

  return mn;
}

