const int INF = 1e9;

int n, a[6060], b[6060], r[6060], r2[6060];

int solve() {
    for(int i=1;i<=n;i++) a[n+i] = a[i], b[n+i] = b[i];
    r[n+n+1] = r2[n+n+1] = n+n;
    for(int i=n+n;i>=1;i--) r[i] = (a[i] == b[i] ? r[i+1] : i-1);
    if(r[1] >= n) return 0;
    for(int i=n+n;i>=1;i--) r2[i] = (a[i] == b[i-1] ? r2[i+1] : i-1);

    int re = INF;
    for(int L=1;L<=n;L++) {
        int R = L+n-1, M = r[L];
        if(a[M+1] == b[R] && r2[M+2] >= R) re = min(re, R-M-1);
    }
    return re;
}

int solve1() {
    int re = solve();
    for(int i=1;i<n;i++) {
        rotate(a+1, a+2, a+1+n);
        re = min(re, solve() + (n-1)*min(i, n-i));
    }
    rotate(a+1, a+2, a+1+n);
    return re;
}

