int probe() {
    if (s[4] == '1') return 1;
    else if (s[5] == '1') return 2;
    static vector<int> v = random_instruction();
    vector<int> stk, hist = {gt()};
    for (auto &i:v) {
        if (s[i] == '0') {
            mv(i);
            stk.push_back(i ^ 1);
            hist.push_back(gt());
        }
    }
    while (stk.size() > 0) {
        mv(stk.back());
        stk.pop_back();
        hist.push_back(gt());
    }
    int val = h(hist);
    if (mp.find(val) == mp.end()) {
        mp[val] = mn_id;
