            E[now][d] = nxt;
            E[nxt][d ^ 1] = now;
            if (now != nxt) dfs(nxt, now);
            mv(d ^ 1);
        }
    }
}

void STP(int v, int tar) {
    vector<int> pre(mxN, -1);
    pre[v] = 0;
    queue<int> q;
    q.push(v);
    while (q.size() > 0) {
        int now = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) if (E[now][d] != -1 && pre[E[now][d]] == -1) {
            pre[E[now][d]] = d;
            q.push(E[now][d]);
        }
    }
    int now = tar;
    vector<int> hist;
    while (true) {
        if (now == v) break;
        hist.push_back(pre[now]);
        now = E[now][pre[now] ^ 1];
    }
    reverse(all(hist));
    for (auto &i:hist) mv(i);
}

