		if(l==r){
			tr[x].c^=1,tr[x].s[0]^=c[l];
			return;
		}
		int mid=l+r>>1;
		if(i<=mid) upd(L,l,mid,i);
		else upd(R,mid+1,r,i);
		tr[x]=tr[L]+tr[R];
	}
	Data que(int x,int l,int r,int ql,int qr){
		if(ql<=l&&r<=qr) return tr[x];
		int mid=l+r>>1;
		if(qr<=mid) return que(L,l,mid,ql,qr);
		if(ql>mid) return que(R,mid+1,r,ql,qr);
		return que(L,l,mid,ql,qr)+que(R,mid+1,r,ql,qr);
	}
	int find(int x,int l,int r,int c){
		if(l==r) return l;
		int mid=l+r>>1;
		if(c<=tr[L].c) return find(L,l,mid,c);
		return find(R,mid+1,r,c-tr[L].c);
	}
	int find(int x,int l,int r,int ql,int qr,int c){
		if(ql<=l&&r<=qr){
			if(c<=tr[x].c) return find(x,l,r,c);
