		}
		int mid=l+r>>1;
		if(qr<=mid) return find(L,l,mid,ql,qr,c);
		if(ql>mid) return find(R,mid+1,r,ql,qr,c);
		int p=find(L,l,mid,ql,qr,c);
		if(p>0) return p;
		int q=find(R,mid+1,r,ql,qr,c+p);
		return q>0?q:p+q;
	}
