}
int getmn(int l,int r){
    if(qry(rt[tot],1,n,l,r)>r) return -1;
    int res=tot;
    for(int i=tot>>1;i;i>>=1) if(qry(rt[res-i],1,n,l,r)<=r) res-=i;
    return res;
}
