        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
        }
        ifact[n] = fact[n].inv();
        for (int i = n; i > 0; i--) {
            ifact[i - 1] = ifact[i] * i;
        }

        auto binom = [&](int n, int m) { return m < 0 || m > n ? 0 : fact[n] * ifact[m] * ifact[n - m]; };

        vector<Mint> a(n + 1);
        a[0] = 1;
        Mint coef = 1;

        for (int i = 1; i <= n; i++) {
            a[i] = coef * a[i - 1];
            coef = coef * 2 - binom(i - 1, k);
        }
        for (int i = 0; i <= n; i++) {
            a[i] *= ifact[i];
        }

        auto c = Poly(a).log(n + 1);
        c[n] *= fact[n];

        cout << c[n] << '\n';
    };
    
    solve();
    
    return 0;
}

