inline int trans(int st){return (st-1)%(k*k)+1;}
Data calc(int st,int len){
    Data ans;
    if(st+len-1<k*k){
        for(int i=0;i<k;i++)ans.num[i]=pre[i][st+len-1]-pre[i][st-1];
        return ans;
    }
    int p=(len-(k*k-st+1))/(k*k),q=(len-(k*k-st+1))-p*k*k;
    for(int i=0;i<k;i++)ans.num[i]=(pre[i][k*k]-pre[i][st-1])+p*k+pre[i][q];
    return ans;
}
int newnode(){
