void pushdown(int k,int l,int r){
    if(!t[k].st)return ;
    int mid=l+((r-l)>>1);
    t[k].ls=newnode();t[t[k].ls].v=calc(t[t[k].ls].st=t[k].st,mid-l+1);
    t[k].rs=newnode();t[t[k].rs].v=calc(t[t[k].rs].st=trans(t[k].st+mid+1-l),r-mid);
    t[k].st=0;
    return ;
}
void trash(int k){
    if(!k)return ;
    st[++tp]=k;
    trash(t[k].ls),trash(t[k].rs);
