}
void modify(int &k,int l,int r,int x,int y,int st){
    if(!k)k=newnode();
    if(l>=x&&r<=y){
        t[k].v=calc(trans(st+l-x),r-l+1);
        trash(t[k].ls),trash(t[k].rs);
