    int mid=l+((r-l)>>1);
    pushdown(k,l,r);
    if(x<=mid)modify(t[k].ls,l,mid,x,y,st);
    if(y>mid)modify(t[k].rs,mid+1,r,x,y,st);
    t[k].v=t[t[k].ls].v+t[t[k].rs].v;
    return ;
}
Data query(int k,int l,int r,int x,int y){
