typedef double D;
typedef complex<D> pt;
#define X real()
#define Y imag()
D dist(pt a, pt dir, char drift, pt q) {
    q-=a;
    while(dir!=pt{1,0}) {
        q*=pt{0,1};
        dir*=pt{0,1};

    }
    if(drift=='R') {
        drift='L';
        q = {q.X,-q.Y};
    }
    // drift = L and dir = {1,0} over.
    D ans = min(abs(q), abs(q-pt{1,1}));
    if(q.X-q.Y>0) {
        ans=min(ans,abs(q-pt{0,1})-1);
    }
    return ans;
}
void read(pt& p) {
    int x,y; cin >> x >> y;
    p={x,y};
}
template<class F>
auto ternSearch(ll a, ll b, F f) {
	assert(a <= b);
	while (b - a >= 5) {
		ll m1 = a + (b-a)/2;
		ll m2 = m1+1;
		if (f(m1) > f(m2)) a = m1; // (A)
		else b = m2;
	}
    D best = f(a);
    for(ll i=a;i<=b;++i) 
        best=min(best,f(i));
	return best;
}
void solve() {
    pt p; read(p);
    string s; cin >> s;
    s+=s;
    s+=s;
    int n = s.size();
    vector<pair<pt,pt>> a = {{pt{0,0},pt{1,0}}};
    for(int i=0;i<n;++i) {
        auto [at,dir] = a.back();
        if(s[i]=='L') {
            at+=pt{1,1}*dir;
            dir*=pt{0,1};
        } else {
            at+=pt{1,-1}*dir;
            dir*=pt{0,-1};
        }
        a.push_back({at,dir});
    }
    pt vec = a.back().first;
    D ans = INFINITY;
    for(int i=0;i<n;++i) {
        ans=min(ans,ternSearch(-1e10,1e10, [&](int k) {
            pt now = a[i].first+ vec*D(k);
            return dist(now,a[i].second,s[i],p);
        }));
    }
    cout << setprecision(15) << ans << '\n';
}
