const ll mod = (73<<24) + 1, root = 3;
// const ll mod = 998244353, root=1;

ll mul(ll a, ll b){
    return a*b%mod;
}ll modpow(ll a, ll e){
    ll ans = 1;
    while(e){
        if (e&1) ans = mul(a,ans);
        a = mul(a,a);
        e/=2;
    }return ans;
}
ll modinv(ll a) {
    return modpow(a, mod-2);
}
typedef vector<ll> vl;

void ntt(vl &a) {
    int n = sz(a), L = 31 - __builtin_clz(n);
    static vl rt(2,1);
    for(static int k = 2, s = 2; k < n; k *= 2, s++) {
        rt.resize(n);
        ll z[] = {1,modpow(root, mod>>s)};
        rep(i,k,2*k) rt[i] = rt[i/2] * z[i&1] % mod;
    }
    vi rev(n);
    rep(i,0,n) rev[i] = (rev[i/2] | (i&1) << L) / 2;
    rep(i,0,n) if (i < rev[i]) swap(a[i], a[rev[i]]);
    for(int k = 1; k < n; k *= 2)
        for(int i = 0; i < n; i += 2*k) rep(j,0,k) {
            ll z = rt[j+k] * a[i+j+k] % mod, &ai = a[i + j];
            a[i+j+k] = ai - z + (z > ai ? mod : 0);
            ai += (ai + z >= mod ? z - mod : z);
        }
}
vl conv(const vl& a, const vl& b){
    if (a.empty() || b.empty()) return {};
    int s = sz(a) + sz(b) - 1, B = 32 - __builtin_clz(s), n = 1<<B;
    int inv = modpow(n, mod - 2);
    vl L(a), R(b), out(n);
    L.resize(n), R.resize(n);
    ntt(L), ntt(R);
    rep(i,0,n) out[-i & (n-1)] = (ll)L[i] * R[i] % mod * inv % mod;
    ntt(out);
    return {out.begin(), out.begin()+s};
}

vl inverse(vl a, int n) {
    vl b =  {modpow(a[0],mod-2)}, m, k;
    for(int i = 1, j; i < n; i *= 2) {
        m = vl(a.begin(), a.begin()+min((int)a.size(),i*2));
        k = conv(m, b);
        for(j = 0, k[0]-=2; j < sz(k); ++j) k[j] = (mod - k[j]) % mod;
        b = conv(k, b);
        b.resize(min(i*2,n));
    }
    b.resize(n);
    return b;
}

