    }

    top[0] = (top[0] + mod - 1) % mod;
    bottom[0] = (bottom[0] + mod - 1) % mod;
    top.erase(top.begin());
    bottom.erase(bottom.begin());
    vl answers = conv(top, inverse(bottom, n+1));
    for(int i=0;i<answers.size();++i) answers[i] = mul(answers[i],fact[i]);
