	int n, en, h[maxn], dis[maxn], vis[maxn], ind[maxn], dfn[maxn], low[maxn], id[maxn], siz[maxn], _G_T;
	stack<int> stk;
	void clear() {
		memset(h, 0xff, sizeof(h));
		memset(ind, 0, sizeof(ind));
		memset(vis, 0, sizeof(vis));
		memset(dfn, 0, sizeof(dfn));
