		e[en] = (Edge){ u, v, h[u] }; h[u] = en++; ind[v]++; n = max(n, max(u, v));
	}
	void dfs1(int r) {
		dfn[r] = low[r] = ++_G_T; vis[r] = 1; stk.push(r);
		for(int j = h[r]; ~j; j = e[j].next) {
			int v = e[j].v;
			if(!dfn[v]) dfs1(v), low[r] = min(low[r], low[v]);
			if(vis[v] == 1) low[r] = min(low[r], low[v]);
		}
		if(dfn[r] == low[r]) {
			while(!stk.empty()) {
				int x = stk.top(); stk.pop();
				vis[x] = 2;
				id[x] = r;
				siz[r]++;
				if(x == r) break;
			}
		}
	}
	
	void tarjan(int s) {
		while(!stk.empty()) stk.pop();
		dfs1(s);
		int m = en; en = 0; memset(ind, 0, sizeof(ind)); memset(h, 0xff, sizeof(h));
		for(int i = 0; i < m; i++) {
			if(vis[e[i].u] && vis[e[i].v] && id[e[i].u] != id[e[i].v]) add(id[e[i].u], id[e[i].v]);
		}
	}
	
