		memset(dis, 0xc0, sizeof(dis));
		queue<int> q;
		for(int i = 1; i <= n; i++) if(ind[i] == 0) dis[i] = (i == s ? 0 : -inf), q.push(i);
		if(ind[s]) dis[s] = 0, q.push(s);
		while(!q.empty()) {
			int r = q.front(); q.pop();
			if(siz[r] > 1 && dis[r] >= 0) dis[r] = inf;
			for(int j = h[r]; ~j; j = e[j].next) {
				int v = e[j].v;
				dis[v] = max(dis[v], min(dis[r] + 1, inf));
				if(--ind[v] == 0 && v != s) q.push(v);
