		}
	} 
	for(int c = 1; c <= 26; c++) {
		f.add(1, c * n * m + 1);
		g.add(1, c * n * m + n * m);
	}
	f.tarjan(1); f.topo(1);
	g.tarjan(1); g.topo(1);
	int q; cin >> q; while(q--) {
		int x, y; cin >> x >> y;
		x++, y++;
		int ans = -1;
		for(int c = 1; c <= 26; c++) {
			int u = c * n * m + (x - 1) * m + y;
			if(!f.dfn[u] || !g.dfn[u]) continue;
			int p;
			if(f.dis[f.id[u]] >= inf || g.dis[g.id[u]] >= inf) p = inf;
			else p = f.dis[f.id[u]] + g.dis[g.id[u]];
			ans = max(ans, p);
		}
		if(ans == -1) cout << "-2\n";
		else if(ans == inf) cout << "-1\n";
		else cout << ans - 1 << '\n';
	}
}

