#include <bits/stdc++.h>
using namespace std;
typedef long long i64;
const int N = 1e5 + 5;
const i64 INF = 1e18;

struct Node {
    i64 a, b;
    Node(i64 a = 0, i64 b = 0) : a(a), b(b) {}
    friend Node operator+ (const Node a, const Node b) {
        return Node(a.a + b.a, a.b + b.b);
    }
} T[N * 4];
i64 addv[N * 4], setv[N * 4];
i64 a[N];
int n, q;

void build(int o, int l, int r) {
    setv[o] = -INF;
    if (l == r) return T[o] = Node(a[l], l * a[l]), void();
    int mid = l + r >> 1; build(o << 1, l, mid); build(o << 1 | 1, mid + 1, r);
    T[o] = T[o << 1] + T[o << 1 | 1];
}

inline void maketag(int o, int l, int r, i64 st, i64 ad) {
    if (st != -INF) {
        setv[o] = st; addv[o] = 0;
        T[o] = Node((r - l + 1) * st, st * (l + r) * (r - l + 1) / 2);
    }

    addv[o] += ad;
    T[o] = T[o] + Node((r - l + 1) * ad, ad * (l + r) * (r - l + 1) / 2);
}

inline void pushdown(int o, int l, int r) {
    int mid = l + r >> 1;
    maketag(o << 1, l, mid, setv[o], addv[o]);
    maketag(o << 1 | 1, mid + 1, r, setv[o], addv[o]);
    setv[o] = -INF; addv[o] = 0;
}

void update(int o, int l, int r, int x, int y, i64 st, i64 ad) {
    if (x <= l && r <= y) return maketag(o, l, r, st, ad);
    pushdown(o, l, r); int mid = l + r >> 1;
    if (x <= mid) update(o << 1, l, mid, x, y, st, ad);
    if (mid < y) update(o << 1 | 1, mid + 1, r, x, y, st, ad);
    T[o] = T[o << 1] + T[o << 1 | 1];
}

Node query(int o, int l, int r, int x, int y) {
    if (x <= l && r <= y) return T[o];
    pushdown(o, l, r); int mid = l + r >> 1;
    if (y <= mid) return query(o << 1, l, mid, x, y);
    if (mid < x) return query(o << 1 | 1, mid + 1, r, x, y);
    return query(o << 1, l, mid, x, y) + query(o << 1 | 1, mid + 1, r, x, y);
}

int main(void) {
    ios::sync_with_stdio(0);
    cin >> n >> q;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    build(1, 1, n);
    while (q--) {
        int op, l, r; i64 x;
        cin >> op >> l >> r;
        if (op == 1) cin >> x, update(1, 1, n, l, r, -INF, x);
        else if (op == 2) cin >> x, update(1, 1, n, l, r, x, 0);
        else {
            auto [s1, s2] = query(1, 1, n, l, r);
            // cerr << s1 << " " << s2 << "\n";
            s2 -= (l - 1) * s1;
            if (s1 == 0) {
                if (s2 == 0) cout << "Yes\n";
                else cout << "No\n";
            } else {
                if (s2 % s1 == 0) {
                    i64 t = s2 / s1;
                    if (1 <= t && t <= r - l + 1) cout << "Yes\n";
                    else cout << "No\n";
                } else cout << "No\n";
            }
        }
    }
    return 0;
}

