struct dxs
{
	ll x[N];
	
	ll& operator [] (int i) {return x[i];}
	
	void dft(int id=1)
	{
		for(int i=0;i<tot;i++) if(i<rev[i]) swap(x[i],x[rev[i]]);
		for(int i=1,rt=2;i<tot;i<<=1,rt<<=1)
		{
			ll wn=ksm(W,(MOD-1)/rt);
			if(id==-1) wn=ksm(wn);
			for(int j=0;j<tot;j+=rt)
			{
				ll w=1;
				for(int k=0;k<i;k++,w=w*wn%MOD)
				{
					ll vx=x[j+k],vy=x[i+j+k]*w%MOD;
					x[j+k]=(vx+vy)%MOD,x[i+j+k]=(vx+MOD-vy)%MOD;
				}
			}
		}
		if(id==-1) for(int i=0;i<tot;i++) x[i]=x[i]*inv%MOD;
	}

