template <class T>
struct P2{
    T x, y;

    P2 (T x_=0, T y_=0){
        x = x_;
        y = y_;
    }

    P2 operator+ (const P2 &p) const{ return P2(x+p.x, y+p.y);}
    P2 operator- (const P2 &p) const{ return P2(x-p.x, y-p.y);}
    P2 operator- (){ return P2(-x, -y);}
    T operator* (const P2 &p) const{ return x*p.x + y*p.y;}
    P2 operator* (const T d) const{ return P2(x*d, y*d);}
    P2 r90() { return P2(y, -x);}
    T operator^ (const P2 &p) const{ return x*p.y-y*p.x;}
    T size() { return x*x+y*y;}
    bool operator< (const P2 &p) const{ return array<T, 2>{x, y} < array<T, 2>{p.x, p.y};}
    bool operator> (const P2 &p) const{ return array<T, 2>{x, y} > array<T, 2>{p.x, p.y};}
    bool operator<= (const P2 &p) const{ return array<T, 2>{x, y} <= array<T, 2>{p.x, p.y};}
    bool operator>= (const P2 &p) const{ return array<T, 2>{x, y} >= array<T, 2>{p.x, p.y};}
    bool operator== (const P2 &p) const{ return x==p.x && y==p.y;}
};
using PT = P2<lb>;
using polygon = vector<PT>;
PT O = PT();

ll ccw(const PT &p1, const PT &p2, const PT &p3){
    lb op = (p2-p1)^(p3-p1);
    return (op>0)-(op<0);
}
polygon convex_hull(polygon v){
    // monotone chain

    int n = v.size();
    int k = 0;

    if (n < 3) return v;

    polygon ans(2*n);

    sort(all(v));
    
    for (int i = 0; i < n; i++){
        while (k >= 2 && ccw(ans[k-2], ans[k-1], v[i]) <= 0){
            k--;
        }
        ans[k] = v[i];
        k++;
    }

    for (int i = n- 1, t = k + 1; i > 0; i--){
        while (k >= t && ccw(ans[k-2], ans[k-1], v[i-1]) <= 0){
            k--;
        }
        ans[k] = v[i-1];
        k++;
    }

    ans.resize(k-1);
    return ans;
}

ll n; 
ll x, y;
polygon v;

inline lb getdist(int j){
    return sqrtl((v[j]-v[(j+1)%n]).size());    
}

lb cal(int i, lb li, int j, lb lj){
    PT P = v[i] + (v[(i+1)%n]-v[i])*li;
    PT Q = v[j] + (v[(j+1)%n]-v[j])*lj;
    return sqrtl((P-Q).size());
}
lb solve(int i, lb li, int j, lb lj, lb d){
    // cout << i << ' ' << j << ' ' << li << ' ' << lj << ' ' << d << endl;

    lb left = li;
    lb right = li + d;

    for (int _ = 0; _ < 100; _++){
        lb d = (right-left)/3;
        lb x1 = left + d;
        lb x2 = right - d;
        lb y1 = cal(i, x1, j, lj + (x1-li) * getdist(i) / getdist(j));
        lb y2 = cal(i, x2, j, lj + (x2-li) * getdist(i) / getdist(j));

        if (y1 < y2) right = x2;
        else left = x1;
    }

    lb x = (left + right) / 2;
    lb res = cal(i, x, j, lj + (x-li) * getdist(i) / getdist(j));
    // cout << "Cursol : " << res << endl;
    return res;
}

