            li += d / getdist(i);
            lj += d / getdist(j);
            
            j++;
            lj = 0;
            if (j == n) j = 0;
        }

        ans = min(ans, solve(i, li, j, lj, 1-li));
        lj += (1-li) * getdist(i) / getdist(j);
    }

    cout << fixed;
    cout.precision(12);
    cout << ans << '\n';

}


