struct Edge
{
	int to, pr, idx;
	
	Edge (int _to, int _pr, int _idx): to(_to), pr(_pr), idx(_idx) {}
	bool operator<(const Edge& ed) const
	{
		return MP(pr, to) < MP(ed.pr, ed.to);
	};
};

const int N = 2e5 + 47;
vector<Edge> g[N];
int dist[N], par[N];

vector<bool> vis, isMain, isBridge;
int tin[N], mtin[N], timer;

struct DSU
{
	int n;
	VI par;
	
	DSU (int _n = 0)
	{
		n = _n;
		par.resize(n);
		iota(all(par), 0);
	}
	int find(int v)
	{
		if (v == par[v])
			return v;
		return par[v] = find(par[v]);
	}
	bool unite(int a, int b)
	{
		a = find(a);
		b = find(b);
		if (a != b)
		{
			if (dist[a] > dist[b])
				par[a] = b;
			else
				par[b] = a;
			
			return true;
		}
		return false;
	}
};

void dfs1(int v, int p = -1, int d = 0)
{
	vis[v] = true;
	par[v] = p;
	dist[v] = d;
	tin[v] = mtin[v] = timer++;
	for (const auto& [to, _, j]: g[v])
	{
		if (to == p)
			continue;
		if (vis[to])
		{
			mtin[v] = min(mtin[v], tin[to]);
			continue;
		}
		
		dfs1(to, v, d + 1);
		mtin[v] = min(mtin[v], mtin[to]);
		
		if (mtin[to] > tin[v])
			isBridge[j] = true;	
	}
}

int solve()
{
	int n, m, q;
	if (!(cin >> n >> m >> q))
		return 1;
	
	timer = 0;
	FOR (i, 0, n)
		g[i].clear();
	vector<pii> ed(m);
	map<pii, int> idx;
	FOR (i, 0, m)
	{
		int a, b;
		cin >> a >> b;
		--a;--b;
		if (a > b)
			swap(a, b);
		ed[i] = {a, b};
		idx[ed[i]] = i;
	}
	
	VI qs(q), res(q), pr(m, 0);
	FOR (i, 0, q)
	{
		int a, b;
		cin >> a >> b;
		--a;--b;
		if (a > b)
			swap(a, b);
		int j = idx[{a, b}];
		qs[i] = j;
		pr[j] = m - i;
	}
	
	VI ord(m);
	iota(all(ord), 0);
	sort(all(ord), [&](int i, int j) -> bool
	{
		return pr[i] < pr[j];
	});
	
	DSU ds(n);
	vis.assign(n, false);
	isMain.assign(m, false);
	isBridge.assign(m, false);
	FOR (i, 0, m)
	{
		auto [a, b] = ed[ord[i]];
		if (ds.unite(a, b))
		{
			int j = idx[{a, b}];
			isMain[j] = true;
			g[a].pb({b, 0, j});
			g[b].pb({a, 0, j});
		}
	}
	
	FOR (i, 0, n)
	{
		if (!vis[i])
			dfs1(i);
	}
	ds = DSU(n);
	int ans = 0;
	FOR (i, 0, m)
	{
		if (pr[i] == 0)
		{
			if (isMain[i])
				++ans;
			else
			{
				auto [a, b] = ed[i];
				a = ds.find(a);
				b = ds.find(b);
				while (a != b)
				{
					if (dist[a] > dist[b])
					{
						ds.unite(a, par[a]);
						a = par[a];
					}
					else
					{
						ds.unite(b, par[b]);
						b = par[b];
					}
					a = ds.find(a);
					b = ds.find(b);
					--ans;
				}
			}
		}
	}
	assert(ans >= 0);
	RFOR(i, q, 0)
	{
		int j = qs[i];
		auto [a, b] = ed[j];
		res[i] = ans;
		
		if (isMain[j])
			++ans;
		else
		{
			a = ds.find(a);
			b = ds.find(b);
			while (a != b)
			{
				if (dist[a] > dist[b])
				{
					ds.unite(a, par[a]);
					a = par[a];
				}
				else
				{
					ds.unite(b, par[b]);
					b = par[b];
				}
				a = ds.find(a);
				b = ds.find(b);
				--ans;
			}
		}
		assert(ans >= 0);
	}
	for (int el: res) cout << el << '\n';
	
	return 0;
}

