        }
    }
    vector<vector<int>>cnt(n,vector<int>(n));
    vector<vector<int>>cnt2(n,vector<int>(n));
    for(int i = 0; i<n; i++){
        for(int j = i+1; j<n; j++){
            for(int k = 0; k<n; k++){
                if(i == k || j == k)continue;
                if(a[i].cross(a[j],a[k]) < 0 && a[k].x >= a[i].x && a[k].x < a[j].x){
                    cnt[a[i].i][a[j].i]++;
                }
                if(a[i].cross(a[j],a[k]) < 0 && a[k].x > a[i].x && a[k].x < a[j].x){
                    cnt2[a[i].i][a[j].i]++;
                }
            }
        }
    }
    auto comp = [&](const pair<P,P>& a, const pair<P,P>& b) -> bool {
        return (a.second - a.first).cross(b.second - b.first) < 0;
    };
    sort(all(arr),comp);
    int ans = 0;
    vector<int>pw(n+1);
