            dp[p2.i] += dp[p1.i] * pw[tri]; dp[p2.i] %= mod;
        }
        reverse(all(arr));
        for(auto [p1,p2] : arr){
            if(vis[p1.i] || vis[p2.i] || p1.t == p2.t || a[t].cross(p1,p2) < 0)continue;
            int tri = cnt2[a[t].i][p2.i] - (cnt2[a[t].i][p1.i] + cnt[p1.i][p2.i]) - 1;
            if(p1.i == a[t].i)tri = 0;
            if(p1.x == p2.x){
                tri = cnt2[a[t].i][p2.i] - cnt2[a[t].i][p1.i];
            }
            dp2[p2.i] += dp2[p1.i] * pw[tri]; dp2[p2.i] %= mod;
        }
        reverse(all(arr));
        for(int i = 0; i<n; i++){
            // cout << dp[i] << ' ' << dp2[i] << '\n';
            if(a[t].i == i || vis[i])continue;
            ans += dp[i] * dp2[i]; ans %= mod;
            if(b[i].t != a[t].t){
                ans--; ans = fix(ans);
            }
        }
        vis[a[t].i] = 1;
        // cout << ans << '\n';
    }
