void slv() {
	cin >> n;
	pw[0] = fac[0] = 1;
	for (int i = 1; i <= (n << 1); i++) pw[i] = 1ll * pw[i - 1] * inv2 % mod, fac[i] = 1ll * i * fac[i - 1] % mod;
	for (int i = 1; i <= n; i++) cnt[i] = 0;
	for (int i = 1; i <= (n << 1); i++) cin >> a[i], cnt[a[i]]++;
	int num = 0;
	for (int i = 1; i <= n; i++) num += !cnt[i];
