//		for (int j = 0; j <= i; j++)
//			for (int k = 0; k <= num; k++)
//				f[i][j][k] = 0;
	f[0][0][0] = 1;
	for (int i = 0; i < (n << 1); i++) {
		for (int j = 0; j <= i; j++)
			for (int k = 0; k <= num; k++)
				if (f[i][j][k]) {
				//	printf("f(i=%d, j=%d, k=%d) = %d\n", i, j, k, f[i][j][k]);
					int val = f[i][j][k];
					add(f[i + 1][j + !a[i + 1]][k], val);
					
					if (i + 2 <= (n << 1)) {
						if (!a[i + 1] && !a[i + 2]) {
							sub(f[i + 2][j][k + 1], 1ll * val * (num - k) % mod);	
						}
						else if ((!a[i + 1] || !a[i + 2]) && cnt[a[i + 1] + a[i + 2]] == 1) {
							sub(f[i + 2][j][k], val); 
						}
					}
				}
	}
	int ans = 0;
	for (int j = 0; j <= (n << 1); j++)
		for (int k = 0; k <= num; k++)
			if (f[(n << 1)][j][k]) {
				int res = f[(n << 1)][j][k];
				add(ans, 1ll * res * fac[j] % mod * pw[num - k] % mod);
			}
	printf("%d\n", ans);
}

