ll mx[N];
int ans[N];
void bd(int u,int L,int R){
    sgt[u]={L};
    rep(i,L+1,R){
        while(sgt[u].size()>1){
            int x=sgt[u].end()[-2],y=sgt[u].end()[-1];
            if(down(x,y,i))sgt[u].pop_back();
            else break;
        }
        sgt[u].push_back(i);
    }
    if(L==R)return;
    int M=L+R>>1,ls=M<<1,rs=M<<1|1;
    bd(ls,L,M),bd(rs,M+1,R);
}
bool chk(int x,int u){
    int l=0,r=sizc(sgt[u])-1;
    while(l<r){
        int mid=l+r>>1;
        if(down(x,sgt[u][mid],sgt[u][mid+1]))l=mid+1;
        else r=mid;
    }
    return mx[x]==pri(x+1,sgt[u][l]);
}
int src(int u,int L,int R,int x){
    if(R<=x)return -1;
    if(L>x&&!chk(x,u))return -1;
    if(L==R)return L;
    int M=L+R>>1,ls=M<<1,rs=M<<1|1;
    int t=src(ls,L,M,x);
    return t>=0?t:src(rs,M+1,R,x);
}
