void dfs(int v, int d, int &Dead, int &Sz, int &Col) {
	if (is[v] && is[v] > d) return;
	if (used[v]) return;
	int i = v;
	used[v] = 1;
	Dead += dead[v];
	Sz++;
	Col += (is[v] > 0);
	for (int to : g[v]) {
		dfs(to, d, Dead, Sz, Col);
	}
}

int id(int i, int j) {
	return (i - 1) * m + j;
}

bool can(int d) {
	for (int i = 1; i <= n * m; ++i) {
		used[i] = 0;
	}
	for (int i = 1; i <= n * m; ++i) {
		if (is[i] > d && dead[i]) {
			return false;
		}
		if (used[i]) continue;
		int Dead = 0, Sz = 0, Col = 0;
		dfs(i, d, Dead, Sz, Col);
		if (Sz - Dead < Col) {
			return false;
		}
	}
	return true;
}

