	if(u==T||!f)return f;
	int r=0;
	for(int e=ns[u];e;ns[u]=e=nx[e]){
		int v=to[e];
		if(dis[v]==dis[u]+1&&cp[e]){
			int w=dfs(v,min(f,cp[e]));
			cp[e]-=w,cp[e^1]+=w;
			f-=w,r+=w;
			if(!f)break;
		}
	}
	return r;
}

