const int MAXN = 2e4 + 5;
const int inf = 0x3f3f3f3f;

template<const int MAXN,const int MAXM>
struct Max_Flow
{
	struct Edge
	{
		int next,to,flow;
	}e[MAXM<<1];
	int head[MAXN], etot;
	inline void add_one(int u,int v,int flow)
	{
		e[++etot] = (Edge){ head[u],v,flow};
		head[u] = etot;
	}
	inline void add_edge(int u,int v,int flow)
	{
		add_one(u,v,flow); add_one(v,u,0);
	}
	inline void add_edge(int u,int v,int flow,int revflow)
	{
		add_one(u,v,flow); add_one(v,u,revflow);
	}
	
	int n,s,t;
	int dep[MAXN], cur[MAXN];
	inline void clear(void){ etot=-1; memset(head,-1,sizeof(head));}
	inline void init(int _n,int _s,int _t){ n = _n; s = _s; t = _t;}
	Max_Flow(void){ clear();}
	bool bfs(void)
	{
		memset(dep,-1,(n+1)<<2); memcpy(cur,head,(n+1)<<2);
		queue<int> q;
		dep[s] = 0; q.push(s);
		while(q.size())
		{
			int u=q.front(); q.pop();
			for(int i=head[u]; ~i; i=e[i].next) if(e[i].flow)
			{
				int v = e[i].to;
				if(dep[v] == -1)
				{
					dep[v] = dep[u] + 1; q.push(v);
					if(v == t) return 1;
				}
			}
		}
		return 0;
	}
	int dfs(int u,int maxf)
	{
		if(u == t || !maxf) return maxf;
		int res = 0, f;
		for(int &i=cur[u]; ~i; i=e[i].next)
			if(e[i].flow && dep[e[i].to] == dep[u]+1 && (f = dfs(e[i].to, min(maxf, e[i].flow))))
			{
				e[i].flow -= f; e[i^1].flow += f;
				res += f; maxf -= f;
				if(!maxf) return res;
			}
		return res;
	}
	int dinic(void)
	{
		int res = 0;
		while(bfs()) res += dfs(s, inf);
		return res;
	}
};

Max_Flow<MAXN + 10, MAXN * 10> mf;

int n,m,H,V,pcnt;
