int type[MAXN];
vector<int> g[MAXN], g_side[MAXN];

int clr[MAXN];
void dfs_clr(int u,int k)
{
	if(clr[u]) return;
	
	clr[u] = k;
	for(int v: g[u])
		if(type[v])
			dfs_clr(v, k);
	for(int v: g_side[u])
		clr[v] = k;
}

void solve(void)
{
	scanf("%d%d%d%d",&n,&m,&H,&V);
	
	s = vector< string >(n+1);
	for(int i=1; i<=n; ++i)
	{
		static char t[MAXN];
		scanf("%s",t+1);
		s[i] = string(t, t+m+1);
	}
	
	pcnt = 0;
	c = pU = pD = pL = pR = vector< vector<int> >(n+1, vector<int>(m+1));
	for(int i=1; i<=n; ++i)
		for(int j=1; j<=m; ++j)
		{
			int u = ++pcnt, v = ++pcnt;
			
			pL[i][j] = u; pR[i][j] = v;
			
			if(s[i][j] == '/')
				pU[i][j] = u, pD[i][j] = v;
			else
				pU[i][j] = v, pD[i][j] = u;
		}
	
	for(int i=1; i<=n; ++i)
	{
		static char t[MAXN];
		scanf("%s",t+1);
		for(int j=1,k=1; j<=m; ++j, k+=2)
		{
			type[ pL[i][j] ] = t[k] == '#';
			type[ pR[i][j] ] = t[k+1] == '#';
		}
	}
	
	for(int i=1; i<=n; ++i)
		for(int j=1; j<=m; ++j)
			scanf("%d",&c[i][j]);
	
	vector< array<int,3> > e_side;
	for(int i=1; i<=pcnt; ++i)
	{
		g[i].clear();
		g_side[i].clear();
	}
	
	for(int i=0; i<=n; ++i)
		for(int j=0; j<=m; ++j)
		{
			vector<int> vec;
			auto push = [&] (int t)
			{
				for(auto v: vec)
				{
					g[t].emplace_back(v);
					g[v].emplace_back(t);
				}
				vec.emplace_back(t);
			};
			if(i && j) push(pR[i][j]), push(pD[i][j]);
			if(i && j<m) push(pL[i][j+1]), push(pD[i][j+1]);
			if(i<n && j) push(pR[i+1][j]), push(pU[i+1][j]);
			if(i<n && j<m) push(pL[i+1][j+1]), push(pU[i+1][j+1]);
		}
	
	for(int i=1; i<=n; ++i)
		for(int j=1; j<=m; ++j)
		{
			auto add_edge = [&] (int u,int v,int w)
			{
				e_side.push_back({u, v, w});
				g_side[u].emplace_back(v);
				g_side[v].emplace_back(u);
			};
			
			add_edge(pL[i][j], pR[i][j], c[i][j]);
			if(i<n)
				add_edge(pD[i][j], pU[i+1][j], H);
			if(j<m)
				add_edge(pR[i][j], pL[i][j+1], V);
		}
	
	memset(clr, 0, sizeof(clr));
	
	int ccnt = 0;
	for(int i=1; i<=pcnt; ++i)
		if(type[i] && !clr[i])
		{
			++ccnt;
			dfs_clr(i, ccnt);
		}
	int useful = ccnt;
	
	for(int i=1; i<=pcnt; ++i)
		if(!clr[i])
			clr[i] = ++ccnt;
	
	vector<int> ans;
	for(int rt=1; rt<=useful; ++rt)
	{
		mf.clear();
		
		int S = ccnt + 1, T = ccnt + 2;
		mf.init(T, S, T);
		
		for(auto t: e_side)
		{
			int u = clr[t[0]], v = clr[t[1]];
			if(u == v) continue;
			
			mf.add_edge(u, v, t[2], t[2]);
		}
		
		for(int i=1; i<=n; ++i)
		{
			mf.add_edge(clr[ pL[i][1] ], T, V, V);
			mf.add_edge(clr[ pR[i][m] ], T, V, V);
		}
		for(int i=1; i<=m; ++i)
		{
			mf.add_edge(clr[ pU[1][i] ], T, H, H);
			mf.add_edge(clr[ pD[n][i] ], T, H, H);
		}
		
		for(int i=1; i<=useful; ++i)
		{
			if(i == rt)
				mf.add_edge(S, i, inf, 0);
			else
				mf.add_edge(i, T, inf, 0);
		}
		
		ans.emplace_back(mf.dinic());
	}
	
	sort(ans.begin(), ans.end());
	
	printf("%d\n",(int)ans.size());
	for(auto t: ans)
		printf("%d ",t);
	printf("\n");
}

