  nup[v] -= ndown[v];
}

array<int, 2> solve(int v) {
  comp = {};
  dfs(v, v);
  if (~sz[v] % 2) return {};
  bool ok = 0;
  for (auto v: comp) {
    int cpar = 0, nodd = 0;
    for (auto u: adj[v]) {
      cpar += u == par[v];
      u = max(u, ~u);
      if (tup[u] >= tin[v] && v == par[u] && (sz[u] - ddown[u]) % 2 && mark[u] != v) ++nodd;
      mark[u] = v;
    }
    for (auto& u: adj[v]) if (u >= 0 && u != par[u] && mark[par[u]] == v && par[par[u]] != v && (nup[u] > 2 || tin[u] < tin[v] == sz[u] % 2)) return {};
    if (int u = par[v]; !cpar && u != v && u != par[u] && mark[par[u]] == v && (ddown[v] > 1? nup[u] > 2 || sz[u] % 2: (nup[v] > 2 || ~sz[v] % 2) && (nup[u] > nup[v] || (sz[u] - sz[v]) % 2))) return {};
    ok |= nodd + 3 <= adj[v].size();
  }
  for (auto a: comp)
  for (auto b: adj[a]) if (b >= 0 && adj[b].size() <= adj[a].size() && (mark[b] = a + N, 1))
  for (auto c: adj[b]) if (c >= 0 && mark[c] == a + N) return {};
  return {!ok, ok};
}

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int n, h; cin >> n >> h;
  for (int i = 0, a, b; i < n; ++i) cin >> a >> b, adj[--a].push_back(--b), adj[b].push_back(a);
  fill(mark, mark + N, -1);
  int a{}, b{};
  for (int i = 0; i < h; ++i) if (!tin[i]) {
    auto [c, d] = solve(i);
    a += c, b += d;
  }
  cout << a << ' ' << b;
}

