struct Line {
	int y, s, t;
};

struct Interval {
	int s, t, id;
	bool operator <(const Interval &o) const {
		return s==o.s ? t<o.t : s<o.s;
	}
};

void solve(int Test) {
	int n, q;
	cin>>n>>q;
	vector<Line> f(q+1);
	vector<int> ys={1, n};//for lsh
	For(i, 1, q) {
		cin>>f[i].y>>f[i].s>>f[i].t;
		ys.push_back(f[i].y);
		if(f[i].y>1) ys.push_back(f[i].y-1);
		if(f[i].y<n) ys.push_back(f[i].y+1);
	}
	//
	// if(Test==9) {
	// 	cerr<<n<<'\n';
	// 	For(i, 1, q) {
	// 		cerr<<f[i].y<<' '<<f[i].s<<' '<<f[i].t<<'\n';
	// 	}
	// }
	//
	sort(ys.begin(), ys.end());
	ys.erase(unique(ys.begin(), ys.end()), ys.end());
	int m=ys.size();//effective number of columns
	vector bd(m+1, set<int>());
	vector br(m+1, set<pair<int, int>>());
#define Findy(y) (lower_bound(ys.begin(), ys.end(), y)-ys.begin()+1)
	For(i, 1, q) {
		auto [y, s, t]=f[i];
		y=Findy(y);
		For(_y, y-1, y+1) if(_y>=1 && _y<=m) {
			For(_s, s-1, s+1) if(_s>=1 && _s<=n) {
				bd[_y].insert(_s);
			}
			For(_t, t, t+2) if(_t>=1 && _t<=n) {
				bd[_y].insert(_t);
			}
		}
		br[y].insert({s, t});
	}
	//
	debug("build bounds and barriers\n");
	//
	vector I(m+1, set<Interval>());
	vector<int> cnt={0};
	int tot=0;
	For(i, 1, m) {
		bd[i].insert(1);
		bd[i].insert(n+1);
		for(auto it=bd[i].begin(); ;) {
			int s=*it;
			int t=*(++it);
			auto test=br[i].lower_bound({t, -1});
			bool flag=true;
			if(test!=br[i].begin()) {
				auto [l, r]=*--test;
				if(l<=t-1 && s<=r) flag=false;
			}
			if(flag) {
				I[i].insert({s, t-1, ++tot});
				cnt.push_back({t-s});
			}
			if(t==n+1) break;
		}
	}
	//
	debug("get intervals:\n");
	For(i, 1, m) {
		debug("y=%d\n", i);
		for(auto t:I[i]) {
			debug("%d %d %d\n", t.s, t.t, t.id);
		}
	}
	//
	vector g(tot+1, vector<int>());
	map<pair<int, int>, bool> vis;
	auto add=[&](int u, int v)->void {
		if(!vis.count({u, v}) && !vis.count({v, u})) {
			g[u].push_back(v), g[v].push_back(u);
			vis[{u, v}]=true;
		}
	};
	For(i, 1, m) {
		for(auto it=I[i].begin(); it!=I[i].end(); it++) {
			auto nx=it;
			if(nx!=I[i].end()) {
				++nx;
				if(it->t+1==nx->s) {
					add(it->id, nx->id);
				}
			}
			for(auto j:{i-1, i+1}) if(j>=1 && j<=m) {
				auto jt=I[j].lower_bound({it->s, -1, -1});
				for(; jt!=I[j].end(); jt++) {
					if(jt->s>it->t) break;
					add(it->id, jt->id);
				}
			}
		}
	}
	//
	debug("the graph:\n");
	For(i, 1, tot) {
		for(auto j:g[i]) if(i<j)
			debug("%d %d\n", i, j);
	}
	//
	vector<int> dfn(tot+1), low(tot+1);
	int dft=0;
	LL ans=0;
	function<void(int, int)> tarjan=[&](int u, int fa)->void {
		dfn[u]=low[u]=++dft;
		int fork=0;
		for(auto v:g[u]) if(v!=fa) {
			if(!dfn[v]) {
				tarjan(v, u);
				low[u]=min(low[u], low[v]);
				if(low[v]>=dfn[u]) {
					fork++;
				}
			}
			else {
				low[u]=min(low[u], dfn[v]);
			}
		}
		if(fork>1 || (fork>0 && fa!=0)) {
			ans+=cnt[u];
		}
	};
	tarjan(1, 0);
	cout<<ans<<'\n';
}

