const int mod = 998244353;
int inc(int x, int y) { return (x += y) >= mod ? x - mod : x; }
int dec(int x, int y) { return (x -= y) < 0 ? x + mod : x; }
int mul(int x, int y) { return 1ll * x * y % mod; }

const int N = 1e6;
int fac[N + 3], ifac[N + 3], inv[N + 3];

int C(int x, int y) {
	if (y < 0 || y > x) return 0;
	return mul(fac[x], mul(ifac[y], ifac[x - y]));
}

void solve() {
	int n, k;
	cin >> n >> k;
	--n; --k;
	vector<int> f(n + 3, 0), g(n + 3, 0);
	f[0] = g[0] = 1;
	for (int i = 1; i <= n; ++i) {
		f[i] = dec(g[i - 1], i - k - 1 >= 0 ? g[i - k - 1] : 0);
		g[i] = inc(g[i - 1], f[i]);
	}

	int ans = 0;
	for (int i = 0; i <= n; ++i) {
		ans = inc(ans, mul(C(n, i), f[n - i]));
	}
	ans = mul(ans, 2);
	cout << dec(ans, 1) << "\n";
}
