#include <bits/stdc++.h>
int N,R,qq,st[200009],kk;
struct n_t{
	int x,y;
} f[200009],dd[400009];
bool cmp1(n_t x,n_t y) {
	if(x.x!=y.x) return x.x<y.x;
	return x.y<y.y;
}
bool cmp2(n_t x,n_t y) {
	if(x.x!=y.x) return x.x<y.x;
	return x.y>y.y;
}
signed main(void) {
	long double pai=asinl(1.0)*2;
	scanf("%d %d",&N,&R);
	int gg=1;
	for(int i=1;i<=N;i++) {
		scanf("%d %d",&f[i].x,&f[i].y);
		if(f[i].x!=f[1].x) gg=0;
	}
	if(gg) {
//		printf("%.12Lf\n",pai);
		printf("%.12Lf",((long double)R)*R*pai/2);
		return 0;
	}
	N++;
	std::sort(f+1,f+N+1,cmp1);
	for(int i=1;i<=N;i++) {
		if(i>1&&f[i].x==f[i-1].x) continue;
		while(kk>=2&&1ll*(f[i].y-f[st[kk]].y)
			*(f[st[kk]].x-f[st[kk-1]].x)<=1ll*(f[i].x-f[st[kk]].x)
			*(f[st[kk]].y-f[st[kk-1]].y)) {
			kk--;
		}
		st[++kk]=i;
	}
	for(int i=1;i<=kk;i++) {
		dd[++qq]=f[st[i]];
	}
	std::sort(f+1,f+N+1,cmp2);kk=0;
	for(int i=1;i<=N;i++) {
		if(i>1&&f[i].x==f[i-1].x) continue;
		while(kk>=2&&1ll*(f[i].y-f[st[kk]].y)
			*(f[st[kk]].x-f[st[kk-1]].x)>=1ll*(f[i].x-f[st[kk]].x)
			*(f[st[kk]].y-f[st[kk-1]].y)) {
			kk--;
		}
		st[++kk]=i;
	}
	for(int i=kk;i>=1;i--) {
		dd[++qq]=f[st[i]];
	}
	long double as=R;
	for(int i=1;i<=qq;i++) {
		n_t x=dd[i],y=dd[i%qq+1];
		if(x.x==y.x&&x.y==y.y) continue;
	//	printf("%d %d %d %d\n",x.x,x.y,y.x,y.y);
		long long siz=1ll*x.x*y.y-1ll*y.x*x.y;
		if(siz<0) siz=-siz;
		long double di=sqrtl((long double)1ll*(x.x-y.x)*(x.x-y.x)+
			1ll*(x.y-y.y)*(x.y-y.y));
//		printf("%d %d %d %.12Lf\n",x,y,siz,di);
		long double aq=siz/di;
	//	printf("%.12Lf\n",aq);
		if(as>aq) as=aq;
	}
//	printf("%.12Lf\n",as);
	long double di2=sqrtl((long double)(1ll*R*R-as*as));
	//printf("%.12Lf %lld\n",di2,R);
	printf("%.12Lf\n",1ll*R*R*acosl(as/R)-as*di2);
}

