void pushup(int x){
    tr[x]=min((ll)2e18,tr[x<<1]+tr[x<<1|1]);
    sm[x]=sm[x<<1]+sm[x<<1|1];
}
void build(int x,int l,int r){
    if(l==r){
        tr[x]=p[l];
        sm[x]=a[h[l]];
        return;
    }
    int mid=l+r>>1;
    build(x<<1,l,mid);
    build(x<<1|1,mid+1,r);
    pushup(x);
}
void modify(int x,int l,int r,int p){
    if(l==r){
        tr[x]=sm[x]=0;
        return;
    }
    int mid=l+r>>1;
    if(p<=mid) modify(x<<1,l,mid,p);
    else modify(x<<1|1,mid+1,r,p);
    pushup(x);
}
tuple<int,ll,ll> qry(int x,int l,int r,int L,ll P){ // return (end,sumP,sumH)
    // cerr<<x<<" "<<l<<" "<<r<<" "<<L<<" "<<P<<'\n';
    if(l==r){
        if(tr[x]>P) return {l,0,0};
        else return {-1,tr[x],sm[x]};
    }
    if(L<=l&&tr[x]<=P) return {-1,tr[x],sm[x]};
    int mid=l+r>>1;
    if(L>mid) return qry(x<<1|1,mid+1,r,L,P);
    auto [a,y,z]=qry(x<<1,l,mid,L,P);
    if(a==-1){
        auto [u,v,w]=qry(x<<1|1,mid+1,r,L,P-y);
        return {u,y+v,z+w};
    }else return {a,y,z};
}
ll calc(){
    ll P=m,cur=1,sm=0;
    while(1){
        //find next cur -> binary search which pi <= P
        int L=cur,R=n,res=n+1;
        while(L<=R){
            int mid=L+R>>1;
            if(p[mid]<=P) res=mid,R=mid-1;
            else L=mid+1;
        }
        if(res==n+1) break;
        cur=res;
        //find whole segment binary search on seg where sm<=P and return (pos,happyness)
        auto [x,y,z]=qry(1,1,n,cur,P);
        // cerr<<x<<" "<<y<<" "<<z<<'\n';
        cur=((x==-1)?n+1:x);
        P-=y;
        sm+=z;
    }   
    return sm;
}
