void ins(int ct,int val,int pos){
    if(val>=1e5) return;
    while(1){
        auto it=s[ct].lower_bound({val,0});
        if(it==s[ct].end()) break;
        if(a[pos]>=a[it->second]){
            s[ct].erase(it);
        }else break;
    }
