    if(it!=s[ct].end()&&it->first==val&&a[pos]<=a[it->second]) fl=0;
    if(it!=s[ct].begin()){
        --it;
        if(a[pos]<=a[it->second]) fl=0;
    }
    if(fl) s[ct].insert({val,pos});
}
