    if(!x) x=++cntn,mn[x]=4e18;
    mn[x]=min(mn[x],v);
    if(l==r) return;
    ll mid=l+r>>1;
    if(p<=mid) modify(ls[x],l,mid,p,v);
    else modify(rs[x],mid+1,r,p,v);
}
ll qry(int x,ll l,ll r,ll L,ll R){
    if(!x) return 4e18;
    if(L<=l&&r<=R) return mn[x];
    ll mid=l+r>>1,res=4e18;
    if(L<=mid) res=min(res,qry(ls[x],l,mid,L,R));
    if(R>mid) res=min(res,qry(rs[x],mid+1,r,L,R));
    return res;
}
