        this -> x = x;
        this -> y = y;
    }
};
bool operator< (Point p1, Point p2){
    return (p1.h > p2.h);
}

struct Node{
    int fen[MAXN];

    Node (){
        memset(fen, 0, sizeof(fen));
    }

    void upd(int x){
        for(; x < MAXN; x += (x & -x)){
            fen[x]++;
        }
    }
    int get(int x){
        if(!x){
            return 0;
        }
        int res = 0;
        for(; x > 0; x -= (x & -x)){
            res += fen[x];
        }
        return res;
    }
    int Res(int y1, int y2){
        return get(y2) - get(y1 - 1);
    }
};
