#include <bits/stdc++.h>
using namespace std;
using ll=long long;
const int INF=1e9;
const int N=1e5+5;
int st[N<<2],tag[N<<2];
void pushdown(int rt)
{
    if(!tag[rt])return;
    st[rt<<1]+=tag[rt];
    st[rt<<1|1]+=tag[rt];
    tag[rt<<1]+=tag[rt];
    tag[rt<<1|1]+=tag[rt];
    tag[rt]=0;
}
int query(int rt,int l,int r,int x,int y)
{
    if(y<l||r<x)return INF;
    if(x<=l&&r<=y)return st[rt];
    int mid=(l+r)>>1;
    pushdown(rt);
    return min(query(rt<<1,l,mid,x,y),query(rt<<1|1,mid+1,r,x,y));
}
void update(int rt,int l,int r,int x,int y)
{
    if(y<l||r<x)return;
    if(x<=l&&r<=y){st[rt]++;tag[rt]++;return;}
    int mid=(l+r)>>1;
    pushdown(rt);
    update(rt<<1,l,mid,x,y);
    update(rt<<1|1,mid+1,r,x,y);
    st[rt]=min(st[rt<<1],st[rt<<1|1]);
}
