struct State
{
    int x,y;
    int top,bottom,left,right,front,back;
    bool operator <(const State &rhs)const
    {
        if(x!=rhs.x)return x<rhs.x;
        if(y!=rhs.y)return y<rhs.y;
        if(top!=rhs.top)return top<rhs.top;
        if(bottom!=rhs.bottom)return bottom<rhs.bottom;
        if(left!=rhs.left)return left<rhs.left;
        if(right!=rhs.right)return right<rhs.right;
        if(front!=rhs.front)return front<rhs.front;
        return back<rhs.back;
    }
    State east()
    {
        return {x,y+1,left,right,bottom,top,front,back};
    }
    State west()
    {
        return {x,y-1,right,left,top,bottom,front,back};
    }
    State north()
    {
        return {x-1,y,front,back,left,right,bottom,top};
    }
    State south()
    {
        return {x+1,y,back,front,left,right,top,bottom};
    }
};
