    {
        ll mask=0;
        for(int j=i;j<n;j++)
        {
            mask|=(1ll<<a[j]);
            int len=j-i+1;
            if(!mp.count(mask))mp[mask]=len;
            else mp[mask]=min(mp[mask],len);
        }
    }
    vector<pair<int,ll>>sol;
    for(auto &&[x,y]:mp)sol.push_back({y,x});
    sort(sol.begin(),sol.end());
    int ans=n;
    ll tar=(1ll<<m)-1;
    for(int i=0;i<sol.size();i++)
        for(int j=i;j<sol.size()&&sol[i].first+sol[j].first<ans;j++)
            if((sol[i].second|sol[j].second)==tar)
                ans=min(ans,sol[i].first+sol[j].first);
    cout<<ans<<"\n";
    return 0;
}

