void process(){
    int n, m;
    cin >> n >> m;
    vector<vector<int>> up(n, vector<int>(m)), down(up), left(up), right(up), a(up);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            up[i][j] = -1;
            for (int k = i - 1; ~k; --k) {
                if (a[k][j] < a[i][j]) {
                    up[i][j] = k;
                    break;
                }
            }
            down[i][j] = n;
            for (int k = i + 1; k < n; ++k) {
                if (a[k][j] < a[i][j]) {
                    down[i][j] = k;
                    break;
                }
            }
            left[i][j] = -1;
            for (int k = j - 1; ~k; --k) {
                if (a[i][k] < a[i][j]) {
                    left[i][j] = k;
                    break;
                }
            }
            right[i][j] = m;
            for (int k = j + 1; k < m; ++k) {
                if (a[i][k] < a[i][j]) {
                    right[i][j] = k;
                    break;
                }
            }
        }
    }
    long long res = 0;
    for (int r1 = 0; r1 < n; ++r1) {
        vector<int> f(m, -1);
        vector<vector<array<int, 2>>> events(n);
        for (int r2 = r1; r2 < n; ++r2) {
            for (int j = 0; j < m; ++j) {
                if (up[r2][j] >= r1 and down[r2][j] < n) {
                    events[down[r2][j]].push_back({left[r2][j], right[r2][j]});
                }
            }
            for (auto [l, r] : events[r2]) {
                if (r < m) {
                    f[r] = max(f[r], l);
                }
            }
            int Max = -1;
            for (int j = 0; j < m; ++j) {
                Max = max(Max, f[j]);
                res += j - Max;
            }
        }
    }
    cout << res << "\n";
}

