class Codechef {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] nums = new int[n];

        for (int i = 0; i < n; i++) {
            nums[i] = sc.nextInt();
        }

        long min = Integer.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            long next = 0;
            long counter = 0;
            for (int j = i - 1; j > -1; j--) {
                double x = Math.floor(1 + (double) next / nums[j]);
                counter += x;
                next = (long)(nums[j] * x);
            }
            next = 0;
            for (int j = i + 1; j < n; j++) {
                double x = Math.floor(1 + (double) next / nums[j]);
                counter += x;
                next = (long)(nums[j] * x);
            }

            min = Math.min(min, counter);
        }

        System.out.println(min);
    }
}

