double query(int tmpk){
	double ans=0;
	for (int l=1,r;l<=n;l=r+1){
		ll tmp=h[l]/tmpk;r=l;int d=0;
		while (l+(1<<d)<=n&&h[l+(1<<d)]/tmpk==tmp) d++;
