void dij(int x,int y) {
	x+=n*n,y+=n*n;
	memset(dis,0x3f,sizeof(dis));
	dis[x][y]=0;
	Q[0].pb({x,y});
	for(int d=0,j=0; d<K&&j<m*m; ++d) {
		while(Q[d].size()) {
			auto [u,v]=Q[d].back();
			Q[d].pop_back();
			if(d!=dis[u][v]) continue;
			fo(i,0,3) {
