	bool operator <(const frac p)const{
		return (__int128)A*p.B>(__int128)p.A*B||((__int128)A*p.B==(__int128)p.A*B&&i>p.i)||((__int128)A*p.B==(__int128)p.A*B&&i==p.i&&j>p.j);
	}
