long long w;
long long ans=0;

long long dfs()
{
	int n;
	long long no;
	cin>>no>>n;
	long long sum=0;
	priority_queue<long long>q;
	for(int i=1;i<=n;i++)
	{
		long long t=dfs();
		q.push(t);
		sum+=t;
	}
	while(sum>w)
	{
		ans++;
		sum-=q.top();
		q.pop();
	}
	no+=sum;
	ans+=no/w;
	no%=w;
	return no;
}

