void gauss()
{
    double d;
    for (int i=1;i<=c;++i)
    {
	for (int j=i+1;j<=c;++j)
	    if (abs(G[i][i])<eps&&abs(G[j][i])>=eps)
	    {
		swap(G[i],G[j]),swap(H[i],H[j]);
		break;
	    }
	for (int j=i+1;j<=c;++j)
	{
	    d=G[j][i]/G[i][i];
	    for (int k=1;k<=c;++k) G[j][k]-=G[i][k]*d,H[j][k]-=H[i][k]*d;
	}
    }
    for (int i=c;i>=1;--i)
    {
	for (int j=i+1;j<=c;++j)
	{
	    d=G[i][j];
	    for (int k=1;k<=c;++k) G[i][k]-=G[j][k]*d,H[i][k]-=H[j][k]*d;
	}
	d=G[i][i];
	for (int j=1;j<=c;++j) G[i][j]/=d,H[i][j]/=d;
    }
    return;
}
