struct frac{
	__int128 p,q;
	frac(ll x,ll y){p=x,q=y;}
};
bool operator < (frac x,frac y){
	return x.p*y.q<x.q*y.p;
}
bool operator <= (frac x,frac y){
	return x.p*y.q<=x.q*y.p;
}
bool operator >= (frac x,frac y){
	return x.p*y.q>=x.q*y.p;
}
frac slope(int x,int y){
	return frac(a[y]-a[x],y-x);
}
struct segt{
vector<int> vec[MAXN<<2];// 维护凸侨
void build(int id=1,int l=1,int r=n){
	int top=-1;
	for(int i=l;i<=r;i++){
		while(top>=1&&slope(vec[id][top],i)<=slope(vec[id][top-1],vec[id][top])){
			vec[id].pop_back();top--;
		}
		top++;vec[id].push_back(i);
	}
	if(l==r) return;
	int mid=l+r>>1;
	build(id<<1,l,mid);build(id<<1|1,mid+1,r);
}
void query(int x,int L,int R,int id=1,int l=1,int r=n){
	if(L<=l&&r<=R){
		int l=0,r=vec[id].size()-1,mid;
		while(l<r){
			mid=l+r>>1;
			if(slope(x,vec[id][mid])<=slope(x,vec[id][mid+1])) r=mid;
			else l=mid+1;
		}
		l=vec[id][l];
		if(a[x]>a[l]) ans=-1;
		else ans=min(ans,(a[l]-a[x])/(l-x));
		return;
	}
	int mid=l+r>>1;
	if(L<=mid) query(x,L,R,id<<1,l,mid);
	if(mid<R) query(x,L,R,id<<1|1,mid+1,r);
}
