bool BFS(int s,int t){
	int Head=0,Tail=0;
	que[++Tail]=s;vis[s]=++ti;dis[s]=0;cur[s]=lnk[s];
	while (Head!=Tail){
		int x=que[++Head];
		for (int j=lnk[x],u;j;j=nxt[j])
			if (vis[u=to[j]]<ti && e[j])
				que[++Tail]=u,vis[u]=ti,dis[u]=dis[x]+1,cur[u]=lnk[u];
	}
	return vis[t]==ti;
}
int DFS(int x,int t,int MIN=2e9){
	if (!MIN || x==t) return MIN;
	int f=0;
	for (int &j=cur[x],u,now;j;j=nxt[j])
		if (dis[x]+1==dis[u=to[j]] && (now=DFS(u,t,min(MIN,e[j])))){
			f+=now;e[j]-=now;e[j^1]+=now;
			if (!(MIN-=now)) break;
		}
	return f;
}
