struct P{double x,y;P(){}constexpr P(const double&x,const double&y):x(x),y(y){}};
inline P calc(const P c,const double r,const double t)
{
	return P(c.x+r*cos(t),c.y+r*sin(t));
}
inline constexpr double sq(const double a){return a*a;}
inline double dis(const P&a,const P&b)
{
	return sqrt(sq(a.x-b.x)+sq(a.y-b.y));
}
constexpr double pi=3.14159265358979324;
void _main()
{
	P a,b,c;cin>>a.x>>a.y>>b.x>>b.y>>c.x>>c.y;
	double R;cin>>R;
	if(dis(a,c)<=R||dis(b,c)<=R)
	{
		printf("%.7lf\n",dis(a,b));
		return ;
	}
	double l=0,r=pi*2;
	while(r-l>1e-7)
	{
		const double m1=(l*2+r)/3,m2=l+r-m1;
		const P p0=calc(c,R,l),p1=calc(c,R,m1),p2=calc(c,R,m2);
		const double d0=dis(p0,a)+dis(p0,b);
		const double d1=dis(p1,a)+dis(p1,b);
		const double d2=dis(p2,a)+dis(p2,b);
		if(d0<d1&&d0<d2)
		{
			l=m2;r=m1+pi*2;
		}
		else if(d1<d0&&d1<d2)
		{
			r=m2;
		}
		else l=m1;
	}
	const P p=calc(c,R,(l+r)/2);
	printf("%.7lf\n",dis(p,a)+dis(p,b));
}
