const int N = 107;
vector<int> zbi[N];
int cap[N];
int wh[N];

void M(int a, int b)
{
	if((int)zbi[a].size() == 0) return;

	cout << a << " " << b << "\n";
	int x = zbi[a].back();
	zbi[a].pop_back();
	zbi[b].pb(x);

	if((int)zbi[b].size() > cap[b])
		cout << "dupa\n";

	wh[x] = b;
}

void Shf(int p, int k, int l)
{
	while((int)zbi[p].size() > l && (int)zbi[k].size() < cap[k])
		M(p, k);
}

int Find(int x)
{
	int s = wh[x];
	for(int i = 0; i < (int)zbi[s].size(); ++i)
		if(zbi[s][i] == x)
			return i;
	return 0;
}

void Empty(int a, int k)
{
	for(int i = a + 1; i <= k; ++i)
		Shf(a, i, 0);
}

void Compress(int a, int k)
{
	int j = k;
	for(int i = a; i <= k; ++i)
	{
		if(i == j) return;
		Shf(j, i, 0);
		while(j > i + 1 && (int)zbi[i].size() < cap[i])
		{
			--j;
			Shf(j, i, 0);
		}
	}
}

void Print(int k)
{
	for(int i = 1; i <= k; ++i)
	{
		cout << "Zbior " << i << " ms: " << cap[i] << ":\n";
		for(int j = 0; j < (int)zbi[i].size(); ++j)
			cout << zbi[i][j] << " ";
		cout << "\n"; 
	}
	cout << "\n";
}

void Solve()
{
	int n, k, a;
	cin >> n >> k;
	for(int i = 1; i <= k; ++i)
	{
		cin >> cap[i];
		for(int j = 1; j <= cap[i]; ++j)
		{
			cin >> a;
			wh[a] = i;
			if(a != 0)
				zbi[i].pb(a);
		}
	}
	int l = 1;
	Empty(1, k);
	// Print(k);
	for(int i = 1; i <= n; ++i)
	{
		if(cap[l] == (int)zbi[l].size())
		{
			++l;
			Empty(l, k);
		}
		int z = wh[i], pos = Find(i);
		int z2 = z - 1;
		int il = (int)zbi[l].size();
		// cout << "\nDo: " << i << " " << z << " " << pos << " l: " << l << "\n";
		// Print(k);

		if(z == l + 1)
			z2 = z + 1;
		if(z2 > k)
			z2 = z - 2;
		for(int j = k; j > z; --j)
			Shf(z, j, pos + 1);
		Shf(z, l, pos + 1);

		bool xd = 0;
		if((int)zbi[z2].size() > 0)
			xd = 1;

		M(z2, l);
		M(z, z2);
		Shf(l, z, il);
		M(z2, l);

		if(xd)
		{
			Shf(z, l, pos + 1);
			M(z, z2);
			Shf(l, z, il + 1);
		}

		Compress(l + 1, k);
	}
	cout << 0 << " " << 0 << "\n";
	// Print(k);
}

int main(){

	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	Solve();

	return 0;
}

