void build(int u,int l,int r){
	if(l==r) return (void)(in[u]=ot[u]=l);
	int m=(l+r)/2;
	build(u*2,l,m),build(u*2+1,m+1,r);
	in[u]=++k,ot[u]=++k;
	add(ot[u*2],ot[u]),add(ot[u*2+1],ot[u]);
	add(in[u],in[u*2]),add(in[u],in[u*2+1]);
}
void link(int u,int l,int r,int L,int R,int k){
	if(L<=l&&r<=R) return (void)(k>0?add(ot[u],k):add(-k,in[u]));
	int m=(l+r)/2;
	if(L<=m) link(u*2,l,m,L,R,k);
	if(R>m) link(u*2+1,m+1,r,L,R,k);
}
void tarjan(int u){
	low[u]=dfn[u]=++tot,ins[u]=1,stk[++top]=u;
	for(int v:G[u]){
		if(!dfn[v]) tarjan(v),low[u]=min(low[u],low[v]);
