    vector <int> bricks(nbBricks);

    for (int i = 0; i < nbBricks; i ++)
    {
        int a; cin >> a;
        bricks[i] = a;
    }
    sort(all(bricks));
    bricks.resize(unique(all(bricks)) - bricks.begin());

    int last = 0;
    for (int cur : bricks)
    {
        if (!(length % cur))
        {
            if (cur == length)
                last = cur;
            if (last)
            {
                cout << "possible\n";
                int d = __gcd(last, cur);
                int l = last * cur / d;
                if (l == length)
                {
                    cout << length / last << "\n";
                    for (int j = 0; j < length / last; j ++)
                        cout << last << " ";
                    cout << "\n" << length / cur << "\n";
                    for (int j = 0; j < length / cur; j ++)
                        cout << cur << " ";
                    cout << "\n";
                    return;
                }
                cout << length / cur << "\n";
                for (int j = 0; j < length / cur; j ++)
                    cout << cur << " ";
                cout << "\n" << (length - l) / cur + l / last << "\n";
                for (int j = 1; j < l / last; j ++)
                    cout << last << " ";
                for (int j = 0; j < (length - l) / cur; j ++)
                    cout << cur << " ";
                cout << last << "\n";
                return;
            }
            else
                last = cur;
        }
    }

    bitset <(int)(3e5 + 1)> dp;
    dp[0] = 1;
    for (int b : bricks)
        for (; b <= length; b <<= 1)
            dp |= dp << b;
    
    if (!dp[length])
    {
        cout << "impossible\n";
        return;
    }

    vector <int> sol;
    int cur = length;

    reverse(all(bricks));

    for (int b : bricks)
        while (b != last && cur >= b && dp[cur - b])
        {
            cur -= b;
            sol.push_back(b);
        }
    
    if (last)
    {
        while (cur >= last && dp[cur - last])
        {
            cur -= last;
            sol.push_back(last);
        }
    }

    sort(all(sol));
    reverse(all(sol));

    if (cur)
    {
        cout << "impossible\n";
        return;
    }

    dbg(sol);

    int mini = sol.back();
    last = 0;
    for (int b : sol)
        if (b > mini)
            last = b;
    
    if (!last)
    {
        cout << "impossible\n";
        return;
    }

    cout << "possible\n";

    cout << size(sol) << "\n" << last << " ";
    int f = 0;
    for (int b : sol)
        if (b > last || (f ++))
            cout << b << " ";
    cout << "\n" << size(sol) << "\n" << mini << " ";
    f = 0;
    for (int b : sol)
        if (b > last)
            cout << b << " ";
    for (int b : sol)
        if (b == mini && (f ++))
            cout << b << " ";
    for (int b : sol)
        if (b == last)
            cout << b << " ";
    cout << "\n";
    return;
}

