void exgcd(int a,int b,int &x,int &y)
{
	if(!b)
	{
		x=1;y=0;
		return;
	}
	exgcd(b,a%b,y,x);
	y-=a/b*x;
}
int inv(int b,int mod)
{
	int x,y;
	exgcd(b,mod,x,y);
	return (x%mod+mod)%mod;
}
