#define all(x) (x).begin(), (x).end()
#define sz(x) (x).size()

struct pt {
  int x, y;
  explicit pt(int x=0, int y=0) : x(x), y(y) {}
  bool operator<(const pt &p) const { return tie(x,y) < tie(p.x,p.y); }
  bool operator==(const pt &p) const { return tie(x,y) == tie(p.x,p.y); }
};

bool sort_x(const pt &p, const pt &q){ return p.x < q.x; }
bool sort_y(const pt &p, const pt &q){ return p.y < q.y; }

int main(){
  vector<pt> p(5);
  for(int i = 0; i < 5; i++)
    cin >> p[i].x >> p[i].y;

  int ans = 0, n = 5;

  // shrink
  while(1){
    set<pt> s(all(p));
    p.assign(all(s));
    n = sz(p);
    if(n == 1) break;
    sort(all(p), sort_x);
    // l
    if(p[0].x < p[1].x){
      ans += p[1].x - p[0].x;
      p[0].x = p[1].x;
      continue;
    }
    // r
    if(p[n-2].x < p[n-1].x){
      ans += p[n-1].x - p[n-2].x;
      p[n-1].x = p[n-2].x;
      continue;
    }

    sort(all(p), sort_y);
    // u
    if(p[0].y < p[1].y){
      ans += p[1].y - p[0].y;
      p[0].y = p[1].y;
      continue;
    }
    // b
    if(p[n-2].y < p[n-1].y){
      ans += p[n-1].y - p[n-2].y;
      p[n-1].y = p[n-2].y;
      continue;
    }

    break;
  }

  if(n >= 4){
    // add rectangle
    int x[2], y[2];
    sort(all(p), sort_x);
    x[0] = p[0].x; x[1] = p[n-1].x;
    sort(all(p), sort_y);
    y[0] = p[0].y; y[1] = p[n-1].y;
    ans += 2*(x[1]-x[0]+y[1]-y[0]);

    // add cross
    for(pt q : p)
      if(x[0] < q.x && q.x < x[1]
            && y[0] < q.y && q.y < y[1])
        ans += min(x[1]-x[0], y[1]-y[0]);
  }

  cout << ans << endl;

}

