const int n = 1e6+2;
int sieve[n] = {0};
ll acc[n] = {0};

int main(){
    for( int i = 2; i < n; i++ ){
        if( sieve[i] == 0 ){
            for( int j = i; j < n; j += i ){
                sieve[j] = i;
            }
        }
    }

    for( int p = 2; p < n; p++ ){
        vector<int> exp;
        int q = p;
        while( q > 1 ){
            int t = sieve[q];
            int cnt = 0;
            while( q%t == 0 ){
                cnt++;
                q /= t;
            }
            exp.push_back(cnt);
        }

        int s = exp.size();
        ll prod = 1;
        for( int e: exp ) prod *= e;

        ll tot = prod<<(2*s);
        ll adj = 2;
        int flag = 1;
        for( int e: exp ){
            if( e%3 > 0 ) flag = 0;
        }
        adj += flag*4;
        flag = 1;
        for( int e: exp ){
            if( e%2 > 0 ) flag = 0;
        }
        adj += flag*2;
        tot -= adj<<s;
        for( int k = p; k < n; k += p ){
            acc[k] += tot;
        }
    }

    for( int i = 0; i < n-1; i++ ){
        acc[i+1] += acc[i];
    }

    int t; cin >> t;
    while(t--){
        ll z; cin >> z;
        ll cbrt = 0;
        for( ll jump = 1<<20; jump > 0; jump /= 2 ){
            ll nw = cbrt+jump;
            if( nw*nw*nw <= z ){
                cbrt = nw;
            }
        }
        cout << acc[cbrt] << "\n";
    }
}

