struct Point {
	int x, y;
};

struct Line {
	Point p1, p2;
};

void rotate_point(Point& p) {
	std::swap(p.x, p.y);
	p.y = -p.y;
}

void rotate_lines(std::vector<Line>& lines) {
	for (Line& l : lines) {
		rotate_point(l.p1);
		rotate_point(l.p2);
		if (l.p1.x > l.p2.x || l.p1.y > l.p2.y) {
			std::swap(l.p1, l.p2);
		}
	}
}

// types:
//  1: add vertical line
//  2: remove vertical line
//  3: process horizontal line
struct Event {
	int type, y, line_id;
};

bool has_square_from_upwards_u(int n, const std::vector<Line>& lines) {
	// store pairs (right-x-coordinate, line index)
	std::map<int, std::set<std::pair<int, int>>> horizontal_by_y;

	std::vector<int> line_ids_by_length(n);

	for (int i = 0; i < n; ++i) {
		Line l = lines[i];
		if (l.p1.y == l.p2.y) {
			horizontal_by_y[l.p1.y].insert({l.p2.x, i});
		}
		line_ids_by_length[i] = i;
	}

	auto get_length = [&](int i) -> int {
		return lines[i].p2.x - lines[i].p1.x + lines[i].p2.y - lines[i].p1.y;
	};

	std::sort(line_ids_by_length.begin(), line_ids_by_length.end(), [&](int i1, int i2) {
		return get_length(i1) > get_length(i2);
	});

	auto find = [&](int need_len, std::vector<int> bad_ids) -> bool {
		for (int i : line_ids_by_length) {
			if (get_length(i) < need_len) {
				return false;
			}
			if (std::find(bad_ids.begin(), bad_ids.end(), i) == bad_ids.end()) {
				return true;
			}
		}
		return false;
	};

	auto check = [&](int base_id, int side1_id, int side2_id) -> bool {
		if (lines[side1_id].p1.x > lines[side2_id].p1.x) {
			std::swap(side1_id, side2_id);
		}

		int len = lines[side2_id].p1.x - lines[side1_id].p1.x;

		int x1 = lines[side1_id].p1.x;
		int x2 = x1 + len;

		int y1 = lines[base_id].p1.y;
		int y2 = y1 + len;

		if (lines[side1_id].p2.y < y2) return false;
		if (lines[side2_id].p2.y < y2) return false;

		if (find(len, {base_id, side1_id, side2_id})) return true;

		auto it1 = horizontal_by_y[y2].lower_bound({x1, 0});
		auto it2 = horizontal_by_y[y2].lower_bound({x2, 0});

		int top_left_id = -1;
		int top_right_id = -1;

		if (it1 != horizontal_by_y[y2].end() && lines[it1->second].p1.x <= x1) {
			top_left_id = it1->second;
		}

		if (it2 != horizontal_by_y[y2].end() && lines[it2->second].p1.x <= x2) {
			top_right_id = it2->second;
		}

		if (top_left_id != -1) {
			if (find(x2 - lines[top_left_id].p2.x, {base_id, side1_id, side2_id, top_left_id})) {
				return true;
			}
		}

		if (top_right_id != -1) {
			if (find(lines[top_right_id].p1.x - x1, {base_id, side1_id, side2_id, top_right_id})) {
				return true;
			}
		}

		if (top_left_id != -1 && top_right_id != -1) {
			std::vector<int> bad_ids = {base_id, side1_id, side2_id, top_left_id, top_right_id};
			if (find(lines[top_right_id].p1.x - lines[top_left_id].p2.x, bad_ids)) {
				return true;
			}
		}

		return false;
	};

	std::vector<Event> events;

	for (int i = 0; i < n; ++i) {
		if (lines[i].p1.x == lines[i].p2.x) {
			events.push_back({1, lines[i].p1.y, i});
			events.push_back({2, lines[i].p2.y, i});
		}
		else {
			events.push_back({3, lines[i].p1.y, i});
		}
	}

	std::sort(events.begin(), events.end(), [&](const Event& e1, const Event& e2) {
		if (e1.y < e2.y) return true;
		if (e1.y > e2.y) return false;
		return e1.type < e2.type;
	});

	// store pairs (x-coordinate, line index)
	std::set<std::pair<int, int>> vertical;

	for (Event e : events) {
		if (e.type == 1) {
			vertical.insert({lines[e.line_id].p1.x, e.line_id});
		}
		else if (e.type == 2) {
			vertical.erase({lines[e.line_id].p1.x, e.line_id});
		}
		else if (e.type == 3) {
			Line base = lines[e.line_id];
			
			auto start = vertical.lower_bound({base.p1.x, 0});
			auto end   = vertical.lower_bound({base.p2.x + 1, 0});

			std::vector<int> v;

			for (auto it = start; it != end; ++it) {
				v.push_back(it->second);
			}

			for (int k = 0; k < 2; ++k) {
				// Monotone Stack, Line hights are non-increasing
				std::vector<int> st;
				
				for (int id : v) {
					while (!st.empty() && lines[st.back()].p2.y < lines[id].p2.y) {
						st.pop_back();
					}
					if (!st.empty() && check(e.line_id, id, st.back())) {
						return true;
					}
					st.push_back(id);
				}

				std::reverse(v.begin(), v.end());
			}
		}
	}

	return false;
}

void solve() {
	int n;
	std::cin >> n;

	std::vector<Line> lines(n);

	for (Line& l : lines) {
		std::cin >> l.p1.x >> l.p1.y >> l.p2.x >> l.p2.y;
	}
	
	for (int i = 0; i < 4; ++i) {
		if (has_square_from_upwards_u(n, lines)) {
			std::cout << "yes" << '\n';
			return;
		}
		rotate_lines(lines);
	}

	std::cout << "no" << '\n';
}

