{
	ios_base::sync_with_stdio(false), cin.tie(0);
	cin >> n;
	for (int i = 1; i <= n; i++) {
		int a, b;
		cin >> a >> b >> h[i];
		adj[a].push_back({b, i});
		adj[b].push_back({a, i});
	}

	dfs(1, -1);
	if (!go(1)) {
		if (!go(-1)) {
			cout << "impossible\n";
			return 0;
		}
	} 

	for (int i = 1; i <= n; i++) {
		cout << start[i] << "\n";
	}
 	return 0;
}

