			}
			if (mx < ans)
			{
				ans = mx;
				bv = a[i][j];
			}
		}
	}
	if (ans == INF)
		cout << "impossible\n";
	else
		cout << bv << ' ' << ans << '\n';
	
	
	return 0;
}

