struct Trie {
    
    vector<map<string, int>> ch;
    vector<int> cnt;
    int root;
    
    int new_node() {
        ch.eb(), cnt.eb(0);
        return SZ(cnt) - 1;
    };
    
    void init() {
        ch.clear(), cnt.clear();
        root = new_node();
    }
    
    void insert(const vector<string> &path) {
        int now = root;
        for (const string &str : path) {
            ++cnt[now];
            if (!ch[now].contains(str)) ch[now][str] = new_node();
            now = ch[now][str];
        }
        ++cnt[now];
    }
    
    int solve() {
        int ans = 0;
        function<void(int)> dfs = [&](int now) {
            for (const auto &[str, id] : ch[now]) {
                ans += min(cnt[id], cnt[root] - cnt[id]);
                dfs(id);
            }
        };
        dfs(root);
        return ans;
    }
    
};

