void solve() {
    // find wrgb square on inf grid, h <= 4000, w <= 50
    // w' at most lcm(h, w)
    
    int H, W; cin >> H >> W;
    int D = gcd(H, W);
    
    vector grid(H, vector<int>(W));
    for (int i = 0; i < H; ++i) {
        string str; cin >> str;
        for (int j = 0; j < W; ++j) {
                 if (str[j] == 'w') grid[i][j] = (1 << 0);
            else if (str[j] == 'r') grid[i][j] = (1 << 1);
            else if (str[j] == 'b') grid[i][j] = (1 << 2);
            else if (str[j] == 'g') grid[i][j] = (1 << 3);
        }
    }
    
    vector cnt(D, vector<int>(16, 0));
    for (int l = 0; l < W; ++l) for (int r = 0; r < W; ++r) {
        if (l == r) continue;
        int dif = (l < r ? r - l : r - l + W);
        
        for (int i = 0; i < H+dif; ++i) {
            int mask_cur = grid[i%H][l] | grid[i%H][r], mask_inv = 0b1111 ^ mask_cur;
            if (i < H) ++cnt[i % D][mask_cur];
            if (i >= dif and cnt[(i-dif) % D][mask_inv]) {
                // debug(l, r, i, (i-dif) % D);
                cout << "possible" << "\n"; return;
            }
        }
        for (int i = 0; i < H; ++i) --cnt[i % D][grid[i][l] | grid[i][r]];
    }
    cout << "impossible" << "\n";
}

