const int mod = 1'000'000'007;

void solve() {
    int N; cin >> N;
    
    vector<int> P(N, -1);
    vector<vector<int>> ch(N);
    for (int i = 1; i < N; ++i) cin >> P[i], ch[P[i]].eb(i);
    
    auto merge_dp = [&](const deque<int> &dpL, const deque<int> &dpR) -> deque<int> {
        int L = SZ(dpL) - 1, R = SZ(dpR) - 1;
        deque<int> dp(L+R+1, 0);
        for (int l = 0; l <= L; ++l) for (int r = 0; r <= R; ++r) {
            dp[l+r] = (dp[l+r] + dpL[l] * dpR[r]) % mod;
        }
        return dp;
    };
    
    vector dp(N, deque<int>{1, 1});
    
    for (int i = N-1; i >= 0; --i) {
        int ch_sz = SZ(ch[i]);
        if (ch_sz == 0) continue;
        dp[i] = dp[ch[i][0]];
        for (int j = 1; j < ch_sz; ++j) dp[i] = merge_dp(dp[i], dp[ch[i][j]]);
        dp[i].ef(1);
    }
    // assert(SZ(dp[0]) == N+1);
    
    // for (int i = 0; i < N; ++i) debug(i, dp[i]);
    
    for (int k = 1; k <= N; ++k) {
        int ans = 0;
        for (int i = 0; i < N; ++i) {
            if (SZ(dp[i]) > k) ans += dp[i][k];
        }
        cout << ans % mod << "\n";
    }
}

int32_t main() {
