struct SCC {
    
    vector<vector<int>> adj;
    vector<int> low, dfn, in_stk, scc_id;
    deque<int> stk;
    int N, dfn_tok, scc_tok;
    
    void init(auto &_adj) {
        N = SZ(_adj);
        adj = _adj;
        low.assign(N, -1), dfn.assign(N, -1), in_stk.assign(N, 0);
        scc_id.assign(N, -1);
        stk.clear();
        dfn_tok = 0, scc_tok = 0;
    }
    
    void dfs(int now) {
        low[now] = dfn[now] = dfn_tok++;
        stk.ef(now), in_stk[now] = 1;
        for (int x : adj[now]) {
            if (dfn[x] == -1) dfs(x), chmin(low[now], low[x]);
            else if (in_stk[x]) chmin(low[now], dfn[x]);
        }
        if (low[now] == dfn[now]) {
            int x;
            do scc_id[x = stk[0]] = scc_tok, in_stk[x] = 0, stk.pf(); while (x != now);
            ++scc_tok;
        }
    }
    
    int solve() {
        for (int i = 0; i < N; ++i) { if (dfn[i] == -1) dfs(i); }
        // for (int i = 0; i < N; ++i) debug(i, scc_id[i], dfn[i]);
        
        vector<int> deg_o(scc_tok, 0);
        for (int i = 0; i < N; ++i) {
            for (int x : adj[i]) deg_o[scc_id[i]] += scc_id[i] != scc_id[x];
        }
        return count(ALL(deg_o), 0);
    }
    
};

