    int R, C, Q;
    cin >> R >> C >> Q;
    vector<int> A;
    vector<vector<pair<int, int>>> I;       // A[i][j] -> (i, j)
    vector<vector<pair<int, int>>> queries; // h -> (w, no)
    vector<int> ans;
    if (R < C) {
        swap(R, C);
        A.resize(C);
        I.resize(R + 1);
        ans.resize(Q);
        queries.resize(R + 1);
        for (auto j = 0; j < C; ++j) {
            for (auto i = 0; i < R; ++i) {
                char ch;
                cin >> ch;
                A[j] = (ch == '.' ? A[j] + 1 : 0);
                I[A[j]].emplace_back(i, j);
            }
        }
        for (auto i = 0; i < Q; ++i) {
            int h, w;
            cin >> w >> h; // swap
            queries[h].emplace_back(w, i);
        }
    } else {
        A.resize(C);
        I.resize(R + 1);
        ans.resize(Q);
        queries.resize(R + 1);
        for (auto i = 0; i < R; ++i) {
            for (auto j = 0; j < C; ++j) {
                char ch;
                cin >> ch;
                A[j] = (ch == '.' ? A[j] + 1 : 0);
                I[A[j]].emplace_back(i, j);
            }
        }
        for (auto i = 0; i < Q; ++i) {
            int h, w;
            cin >> h >> w;
            queries[h].emplace_back(w, i);
        }
    }
    atcoder::dsu D(R * C);
    vector<bool> used(R * C);
    vector<int> freq(C + 1);
    for (auto i = R; 0 < i; --i) {
        for (auto [r, c] : I[i]) {
            used[r * C + c] = true;
            if (c + 1 < C && used[r * C + c + 1]) {
                auto len = D.size(r * C + c + 1);
                --freq[len];
                D.merge(r * C + c, r * C + c + 1);
            }
            if (0 <= c - 1 && used[r * C + c - 1]) {
                auto len = D.size(r * C + c - 1);
                --freq[len];
                D.merge(r * C + c - 1, r * C + c);
            }
            auto len = D.size(r * C + c);
            ++freq[len];
        }
        for (auto [w, no] : queries[i]) {
            for (auto l = w; l <= C; ++l) {
                ans[no] += freq[l] * (l - w + 1);
            }
        }
    }
    ranges::copy(ans, ostream_iterator<int>(cout, "\n"));
}

