int main() {
    cin.tie(0)->sync_with_stdio(0);
    int N, K;
    cin >> N >> K;
    vector<int> T(N), F(N);
    for (auto i = 0; i < N; ++i) {
        cin >> T[i] >> F[i];
    }
    vector<int> P(K), D(K), C(K);
    for (auto i = 0; i < K; ++i) {
        cin >> P[i] >> D[i] >> C[i];
    }
    vector<long long> dp(N, -1);
    auto f = [&](auto self, int pos) -> long long {
        if (pos == N) {
            return 0LL;
        }
        auto &ret = dp[pos];
        if (~ret) {
            return ret;
        }
        ret = F[pos] + self(self, pos + 1);
        for (auto i = 0; i < K; ++i) {
            auto iota_view = views::iota(pos, N);
            auto pred = [&](int x) {
                return x - pos < D[i] && T[x] - T[pos] < P[i];
            };
            auto it = ranges::partition_point(iota_view, pred);
            auto val = C[i] + self(self, *it);
            ret = min(ret, val);
        }
        return ret;
    };
    auto ans = f(f, 0);
    cout << ans;
}

