using namespace std;

template <long long p, long long m> struct simple_string_hash {
    explicit simple_string_hash(string_view s) : n_((int)size(s)), hash_(n_ + 1), power_(n_ + 1) {
        for (auto i = 0; i < n_; ++i) {
            hash_[i + 1] = (modmul(hash_[i], p) + s[i]) % m;
        }
        power_[0] = 1;
        for (auto i = 0; i < n_; ++i) {
            power_[i + 1] = modmul(power_[i], p);
        }
    }
    long long operator()(int l, int r) { // [l, r)
        return (hash_[r] - modmul(hash_[l], power_[r - l]) + m) % m;
    }

private:
    long long modmul(__int128 a, __int128 b) { return (long long)(a * b % m); }
    int n_;
    vector<long long> hash_, power_;
};

int main() {
    cin.tie(0)->sync_with_stdio(0);
    string S;
    cin >> S;
    auto N = (int)size(S);
    simple_string_hash<31, (1LL << 61) - 1> H(S);
    vector<tuple<long long, int, int>> v;
    v.reserve(N * (N + 1) / 2);
    for (auto i = 0; i < N; ++i) {
        for (auto j = i + 1; j <= N; ++j) {
            v.emplace_back(H(i, j), i, j);
        }
    }
    ranges::sort(v);
    auto ans = N + 1;
    auto V = (int)size(v);
    for (auto i = 0, prev_r = -1, cnt = 0; i < V; ++i) {
        auto [k, l, r] = v[i];
        if (prev_r <= l) {
            prev_r = r;
            ++cnt;
        }
        if (i == V - 1 || get<0>(v[i]) != get<0>(v[i + 1])) {
            auto len = r - l;
            auto val = N + (1 - len) * cnt + len;
            ans = min(ans, val);
            prev_r = -1, cnt = 0;
        }
    }
    println("{}", ans);
}

