class Math{
	using LL=long long;
	
	private:
		LL _a,_b,_c,_x,_y,_g;
		LL _mod;
	public:
		Math(){}
		Math(LL mod){_mod=mod;}
		LL qpow(LL a,LL n,LL mod){
			LL ans=1;
			while (n){
				if (n&1) ans=ans*a%mod;
				a=a*a%mod;
				n>>=1;
			}
			return ans;
		}
		
		LL lcm(LL x,LL y){
			return x*y/__gcd(x,y);
		}
		
		LL ceil(LL x, LL y) {return x / y + !!(x % y);}      //计算a/b上取整
		
		LL exgcd(LL a,LL b,LL& x,LL& y) {
			if (b==0) {
				x=1;
				y=0;
				return a;
			}
			LL d=exgcd(b,a%b,x,y);
			LL temp=x;
			x=y;
			y=temp-a/b*y;
			return d;
		}

        LL inverse(LL a,LL m){
            LL x,y;
            exgcd(a,m,x,y);
            return (x%m+m)%m;
            //a关于m的逆元（exgcd法）
        }
		
		LL liEu(LL a,LL b,LL c) {		//ax+by=c	<==>	ax同余c(mod b) 
			LL d=exgcd(a,b,_x,_y);
			if (c%d!=0) return 0;             //no solution
			LL k=c/d;
			_x*=k;
			_y*=k;
			_a=a, _b=b, _c=c;
			_g=d;
			return d;
			//返回值为a，b的gcd
		}
		
		LL exgcd_fin_y(LL mn)
		{
			LL g=llabs(_g);
			LL p=llabs(_a/g);
			if (_y<=mn){
				LL k=ceil(mn-_y,p);
				return _y+k*p;
			}
			LL k=(_y-mn)/p;
			return _y-k*p;
		  /*计算y解集中大于等于mn的y,g为liEu的返回值*/
		  //y=y0+k*(a/g)
		}
		
		LL exgcd_fin_x(LL mn)
		{
			LL g=llabs(_g);
			LL p=llabs(_b/g);
			if (_x<=mn){
				LL k=ceil(mn-_x,p);
				return _x+k*p;
			}
			LL k=(_x-mn)/p;
			return _x-k*p;
		}
		
		LL get_x(){
			return _x;
		}
		
		LL get_y(){
			return _y;
		}
		
		LL CRT(int k,vector <LL> a, vector <LL> r) {               //求解满足多组同余方程 x同余a[i](mod r[i])的解 
			LL n=1,ans=0;
			for (int i=1;i<=k;i++) n=n*r[i];
			for (int i=1;i<=k;i++) {
				LL m=n/r[i],b,y;
				exgcd(m,r[i],b,y);  // b * m mod r[i] = 1
				ans=(ans+a[i]*m*b%n)%n;
			}
			return (ans%n+n)%n;
		}
		
		LL exCRT(int n,vector <LL> a,vector <LL> r) {
			LL A=r[1],B=a[1];
			for(int i=2;i<=n;i++) {
				LL x0,y0;
				LL c=a[i]-B;
				LL GCD=exgcd(A,r[i],x0,y0);
				if(c%GCD!=0) return -1;
				x0*=c/GCD;y0*=c/GCD;
				LL x=x0*A+B;
				A=lcm(A,r[i]);
				x=(x%A+A)%A;
				B=x;
			}
			return (B%A+A)%A;
		  /*
		  **最后返回结果在A(模数的lcm)范围内是唯一解
		  **使用前先引用exgcd
		  **当r互相不互质时CRT会出问题，这时使用exCRT
		  **无解返回-1
		  */
		}
		
		LL SUMp(LL a1,LL an,LL q,LL mod) {
			LL ans=((an*q-a1)%mod+mod)%mod;
			LL dz=qpow(q-1,mod-2,mod);
			return ans*dz%mod;
			//计算等比数列求和
		}

        vector <LL> allinv(int n,int p){
            vector <LL> inv(n+1,0);
            inv[1]=1;
            for (int i=2;i<=n;i++){
                inv[i]=(p-p/i)*inv[p%i]%p;
            }
            return inv;
            //O(n)得到1~n关于p的逆元
        }
        
        LL Euler_phi(LL x){
			LL res=x;
			for (LL i=2;i*i<=x;i++){
				if (x%i==0){
					res-=res/i;
					while (x%i==0) x/=i;
				}
			}
			if (x>1) res-=res/x;
			return res;
		}
		
		LL exEuler(LL a,string b,LL m){
			LL phi=Euler_phi(m);
			LL x=0;
			bool flag=0;
			for (char c:b){
				x=x*10+(c-'0');
				if (x>=phi) flag=1;
				x%=phi;
			}
			if (flag) x+=phi;
			return qpow(a,x,m);
		}
};

class Sieve{
	using LL=long long;

	private:
		int _n;
		vector <int> _minp,_prime,_phi;
		vector <int> _mu;
	
	public:
		Sieve(){}
		Sieve(int n){init(n);}
		
		void init(int n){
			_n=n;
			_minp.assign(n+10,0),_phi.assign(n+10,0),_mu.assign(n+10,0);
			_prime.reserve(n/log(n+1));
			_phi[1]=1,_mu[1]=1;
			
			for (int i=2;i<=n;i++){
				if (_minp[i]==0){
					_minp[i]=i;
					_prime.push_back(i);
					_phi[i]=i-1;
					_mu[i]=-1;
				}
				for (int p:_prime){
					if (i*p>n) break;
					_minp[i*p]=p;
					if (i%p==0){
						_phi[i*p]=p*_phi[i];
						_mu[i*p]=0;
						break;
					}
					_phi[i*p]=_phi[i]*_phi[p];
					_mu[i*p]=-_mu[i];
				}
			}
		}
		
		int isprime(int x) const{
			if (x<0 or x>_n) return -1;
			return x>=2 and _minp[x]==x;
		}
		
		int minprime(int x) const{
			if (x<0 or x>_n) return -1;
			return _minp[x];
		}
		
		int sizeofprime() const{
			return (int)_prime.size();
		}
		
		int getphi(int x) const{
			return _phi[x];
		}
		
		int getmu(int x) const{
			return _mu[x];
		}
};

class Combination{
	using LL=long long;
	
	private:
		int _n;
		vector <LL> _fac,_ffac;
		LL _mod;
		Math _math;
	
	public:
		void init(int n,LL mod){
			_n=n;
			_fac.assign(n+1,1);
			_ffac.assign(n+1,1);
			_mod=mod;
			for (int i=2;i<=n;i++) _fac[i]=_fac[i-1]*i%_mod;
			_ffac[n]=_math.qpow(_fac[n],_mod-2,_mod);
			for (int i=n-1;i>=1;i--) _ffac[i]=_ffac[i+1]*(i+1)%_mod;
		}
		
		LL C(int n,int m){
			if (n==m and n==0) return 1;
			if (n<m or n<=0) return -1;
			return _fac[n]*_ffac[m]%_mod*_ffac[n-m]%_mod;
		}
		
		LL A(int n,int m){
			if (n==m and n==0) return 1;
			if (n<m or n<=0) return -1;
			return _fac[n]*_ffac[n-m]%_mod;
		}
		
		LL getfac(int x){return _fac[x];}
		LL getffac(int x) {return _ffac[x];}
		
		LL Catalan(int x,LL mod){
			LL ans=1;
			for (int i=1;i<=x;i++) ans=ans*(4*i-2)*_math.qpow(i+1,mod-2,mod);
			return ans;
		}
};

struct Complex {
	double x, y;
	
	Complex(double _x = 0.0, double _y = 0.0) {
		x = _x;
		y = _y;
	}
	
	Complex operator - (const Complex &b) const {
		return Complex(x - b.x, y - b.y);
	}
	
	Complex operator + (const Complex &b) const {
		return Complex(x + b.x, y + b.y);
	}
	
	Complex operator * (const Complex &b) const {
		return Complex(x * b.x - y * b.y, x * b.y + y * b.x);
	}
};
class Polynomial{
	using LL=long long;
	using cp=Complex;
	const double PI=acos(-1.0);
	#define N 800010
	
	private:
		void change(Complex y[], int len){
			int i, j, k;
			for (int i = 1, j = len / 2; i < len - 1; i++) {
				if (i < j) std::swap(y[i], y[j]);
				k = len / 2;
				while (j >= k) {
					j = j - k;
					k = k / 2;
				}
				if (j < k) j += k;
			}
		}
		
		bool check_G(int g,int x){
			int tem[8005]={0};
			for (int i=0,tep=1;i<x-1;i++,tep=1ll*tep*g%x){
				if (tem[tep]) return 0;
				tem[tep]++;
			}
			return 1;
		}
		
		LL qpow(LL a,LL n,LL mod){
			LL ans=1;
			while (n){
				if (n&1) ans=ans*a%mod;
				a=a*a%mod;
				n>>=1;
			}
			return ans;
		}
		
		int make=0,p=0;
		vector <int> rev;
		void make_rev(int len){
			if (make) return;
			make=1;
			rev.assign(len+1,0);
			for (int i=0;i<len;i++) rev[i]=(rev[i>>1]>>1)|((i&1)<<(p-1));
		}
		

	
	public:
		void fft(Complex y[], int len, int on){
			change(y, len);
			for (int h = 2; h <= len; h <<= 1) {
				Complex wn(cos(2 * PI / h), sin(on * 2 * PI / h));
				for (int j = 0; j < len; j += h) {
					Complex w(1, 0);
					for (int k = j; k < j + h / 2; k++) {
						Complex u = y[k];
						Complex t = w * y[k + h / 2];
						y[k] = u + t;
						y[k + h / 2] = u - t;
						w = w * wn;
					}
				}
			}
			if (on == -1) {
				for (int i = 0; i < len; i++) {
					y[i].x /= len;
					y[i].y /= len;
				}
			}
		}
		
		static void FWT_Or(LL f[],int len,int type,LL mod,LL inv2){
			for (int mid=1;mid<len;mid<<=1){
				for (int block=mid<<1,j=0;j<len;j+=block){
					for (int i=j;i<j+mid;i++){
						f[i+mid]=(f[i+mid]+f[i]*type+mod)%mod;
					}
				}
			}
		}
		
		static void FWT_And (LL f[],int len,int type,LL mod,LL inv2){
			for (int mid=1;mid<len;mid<<=1){
				for (int block=mid<<1,j=0;j<len;j+=block){
					for (int i=j;i<j+mid;i++){
						f[i]=(f[i]+f[i+mid]*type+mod)%mod;
					}
				}
			}
		}
		
		static void FWT_Xor(LL f[],int len,int type,LL mod,LL inv2){
			for (int mid=1;mid<len;mid<<=1){
				for (int block=mid<<1,j=0;j<len;j+=block){
					for (int i=j;i<j+mid;i++){
						LL x=f[i],y=f[i+mid];
						f[i]=(x+y)%mod*(type==1?1:inv2)%mod;
						f[i+mid]=(x-y+mod)%mod*(type==1?1:inv2)%mod;
					}
				}
			}
		}
		
		void FFT(Complex A[],Complex B[],Complex C[],int len){
			fft(A,len,1);
			fft(B,len,1);
			for (int i=0;i<len;i++) C[i]=A[i]*B[i];
			fft(C,len,-1);
			//算出来的结果+0.5，比如输出真实的C[i]要写cout<<(int)(C[i].x+0.5)<<'\n'; 
		}
		
		int getfftlen(int len1,int len2){
			int len=1;
			while (len<len1+len2) len<<=1,p++;
			return len;
		}

		long long robust_round(double value, double epsilon = 1e-6) const{
		    return static_cast<long long>(std::round(value));
		}
		
		//快速数论变换 
		void FNTT(LL f[],int len,int type,LL mod,int G){
			make_rev(len);
			for (int i=0;i<len;++i){
				if (rev[i]<i) swap(f[i],f[rev[i]]);
			}
			for(int k=1;k<len;k<<=1)
				for(int i=0,w=qpow(G,(mod-1)/(k<<1),mod);i<len;i+=(k<<1))
					for(int j=0,prodw=1;j<k;j++,prodw=1ll*prodw*w%mod){
						LL x=f[i|j],y=1ll*f[i|j|k]*prodw%mod;
						f[i|j]=(x+y)%mod;
						f[i|j|k]=(x-y+mod)%mod;
					}
			if(type==-1){
				LL tmpinv=qpow(len,mod-2,mod);
				f[0]=1ll*f[0]*tmpinv%mod;
				for(int i=1;i<=(len>>1);i++){
					f[i]=1ll*f[i]*tmpinv%mod;
					if(i!=len-i)
						f[len-i]=1ll*f[len-i]*tmpinv%mod;
					swap(f[i],f[len-i]);
				}
			}
		}
		
		int get_G(int x){
			int ans=2;
			while (1){
				if (check_G(ans,x)) return ans;
				ans++;
			}
		}
		
		void FWT(LL A[],LL B[],LL C[],int len,void (*cul)(LL f[],int len,int type,LL mod,LL inv2),LL mod){
			LL inv2=qpow(2,mod-2,mod);
			cul(A,len,1,mod,inv2);
			cul(B,len,1,mod,inv2);
			for (int i=0;i<len;i++) C[i]=A[i]*B[i]%mod;
			cul(C,len,-1,mod,inv2);
			cul(A,len,-1,mod,inv2);
			cul(B,len,-1,mod,inv2);
		}
	
	#undef N
};

class Inversion{
	using LL=long long;
	
	private:
		LL _mod;
		Combination _cb;
		vector <int> _mu,_prime,_vis;
		Sieve _sieve;
		
	public:
		void init(int n,LL mod){
			_mod=mod;
			_cb.init(n,mod);
		}
		
		//至少到恰好的转换 
		LL binomialA(LL g[],int n,int maxn){
			int d=1;
			LL ans=0;
			for (int i=n;i<=maxn;i++){
				ans=ans+d*_cb.C(i,n)*g[i]%_mod;
				ans=(ans+_mod)%_mod;
				d*=-1;
			}
			return ans;
		}
		
		//至多到恰好的转换 
		LL binomialB(LL g[],int n){
			int d=1;
			LL ans=0;
			for (int i=n;i>=0;i--){
				ans=ans+d*_cb.C(n,i)*g[i]%_mod;
				ans=(ans+_mod)%_mod;
				d*=-1;
			}
			return ans;
		}
		
		//g(x)=SUM{[d|n]f(d)} <=> f(x)=SUM{[d|n]mu(n/d)g(d)}
		LL mobius(LL g[],int n){
			int ans=0;
			_sieve.init(n);
			for (int i=1;i*i<=n;i++){
				if (n%i==0){
					ans+=_sieve.getmu(n/i)*g[i];
					if (i*i!=n) ans+=_sieve.getmu(i)*g[n/i];
				}
			}
			return ans;
		}
};

class NetworkFlow{
	using LL=long long;
	struct edge{
		int to;
		LL cap;
		int rev;
		LL w;
	};
	#define N 600010
//	#define INF 4e18
	const LL INF=1e18;
	LL inf=4e11;
	
	private:
		vector <edge> v[N];
		vector <int> dep,lev,iter,cur;
		vector <LL> vis,dist;
		int S,T,Vis;
		bitset <N> b;
		LL maxflow,Cost;
		
		bool bfs(int n){
			lev.assign(n+1,-1);
		    cur.assign(n+1,0);
			lev[S]=0;
			queue<int>q;
			q.push(S);
			while(!q.empty()){
				int u=q.front(); q.pop();
		        for(auto i:v[u]){
					int d=i.to;
					if(lev[d]<0&&i.cap){
						lev[d]=lev[u]+1;
			            q.push(d);
					}
				}
			}
			dep=lev;
			return dep[T]!=-1;
		}
		
		bool spfa(int n){
			vis.assign(n+1,0);
			dist.assign(n+1,INF);
		    dist[S]=0;
		    vis[S]=1;
		    queue<int>q;
		    q.push(S);
		    int cnt=0;
		    while(!q.empty()){
		        int u=q.front(); q.pop();
		        vis[u]=0;
		        for(auto p:v[u]){
		            int d=p.to;
		            if(dist[d]>dist[u]+p.w and p.cap){
		                dist[d]=dist[u]+p.w;
		                if(vis[d]==0){
		                    q.push(d);
		                    vis[d]=1;
		                }
		            }
		        }
		    }
		    return dist[T]!=INF;
		}
		
		int dfs(int u,LL flow){
		    LL rlow=0;
		    if(u==T){
		    	Vis==1;
		    	maxflow+=flow;
		    	return flow;
			}
		    int used=0;//该点已经使用的流量
			for(int i=cur[u];i<(int)v[u].size();i++){
		        cur[u]=i;//修改当前弧 
				int d=v[u][i].to;
		        if(v[u][i].cap&&dep[d]==dep[u]+1){
			        if(rlow=dfs(d,min((LL)flow-used,v[u][i].cap))){
			        	used+=rlow;
			            v[u][i].cap-=rlow;
			            v[d][v[u][i].rev].cap+=rlow;
			            if(used==flow)break;
			        }
		        }
		    }
		    return used;//返回该点已使用流量
		}//寻找增广路 		
		
		LL dfs_spfa(int u,LL flow){
		    if(u==T){vis[T]=1;maxflow+=flow;return flow;}//可以到达t，加流 
		    int used=0;//该点使用了的流量 
		    vis[u]=1;
		    for(auto &p:v[u]){
		        int d=p.to;
		        if((vis[d]==0||d==T)&&p.cap!=0&&dist[d]==dist[u]+p.w){
		            LL minflow=dfs_spfa(d,min((LL)flow-used,p.cap));
		            if(minflow!=0){
						Cost+=p.w*minflow;
						p.cap-=minflow;
						v[d][p.rev].cap+=minflow;
						used+=minflow;
					}
		            //可以到达t，加费用，扣流量 
					if(used==flow)break;//小小的优化 
		        }
		    }
		    return used;
		}
		
		LL doFF(int d,int t,LL f){
			if (d==t) return f;
			b[d]=1;
			for (auto &p:v[d]){
				if (!b[p.to]&&p.cap){
					LL tp=doFF(p.to,t,min(f,p.cap));
					if (tp){
						p.cap-=tp;
						v[p.to][p.rev].cap+=tp;
						return tp;
					}
				}
			}
			return 0ll;
		}
		
	public:
		void add(int x,int y,LL z,LL w=0){
//			cout<<x<<" "<<y<<'\n';
			v[x].push_back({y,z,int(v[y].size()),w});
			v[y].push_back({x,0,int(v[x].size()-1),-w});
		}
		
		/**
		 * 最大流 
		 * 
		 * 一般网络 O(mn^2) 
		 * 各边容量均为1的网络 O(m MIN{m^(1/2),m^(2/3)})
		 * 满足除源汇外各点入度不超过1或出度不超过1 O(mn^(1/2))
		 * 
		 **/
		LL Dinic(int _s,int _t,int n){
			S=_s,T=_t;
			maxflow=0;
			while (bfs(n)){
				dfs(S,INF);
			}
			return maxflow;
		}
		
		pair<LL,LL> Dinic_spfa(int _s,int _t,int n){
			S=_s,T=_t;
			maxflow=0;
			Cost=0;
			while(spfa(n)){
		        vis[T]=1;
		        while(vis[T]){//能到达t就继续
			        vis.assign(n+1,0);
			        dfs_spfa(S,INF);	
			    }
		    }
			return {maxflow,Cost};
		}
		
		//最大流 时间复杂度O(f|E|) f为最大流的值（几乎达不到这个上界） 
		LL Ford_Fulkerson(int _s,int _t){
			S=_s; T=_t;
			LL ans=0;
			for (;;){
				b.reset();
				int f=doFF(S,T,INF);
				if (!f) break;
				ans+=f;
			}
			return ans;
		}
		
		void toans(){
		}
		
	#undef N
	#undef INF
};

class Gauss{
	using LL=long long;
	
	private:
		LL P;
		LL power(LL a,LL n){
			LL ans=1;
			while (n){
				if (n&1) ans=ans*a%P;
				a=a*a%P;
				n>>=1;
			}
			return ans;
		}
		
		std::vector<int> plus (const std::vector<int> &lhs, const std::vector<int> &rhs) {
		    std::vector<int> res(lhs.size() + rhs.size() - 1);
		    for (int i = 0; i < int(lhs.size()); ++i)
		        for (int j = 0; j < int(rhs.size()); ++j)
		            res[i + j] = (res[i + j] + 1ll * lhs[i] * rhs[j]) % P;
		    return res;
		}
		std::vector<int> module (const std::vector<int> &lhs, const std::vector<int> &rhs) {
		    auto res = lhs;
		    int m = rhs.size() - 1;
		    int inv = power(rhs.back(), P - 2);
		    for (int i = res.size() - 1; i >= m; --i) {
		        int x = 1ll * inv * res[i] % P;
		        for (int j = 0; j < m; ++j)
		            res[i - m + j] = (res[i - m + j] + 1ll * (P - x) * rhs[j]) % P;
		    }
		    if (int(res.size()) > m)
		        res.resize(m);
		    return res;
		}
		
	public:
		Gauss(){}
		Gauss(LL p){
			P=p;
		}
		/**
		 *  1:有解 
		 *  0:无解
		 *  -1:无穷多解 
		 **/
		int has_solve=1;
		
		//高斯消元，整数取模 
		std::vector<int> gauss(std::vector<std::vector<int>> a, std::vector<int> b) {
			has_solve=1;
		    int n = a.size();
		    std::vector<int> free_vars;
		    
		    for (int i = 0; i < n; ++i) {
		        int r = i;
		        while (r < n and a[r][i] == 0)
		            ++r;
		        if (r == n){
					free_vars.push_back(i);
					continue;
				}
		        std::swap(a[i], a[r]);
		        std::swap(b[i], b[r]);
		        int inv = power(a[i][i], P - 2);
		        for (int j = i; j < n; ++j)
		            a[i][j] = 1ll * a[i][j] * inv % P;
		        b[i] = 1ll * b[i] * inv % P;
		        for (int j = 0; j < n; ++j) {
		            if (i == j or a[j][i] == 0)
		                continue;
		            int x = a[j][i];
		            for (int k = i; k < n; ++k)
		                a[j][k] = (a[j][k] + 1ll * (P - x) * a[i][k]) % P;
		            b[j] = (b[j] + 1ll * (P - x) * b[i]) % P;
		        }
		    }
		    
		    for (int i=0;i<n;++i){
				bool all_zero = true;
				for (int j=0;j<n;++j){
					if (a[i][j]!=0){
						all_zero=false;
						break;
					}
				}
				if (all_zero and b[i]!=0){
					has_solve=0;
				}
			}
			
			if (has_solve and !free_vars.empty()) has_solve=-1;
		    return b;
		}
		
		//高斯消元，不取模 
		std::vector<double> gauss(std::vector<std::vector<double>> a, std::vector<double> b) {
		    int n = a.size();
		    for (int i = 0; i < n; ++i) {
		        double x = a[i][i];
		        for (int j = i; j < n; ++j) a[i][j] /= x;
		        b[i] /= x;
		        for (int j = 0; j < n; ++j) {
		            if (i == j) continue;
		            x = a[j][i];
		            for (int k = i; k < n; ++k) a[j][k] -= a[i][k] * x;
		            b[j] -= b[i] * x;
		        }
		    }
		    return b;
		}
};

class Basis{
	using LL=long long;
	int t[70];
	LL p[70];
	LL v[70];
	
	public:
		int add(LL x,int las=60,int tme=1e7){
			int tp=x;
			for (int i=las;i>=0;i--){
				if (x>>i&1){
					if (p[i]==0){
						p[i]=x;
						t[i]=tme;
						v[i]=tp;
						return 1;
					}
					if (tme>t[i]){
						swap(tme,t[i]);
						swap(x,p[i]);
					}
					x^=p[i];
				}
			}
			return 0;
		}
		LL gtmax(int las=60,int tme=0){
			LL ans=0;
			for (int i=las;i>=0;i++) if (t[i]>=tme) ans=max(ans,ans^p[i]);
			return ans;
		}
		void clear(int las=60){
			for (int i=0;i<=las;i++) p[i]=t[i]=0;
		}
		LL getv(int x){
			return v[x];
		}
		LL getp(int x){
			return p[x];
		}
};

class Tree_Chain_Decomposition{
	public:
		vector <int> fa,dep,siz,top,dfn,rnk,bot;
	
	private:
		int n;
		vector <vector <int> > v;
		int cur=0;
		void dfs1(int u){
			if (fa[u]!=-1) v[u].erase(find(v[u].begin(),v[u].end(),fa[u]));
			siz[u]=1;
			for (auto &p:v[u]){
				fa[p]=u;
				dep[p]=dep[u]+1;
				dfs1(p);
				siz[u]+=siz[p];
				if (siz[p]>siz[v[u][0]]) swap(p,v[u][0]);
			}
		}
		void dfs2(int u){
			dfn[u]=++cur;
			rnk[cur]=u;
			for (auto &p:v[u]){
				top[p]=(p==v[u][0]?top[u]:p);
				dfs2(p);
			}
			bot[u]=cur;
		}
	
	public:
		Tree_Chain_Decomposition(){}
		Tree_Chain_Decomposition(int _n) {init(_n);}
		void init(int _n){
			n=_n;
			fa.resize(n+1);
			dep.resize(n+1);
			siz.resize(n+1);
			bot.resize(n+1);
			top.resize(n+1);
			dfn.resize(n+1);
			rnk.resize(n+1);
			v.assign(n+1,{});
			cur=0;
		}
		void add(int x,int y){
			v[x].push_back(y);
			v[y].push_back(x);
		}
		void work(int root=1){
			top[root]=root;
			dep[root]=0;
			fa[root]=-1;
			dfs1(root);
			dfs2(root);
		}
		int lca(int x,int y){
			while (top[x]!=top[y]){
				if (dep[top[x]]<dep[top[y]]) swap(x,y);
				x=fa[top[x]];
			}
			return (dep[x]<dep[y]?x:y);
		}
		int dist(int x,int y){
			return dep[x]+dep[y]-2*dep[lca(x,y)];
		}
		//向上跳k层 
		int jump(int x,int k){
			if (dep[x]<k) return -1;
			int d=k-dep[x];
			while (dep[top[x]]>d) x=fa[top[x]];
			return rnk[dfn[x]-(dep[x]-d)];
		}
		bool isAncester(int x,int y){
			return dfn[x]<=dfn[y] and bot[x]>dfn[y];
		}
};

class Pcode{
	public:
		vector <vector <bool> > Gray(int n){
			vector <vector <bool> > ans;
			ans.assign((1<<n)+1,{});
			
			for (int i=0;i<(1<<n);i++){
				int id=i;
				for (int j=0;j<n;j++){
					int mid=(1<<(n-j-1));
					if (id<mid) ans[i].push_back(0);
					else{
						ans[i].push_back(1);
						id=2*mid-id-1;
					}
				}
			}
			return ans;
		}
		vector <bool> Grayid(int n,long long k){
			long long id=k;
			vector <bool> ans;
			for (int i=0;i<n;i++){
				long long mid=(1ll<<(n-i-1));
				if (id<mid) ans.push_back(0);
				else{
					ans.push_back(1);
					id=2*mid-id-1;
				}
			}
			return ans;
		}
};

