class Math{
	using LL=long long;
	
	private:
		LL _a,_b,_c,_x,_y,_g;
		LL _mod;
	public:
		Math(){}
		Math(LL mod){_mod=mod;}
		LL qpow(LL a,LL n,LL mod){
			LL ans=1;
			while (n){
				if (n&1) ans=ans*a%mod;
				a=a*a%mod;
				n>>=1;
			}
			return ans;
		}
		
		LL lcm(LL x,LL y){
			return x*y/__gcd(x,y);
		}
		
		LL ceil(LL x, LL y) {return x / y + !!(x % y);}      //计算a/b上取整
		
		LL exgcd(LL a,LL b,LL& x,LL& y) {
			if (b==0) {
				x=1;
				y=0;
				return a;
			}
			LL d=exgcd(b,a%b,x,y);
			LL temp=x;
			x=y;
			y=temp-a/b*y;
			return d;
		}

        LL inverse(LL a,LL m){
            LL x,y;
            exgcd(a,m,x,y);
            return (x%m+m)%m;
            //a关于m的逆元（exgcd法）
        }
		
		LL liEu(LL a,LL b,LL c) {		//ax+by=c	<==>	ax同余c(mod b) 
			LL d=exgcd(a,b,_x,_y);
			if (c%d!=0) return 0;             //no solution
			LL k=c/d;
			_x*=k;
			_y*=k;
			_a=a, _b=b, _c=c;
			_g=d;
			return d;
			//返回值为a，b的gcd
		}
		
		LL exgcd_fin_y(LL mn)
		{
			LL g=llabs(_g);
			LL p=llabs(_a/g);
			if (_y<=mn){
				LL k=ceil(mn-_y,p);
				return _y+k*p;
			}
			LL k=(_y-mn)/p;
			return _y-k*p;
		  /*计算y解集中大于等于mn的y,g为liEu的返回值*/
		  //y=y0+k*(a/g)
		}
		
		LL exgcd_fin_x(LL mn)
		{
			LL g=llabs(_g);
			LL p=llabs(_b/g);
			if (_x<=mn){
				LL k=ceil(mn-_x,p);
				return _x+k*p;
			}
			LL k=(_x-mn)/p;
			return _x-k*p;
		}
		
		LL get_x(){
			return _x;
		}
		
		LL get_y(){
			return _y;
		}
		
		LL CRT(int k,vector <LL> a, vector <LL> r) {               //求解满足多组同余方程 x同余a[i](mod r[i])的解 
			LL n=1,ans=0;
			for (int i=1;i<=k;i++) n=n*r[i];
			for (int i=1;i<=k;i++) {
				LL m=n/r[i],b,y;
				exgcd(m,r[i],b,y);  // b * m mod r[i] = 1
				ans=(ans+a[i]*m*b%n)%n;
			}
			return (ans%n+n)%n;
		}
		
		LL exCRT(int n,vector <LL> a,vector <LL> r) {
			LL A=r[1],B=a[1];
			for(int i=2;i<=n;i++) {
				LL x0,y0;
				LL c=a[i]-B;
				LL GCD=exgcd(A,r[i],x0,y0);
				if(c%GCD!=0) return -1;
				x0*=c/GCD;y0*=c/GCD;
				LL x=x0*A+B;
				A=lcm(A,r[i]);
				x=(x%A+A)%A;
				B=x;
			}
			return (B%A+A)%A;
		  /*
		  **最后返回结果在A(模数的lcm)范围内是唯一解
		  **使用前先引用exgcd
		  **当r互相不互质时CRT会出问题，这时使用exCRT
		  **无解返回-1
		  */
		}
		
		LL SUMp(LL a1,LL an,LL q,LL mod) {
			LL ans=((an*q-a1)%mod+mod)%mod;
			LL dz=qpow(q-1,mod-2,mod);
			return ans*dz%mod;
			//计算等比数列求和
		}

        vector <LL> allinv(int n,int p){
            vector <LL> inv(n+1,0);
            inv[1]=1;
            for (int i=2;i<=n;i++){
                inv[i]=(p-p/i)*inv[p%i]%p;
            }
            return inv;
            //O(n)得到1~n关于p的逆元
        }
        
        LL Euler_phi(LL x){
			LL res=x;
			for (LL i=2;i*i<=x;i++){
				if (x%i==0){
					res-=res/i;
					while (x%i==0) x/=i;
				}
			}
			if (x>1) res-=res/x;
			return res;
		}
		
		LL exEuler(LL a,string b,LL m){
			LL phi=Euler_phi(m);
			LL x=0;
			bool flag=0;
			for (char c:b){
				x=x*10+(c-'0');
				if (x>=phi) flag=1;
				x%=phi;
			}
			if (flag) x+=phi;
			return qpow(a,x,m);
		}
};

class Sieve{
	using LL=long long;

	private:
		int _n;
		vector <int> _minp,_prime,_phi;
		vector <int> _mu;
	
	public:
		Sieve(){}
		Sieve(int n){init(n);}
		
		void init(int n){
			_n=n;
			_minp.assign(n+10,0),_phi.assign(n+10,0),_mu.assign(n+10,0);
			_prime.reserve(n/log(n+1));
			_phi[1]=1,_mu[1]=1;
			
			for (int i=2;i<=n;i++){
				if (_minp[i]==0){
					_minp[i]=i;
					_prime.push_back(i);
					_phi[i]=i-1;
					_mu[i]=-1;
				}
				for (int p:_prime){
					if (i*p>n) break;
					_minp[i*p]=p;
					if (i%p==0){
						_phi[i*p]=p*_phi[i];
						_mu[i*p]=0;
						break;
					}
					_phi[i*p]=_phi[i]*_phi[p];
					_mu[i*p]=-_mu[i];
				}
			}
		}
		
		int isprime(int x) const{
			if (x<0 or x>_n) return -1;
			return x>=2 and _minp[x]==x;
		}
		
		int minprime(int x) const{
			if (x<0 or x>_n) return -1;
			return _minp[x];
		}
		
		int sizeofprime() const{
			return (int)_prime.size();
		}
		
		int getphi(int x) const{
			return _phi[x];
		}
		
		int getmu(int x) const{
			return _mu[x];
		}
};

class Combination{
	using LL=long long;
	
	private:
		int _n;
		vector <LL> _fac,_ffac;
		LL _mod;
		Math _math;
	
	public:
		void init(int n,LL mod){
			_n=n;
			_fac.assign(n+1,1);
			_ffac.assign(n+1,1);
			_mod=mod;
			for (int i=2;i<=n;i++) _fac[i]=_fac[i-1]*i%_mod;
			_ffac[n]=_math.qpow(_fac[n],_mod-2,_mod);
			for (int i=n-1;i>=1;i--) _ffac[i]=_ffac[i+1]*(i+1)%_mod;
		}
		
		LL C(int n,int m){
			if (n==m and n==0) return 1;
			if (n<m or n<=0) return -1;
			return _fac[n]*_ffac[m]%_mod*_ffac[n-m]%_mod;
		}
		
		LL A(int n,int m){
			if (n==m and n==0) return 1;
			if (n<m or n<=0) return -1;
			return _fac[n]*_ffac[n-m]%_mod;
		}
		
		LL getfac(int x){return _fac[x];}
		LL getffac(int x) {return _ffac[x];}
		
		LL Catalan(int x,LL mod){
			LL ans=1;
			for (int i=1;i<=x;i++) ans=ans*(4*i-2)*_math.qpow(i+1,mod-2,mod);
			return ans;
		}
};

