	public:
		int add(LL x,int las=60,int tme=1e7){
			int tp=x;
			for (int i=las;i>=0;i--){
				if (x>>i&1){
					if (p[i]==0){
						p[i]=x;
						t[i]=tme;
						v[i]=tp;
						return 1;
					}
					if (tme>t[i]){
						swap(tme,t[i]);
						swap(x,p[i]);
					}
					x^=p[i];
				}
			}
			return 0;
		}
		LL gtmax(int las=60,int tme=0){
			LL ans=0;
			for (int i=las;i>=0;i++) if (t[i]>=tme) ans=max(ans,ans^p[i]);
			return ans;
		}
		void clear(int las=60){
			for (int i=0;i<=las;i++) p[i]=t[i]=0;
		}
		LL getv(int x){
			return v[x];
		}
		LL getp(int x){
			return p[x];
		}
};

class Tree_Chain_Decomposition{
	public:
		vector <int> fa,dep,siz,top,dfn,rnk,bot;
	
	private:
		int n;
		vector <vector <int> > v;
		int cur=0;
		void dfs1(int u){
			if (fa[u]!=-1) v[u].erase(find(v[u].begin(),v[u].end(),fa[u]));
			siz[u]=1;
			for (auto &p:v[u]){
				fa[p]=u;
				dep[p]=dep[u]+1;
				dfs1(p);
				siz[u]+=siz[p];
				if (siz[p]>siz[v[u][0]]) swap(p,v[u][0]);
			}
		}
		void dfs2(int u){
			dfn[u]=++cur;
			rnk[cur]=u;
			for (auto &p:v[u]){
				top[p]=(p==v[u][0]?top[u]:p);
				dfs2(p);
			}
			bot[u]=cur;
		}
	
	public:
		Tree_Chain_Decomposition(){}
		Tree_Chain_Decomposition(int _n) {init(_n);}
		void init(int _n){
			n=_n;
			fa.resize(n+1);
			dep.resize(n+1);
			siz.resize(n+1);
			bot.resize(n+1);
			top.resize(n+1);
			dfn.resize(n+1);
			rnk.resize(n+1);
			v.assign(n+1,{});
			cur=0;
		}
		void add(int x,int y){
			v[x].push_back(y);
			v[y].push_back(x);
		}
		void work(int root=1){
			top[root]=root;
			dep[root]=0;
			fa[root]=-1;
			dfs1(root);
			dfs2(root);
		}
		int lca(int x,int y){
			while (top[x]!=top[y]){
				if (dep[top[x]]<dep[top[y]]) swap(x,y);
				x=fa[top[x]];
			}
			return (dep[x]<dep[y]?x:y);
		}
		int dist(int x,int y){
			return dep[x]+dep[y]-2*dep[lca(x,y)];
		}
		//向上跳k层 
		int jump(int x,int k){
			if (dep[x]<k) return -1;
			int d=k-dep[x];
			while (dep[top[x]]>d) x=fa[top[x]];
			return rnk[dfn[x]-(dep[x]-d)];
		}
		bool isAncester(int x,int y){
			return dfn[x]<=dfn[y] and bot[x]>dfn[y];
		}
};

class Pcode{
	public:
		vector <vector <bool> > Gray(int n){
			vector <vector <bool> > ans;
			ans.assign((1<<n)+1,{});
			
			for (int i=0;i<(1<<n);i++){
				int id=i;
				for (int j=0;j<n;j++){
					int mid=(1<<(n-j-1));
					if (id<mid) ans[i].push_back(0);
					else{
						ans[i].push_back(1);
						id=2*mid-id-1;
					}
				}
			}
			return ans;
		}
		vector <bool> Grayid(int n,long long k){
			long long id=k;
			vector <bool> ans;
			for (int i=0;i<n;i++){
				long long mid=(1ll<<(n-i-1));
				if (id<mid) ans.push_back(0);
				else{
					ans.push_back(1);
					id=2*mid-id-1;
				}
			}
			return ans;
		}
};

