inline int lowbit(int x) {
    return x & (-x);
}
inline void upd(int x, int v) {
    while (x <= n) {
        c[x] += v;
        x += lowbit(x);
    }
}
inline int qry(int x) {
    int res = 0;
    while (x) {
        res += c[x];
        x -= lowbit(x);
    }
    return res;
}
inline int qry(int l, int r) {
    return qry(r) - qry(l - 1);
}
