void build(int p, int l, int r) {
	for(int i = 1; i <= w; i++)
		pos[p][i] = i;
	if(l == r)return;
	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
}
void modify(int p, int l, int r, int x, int v) {
	if(l == r) {
		swap(pos[p][v], pos[p][v + 1]);
		return;
	}
	int mid = (l + r) >> 1;
	if(x <= mid)modify(p << 1, l, mid, x, v);
	else modify(p << 1 | 1, mid + 1, r, x, v);
	for(int i = 1; i <= w; i++)
		pos[p][i] = pos[p << 1 | 1][pos[p << 1][i]];
}
