        for(int i=1;i<a;++i) ans[i]=n-a+i;
    }
    for(int i=1;i<=n;++i) if(ans[i]==0) ans[i]=++val;
    for(int i=1;i<=n;++i) cout<<ans[i]<<" \n"[i==n];
