int W[201000],n,q,WI[201000];
const int mod=1e9+7,P=131;
int qpow(int a,int b){
	int c=1;
	for(;b;b>>=1){
		if(b&1)c=1ll*a*c%mod;
		a=1ll*a*a%mod;
	}
	return c;
}
const int P_=qpow(P,mod-2);
struct BIT{
	int tr[200100];
	inline void ad(int x,int z){for(;x<=n;x+=(x&-x))(tr[x]+=z)%=mod;}
	inline int ask(int x){int s=0;for(;x;x-=(x&-x))(s+=tr[x])%=mod;return s;}
	inline int sl(int l,int r){
		int xx=1ll*(ask(r)-ask(l-1))*WI[l]%mod;
		if(xx<0)xx+=mod;return xx;
	}
}T1,T2;
int fa[201000];
#define pb push_back
vector<int>g[201000];
void add(int x,int z){
	T1.ad(x,1ll*z*W[x]%mod),x=n-x+1;
	T2.ad(x,1ll*z*W[x]%mod);
}
void mer(int x,int y){
	x=fa[x],y=fa[y];
	assert(x!=y);
	if(g[x].size()<g[y].size())swap(x,y);
	for(int o:g[y])fa[o]=x,add(o,x-y),g[x].pb(o);
}
void sol(int L,int R){
	if(L>R)return;
	int l=1,r=R-L+1,lc=0;
	while(l<=r){
		int mi=(l+r)>>1;
		if(T1.sl(L,L+mi-1)==T2.sl(n-R+1,n-(R-mi+1)+1))lc=mi,l=mi+1;
		else r=mi-1;
	}
	if(lc*2>=R-L+1)return;
	mer(L+lc,R-lc),sol(L+lc+1,R-lc-1);
}
