	W[0]=WI[0]=1;
	for(int i=1;i<=n;i++)W[i]=1ll*W[i-1]*P%mod,WI[i]=1ll*WI[i-1]*P_%mod;
	for(int i=1;i<=n;i++)fa[i]=i,add(i,i),
	g[i].pb(i);
