using namespace std;

typedef pair<int, int> PII;
const int N = 1e5 + 10;

int n;
char S[N];
bool st[N];
map<PII, vector<int> > pos;
set<PII> q[50];
map<PII, int> sg;
set<PII> s;
int Sg;

int solve(int l, int r, int k){
    if(r - l + 1 < k) return -1;
    PII seg(l, r);
    if(sg.contains(seg)) return sg[seg];
    bool flag = false;
    int cnt = 0;
    pos[seg].resize(50, 0);
    for(int i = l; i <= r + 3 && i <= n; i ++){
        if(i <= r) cnt += st[i];
        if(i - 4 >= l) cnt -= st[i - 4];
        if(cnt == k && i - 3 >= 1){
            flag = true;
            int a = solve(l, i - 4, k), b = solve(i + 1, r, k);
            if(a == -1) a = 0;
            if(b == -1) b = 0;
            pos[seg][a ^ b] = i - 3;
        }
    }
    if(!flag) return sg[seg] = -1;
    int t = 0;
    while(pos[seg][t]) t ++;
    return sg[seg] = t;
}

void update(int x){
    for(int i = x; i <= x + 3; i ++)
        if(st[i]) st[i] = false;
}

void insert(PII seg, int t){
    if(t != -1){
        s.insert(seg);
        Sg ^= t;
        q[t].insert(seg);
    }
}

int main(){
    scanf("%d", &n);
    scanf("%s", S + 1);
    for(int i = 1; i <= n; i ++) st[i] = S[i] == 'b';
    for(int k = 4; k; k --){
        Sg = 0;
        for(int i = 1, l = 1, r, cnt = 0; i <= n + 1; i ++){
            if(i == n + 1){
                insert(PII(l, n), solve(l, n, k));
                break;
            }
            if(!st[i]) cnt ++;
            else cnt = 0;
            if(cnt + k > 4){
                insert(PII(l, i - cnt), solve(l, i - cnt, k));
                l = i + 1;
                cnt = 0;
            }
        }

        while(!s.empty()){
            int x;
            scanf("%d", &x);
            update(x);
            if(s.lower_bound(PII(x+4, 0))==s.begin())
                return 0;
            auto it = --s.lower_bound(PII(x+4, 0));
            PII seg = *it;
            s.erase(it);
            int T = sg[seg];
            Sg ^= T;
            q[T].erase(seg);
            int l = seg.first, r = seg.second;
            insert(PII(l, x - 1), solve(l, x - 1, k));
            insert(PII(x + 4, r), solve(x + 4, r, k));
            for(int t = 0; t < 50; t ++)
                if(((t ^ Sg) < t || !Sg) && !q[t].empty()){
                    seg = *q[t].begin();
                    q[t].erase(q[t].begin());
                    x = 0;
                    if(Sg) x = pos[seg][t ^ Sg];
                    else for(int z = pos[seg].size() - 1; z >= 0; z --)
                        if(pos[seg][z]){
                            x = pos[seg][z];
                            break;
                        }
                    s.erase(seg);
                    Sg ^= t;
                    update(x);
                    l = seg.first, r = seg.second;
                    insert(PII(l, x - 1), solve(l, x - 1, k));
                    insert(PII(x + 4, r), solve(x + 4, r, k));
                    printf("%d\n", x);
                    fflush(stdout);
                    break;
                }
        }
        pos.clear();
        s.clear();
        sg.clear();
        for(int i = 0; i < 50; i ++) q[i].clear();
    }
}

