    tran(it[2].t);
    for(int i=2;i<=n;i++){
        ll fi=it[i].f;
        ll ti=it[i].t;
        for(int j=0;j<=M;j++){
            F[j]=ask((j-fi&1),(j-fi+2*max(0ll,fi-j)>>1),(j-fi+2*min(fi,(M+fi-j)>>1)>>1));
            // for(int k=max(0ll,fi-j);k<=min(fi,(M+fi-j>>1));k++){
            //     // G[j]=min(G[j],F[j-fi+2*k]+ti*fi-ti*k);
            //     F[j]=min(F[j],S[(j-fi)&1][(j-fi+k*2)>>1]);
            // }
            if(F[j]<inf)F[j]+=ti*fi+ti*((j-fi-(j-fi&1))>>1);
        }
        tran(it[i+1].t);
    }
    ll mn=inf;
    for(int i=0;i<=M;i++){
        mn=min(mn,F[i]);
    }
    printf("%lld\n",mn);
    return 0;
}

