stack<int> st;
void tarjan(int x){
    dfn[x]=low[x]=++dfsnum;
    st.push(x),vis[x]=1;
    for(auto y:E[x]){
        if(!dfn[y])tarjan(y),low[x]=min(low[x],low[y]);
