        for(int i=1;i<=n;i++)if(ban[i][1]+ban[i][2]+ban[i][3]==3)tag=1;
        if(tag)continue;
        for(int i=1;i<=n;i++)num[i]=ban[i][1]+ban[i][2]+ban[i][3];
