                        adde(i,id[v]+tot),adde(id[v]+tot,i),adde(i+tot,id[v]),adde(id[v],i+tot);
                    else
                        adde(i,id[v]+tot),adde(id[v],i+tot);
                }
        }
        dfsnum=scc=0;for(int i=0;i<2*tot;i++)dfn[i]=0;
        for(int i=0;i<2*tot;i++)if(!dfn[i])tarjan(i);
        for(int i=0;i<tot;i++)if(bl[i]==bl[i+tot])tag=1;
        if(tag)continue;
        for(int i=0;i<tot;i++){
            int u=1,v=(ban[buf[i]][2]?3:2);
