unordered_map<uint64_t, int> mem;

int solve(int n, int h, int w, int m) {
  if (h < w) swap(h, w);
  if (!n) return 1;
  if (n > h * w - (h + w - 2 - m) * (h + w - 1 - m) / 2 || n < min(w * (m - w + 2), h * (m - h + 2))) return 0;
  if (h == w && h == m + 1 && h + 1 < M && h * (h + 1) / 2 - n < N) return tri[h + 1][h * (h + 1) / 2 - n];
  if (n < w * (m - w + 2)) w = (m + 2 - __builtin_sqrt((m + 2) * (m + 2) - 4 * n)) / 2;
  auto& loc = mem.emplace(n + 0ull << 48 | h + 0ull << 32 | w + 0ull << 16 | m, -1).first->second;
  return ~loc? loc: loc = add(solve(n - w * (m - w + 2), h - (m - w + 2), w - 1, w - 2), solve(n, h, w - 1, m));
}

