        }
    }
    for(int i = 0; i<n; i++){
        if(arr[i].X<minh){
            continue;
        }
        int sum=0;
        set<int>vert;
        for(int j = 0; j<n; j++){
            if(j==i || horz.count(j)){
                continue;
