        memset(dp,-1,sizeof(dp));
        dp[0][sum]={-1,1};
        int maxx=w-arr[i].X;
        if(sum>maxx){
            continue;
        }
        for(int j = 0; j<n; j++){
            for(int k = sum; k<=maxx; k++){
                if(dp[j][k].Y==-1){
                    continue;
                }
                if(dp[j+1][k].Y==-1){
                    dp[j+1][k]={-1,1};
                }
                if(j==i || vert.count(j) || horz.count(j)){
                    continue;
                }
                if(k+arr[j].Y<=maxx){
                    dp[j+1][k+arr[j].Y]={j,1};
                }
            }
        }
        int maxon=0;
        for(int j = sum; j<=maxx; j++){
