pair<int,int> simulate(int t,int e,vector<pair<int,int>>&stages,bool once){
    int idx=0;
    int inite=e;
    do{
        auto [ct,ende]=stages[idx];
        if(ct<=e){
            t+=sum(e-ct+1,e);
            e-=ct-2;
        }else{
            t+=sum(0,e);
            e=0;
        }
        idx++;
        idx%=stages.size();
        if(idx==0){
            if(once){
                return {t,e};
            }
        }
        if(idx==0 && e>=inite){
            return {-1,-1};
        }
    }while(e);
    return {t,e};
}
