using namespace std;
using T = double;
struct Point {
	T x, y;
	Point operator+(Point a) {return {x+a.x,y+a.y};}
	Point operator-(Point a) {return {x-a.x,y-a.y};}
	Point operator*(T k) {return {x*k,y*k};}
	T operator*(Point a) {return x*a.x+y*a.y;}
	T len() {return sqrt((*this)*(*this));}
};
int n;
T S;
void solve() {
	scanf("%lf%d",&S,&n);
	vector<Point> p(n);
	vector<T> L(n), Time = {0};
	for(int i=0;i<n;i++) scanf("%lf%lf",&p[i].x,&p[i].y);
	for(int i=1;i<n;i++) L[i] = L[i-1]+(p[i]-p[i-1]).len();
	T now = 0;
	int r = 0, l = 0;
	while(L[r+1] < S) r ++;
	while(r < n-1) {
		if(L[l+1]-now < L[r+1]-(now+S)) {
			now += L[l+1]-now;
			l ++;
		} else {
			now += L[r+1]-(now+S);
			r ++;
		}
		Time.push_back(now);
	}
	auto get = [&](T x) {
		auto t = lower_bound(L.begin(),L.end(),x)-L.begin();
		T more = L[t]-x;
		Point v = p[t-1]-p[t];
		return p[t]+v*(more/(L[t]-L[t-1]));
	};
	auto f = [&](T t) {
		return (get(t)-get(t+S)).len();
	};
	T ans = 1e9;
	for(int i=1;i<Time.size();i++) {
		T l = Time[i-1], r = Time[i];
		for(int turn=0;turn<=50;turn++) {
			T midL = l+(r-l)/3, midR = l+(r-l)/3*2;
			if(f(midL) > f(midR)) l = midL;
			else r = midR;
		}
		ans = min({ans, f(l), f(Time[i]), f(Time[i-1])});
	}
	printf("%.9lf\n",ans);
}

