		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	const ll inf = 1e17;
	vll dfs(n, inf), sub(n), depth(n), par(n, -1);
	function<void(ll)> calcdfs = [&](ll i) {
		if (i == k) dfs[i] = 1;
		sub[i] = 1;
		for (ll& e : adj[i]) if (e != par[i]) {
			depth[e] = depth[i] + 1;
			par[e] = i;
			calcdfs(e);
			sub[i] += sub[e];
		}
		ll ans = 1;
		for (ll& e : adj[i]) if (e != par[i]) {
			if (dfs[e] < inf) dfs[i] = ans + dfs[e];
			ans += sub[e];
		}
	};
	calcdfs(0);

	vll bfs(n, inf), above(n), at(n);
	function<void(ll)> calcbfs = [&](ll i) {
		if (i == k) {
			bfs[i] = 1;
			return;
		}
		if (depth[i] > depth[k]) return;
		if (depth[i] == depth[k]) at[i] = 1;
		else above[i] = 1;

		for (ll& e : adj[i]) if (e != par[i]) {
			calcbfs(e);
			above[i] += above[e];
			at[i] += at[e];
		}

		ll sum = 1;
		for (ll& e : adj[i]) if (e != par[i]) sum += above[e];
		for (ll& e : adj[i]) if (e != par[i]) {
			sum += at[e];
			if (bfs[e] < inf) bfs[i] = sum - above[e] - at[e] + bfs[e];
		}
	};
	calcbfs(0);

	vll dfspath;
	function<void(ll)> pathdfs = [&](ll i) {
		dfspath.push_back(i);
		for (ll& e : adj[i]) if (e != par[i]) pathdfs(e);
	};
	pathdfs(0);

	vll bfspath;
	queue<ll> q;
	q.push(0);
	while (!q.empty()) {
		ll i = q.front(); q.pop();
		bfspath.push_back(i);
		for (ll& e : adj[i]) if (e != par[i]) q.push(e);
	}

	{
		ll ans = inf, cur = 0;
		for (ll i : bfspath) {
			++cur;
			if (i == k) ans = min(ans, cur);
			else if (dfs[i] < inf) ans = min(ans, cur + dfs[i] - 1);
		}
