int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int D;
    std::cin >> D;

    std::vector<int> n(3), s(3);
    std::vector<i64> a(3);
    std::vector<std::vector<int>> y(3);
    for (int i = 0; i < 3; i++) {
        std::cin >> n[i] >> s[i];
        y[i].resize(n[i]);
        for (auto &y : y[i]) {
            std::cin >> y;
        }
        a[i] = 1LL * s[i] * s[i];
        y[i].push_back(-1);
        std::sort(y[i].begin(), y[i].end());
    }

    std::vector<std::pair<int, int>> que;
    for (int i = 0; i < 3; i++) {
        for (int j = 1; j <= n[i]; j++) {
            que.emplace_back(i, j);
        }
    }
    std::sort(que.begin(), que.end(), [&](auto a, auto b) {
        auto [ai, aj] = a;
        auto [bi, bj] = b;
        return y[ai][aj] < y[bi][bj];
    });

    auto check = [&](int i, int a, int j, int b) {
        if (a == 0 || b == 0) {
            return true;
        }
        if (i > j) {
            std::swap(i, j);
            std::swap(a, b);
        }
        if (i == j) {
            return std::abs(y[i][a] - y[j][b]) >= s[i];
        } else {
            int x = std::abs(y[i][a] - y[j][b]);
            return s[i] + s[j] - x <= (j - i) * D;
        }
    };

    auto chmax = [&](i64 &a, i64 b) {
        a = std::max(a, b);
    };

    std::vector dp(n[0] + 1, std::vector(n[1] + 1, std::vector(n[2] + 1, -INF)));
    dp[0][0][0] = 0;
    for (int i = 0; i <= n[0]; i++) {
        for (int j = 0; j <= n[1]; j++) {
            for (int k = 0; k <= n[2]; k++) {
                for (auto [t, c] : que) {
                    if (y[t][c] < y[0][i] || y[t][c] < y[1][j] || y[t][c] < y[2][k]) {
                        continue;
                    }
                    if (c <= std::array<int, 3>{i, j, k}[t]) {
                        continue;
                    }
                    if (check(0, i, t, c) && check(1, j, t, c) && check(2, k, t, c)) {
                        if (t == 0) {
                            chmax(dp[c][j][k], dp[i][j][k] + a[0]);
                        } else if (t == 1) {
                            chmax(dp[i][c][k], dp[i][j][k] + a[1]);
                        } else {
                            chmax(dp[i][j][c], dp[i][j][k] + a[2]);
                        }
                    }
                }
            }
        }
    }

    i64 ans = 0;
    for (int i = 0; i <= n[0]; i++) {
        for (int j = 0; j <= n[1]; j++) {
            for (int k = 0; k <= n[2]; k++) {
                ans = std::max(ans, dp[i][j][k]);
            }
        }
    }

    std::cout << ans << "\n";

    return 0;
}

