#include<bits/stdc++.h>
using namespace std;
const int N=4e5+5;
int n,m,a[N],h[N],val[N],pos[N];
struct dat{
	int x,v;
	inline bool operator<(const dat&rhs)const{
		return x!=rhs.x?x<rhs.x:v<rhs.v;
	}
}A[N];
int mn[N*4],tag[N*4];
pair<int,int>mxv[N*4];
inline void pushdown(int o){
	if(int&x=tag[o]){
		tag[o<<1]+=x,tag[o<<1|1]+=x;
		mn[o<<1]+=x,mn[o<<1|1]+=x;
		x=0;
	}
}
void build(int l,int r,int o){
	if(l==r){
		if(A[l].v>0)
			mxv[o]=make_pair(A[l].v,-l);
		return;
	}
	const int mid=(l+r)/2;
	build(l,mid,o<<1),build(mid+1,r,o<<1|1);
	mxv[o]=max(mxv[o<<1],mxv[o<<1|1]);
}
void modify(int l,int r,int o,const int&L,const int&R,const int&v){
	if(L<=l&&r<=R){
		tag[o]+=v,mn[o]+=v;
		return;
	}
	pushdown(o);
	const int mid=(l+r)/2;
	if(L<=mid)modify(l,mid,o<<1,L,R,v);
	if(mid<R)modify(mid+1,r,o<<1|1,L,R,v);
	mn[o]=min(mn[o<<1],mn[o<<1|1]);
}
int find(int l,int r,int o){
	if(l==r)return l;
	pushdown(o);
	const int mid=(l+r)/2;
	if(mn[o<<1]==mn[o])return find(l,mid,o<<1);
	return find(mid+1,r,o<<1|1);
}
pair<int,int>query(int l,int r,int o,const int&L,const int&R){
	if(L<=l&&r<=R)return mxv[o];
	pushdown(o);
	const int mid=(l+r)/2;
	pair<int,int>res=make_pair(0,0);
	if(L<=mid)res=query(l,mid,o<<1,L,R);
	if(mid<R)res=max(res,query(mid+1,r,o<<1|1,L,R));
	return res;
}
void cng(int l,int r,int o,const int&pos){
	if(l==r){mxv[o]=make_pair(0,0);return;}
	const int mid=(l+r)/2;
	if(pos<=mid)cng(l,mid,o<<1,pos);
	else cng(mid+1,r,o<<1|1,pos);
	mxv[o]=max(mxv[o<<1],mxv[o<<1|1]);
}
void work(){
	for(int i=1;i<=n;++i)A[i]=(dat){a[i],-i};
	for(int i=1;i<=m;++i)A[i+n]=(dat){h[i],val[i]};
	sort(A+1,A+n+m+1);
	for(int i=1;i<=n+m;++i)
		if(A[i].v<0)pos[-A[i].v]=i;
	build(1,n+m,1);
	long long ans=0;
	for(int i=1;i<=n;++i){
		int p=pos[i];
		modify(1,n+m,1,p,n+m,-1);
		int np=find(1,n+m,1);
		auto v=query(1,n+m,1,1,np);
		ans+=v.first;
		cout<<ans<<" \n"[i==n];
		if(v.first==0)
			modify(1,n+m,1,1,n+m,1);
		else{
			modify(1,n+m,1,-v.second,n+m,1);
			cng(1,n+m,1,-v.second);
		}
	}
}
