vector<pair<int,int> > e[N];
ll dis[N],ans[N];
priority_queue<pair<ll,int> >pq;
void dij(int s,int l,int r){
    for(int i=l;i<=r;++i) dis[i]=1e18;
    dis[s]=0;
    pq.push({0,s});
    while(!pq.empty()){
        auto [d,u]=pq.top(); pq.pop();
        if(d!=-dis[u]) continue;
        for(auto [v,w]:e[u]){
            if(v<l||v>r) continue;
            if(dis[v]>dis[u]+w){
                dis[v]=dis[u]+w;
                pq.push({-dis[v],v});
            }
        }
    }
}
void solve(int l,int r,vector<tuple<int,int,int> >Q){
    int mid=l+r>>1;
    int nl=max(l,mid-4),nr=min(r,mid+5);
    vector<tuple<int,int,int> > Ql,Qr;
    for(int i=nl;i<=nr;++i){
        dij(i,l,r);
        for(auto [l,r,id]:Q){
            ans[id]=min(ans[id],dis[l]+dis[r]);

        }
    }
    for(auto [l,r,id]:Q){
        if(r<nl) Ql.push_back({l,r,id});
        if(l>nr) Qr.push_back({l,r,id});
    }
    if(Ql.size()) solve(l,nl-1,Ql);
    if(Qr.size()) solve(nr+1,r,Qr);
}
