vector<int> g[200005];
void dfs(int x,int f){
	fa[x]=f;
	for(int y:g[x])if(y!=f)dfs(y,x);
}
LL Calc(LL mid){
	if(mid==0)return X+1;
	LL fm=(1ll<<62),sum=0;
	for(int i=1;i<=m;i++){
		if(A[i]==B[i])continue;
		LL u=(fm*(B[i]-A[i]))/mid;
		LL l=0,r=X+1,ans=-1;
		while(l<=r){
			LL t=(l+r)>>1;
			if(t*t+(A[i]+B[i]+1)*t+(A[i]*B[i]+A[i])<=u)ans=t,l=t+1;
			else r=t-1;
		}
		Ans[i]=ans;
		sum+=ans+1;
	}
	return sum;
}
