				if(z==fa[y])continue;
				B[m]+=a[z];
			}
			poi[m]=cur;
			cur=y;
		}
	}
	bool special=1;
	for(int i=1;i<=m;i++){
		if(A[i]!=B[i])special=0;
	}
	if(special){
