		Print();
	}
	//最大的，使得只要 >= 的，就 >=X
	LL l=0,r=(1ll<<62)-1,ans=0;
	while(l<=r){
		LL mid=(l+r)/2;
		if(Calc(mid)>=X)l=mid+1,ans=mid;
		else r=mid-1;
	}
	assert(ans!=0);
	Calc(ans);
	LL mnfz=1,mnfm=0;
	int mnc=0;
	for(int i=1;i<=m;i++){
		if(A[i]==B[i]||Ans[i]==-1)continue;
		//cout<<A[i]<<'/'<<B[i]<<'\n';
