		LL fz=B[i]-A[i],t=Ans[i],fm=t*t+(A[i]+B[i]+1)*t+(A[i]*B[i]+A[i]);
		if(fz*mnfm==mnfz*fm)mnc++;
		else if(fz*mnfm<mnfz*fm)mnc=1,mnfz=fz,mnfm=fm;
	}
	LL done=0;
	for(int i=1;i<=m;i++){
		if(A[i]==B[i]||Ans[i]==-1)continue;
		LL fz=B[i]-A[i],t=Ans[i],fm=t*t+(A[i]+B[i]+1)*t+(A[i]*B[i]+A[i]);
		if(fz*mnfm==mnfz*fm){
			fin[poi[i]]=t,done+=t;
		}
		else {
			fin[poi[i]]=t+1,done+=t+1;
		}
	}
	for(int i=1;i<=m;i++){
		if(A[i]==B[i]||Ans[i]==-1)continue;
		LL fz=B[i]-A[i],t=Ans[i],fm=t*t+(A[i]+B[i]+1)*t+(A[i]*B[i]+A[i]);
		if(fz*mnfm==mnfz*fm&&done<X){
			fin[poi[i]]++,done++;
		}
	}
	assert(done==X);
	Print();
