int sign(__int128 x)
{ return x==0 ? 0 : (x > 0 ? 1 : -1); }
template <typename T> struct P {
  T x, y;
  P (T _x = 0, T _y = 0) : x(_x), y(_y) {}
  P<T> operator + (P<T> o) {
    return P<T>(x + o.x, y + o.y);}
  P<T> operator - (P<T> o) {
    return P<T>(x - o.x, y - o.y);}
  P<T> operator * (T k) {return P<T>(x * k, y * k);}
  P<T> operator / (T k) {return P<T>(x / k, y / k);}
  T operator * (P<T> o) {return x * o.x + y * o.y;}
  T operator ^ (P<T> o) {return x * o.y - y * o.x;}
  friend ostream& operator << (ostream &o, P<T> a) {
    return o << "(" << a.x << ", " << a.y << ")"; }
  bool operator == (P<T> o) {
    return sign(x - o.x) == 0 && sign(y - o.y) == 0;}
};
using Pt = P<__int128>;
int ori(Pt o, Pt a, Pt b)
{ return sign((o - a) ^ (o - b)); }
int pos(Pt a)
{ return sign(a.y) == 0 ? sign(a.x) < 0 : a.y < 0; }
bool cmp(Pt a, Pt b)
{ return pos(a) == pos(b) ? sign(a ^ b) > 0 :
         pos(a) < pos(b); }

signed main(){
    ios_base::sync_with_stdio(0),cin.tie(0);
    int n; cin >> n;
    vector<Pt> a(n);
    for(int i=0; i<n; ++i){
        int x,y; cin >> x >> y;
        a[i]=Pt(x,y);
    }
    __int128 tot=0,totx=0,toty=0;
    for(int i=1; i<n-1; ++i){
        __int128 area=(a[i]-a[0])^(a[i+1]-a[0]);
        tot+=area*3;
        totx+=area*(a[0].x+a[i].x+a[i+1].x);
        toty+=area*(a[0].y+a[i].y+a[i+1].y);
        //cout << ((ll)area) << ' ' << ((ll)tot) << ' ' << ((ll)totx) << ' ' << ((ll)toty) << endl;
    }
    assert(tot!=0);
    if(tot<0) tot*=-1,totx*=-1,toty*=-1;
    //cout << ((ll)tot) << ' ' << ((ll)totx) << ' ' << ((ll)toty) << endl;
    //return 0;
    vector<Pt> b;
    for(int i=0; i<n; ++i){
        a[i].x=a[i].x*tot-totx;
        a[i].y=a[i].y*tot-toty;
        if(a[i].x!=0||a[i].y!=0) b.pb(a[i]);
        //cout << i << ' ' << ((ll)a[i].x) << ' ' << ((ll)a[i].y) << endl;
    }
    sort(all(b),cmp);
    ll m=sz(b);
    ll res=1ll*m*(m-1)*(m-2)/6;
    int r=0;
    for(int i=0; i<m; ++i){
        if(i==r) r=(r+1)%m;
        while(ori(Pt(0,0),b[i],b[(r+1)%m])>=0) r=(r+1)%m;
        ll cnt;
        if(r>=i) cnt=r-i;
        else cnt=r-i+m;
        res-=cnt*(cnt-1)/2;
    }
    cout << res << "\n";
}

