#include <bits/stdc++.h>
using namespace std;
const int mod = 999999937;
int n,a[500005],b[500005],c[500005],posb[500005],dep[500005],s[500005],sz[500005],fac[500005],inv[500005],cnt,ans = 1,g,g2;
vector<int> v[500005];
inline void build(int la,int ra,int lb,int rb){
    if(la >= ra) return;
    v[a[la]].push_back(a[la + 1]);
    int t = posb[a[la + 1]];
    build(la + 1,la + 1 + t - lb,lb,t);
    if(t < rb - 1){
		v[a[la]].push_back(b[rb - 1]);
    	build(la + 2 + t - lb,ra,t + 1,rb - 1);
    }
}
inline void dfs(int x,int y){
	dep[x] = y,sz[x] = 1;
	if(!v[x].size()) return;
	dfs(v[x][0],y + 1),sz[x] += sz[v[x][0]],s[x] += s[v[x][0]];
	if(v[x].size() > 1) dfs(v[x][1],y + 1),sz[x] += sz[v[x][1]],s[x] += s[v[x][1]];
	else if(!s[x]) cnt++;
}
inline int pw(int x,int y){
	int an = 1,tmp = x;
	while(y){
		if(y & 1) an = 1ll * an * tmp % mod;
		tmp = 1ll * tmp * tmp % mod;
		y >>= 1;
	}
	return an;
}
inline int C(int x,int y){
	//cout << x << '?' << y << ' '; 
	if(x < y || y < 0) return 0;
	return 1ll * fac[x] * inv[y] % mod * inv[x - y] % mod;
}
inline void solve(int x,int now,int cc){
	if(v[x].size()){
		if(v[x].size() == 1) solve(v[x][0],now,cc + 1);
		else solve(v[x][0],now,cc);
		now += sz[v[x][0]];
	}
	if(x == g){
		if(s[x] == 1 && v[x].size() == 1) ans = (C(cc,g2 - now) + C(cc,g2 + sz[v[x][0]] - now)) % mod;
		else if(v[x].size() == 1 && !c[g2 - 1]) ans = C(cc,g2 + sz[v[x][0]] - now);
		else ans = C(cc,g2 - now);
	}
	if(v[x].size() == 2) solve(v[x][1],now + 1,cc);
}
