inline void chkmin(ll &x,ll y) { x=x<y?x:y; }
struct Line {
	ll k,b;
	inline ll chg(Line x) {
		return x.k<=k?inf:(b-x.b)/(x.k-k);
	}
	inline friend Line operator +(Line x,Line y) {
		return {x.k+y.k,x.b+y.b};
	}
	inline friend bool operator >(Line x,Line y) {
		return x.b>y.b||(x.b==y.b&&x.k>y.k);
	}
};
struct Info {
	Line lx,rx,mx,sum;
	ll lim;
	inline friend Info operator +(Info ls,Info rs) {
		Info p{ls.sum+rs.lx,rs.sum+ls.rx,ls.rx+rs.lx,ls.sum+rs.sum,min(ls.lim,rs.lim)};
		if(ls.lx>p.lx) swap(p.lx,ls.lx);
		chkmin(p.lim,p.lx.chg(ls.lx));
		if(rs.rx>p.rx) swap(p.rx,rs.rx);
		chkmin(p.lim,p.rx.chg(rs.rx));
		if(ls.mx>p.mx) swap(p.mx,ls.mx);
		chkmin(p.lim,p.mx.chg(ls.mx));
		if(rs.mx>p.mx) swap(p.mx,rs.mx);
		chkmin(p.lim,p.mx.chg(rs.mx));
		return p;
	}
	inline Info operator *=(ll z) {
		lx.b+=lx.k*z,rx.b+=rx.k*z,mx.b+=mx.k*z,sum.b+=sum.k*z,lim-=z;
		return *this;
	}
};
