struct SegmentTree {
	struct Node {
		Info I;
		ll add;
	}	tr[1<<20|5];
	inline int L(int p) { return p<<1; }
	inline int R(int p) { return p<<1|1; }
	inline void psu(int p) { tr[p].I=tr[L(p)].I+tr[R(p)].I; }
	inline void adt(int p,ll z) { tr[p].add+=z,tr[p].I*=z; }
	inline void psd(int p) { adt(L(p),tr[p].add),adt(R(p),tr[p].add),tr[p].add=0; }
	inline void build(int l=1,int r=n,int p=1) {
		if(l==r) {
			Line val={1,a[l]};
			tr[p].I={val,val,val,val,inf};
			return ;
		}
		int mid=(l+r)>>1;
		build(l,mid,L(p)),build(mid+1,r,R(p)),psu(p);
	}
	inline void add(int ul,int ur,ll k,int l=1,int r=n,int p=1) {
		if(ul<=l&&r<=ur&&tr[p].I.lim>=k) return adt(p,k);
		int mid=(l+r)>>1; psd(p);
		if(ul<=mid) add(ul,ur,k,l,mid,L(p));
		if(mid<ur) add(ul,ur,k,mid+1,r,R(p));
		psu(p);
	}
	inline Info qry(int ul,int ur,int l=1,int r=n,int p=1) {
		if(ul<=l&&r<=ur) return tr[p].I;
		int mid=(l+r)>>1; psd(p);
		if(ur<=mid) return qry(ul,ur,l,mid,L(p));
		if(mid<ul) return qry(ul,ur,mid+1,r,R(p));
		return qry(ul,ur,l,mid,L(p))+qry(ul,ur,mid+1,r,R(p));
	}
}	T;
