inline int find(int x){while(x^fa[x])x=fa[x]=fa[fa[x]];return x;}
void init(){
	for(int i=0;i<n;i++) siz[i]=1,fa[i]=i,sz1[i]=tap[i];
}
void add(int u,int v,int w){
	// cerr<<"add "<<u<<' '<<v<<' '<<w<<'\n';
	E.push_back({w,u,v,find(u)!=find(v)});
	u=find(u),v=find(v);
	if(u==v) return;
	if(siz[u]>siz[v]) swap(u,v);
	fa[v]=u;siz[u]+=siz[v];sz1[u]+=sz1[v];
	rec.push_back({u,v});
}
void del(int w){
	// cerr<<"del "<<w<<'\n';
	int cnt=1;
	while(E[E.size()-cnt][0]!=w) cnt++;
	vector<array<int,4>> rE;
	cnt=min(2*cnt,(int)E.size());
	// cerr<<cnt<<'\n';
	while(cnt--){
		rE.push_back(E.back()),E.pop_back(),rE.back()[0]*=-1;
		if(rE.back()[3]){
			auto [u,v]=rec.back();rec.pop_back();
			fa[v]=v;siz[u]-=siz[v];sz1[u]-=sz1[v];
		}
	}
	sort(rE.begin(),rE.end());
	assert(-rE.back()[0]==w);
	rE.pop_back();
	for(auto [w,u,v,e]:rE) add(u,v,-w);
}
bool qwq(int x){
	return siz[find(x)]>K&&sz1[find(x)]>0;
}
}D;
