		}
		int ans=1e9;
		for(int i=n-B;i<n;i++) if(dis[i]<=diet[i]) ans=min(ans,dis[i]);
		if(ans==1e9) cout<<"IMPOSSIBLE\n";
		else cout<<ans<<'\n';
	}
	return 0;
}

