	if(x.x>0&&x.y==0) return 0;
	if(x.x==0&&x.y>0) return 1;
	if(x.x<0&&x.y==0) return 2;
	if(x.x==0&&x.y<0) return 3;
	return (x.x>0?0:1)^(x.y>0?0:3);
}
