bool on_segment(Point X,Point A,Point B){
	// check if X on segment AB
	if((A-B)*(X-B)!=0) return false;
	return min(A.x,B.x)<=X.x&&X.x<=max(A.x,B.x)&&
		min(A.y,B.y)<=X.y&&X.y<=max(A.y,B.y);
}
