typedef long long ll;
const int N=1e6+5;
vector<int> V[N];int m;
int calc(int n,int c){
	if(n<m)return 1;
	int A=V[m][c-1],B=(c==1)?-1:V[m][c-2];
	if((n+A)%2==0&&!calc((n+A)/2,c))return 1;
	if(B!=-1&&(n+B)%2==0&&(n-B)/2<=m&&!calc((n+B)/2,c-1))return 1;
	if(B!=-1&&A-B==m+2&&n==A-1+(m+1)/2)return 1;
	return 0;
}
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    for(int i=3;i<N-1;i+=2){
    	V[i].emplace_back(i+1);m=i;
    	while(V[i].back()+i+1<N)
    	V[i].emplace_back(V[i].back()+i+1+calc(V[i].back()+i+1,V[i].size()));
	}
	int T;cin>>T;
	while(T--){
		int n,m;cin>>n>>m;
		if(m%2==0){
			if(n%(m+1)==0)cout<<"NO\n";
			else cout<<"YES\n";
		}
		else{
			int p=lower_bound(V[m].begin(),V[m].end(),n)-V[m].begin();
			if(p!=V[m].size()&&V[m][p]==n)cout<<"NO\n";
			else cout<<"YES\n";
		}
	}
	return 0;
}

