using pii = pair<int, int>;
using pll = pair<ll, ll>;

int n, m, tot, a[110];
bool vis[110];
vector<int> ans[2020];

void dfs(int l, int r) {
	if (tot >= 2000) {
		return;
	}
	mems(vis, 0);
	int cnt = 0;
	for (int i = 1; i <= n; ++i) {
		if (!a[i] || vis[i]) {
			continue;
		}
		int u = i;
		do {
			vis[u] = 1;
			u = a[u];
		} while (u && u != i);
		cnt += (u == i);
	}
	int x = cnt + min(r - l + 1, 1), y = cnt + r - l + 1;
	if (!(x <= m && m <= y)) {
		return;
	}
	if (l > r) {
		vector<int> b;
		for (int i = 1; i <= n; ++i) {
			b.pb(a[i]);
		}
		ans[++tot] = b;
		return;
	}
	a[l] = n - r + l;
	dfs(l + 1, r);
	a[l] = 0;
	if (l < r) {
		a[r] = n - r + l;
		dfs(l, r - 1);
		a[r] = 0;
	}
}

void solve() {
	scanf("%d%d", &n, &m);
	dfs(1, n);
	printf("%d\n", tot);
	for (int i = 1; i <= tot; ++i) {
		for (int j = 0; j < n; ++j) {
			printf("%d%c", ans[i][j], " \n"[j == n - 1]);
		}
	}
}

int main() {
	int T = 1;
	// scanf("%d", &T);
	while (T--) {
		solve();
	}
	return 0;
}

