	{
		return u * n + v;
	};

	vector<vector<pair<int, char>>> graph(n);
	vector<vector<pair<int, char>>> rev(n); 

vector<bool> vis(n * n, false);

	vector<int> q;
	q.reserve(n * n);
	auto push_queue = [&](int id)
	{
		if (!vis[id])
			vis[id] = true, q.emplace_back(id);
	};

