		push_queue(fuck(i, i));

	while (!q.empty())
	{
		auto i = q.back();
		int u = i / n, v = i % n;
		q.pop_back();

		for (auto [s, c] : rev[u])
			for (auto [t, d] : graph[v])
				if (c == d)
					push_queue(fuck(s, t));
	}

