const int X=1536;
struct XB{
	vector<pair<bitset<X>,bitset<X> > > v;
	XB(){
		v.resize(X);
	}
	pair<bool,vector<int> > insert(bitset<X> x,int p){
		bitset<X> a;
		a[p]=1;
		for(int i=0;i<X;i++){
			if(x[i]){
				if(v[i].fs[i]==0){
					v[i].fs=x;
					v[i].sc=a;
					return pair<bool,vector<int> >(0,vector<int>(0));
				}
				else{
					x^=v[i].fs;
					a^=v[i].sc;
				}
			}
		}
		vector<int> g;
		for(int i=0;i<X;i++){
			if(a[i]){
				g.push_back(i);
			}
		}
		return pair<bool,vector<int> >(1,g);
	}
};
