struct node{
	int x,y,z;
}c[N];
int find(int x){
	if(x==bcj[x])return x;
	return bcj[x]=find(bcj[x]);
}
int maxx(int x,int y){
	return x>y?x:y;
}
bool cmp(int x,int y){
	return a[x]<a[y];
}
bool cmp2(node x,node y){
	return x.z<y.z;
}
void dfs1(int u){
	sze[u]=1;
	for(auto v:ve[u]){
		dfs1(v);
		sze[u]+=sze[v];
	}
}
void dfs2(int u,int fa){
	f[u]=f[fa]-1ll*a[fa]*sze[u]+1ll*a[u]*sze[u];
	for(auto v:ve[u]){
		dfs2(v,u);
	}
}
