	for(int i=1;i<=n;i++)rev[b[i]]=i;
	for(int i=1;i<=m;i++){
		scanf("%d %d",&c[i].x,&c[i].y);
		c[i].z=maxx(rev[c[i].x],rev[c[i].y]);
	}
	sort(c+1,c+m+1,cmp2);
	for(int i=1;i<=m;i++){
		x=c[i].x;y=c[i].y;
		if(rev[x]<rev[y]){
			x=find(x);
			if(x!=y)bcj[x]=y,fa[x]=y;
		}
		else{
			y=find(y);
			if(y!=x)bcj[y]=x,fa[y]=x;
		}
	}
