    vector<array<int,4>> A(N);
    rep(i,0,N) rep(j,1,4) cin >> A[i][j];
    // [l, r)
    auto solve = [&](auto&& self, int l, int r) -> vi {
        int len = r-l;
        vi ans(3*len+1, INF);
        ans[0] = 0;
        // special-case small len to speedup
        if (len <= SMALL) {
            rep(i,l,r) {
                for (int j = sz(ans)-1; j >= 1; --j) {
                    for (int k = min(3ll, j); k >= 1; --k) {
                        ans[j] = min(ans[j], ans[j-k]+A[i][k]);
                    }
                }
            }
        } else {
            int m = l+(r-l)/2;
            vi ans_l = self(self, l, m);
            vi ans_r = self(self, m, r);
            int i = 0, j = 0;
            while (i+1 < sz(ans_l) || j+1 < sz(ans_r)) {
                // advance pointer
                if (i+1 == sz(ans_l)) ++j;
                else if (j+1 == sz(ans_r)) ++i;
                else { // determine which one to push
                    int dif_i = ans_l[i+1]-ans_l[i];
                    int dif_j = ans_r[j+1]-ans_r[j];
                    if (dif_i < dif_j) ++i;
                    else ++j;
                }
                // search around
                int nxt_i = i, nxt_j = j;
                rep(ii, max(0ll, i-B), min(sz(ans_l), i+B+1)) {
                    int jj = i+j-ii;
                    if (jj < 0ll || jj >= sz(ans_r)) continue;
                    int cans = ans_l[ii]+ans_r[jj];
                    if (cans < ans[ii+jj]) {
                        ans[ii+jj] = cans;
                        nxt_i = ii, nxt_j = jj;
                    }
                }
                i = nxt_i, j = nxt_j;
            }
        }
        return ans;
    };
    vi ans = solve(solve, 0, N);
    assert(sz(ans) == 3*N+1);
    rep(i,1,3*N+1) cout << ans[i] << '\n';

}

