typedef double ld;
const ld eps = 1e-9;
const ld PI = acos(-(ld)1);

struct Point
{
    ld x, y, z;
    Point() : x(0), y(0), z(0) {}
    Point(ld x, ld y, ld z) : x(x), y(y), z(z) {}

    Point operator + (Point p) { return Point(x+p.x, y+p.y, z+p.z); }
    Point operator - (Point p) { return Point(x-p.x, y-p.y, z-p.z); }
    ld operator * (Point p) { return x*p.x+y*p.y+z*p.z; }
    Point operator / (Point p) { return Point(y*p.z-z*p.y, z*p.x-x*p.z, x*p.y-y*p.x); }
    ld norm() { return sqrt(x*x+y*y+z*z); }
    Point operator * (ld p) { return Point(x*p, y*p, z*p); }
};

Point proj(Point u, Point v)
{
    return u*((u*v)/(u*u));
}

ld f(Point a, Point b, Point c)
{
    Point p=(b-a)/(c-a);
    p=p*(1/p.norm());
    // cout << fixed << abs(p*a) << "!\n";
    return abs(p*a);
}
