    for(int i=1; i<=N; i++)
    {
        for(int j=i+1; j<=N; j++)
        {
            Point p=A[i]/A[j];
            if(p.norm()<eps) continue;
            cnt++;
            int x=0, y=0;
            for(int k=1; k<=N; k++)
            {
                if(p*A[k]>eps) x++;
                if(p*A[k]<-eps) y++;
            }
            if(x==0 || y==0) return !(cout << "90\n");
        }
    }
    if(cnt==0) return !(cout << "90\n");


    ld ans=1;
    for(int i=1; i<=N; i++)
    {
        for(int j=i+1; j<=N; j++)
        {
            if((A[i]-A[j]).norm()<eps) continue;
            Point m=(A[i]+A[j])*0.5;
            if(m.norm()<eps) continue;
            
            int x=0, y=0;
            Point px, py;
            for(int k=1; k<=N; k++)
            {
                Point p=A[k]-proj(A[i]-A[j], A[k])-m;
                if(p.norm()<eps) continue;
                Point q=p*(1/p.norm());
