                }
            }
            // printf("%d %d : %d %d\n", i, j, x, y);
            // cout << (px/py)*(A[i]-A[j]) << "?\n";
            if(x && y)
            {
                if((px/py)*(A[i]-A[j])>eps)
                {
                    if(x) ans=min(ans, f(A[i], A[j], A[x]));
                    if(y) ans=min(ans, f(A[i], A[j], A[y]));
                }
            }
            else if(x) ans=min(ans, f(A[i], A[j], A[x]));
            else if(y) ans=min(ans, f(A[i], A[j], A[y]));
        }
    }
    cout << fixed << acos(ans)/PI*180 << "\n";
}

