#include<bits/stdc++.h>
using namespace std;
int r[45];
int n ;
typedef double db;
const db eps = 1e-8;
const db pi = acos(-1);
int sgn(const db &x) { return x < -eps ? -1 : x > eps; }
struct Point {
  db x, y;
  Point operator+(const Point &s) const {
    return {x + s.x, y + s.y};
  }
  Point operator-(const Point &s) const {
    return {x - s.x, y - s.y};
  }
  Point operator*(const db &a) const {
    return {x * a, y * a};
  }
  Point operator/(const db &a) const {
    return {x / a, y / a};
  }
  bool operator<(const Point &b) const {
    return sgn(x - b.x) ? sgn(x - b.x) < 0
                        : sgn(y - b.y) < 0;
  }
  bool operator>(const Point &b) const { return b < *this; }
  bool operator==(const Point &b) const {
    return !sgn(x - b.x) && !sgn(y - b.y);
  }
  db Len() const { return sqrt(x * x + y * y); }
  db Len2() const { return x * x + y * y; }
  db angle() const { return atan2(y, x); }
  Point Len(const db &d) const {
    return *this * (d / Len());
  }
  Point unit() const { return *this / Len(); }
  Point normal() const { return {-y, x}; }
  Point symmetry(const Point &b) const {
    return b + b - *this;
  }
}p[45];
db dot(const Point &a, const Point &b) {
  return a.x * b.x + a.y * b.y;
}
db det(const Point &a, const Point &b) {
  return a.x * b.y - a.y * b.x;
}

vector<Point> circle_circle_intersection(Point o1, db r1,
                                         Point o2, db r2) {
  if (o2 == o1) return {};
  db t1 = ((o2 - o1).Len2() + r1 * r1 - r2 * r2) /
          (2 * (o2 - o1).Len());
  db t2 = r1 * r1 - t1 * t1;
  if (sgn(t2) < 0)
    return {};
  else if (!sgn(t2))
    return {o1 + (o2 - o1).Len(t1)};
  else {
    Point h = o1 + (o2 - o1).Len(t1);
    Point p1 = (o2 - o1).normal().Len(sqrt(t2)) + h;
    Point p2 = p1.symmetry(h);
    return {p1, p2};
  }
}

bool chk(Point o,db R){
    vector<pair<db,int> > g;
    // printf("%lf %lf %lf\n",o.x,o.y,R);
    for(int i = 1;i <= n ;i ++) {
        auto v = circle_circle_intersection(o , R , p[i] , r[i]) ;
        if(v.size() < 2) continue ;
        db a2 = atan2(v[0].y - o.y , v[0].x - o.x);
        db a1 = atan2(v[1].y - o.y , v[1].x - o.x);
        // printf("a1 %lf a2 %lf\n",a1,a2);
        if(a1 < a2) {
            g.push_back({a1 - eps, 1});
            g.push_back({a2 + eps , -1}) ;
        }
        else {
            g.push_back({a1-eps , 1}) ;
            g.push_back({-pi , 1}) ;
            g.push_back({a2+eps , -1});
        }
    }
    sort(g.begin() , g.end()) ;
    int cnt = 0;
    for(auto [u,v] : g) {
        cnt += v;
        if(cnt == 0) return 0;
    }
    return 1;
}
int main() {
    ios::sync_with_stdio(false) ; cin.tie(0) ;
    cin >> n;
    for(int i= 1;i <= n;i++) cin >> p[i].x >> p[i].y >> r[i];
    vector<Point> inter;
    for(int i = 1 ; i <= n;i++) {
        for(int j = i + 1;j <= n ;j++) {
            auto v = circle_circle_intersection(p[i] , r[i] , p[j] , r[j]) ;
            for(auto g : v) {
                bool ok = 1;
                for(int k = 1 ; k <= n ; k++) {
                    if(k == i || k == j) continue ;
                    if((p[k] - g).Len2()  < r[k] * r[k]) {ok = 0 ; break ;}
                }
                if(ok) inter.push_back(g) ;
            }
        }
    }
    db ans = *max_element(r + 1 , r + n + 1);

    // printf("INTER %d\n" , (int)inter.size());
    // for(auto p : inter) printf("%lf %lf\n",p.x,p.y);
    for(int i = 0;i < inter.size() ; i++) {
        for(int j = i + 1 ; j < inter.size() ; j++) {
            for(int k = j + 1 ; k < inter.size() ; k++) {
                Point u = inter[k] - inter[i] , v = inter[j] - inter[i];
                if(abs(det(u , v)) < eps) continue ;
                Point o = inter[i] - (v.normal() * u.Len2()  -  u.normal() * v.Len2()) / (2 * det(u , v)) ;
                db R = (o - inter[i]).Len() ;
                if(R <= ans) continue ;
                if(chk(o , R)) {
                    // printf("%lf %lf %lf\n",o.x,o.y,R);
                    ans = max(ans , R);
                }
                // printf("-------\n");
            }
        }
    }
    cout << fixed << setprecision(15) << ans << '\n';
    return 0;
}

