#include<bits/stdc++.h>
using namespace std;

typedef vector<int> poly;
const int N = (1 << 19) + 10, p = 998244353;
const int mod = p;
int n ;

inline int Qmi(int x, int y = p - 2) {
  int ans = 1;
  for (; y; y >>= 1, x = 1ll * x * x % p)
    if (y & 1) ans = 1ll * ans * x % p;
  return ans;
}
namespace Core {
int a[N], b[N], w[N], rev[N];
inline void NTT(int *a, int len) {
  for (int i = 1; i < len; ++i)
    if (i > rev[i]) swap(a[i], a[rev[i]]);
  for (int d = 1; d < len; d <<= 1)
    for (int m = d << 1, i = 0; i < len; i += m)
      for (int j = 0; j < d; ++j) {
        int x = a[i + j], y = 1ll * a[i + j + d] * w[len / m * j] % p;
        a[i + j] = (x + y >= p ? x + y - p : x + y);
        a[i + j + d] = (x - y < 0 ? x - y + p : x - y);
      }
}
}  // namespace Core
int pre_len = -1;
inline poly operator*(const poly &va, const poly &vb) {
  using namespace Core;
  int len = 1;
  while (len < (int)va.size() + (int)vb.size() - 1) len <<= 1;
  for (int i = 0; i < len; ++i) a[i] = (i < (int)va.size() ? va[i] : 0);
  for (int i = 0; i < len; ++i) b[i] = (i < (int)vb.size() ? vb[i] : 0);
  if(len !=pre_len) {
    for (int i = 1; i < len; ++i) rev[i] = rev[i >> 1] >> 1 | (i & 1 ? len >> 1 : 0);
    w[0] = 1;
    w[1] = Qmi(3, (p - 1) / len);
    for (int i = 2; i < len; ++i) w[i] = 1ll * w[i - 1] * w[1] % p;
    pre_len = len;
  }
  NTT(a, len);
  NTT(b, len);
  for (int i = 0; i < len; ++i) a[i] = 1ll * a[i] * b[i] % p;
  reverse(a + 1, a + len);
  NTT(a, len);
  poly c(va.size() + vb.size() - 1);
  for (int i = 0, invlen = Qmi(len); i < (int)c.size(); ++i) c[i] = 1ll * a[i] * invlen % p;
  return c;
}

vector<int> E[N];
int f[N] , fs[N];
int fp[N];
void dfs0(int fa,int u) {
    fs[u] = 1;
    f[u] = fa;
    for(auto v : E[u]) {
        if(v == fa) continue ;
        dfs0(u , v) ;
        fs[u] += fs[v];
        fp[u] = (fp[u] + 1LL * fs[v] * fs[v]) % mod ;
    }
}
int calc(int u,int v) { ///u的v方向被占用，方案数
    if(v == f[u]) {
        int ans = (1LL * fs[u] * fs[u] - fp[u] + mod) % mod ;
        return ans ;
    }
    int sz = n - fs[v];
    int ans = (1LL * sz * sz - fp[u] + 1LL * fs[v] * fs[v] % mod - 1LL * (n - fs[u]) * (n - fs[u]) % mod + mod * 2) % mod ;
    return ans ;
}
bool vis[N];
int sz[N];
int num;
int mn , cen;
poly operator+(const poly& a,const poly& b) {
    // printf("J %d %d\n",(int)a.size() , (int)b.size()) ;
    poly c(max(a.size() , b.size())) ;
    for(int i = 0;i < c.size() ;i++) {
        if(i < a.size()) c[i] = a[i];
        if(i < b.size()) c[i] = (c[i] + b[i]) % mod ;
    }
    return c;
}
poly operator-(const poly& a,const poly& b) {
    poly c(max(a.size() , b.size())) ;
    for(int i = 0;i < c.size() ;i++) {
        if(i < a.size()) c[i] = a[i];
        if(i < b.size()) c[i] = (c[i] - b[i] + mod) % mod ;
    }
    return c;
}
poly operator * (const poly&a,int b) {
    poly c = a;
    for(auto &x : c) x= 1LL * x * b % mod;
    return c;
}
void dfs(int fa,int u) {
    sz[u] = 1;
    for(auto v : E[u]) {
        if(v == fa || vis[v]) continue ;
        dfs(u , v);
        sz[u] += sz[v];
    }
}
void dfs2(int fa,int u) {
    int mx = 0;
    for(auto v : E[u]) {
        if(v == fa || vis[v]) continue ;
        dfs2(u , v);
        mx = max(mx , sz[v]);
    }
    mx = max(mx , num - sz[u]) ;
    if(mx < mn) {
        mn = mx;
        cen = u;
    }
}
void dfs3(int fa,int u,poly& p,int d) {
    // printf("D %d\n" , d) ;
    while(d >= p.size()) p.push_back(0) ;
    p[d] = (p[d] + calc(u , fa)) % mod ;

    for(auto v : E[u]) {
        if(v == fa || vis[v]) continue ;
        dfs3(u , v , p , d + 1);
    }
}
poly all;
void solve(int u) {
    dfs(0 , u) ;
    num = sz[u];
    mn = 1e9;
    dfs2(0 , u) ;

    vis[cen] = 1;

    poly sum , ans;
    
    // cerr << "CEN " << cen << endl ;
    for(auto v : E[cen]) {
        if(vis[v]) continue ;
        poly p;
        dfs3(cen , v , p , 1) ;
        if(p.size() > sum.size()) sum.resize(p.size()) ;
        for(int i = 0;i < p.size() ;i++) sum[i] = (sum[i] + p[i]) % mod ;
        // sum = sum + p;
        if(p.size()) {
            auto x = p * p + p * ((1 - 2LL * calc(cen  ,v) % mod + mod) % mod) ;
            if(x.size() > ans.size()) ans.resize(x.size()) ;
            for(int i = 0;i < x.size() ;i++) ans[i] = (ans[i] - x[i] + mod) % mod;
            // ans = ans - (p * p + p) ;
            // ans = (ans + p * (2LL * calc(cen , v) % mod));
        }
        // cerr << "V " << v <<' ' <<E[v].size() << endl ;
    }
    if(sum.size()) ans = ans + (sum * sum + sum) ;
    // cerr << "CEN " << cen <<' ' <<sum.size() << endl ;

    int r2 = (mod + 1) / 2;
    for(int i = 0;i < ans.size() && i < n;i ++) {
        // printf("%d %d\n",i,ans[i]) ;
        all[i] = (all[i] + 1LL * ans[i] * r2) % mod ;
    }

    int cc = cen;
    for(auto v : E[cc]) {
        if(vis[v]) continue ;
        solve(v) ;
    }
    return ;
}
int main() {
    ios::sync_with_stdio(false) ; cin.tie(0) ;
    cin >> n ;
    for(int i = 1;i < n;i++) {
        int u , v;cin >>u >> v;
        E[u].push_back(v) ;
        E[v].push_back(u);
    }
    dfs0(0 , 1) ;
