#include<bits/stdc++.h>
using namespace std;
const int N = 4005;
typedef long long ll ;
int x[N] , y[N];
int n ;
int vis[N * N * 2];
ll len[N * N * 2];
int rv[N * N];

typedef pair<int,int> pii;
const int inf = 1e9;
unordered_map<int,int> mx,my;
vector<int> vx , vy;

array<ll,3> mov(int u) {
    
    auto get =[&](vector<int>& v,int x) -> int {
        auto it = lower_bound(v.begin() , v.end() , x);
        if(it != v.end() && (*it) == x) return it-v.begin() ;
        return -1;
    };
    ll cur_len = 0;
    int nx = -inf, ny = -inf;
    int nt = u/(n*n) , ni = (u/n)%n , nj = u%n;
    int jmp;
    if(nt == 0) {
        {
            int j = mx[vx[ni]] ;
            jmp = j;
            nx = vx[ni] ,ny = 2 * y[j] - vy[nj];
            nj = get(vy , ny) ;
            cur_len += 2 * abs(y[j] - vy[nj]);
        }
    }
    else {
        {
            int j = my[vy[nj]];
            jmp = j;
            nx = 2 * x[j] - vx[ni] , ny = vy[nj];
            ni = get(vx , nx) ;
            cur_len += 2 * abs(x[j] - vx[ni]) ;
        }
    }
    if(nx != -inf) {
        nt ^= 1;
        if(ni == -1 || nj == -1) return {-1,-1,-1} ;
        u = nt * n * n + ni * n + nj;
    }
    else {
        return {-1,-1,-1};
    }
    return {cur_len , jmp , u} ;
}
ll ans = 0;
void chk(int u) {
    ll len = 0;
    static int id = 0;
    ++id ;
    auto [l,j,v] = mov(u) ;
    rv[j] = id;
    len = l;
    while(v != u) {
        auto [l,j,v2] = mov(v) ;
        if(rv[j] == id) return ;
        rv[j] = id;
        v = v2;
        len += l;
    }
    ans = max(ans , len) ;
    return ;
}
int main() {
    ios::sync_with_stdio(false) ; cin.tie(0) ;
    cin >> n ;
    for(int i = 1; i<= n;i++) {
        cin >> x[i] >> y[i];
        mx[x[i]] = i;
        my[y[i]] = i;
        vx.push_back(x[i]);
        vy.push_back(y[i]);
    }
    sort(vx.begin() , vx.end());
    sort(vy.begin() , vy.end());

    int id = 0;
    for(int i = 0;i < vx.size() ; i++) {
        for(int j = 0;j < vy.size() ; j++) {
            for(int t = 0 ; t < 2; t++) {
                int uid = t * n * n + i * n + j;
                int u = uid ;
                if(vis[u]) continue ;
                ++id;
                ll cur_len = 0;
                while(!vis[u]) {
                    vis[u] = id;
                    len[u] = cur_len ;
                    auto [lu,j,nu] = mov(u) ;
                    u = nu ;
                    if(nu == -1) { break ;}
                    cur_len += lu;
                }

                if(u == -1 || vis[u] != id) continue ;

                chk(u) ;
            }
        }
    }

    cout << ans << '\n' ;
}

#include<bits/stdc++.h>
using namespace std;
const int N = 1005;
typedef long long ll ;
int n , c , L;
const ll inf = 1e18;
ll up(ll x,ll y) {
    if(y < 0) x *= -1 , y *= -1;
    if(x >= 0) return (x + y - 1) / y;
    return x / y;
}
ll down(ll x,ll y) {
    if(y < 0) x *= -1 , y *= -1;
    if(x >= 0) return x / y;
    return -((-x + y - 1) / y);
}
struct frac {
    ll x,y;
    frac() {

    }
    frac(ll _x,ll _y) {
        x = _x;
        y = _y;
    }
    ll Up() {
        return up(x,y) ;
    }
    void norm() {
        if(y < 0) {x *= -1 ; y *= -1;}
        ll g = __gcd(abs(x),y) ;
        x /= g;
        y /= g;
    }
};
bool operator < (frac a,frac b) {
    return a.x * b.y < a.y * b.x;
}
bool operator <= (frac a,frac b) {
    return a.x * b.y <= a.y * b.x;
}
int x[N] , v[N];
ll Tm[N][N];
struct P1{
    priority_queue<ll> p , q;
    P1() {
        p.push(-inf) ;
    }
    void ins(ll x) {
        p.push(x);
    }
    void ers(ll x) {
        q.push(x) ;
    }
    ll qry() { /// max
        while(q.size() && p.top() == q.top()) {
            p.pop() ; q.pop() ;
        }
        return p.top() ;
    }
}p1;
struct P2{
    priority_queue<ll , vector<ll> , greater<ll> > p , q;
    P2() {
        p.push(inf) ;
    }
    void ins(ll x) {
        p.push(x);
    }
    void ers(ll x) {
        q.push(x) ;
    }
    ll qry() { /// min
        while(q.size() && p.top() == q.top()) {
            p.pop() ; q.pop() ;
        }
        return p.top() ;
    }
}p2;

struct ev {
    frac T;
    int x,y;
};
int sgn(ll x) {
    if(x < 0) return -1;
    return x > 0;
}
int main() {
    ios::sync_with_stdio(false) ; cin.tie(0) ;
    cin >> n >> c >> L;
    x[0] = 0 ; v[0] = 0;
    x[n + 1] = L ; v[n + 1] = 0;
    for(int i = 1;i <= n;i++) {
        cin >> x[i] >> v[i];
    }
    vector<int> p(n + 2) ;
    iota(p.begin() , p.end() , 0) ;
    sort(p.begin() , p.end() , [&](int a,int b) {
        if(x[a] == x[b]) return v[a] < v[b];
        return x[a] < x[b];
    });
    vector<int> pos(n + 2) ;
    for(int i = 0;i < p.size() ;i++) pos[p[i]] = i;

    int q ; cin >> q;

    vector<ev > V;

    vector<int> in(n + 2) ;

    // for(int i = 0;i < p.size() ;i ++) printf("%d ",p[i]) ; printf("\n") ;

    for(int i = 0;i <= n + 1;i++) {
        for(int j = 0;j <= n + 1;j++) {
            if(i == j) continue ;
            if(v[i] == v[j]) {
                if(x[i] - x[j] >= c) Tm[i][j] = -inf; /// >= Tm
                else Tm[i][j] = inf;
            }
            else if(v[i] > v[j]) Tm[i][j] = up(c - x[i] + x[j] , v[i] - v[j]) ; /// if(v[i] > v[j]) , 要求 >= Tm ; otherwise <= Tm
            else Tm[i][j] = down(c - x[i] + x[j] , v[i] - v[j]) ;

            if(x[i] < x[j] && v[i] > v[j]) {
                // ll t = up(x[j] - x[i] , v[i] - v[j]) ;
                // printf("T %lld %d %d\n",t,i,j) ;
                frac t = {x[j] - x[i] , v[i] - v[j]} ;
                t.norm() ;
                V.push_back({t , i , j}) ; /// time (t-1,t] , i over j
            }
        }
    }



    sort(V.begin() , V.end() , [&](ev a,ev b) {
        if(a.T.x != b.T.x || a.T.y != b.T.y) return a.T < b.T;
        if(v[a.x] != v[b.x]) return v[a.x] > v[b.x];
        return v[a.y] > v[b.y];
    });
    reverse(V.begin() , V.end()) ;

    auto ins = [&](int i , frac T) -> void {
        if(i < 0 || i + 1 >= p.size()) return ;
        // printf("expect ins %d , %lld %lld\n" , i , x[p[i]] + T * v[p[i]] , x[p[i + 1]] + T * v[p[i + 1]]) ;
        ll va =  x[p[i]] * T.y + T.x * v[p[i]] + sgn(v[p[i]]);
        ll vb = x[p[i + 1]] * T.y + T.x * v[p[i + 1]] + sgn(v[p[i + 1]]);
        if(0 <= va && va <= L * T.y && 0 <= vb && vb <= L * T.y ) {
            in[i] = 1;
            // printf("INS %d , %lld\n",i , Tm[p[i + 1]][p[i]]) ;
            if(v[p[i + 1]] >= v[p[i]]) p2.ins(Tm[p[i + 1]][p[i]]) ; /// >= Tm , 取min
            else p1.ins(Tm[p[i + 1]][p[i]]) ;
        }
    };
    auto ers = [&](int i) -> void {
        if(i < 0 || i + 1 >= p.size()) return ;
        if(in[i]) {
            in[i] = 0;
            // printf("ERS %d ,  %lld\n",i  , Tm[p[i + 1]][p[i]]) ;
            if(v[p[i + 1]] >= v[p[i]]) p2.ers(Tm[p[i + 1]][p[i]]) ;
            else p1.ers(Tm[p[i + 1]][p[i]]) ;
        }
    };
    for(int i = 0;i + 1 < p.size() ; i++) {
        ins(i , (frac){0,1}) ;
    }

    auto oper = [&]() -> void {
        int x = V.back().x , y = V.back().y;
        // printf("%d %d : %d %d\n",x,y,pos[x],pos[y]) ;
        assert(pos[x] + 1 == pos[y]) ;
        for(int i = pos[x] - 1 ; i <= pos[y] ; i++) ers(i) ;
        swap(p[pos[x]] , p[pos[y]]);
        swap(pos[x] , pos[y]);
        for(int i = pos[y] - 1 ; i <= pos[x] ; i++) ins(i , V.back().T ) ;
        V.pop_back() ;
    };
    while(q--) {
        int T ; cin >> T;

        frac cur = {T , 1} ;
        while(V.size() && V.back().T <= cur) {
            oper() ;
        }

        // for(int i = 0;i <= n + 1;i++) printf("%lld " , x[p[i]] + 1LL * T * v[p[i]]) ; printf("\n") ;

        // printf("LM %lld %lld\n" , p2.qry() , p1.qry()) ;
        if(T >= p2.qry() || T <= p1.qry()) cout << "Y\n";
        else cout << "N\n";
    }

}

