const int INF=0x3f3f3f3f;
const ll LLINF=0x3f3f3f3f3f3f3f3f;

const int N=2e5+5;
int n,q,S;
ll s[N],p[N],ans[N];
vector<pii> tmp,tmpp;
void solve(int l,int r,int L,int R){//
	// printf("%d %d %d %d\n",l,r,L,R);
	if(l>r||L>R) return;
	int mid=l+r>>1;
	if(tmpp[R].first<s[mid]) solve(l,mid-1,L,R);
	else if(tmpp[L].second<p[mid]+1) solve(mid+1,r,L,R);
	else{
		ll cur=-LLINF;
		int pos=L;
		for(int i=L;i<=R;i++){
			ll nx=(ll)(tmpp[i].first-s[mid]+1)*(tmpp[i].second-p[mid]);//(E,R) (P+1,S)
			if(!(tmpp[i].first-s[mid]+1<=0&&tmpp[i].second-p[mid]<=0)&&nx>cur) cur=nx,pos=i;
		}
		// printf("(%d,%d) try (%d,%d) New=%d\n",s[mid],p[mid]+1,tmpp[pos].first,tmpp[pos].second,cur);
		ans[mid]=max(ans[mid],cur);
		solve(l,mid-1,L,pos),solve(mid+1,r,pos,R);		
	}
}
