struct Thing {
	ll x, val, sum, num;
};
bool operator<(const Thing &a, const Thing &b) {
	ll vab = a.val + b.val + b.sum * a.num;
	ll vba = b.val + a.val + a.sum * b.num;
	return vab < vba; // a > b => a 在 b 前
}
int n, fa[400005], p[400005], done[400005];
Thing cur[400005];
vector<int> g[400005];
void dfs(int x, int f) {
	p[x] = f;
	for (int y : g[x]) {
		if (y == f) continue;
		dfs(y, x);
	}
}
int gf(int x) { return x == fa[x] ? x : fa[x] = gf(fa[x]); }
int main() {
