	for (int i = 1; i <= n; i++) {
		cur[i] = {i, i, i, 1};
		if (i != R) pq.push(cur[i]);
		fa[i] = i;
	}
	while (!pq.empty()) {
		Thing t = pq.top();
		pq.pop();
		if (done[t.x]) continue;
		int x = gf(t.x), f = p[x];
		assert(x == t.x);
		assert(f);
		f = gf(f);
		cur[f].sum += cur[x].sum;
		cur[f].val += cur[x].val + cur[x].sum * cur[f].num;
		cur[f].num += cur[x].num;
		if (f != R) pq.push(cur[f]);
		done[x] = 1;
		fa[x] = f;
		// cout << x << '\n';
	}
	cout << cur[R].val << endl;
}

