#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int, int> pr;
struct Line {
	int K, z, xl, xr;
	// y = K*x + z (x in [xl, xr])
};
int n;
bool Inter(Line a, Line b) {
	if (a.K == b.K) {
		if (a.z != b.z) return 0;
		return max(a.xl, b.xl) <= min(a.xr, b.xr);
	}
	int y = a.z + b.z;
	if (y & 1) return 0;
	y /= 2;
	int x = (y - a.z) / a.K;
	return a.xl <= x && x <= a.xr && b.xl <= x && x <= b.xr;
}
Line getInter(Line a, Line b) {
	if (a.K == b.K) return {a.K, a.z, max(a.xl, b.xl), min(a.xr, b.xr)};
	int y = a.z + b.z;
	y /= 2;
	int x = (y - a.z) / a.K;
	return {1, y - x, x, x};
}
int main() {
	vector<Line> lines;
	cin >> n;
	for (int i = 1; i <= n; i++) {
		int x, y, d;
		cin >> x >> y >> d;
		vector<Line> myLines;
		if (d == 0) {
			myLines.push_back({1, y - x, x, x});
		} else {
			myLines.push_back({1, y - (x - d), x - d, x - 1}); // (x-d, y)
			myLines.push_back({-1, x + y + d, x, x + d - 1});
			myLines.push_back({1, y - (x + d), x + 1, x + d}); // (x+d, y)
			myLines.push_back({-1, x + y - d, x - d + 1, x});
		}
		if (i == 1) lines = myLines;
		else {
			vector<Line> res;
			for (auto u : lines) {
				for (auto v : myLines) {
					if (!Inter(u, v)) continue;
					res.push_back(getInter(u, v));
				}
			}
			lines = res;
		}
	}
	vector<pr> ans;
	for (auto u : lines) {
		for (int x = u.xl; x <= u.xr; x++) {
			ans.push_back({x, u.K * x + u.z});
		}
	}
	sort(ans.begin(), ans.end());
	for (auto u : ans) {
		cout << u.first << " " << u.second << '\n';
	}
}

