#include <bits/stdc++.h>
using namespace std;
using i64 = long long;
const int inf = 1e9;

void sol() {
  int n;
  cin >> n;

  vector<vector<int>> adj(n + 1);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    cin >> u >> v;
    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  vector<int> siz(n + 1), vis(n + 1);
  vector<pair<int, int>> ans(n + 1, {inf, inf}); 
  // ans[u] = {最短距离, 对应点编号}

  auto getsize = [&](auto &&self, int u, int p) -> void {
    siz[u] = 1;
    for (int to : adj[u]) {
      if (to == p || vis[to]) continue;
      self(self, to, u);
      siz[u] += siz[to];
    }
  };

  auto getcentroid = [&](auto &&self, int u, int p, int tot) -> int {
    for (int to : adj[u]) {
      if (to == p || vis[to]) continue;
      if (siz[to] > tot / 2) {
        return self(self, to, u, tot);
      }
    }
    return u;
  };

  auto dfs = [&](auto &&self, int u, int p, int d,
                 vector<pair<int, int>> &vec) -> void {
    vec.push_back({u, d}); // 记录：点 u 到当前重心距离 d
    for (int to : adj[u]) {
      if (to == p || vis[to]) continue;
      self(self, to, u, d + 1, vec);
    }
  };

  auto work = [&](auto &&self, int entry) -> void {
    getsize(getsize, entry, 0);
    int c = getcentroid(getcentroid, entry, 0, siz[entry]);

    vector<pair<int, int>> vec;
    dfs(dfs, c, 0, 0, vec);

    // 按点编号从大到小扫
    sort(vec.rbegin(), vec.rend());

    pair<int, int> bst = {inf, inf};
    // bst = 已扫过点(即编号更大的点)中，(到重心距离, 点编号) 最小者
    for (auto [u, d] : vec) {
      if (bst.first < inf) {
        ans[u] = min(ans[u], {d + bst.first, bst.second});
      }
      bst = min(bst, {d, u});
    }

    vis[c] = 1;
    for (int to : adj[c]) {
      if (!vis[to]) self(self, to);
    }
  };

  work(work, 1);

  // 最富城市没有更富城市，答案是自己
  ans[n] = {0, n};

  for (int i = 1; i <= n; ++i) {
    cout << ans[i].second << " \n"[i == n];
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int t = 1;
  // cin >> t;
  while (t--) sol();

  return 0;
}

