	n = strlen(s + 1);
	for (int i = 1; i <= n; i++) {
		if (isalpha(s[i])) s[i] = 'a';
		else if (s[i] != '(' && s[i] != ')') s[i] = '+';

		if (s[i] == 'a') {
			if (i == 1 || s[i - 1] == 'a') {
				f[i] = f[i - 1] + 1;
				continue;
			}
			if (s[i - 1] == '+') {
				f[i] = f[i - 2] + 1;
				continue;
			}
			if (s[i - 1] == '(') {
				f[i] = 1;
				continue;
			}
			if (s[i - 1] == ')') {
				f[i] = 1;
				Mklst(i);
				continue;
			}
		}
		if (s[i] == '+') {
			if (i > 1 && (s[i - 1] == 'a' || s[i - 1] == ')')) {
				f[i] = 0;
				continue;
			}
			Mklst(i);
			continue;
		}
		if (s[i] == '(') {
			if (i == 1 || s[i - 1] == '+' || s[i - 1] == '(') {
				f[i] = 0;
				st[++top] = i;
				continue;
			}
			Mklst(i);
			st[++top] = i;
			continue;
		}
		if (s[i] == ')') {
			if (top == 0 || i == 1 || s[i - 1] == '+' || s[i - 1] == '(') {
				Mklst(i);
				continue;
			}
			int fr = st[top--];
			if (fr == 1) {
				f[i] = 1;
				continue;
			}
			if (s[fr - 1] == '+') {
				f[i] = f[fr - 2] + 1;
				continue;
			}
			f[i] = 1;
			continue;
		}
	}
	for (int i = 1; i <= n; i++) sum += f[i];
