void Dij(int s, ll dis[]) {
	for (int i = 1; i <= n; i++) dis[i] = inf;
	dis[s] = 0;
	priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
	pq.push({0, s});
	while (!pq.empty()) {
		auto [d, u] = pq.top();
		pq.pop();
		if (d > dis[u]) continue;
		for (auto [v, w] : g[u]) {
			if (del[v]) continue;
			if (dis[v] > dis[u] + w) {
				dis[v] = dis[u] + w;
				pq.push({dis[v], v});
			}
		}
	}
}
