const int N = (int)1e6 + 1, M = N * 10;

ld area(ld cx, ld cy, ld r, ld x1, ld y1, ld x2, ld y2){
    if (r <= 0) return 0.0L;
    ld X1 = x1 - cx, X2 = x2 - cx;
    ld Y1 = y1 - cy, Y2 = y2 - cy;
    if (X1 > X2) swap(X1, X2);
    if (Y1 > Y2) swap(Y1, Y2);
    ld L = max<ld>(X1, -r), R = min<ld>(X2, r);
    if (L >= R) return 0.0L;

    auto F = [&](ld x)->ld{
        ld t = max<ld>(0.0L, r*r - x*x);
        ld s = sqrt(t);
        ld a = max<ld>(-1.0L, min<ld>(1.0L, x/r));
        return 0.5L * (x*s + r*r*asin(a));
    };

    vector<ld> pts = {L, R};
    auto add_pt = [&](ld y, bool need){
        if (!need) return;
        if (fabsl(y) > r) return;
        ld xx = sqrt(max<ld>(0.0L, r*r - y*y));
        pts.push_back(-xx);
        pts.push_back(xx);
    };
    add_pt(Y1, true);
    add_pt(Y2, true);
    pts.push_back(0.0L);

    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end(), [](ld a, ld b){ return fabsl(a-b) < 1e-15L; }), pts.end());

    ld area_sum = 0.0L;
    for (size_t i = 1; i < pts.size(); ++i){
        ld a = max<ld>(L, pts[i-1]);
        ld b = min<ld>(R, pts[i]);
        if (b <= a) continue;
        ld xm = (a + b) * 0.5L;
        ld s2 = r*r - xm*xm;
        if (s2 <= 0) continue;
        ld s = sqrt(s2);
        bool lower_clip = (Y1 > -s);
        bool upper_clip = (Y2 <  s);
        if (!lower_clip && !upper_clip){
            area_sum += 2.0L * (F(b) - F(a));
        } else if (lower_clip && !upper_clip){
            area_sum += (F(b) - F(a)) - Y1 * (b - a);
        } else if (!lower_clip && upper_clip){
            area_sum += (F(b) - F(a)) + Y2 * (b - a);
        } else {
            ld h = Y2 - Y1;
            if (h > 0) area_sum += h * (b - a);
        }
    }
    if (!(area_sum >= 0)) area_sum = 0.0L;
    return area_sum;
}

void solve(){
    int n;
    ld r, w, h;
    cin >> n >> r >> w >> h;

    ld E = 0;
    for(int i = 0; i < n; i++){
        ld x, y, v;
        cin >> x >> y >> v;
        E = E + v * area(x, y, r, 0, 0, w, h);
    }

    cout << setprecision(20) << E / (w * h) << "\n";
}

