signed main() {
    cin.tie(0)->sync_with_stdio(0);

    int N, M; cin >> N >> M;
    struct Edge {
        int u, v, w; 
        bool operator<(const Edge& o) const { return w < o.w; }
    };
    vector<Edge> edges(M);
    for (auto& [u, v, w] : edges) {
        cin >> u >> v >> w;
    }
    sort(all(edges));
    vector<vector<pii>> adj(N+1);
    vector<vector<pii>> all_adj(N+1);
    ll mst_weight = 0;
    int id = 0;
    {
        vector<int> par(N+1), siz(N+1, 1);
        rep(i,1,N+1) par[i] = i;
        auto find = [&](auto&& self, int n) -> int {
            if (par[n] == n) return n;
            return par[n] = self(self, par[n]);
        };
        auto unite = [&](int a, int b) -> void {
            if (siz[a] < siz[b]) swap(a, b);
            siz[a] += siz[b];
            par[b] = a;
        };
        for (auto [u, v, w] : edges) {
            int uu = find(find, u);
            int vv = find(find, v);
            if (uu != vv) {
                adj[u].push_back({v, w});
                adj[v].push_back({u, w});
                unite(uu, vv);
                mst_weight += w;
            } else {
                all_adj[u].push_back({id, w});
                all_adj[v].push_back({id, w});
                ++id;
            }
        }
    }
    int worst_swap = 0;
    auto dfs = [&](auto&& self, int c, int p, int pw) -> multiset<pii> {
        multiset<pii> outgoing;
        for (auto [id, w] : all_adj[c]) {
            outgoing.insert({w, id});
        }
        for (auto [t, w] : adj[c]) {
            if (t == p) continue;
            auto t_outgoing = self(self, t, c, w);
            if (sz(outgoing) < sz(t_outgoing)) {
                swap(outgoing, t_outgoing);
            }
            for (auto& [w, id] : t_outgoing) {
                if (auto it = outgoing.find({w, id}); it != outgoing.end()) {
                    outgoing.erase(it);
                } else {
                    outgoing.insert({w, id});
                }
            }
        }
        if (p) {
            assert(sz(outgoing));
            int cheapest_replacement = outgoing.begin()->first;
            int cur_swap = -pw + cheapest_replacement;
            assert(cur_swap >= 0);
            worst_swap = max(worst_swap, cur_swap);
        }
        return outgoing;
    };
    dfs(dfs, rng()%N+1, 0, 0);

    ll ans = mst_weight + worst_swap;
    cout << ans << '\n';

}

