#define fornd(i, x, y) for (int i = x - 1a; i >= y; i--)
const ll MAX = 1e18;
const ll MOD = 1e9 + 7;
bool testcases = false;

ll w, h;
ll len = 0;
vvi scam;
pii apple;
vector<pair<int, int>> delta = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

bool dfs(int t, pii head, pii bad, vvi obstacles) {
    obstacles[head.first][head.second] = -1;
    if (head == apple || t >= 16) {
        return true;
    }
    for (auto &[dx, dy] : delta) {
        pii newH = {head.first+dx, head.second+dy};
        auto &[nX, nY] = newH;
         if (bad != newH && nX >= 0 && nX < w && nY >= 0 && nY < h && len-obstacles[nX][nY] <= t) {
            if (dfs(t+1, newH, head, obstacles)) return true;
        }
    }
    return false;
}

void solve() {
    pii head, one;
    cin >> w >> h;
    scam = vvi(w, vector<int>(h, 1e9)); // higher obstacle = sooner
    for (int i = 0; i < w; i++) {
        for (int j = 0; j < h; j++) {
            char x; cin >> x;
            if (x >= '1' && x <= '9') {
                scam[i][j] = x-'0';
                len++;
            }
            if (x >= 'a' && x <= 'f') {
                scam[i][j] = x-'a'+11;
                len++;
            }
            if (x == '0') head = {i, j};
            if (x == '1') one = {i, j};
            if (x == 'A') apple = {i, j};
        }
    }
    cout << dfs(0, head, one, scam) << endl;
}


