const int N=1e5+10;
int n;
struct node{
    double p,w,cnt;
    int id;
    bool operator < (node x) const{
        return w<x.w;
    }
}a[N];
int fa[N];
int find(int x){return fa[x]==x?x:fa[x]=find(fa[x]);}
int main(){
    cin>>n;
    double sum=0;
    for(int i=1;i<=n;i++){
        a[i]={read(),read(),1,i};
        sum+=1ll*a[i].p*a[i].w;
        fa[i]=i;
    }
    fa[n+1]=n+1,a[n+1].p=1e12;
    if(sum>0){
        reverse(a+1,a+1+n);
        for(int i=1;i<=n;i++) a[i].p*=-1,a[i].id=n+1-a[i].id;
    }
    else sum*=-1;
    priority_queue<node> q;
    for(int i=1;i<=n;i++){
        q.push(a[i]);
    }
    double ans=0;
    while(q.size()){
        node nd=q.top(); q.pop();
        //cout<<nd.p<<" "<<nd.id<<" "<<nd.w<<"\n";
        if(nd.w!=a[nd.id].w||nd.cnt!=a[nd.id].cnt) continue;
        int x=find(nd.id+1);
        double dis=(a[x].p-nd.p)*nd.cnt;
        if(nd.w*dis>=sum||nd.id==n){
            printf("%.10lf",ans+sum/nd.w);
            break;
        }
        sum-=dis*nd.w;
        ans+=dis;
        fa[nd.id]=x;
        a[x].w=(a[x].w*a[x].cnt+nd.w*nd.cnt)/(a[x].cnt+nd.cnt);
        a[x].cnt+=nd.cnt;
        q.push(a[x]);
    }
    return 0;
}

