}p[1010];
node operator-(node a,node b){
	return node{a.x-b.x,a.y-b.y,a.z-b.z};
}
bool operator==(node a,node b){
	return a.x==b.x&&a.y==b.y&&a.z==b.z;
}
bool operator<(node a,node b){
	return a.x==b.x?a.y==b.y?a.z<b.z:a.y<b.y:a.x<b.x;
}
node operator^(node a,node b){
	return node{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};
}
ll operator*(node a,node b){
	return a.x*b.x+a.y*b.y+a.z*b.z;
}
bool cmp(line a,line b){
	return a.pos<b.pos;
}
ll dis(node a){
	return a.x*a.x+a.y*a.y+a.z*a.z;
}
bool ck(node a,node b,node c){
	if((a^b)*c!=0)return 1;
	if((a^b)*(b^c)<=0)return 1;
	if((b^c)*(c^a)<=0)return 1;
	if((c^a)*(a^b)<=0)return 1;
	return 0;
}
node nom(node a){
	int d=__gcd(abs(a.x),__gcd(abs(a.y),abs(a.z)));
	return node{a.x/d,a.y/d,a.z/d};
}
