struct vec
{
	ll x,y;
	void read(){cin>>x>>y;}
	vec operator+(vec b)const{return {x+b.x,y+b.y};}
	vec operator-(vec b)const{return {x-b.x,y-b.y};}
	ll operator*(vec b)const{return x*b.y-y*b.x;}
};

int c[N];

bool sol(vector<array<vec,4>>S)
{
	if(S.size()==1)return 1;
	int i,j,k,u,v,n=S.size(),fl=0;
	auto chk=[&](vec A,vec B,int id)
	{
		int in=0,ax=0;
		for(int t=0;t<4;++t)
		{
			in=min(in,sgn((B-A)*(S[id][t]-A)));
			ax=max(ax,sgn((B-A)*(S[id][t]-A)));
		}
		if(in==-1&&ax==1)return 0;
		return ax?ax:in;
	};
	for(i=0;i<n;++i)
		for(j=i+1;j<n;++j)
			for(u=0;u<4;++u)
				for(v=0;v<4;++v)
					if(chk(S[i][u],S[j][v],i)&&chk(S[i][u],S[j][v],j))
					{
						for(k=0;k<n;++k)
							if(!(c[k]=chk(S[i][u],S[j][v],k)))
								break;
						if(k==n)
						{
							for(k=1;k<n;++k)
								if(c[k]!=c[k-1])
									break;
							if(k!=n){fl=1;goto LP;}
						}
					}
	if(!fl)return 0;
	LP:
	vector<array<vec,4>>A,B;
	for(k=0;k<n;++k)
		if(c[k]==1)
			A.push_back(S[k]);
		else
			B.push_back(S[k]);
	return sol(A)&&sol(B);
}

