#include <bits/stdc++.h>
using namespace std;

using edge = tuple<int, int, int>;

const int N = 710, S = N - 1, T = 0;

int n, m, tot;
vector<edge> g[N];

void addEdge(int u, int v, int w) {
    int a = g[u].size(), b = g[v].size();
    g[u].emplace_back(v, w, b);
    g[v].emplace_back(u, 0, a);
}

void reset(int x) {
    for(int i = 0; i < N; i ++)
        for(auto &[v, w, r] : g[i]) {
            if(v < i) continue;
            auto &[_, rw, __] = g[v][r];
            rw += w;
            w = 0;
        }
    for(int i = 1; i <= n; i ++)
        for(auto &[v, w, r] : g[i])
            if(v == T)
                w = x;
}

int d[N];
bool b[N];

bool dinix() {
    memset(d, -1, sizeof d);
    memset(b, 0, sizeof b);
    queue<int> q;
    q.push(S);
    d[S] = 0;
    while(q.size()) {
        int u = q.front();
        q.pop();
        for(auto &[v, w, r] : g[u]) {
            if(w <= 0 || d[v] >= 0) continue;
            d[v] = d[u] + 1;
            q.push(v);
        }
    }
    return d[T] >= 0;
}

int dinic(int u, int f) {
    if(u == T) return f;
    if(b[u]) return 0;
    int ret = 0;
    for(auto &[v, w, r] : g[u]) {
        if(w <= 0 || d[v] != d[u] + 1) continue;
        int df = dinic(v, min(w, f));
        f -= df;
        w -= df;
        ret += df;
        auto &[_, rw, __] = g[v][r];
        rw += df;
        if(f <= 0) break;
    }
    if(f > 0) b[u] = true;
    return ret;
}

bool check(int x) {
    reset(x);
    int ans = 0;
    while(dinix()) {
        ans += dinic(S, tot);
    }
    return ans >= x * n;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;
    for(int i = 1, u, v, w; i <= m; i ++) {
        cin >> u >> v >> w;
        addEdge(S, n + i, w);
        addEdge(n + i, u, w);
        addEdge(n + i, v, w);
        tot += w;
    }
    for(int i = 1; i <= n; i ++)
        addEdge(i, T, 0);

    int l = 0, r = tot + 1;
    while(l + 1 < r) {
        int mid = (l + r) / 2;
        if(check(mid)) l = mid;
        else r = mid;
    }
    cout << tot - l * n << "\n";
}

