const int MAXN = 505;

using pt = pair<ll, ll>;

pt pts[MAXN], b[2];

pt operator-(const pt &a, const pt &b) {
  return {a.f-b.f, a.s-b.s};
}

ll cross(const pt &a, const pt &b) {
  return a.f*b.s - a.s*b.f;
}

ll dot(const pt &a, const pt &b) {
  return a.f*b.f + a.s*b.s;
}

double dist(const pt &a, const pt &b) {
  return hypot<double>(a.f-b.f, a.s-b.s);
}

bool onseg(const pt &s, const pt &e, const pt &p) {
  return cross(s-p, e-p) == 0 && dot(s-p, e-p) <= 0;
}

pt pv[3];

bool inpoly(const pt &p) {
  int cnt = 0, n = 3;
  for (int i = 0; i < n; i++) {
    pt q = pv[(i+1)%n];
    if (onseg(pv[i], q, p)) return false;
    cnt ^= ((p.s < pv[i].s) - (p.s < q.s)) * cross(pv[i]-p, q-p) > 0;
  }
  return cnt;
}

double dp[MAXN][MAXN], ad[2][MAXN][MAXN];

int main() {
  cin.tie(0)->sync_with_stdio(0); // initialize fast I/O

  const double inf = 1e18;

  double ans = inf;

  int n; cin >> n;
  for (int i = 0; i < n; i++)
    cin >> pts[i].f >> pts[i].s;
  cin >> b[0].f >> b[0].s >> b[1].f >> b[1].s;

  for (int j = 2; j < n; j++) {
    for (int i = 0; i < n; i++) {
      int ep = (i + j) % n;
      dp[i][j] = ad[0][i][j] = ad[1][i][j] = 1e18;
      pv[0] = pts[i];
      pv[1] = pts[ep];
      for (int ki = 1; ki < j; ki++) {
        int k = (i+ki)%n;
        double cand = 1e18;
        if (ki == 1) {
          cand = dist(pts[k], pts[ep])+dp[(i+1)%n][j-1];
        } else if (ki == j-1) {
          cand = dist(pts[k], pts[i])+dp[i][j-1];
        } else {
          double cost = dist(pts[i], pts[k]) + dist(pts[k], pts[ep]);
          cand = cost+dp[i][ki]+dp[k][j-ki];
        }
        if (j == 2) cand = 0;
        dp[i][j] = min(dp[i][j], cand);
        pv[2] = pts[k];
        for(int bb = 0; bb < 2; bb++) {
          if (inpoly(b[bb])) {
            ad[bb][i][j] = min(ad[bb][i][j], cand);
          }
        }
      }
    } 
  }


  for (int i = 0; i < n; i++) {
    for (int d = 1; d < n; d++) {
      for (int da = 2; d+da+2 <= n; da++) {
        double fx = (d > 1 ? dist(pts[i], pts[(i+d)%n])+dp[i][d] : 0);
        int db = n-d-da;
        int j = (i+d)%n;
        int k = (j+da)%n;
        fx += dist(pts[j], pts[k]) + dist(pts[i], pts[k]);
        ans = min(ans, fx + ad[0][j][da] + ad[1][k][db]);
        ans = min(ans, fx + ad[1][j][da] + ad[0][k][db]);
      }
    }
  }


  if (ans == inf) {
    cout << "IMPOSSIBLE";
  } else {
    cout << fixed << setprecision(15) << ans << "\n";
  }

  return 0;
}

