// 计算杨辉三角模2前n行的1的总数
long long solve_0110(long long n) {
  if (n == 0) return 0;
  long long m = 1;
  long long p3 = 1;
  while (m * 2 <= n) {
    m *= 2;
    p3 *= 3;
  }
  if (m == n) return p3;
  return p3 + 2 * solve_0110(n - m);
}

void solve() {
  string f;
  char type;
  cin >> f >> type;
  if (type == 'B') {
    long long r, i;
    cin >> r >> i;
    if (f[3] == '1') {
      cout << 1 << "\n";
    } else if (f == "0000") {
      if (i == 1 || i == r)
        cout << 1 << "\n";
      else
        cout << 0 << "\n";
    } else if (f == "0010" || f == "1010") {
      if (i == 1 || i == r)
        cout << 1 << "\n";
      else if ((r % 2) == (i % 2))
        cout << 1 << "\n";
      else
        cout << 0 << "\n";
    } else if (f == "0100" || f == "1100") {
      if (i == 1 || i == r)
        cout << 1 << "\n";
      else if (i % 2 == 1)
        cout << 1 << "\n";
      else
        cout << 0 << "\n";
    } else if (f == "0110") {
      // 卢卡斯定理判断组合数奇偶性
      if (((r - 1) & (i - 1)) == (i - 1))
        cout << 1 << "\n";
      else
        cout << 0 << "\n";
    } else if (f == "1000") {
      if (i == 1 || i == r)
        cout << 1 << "\n";
      else if (r % 2 == 0)
        cout << 0 << "\n";
      else if (i == 2 || i == r - 1)
        cout << 0 << "\n";
      else
        cout << 1 << "\n";
    } else if (f == "1110") {
      if (i == 1 || i == r)
        cout << 1 << "\n";
      else if (r % 2 == 0)
        cout << 1 << "\n";
      else
        cout << 0 << "\n";
    }
  } else {
    long long r;
    cin >> r;
    if (f[3] == '1') {
      cout << r * (r + 1) / 2 << "\n";
    } else if (f == "0000") {
      if (r == 1)
        cout << 1 << "\n";
      else
        cout << 2 * r - 1 << "\n";
    } else if (f == "0010" || f == "1010" || f == "0100" || f == "1100") {
      cout << r + r * r / 4 << "\n";
    } else if (f == "0110") {
      cout << solve_0110(r) << "\n";
    } else if (f == "1000") {
      if (r == 1)
        cout << 1 << "\n";
      else if (r == 2)
        cout << 3 << "\n";
      else if (r == 3)
        cout << 5 << "\n";
      else {
        long long ans = 5;
        long long c0 = r / 2 - 1;  // 偶数行数量
        ans += c0 * 2;
        long long max_odd = (r % 2 != 0) ? r : r - 1;
        if (max_odd >= 5) {
          long long c1 = (max_odd - 5) / 2 + 1;  // 奇数行数量
          // 等差数列求和: 首项为3, 公差为2
          ans += c1 * 3 + c1 * (c1 - 1);
        }
        cout << ans << "\n";
      }
    } else if (f == "1110") {
      if (r == 1)
        cout << 1 << "\n";
      else if (r == 2)
        cout << 3 << "\n";
      else {
        long long ans = 3;
        long long max_odd = (r % 2 != 0) ? r : r - 1;
        if (max_odd >= 3) {
          long long c1 = (max_odd - 3) / 2 + 1;
          ans += c1 * 2;
        }
        long long max_even = (r % 2 == 0) ? r : r - 1;
        if (max_even >= 4) {
          long long c0 = (max_even - 4) / 2 + 1;
          // 等差数列求和: 首项为4, 公差为2
          ans += 4 * c0 + c0 * (c0 - 1);
        }
        cout << ans << "\n";
      }
    }
  }
}

