typedef long long ll;
typedef long double db;
struct Point{
    int x,y;
}a[5005];
int n,m,ispeak[5005];
db L[5005],R[5005],RR;
db Gety(int x){
    for(int i=1;i<n;i++){
        if(a[i].x<=x&&x<=a[i+1].x){
            return a[i].y+(db)(a[i+1].y-a[i].y)/(db)(a[i+1].x-a[i].x)*(x-a[i].x);
        }
    }
    return -1;
}
int Getp(int x){
    for(int i=1;i<n;i++){
        if(a[i].x<=x&&x<=a[i+1].x){
            return i;
        }
    }
    return -1;
}
db Solve(int l,int r,int x,db xtank){
    db sum=xtank;
    for(int i=l+1;i<r;i++){
        if(a[i].x<=x&&(ispeak[i]&1))sum+=L[i];
        if(a[i].x>=x&&(ispeak[i]&2))sum+=R[i];
    }
    return sum/(a[r].x-a[l].x)/RR;
}
int main(){
    cin>>n>>RR>>m;
    for(int i=1;i<=n;i++)cin>>a[i].x>>a[i].y;
    for(int i=1;i<=n;i++){
        db cury=a[i].y;
        if(a[i-1].y<a[i].y&&i>1){
            for(int j=i;j>1;j--){
                if(a[j-1].y>cury){
                    db nx=a[j].x-(cury-a[j].y)/((db)(a[j-1].y-a[j].y)/(a[j].x-a[j-1].x));
                    L[i]+=(a[j].x-nx)*(cury-a[j].y)/2;
                    break;
                }
                else {
                    L[i]+=(cury-max(a[j].y,a[j-1].y))*(a[j].x-a[j-1].x);
                    L[i]+=abs(a[j].y-a[j-1].y)*(a[j].x-a[j-1].x)/2.0;
                }
            }
        }
        if(i<n&&a[i+1].y<a[i].y){
            for(int j=i;j<n;j++){
                if(a[j+1].y>a[i].y){
                    db nx=(cury-a[j].y)/((db)(a[j+1].y-a[j].y)/(a[j+1].x-a[j].x))+a[j].x;
                    R[i]+=(nx-a[j].x)*(cury-a[j].y)/2;
                    break;
                }
                else {
                    R[i]+=(cury-max(a[j].y,a[j+1].y))*(a[j+1].x-a[j].x);
                    R[i]+=abs(a[j].y-a[j+1].y)*(a[j+1].x-a[j].x)/2.0;
                }
            }
        }
    }
    for(int i=1;i<=m;i++){
