            xtank+=(cury-a[pos+1].y)*(a[pos+1].x-x)/2.0;
            for(int j=pos+1;j<n;j++){
                if(a[j+1].y>cury){
                    db nx=(cury-a[j].y)/((db)(a[j+1].y-a[j].y)/(a[j+1].x-a[j].x))+a[j].x;
                    xtank+=(nx-a[j].x)*(cury-a[j].y)/2;
                    break;
                }
                else {
                    xtank+=(cury-max(a[j].y,a[j+1].y))*(a[j+1].x-a[j].x);
                    xtank+=abs(a[j].y-a[j+1].y)*(a[j+1].x-a[j].x)/2.0;
                }
            }
        }
        else {
            xtank+=(cury-a[pos].y)*(x-a[pos].x)/2.0;
            for(int j=pos;j>1;j--){
                if(a[j-1].y>cury){
                    db nx=a[j].x-(cury-a[j].y)/((db)(a[j-1].y-a[j].y)/(a[j].x-a[j-1].x));
                    xtank+=(a[j].x-nx)*(cury-a[j].y)/2;
                    break;
                }
                else {
                    xtank+=(cury-max(a[j].y,a[j-1].y))*(a[j].x-a[j-1].x);
                    xtank+=abs(a[j].y-a[j-1].y)*(a[j].x-a[j-1].x)/2.0;
                }
            }
        }
        memset(ispeak,0,sizeof(ispeak));
        for(int j=pos;j>=1;j--){
            if(j!=1&&a[j-1].y>=a[j].y)continue;
            if(j!=1&&a[j].y<=cury)continue;
            if(a[j].y>cury)ispeak[j]|=1;
            db curry=Gety(x);
            for(int k=pos+1;k<=n;k++){
                if(k!=n&&a[k+1].y>=a[k].y)continue;
                if(k!=n&&a[k].y<=curry)continue;
                if(a[k].y>curry)ispeak[k]|=2;
                ans=min(ans,Solve(j,k,x,xtank));
                //cout<<j<<' '<<k<<' '<<ans<<'\n';
                curry=a[k].y;
            }
            cury=a[j].y;
        }
        cout<<fixed<<setprecision(10)<<ans<<'\n';
    }
}

