def dot(v1, v2):
    return v1[0]*v2[0] + v1[1]*v2[1] + v1[2]*v2[2]
def cross(v1, v2):
    return [v1[1]*v2[2]-v2[1]*v1[2], v1[2]*v2[0]-v1[0]*v2[2], v1[0]*v2[1]-v1[1]*v2[0]]
def plus(v1, v2):
    return [v1[0]+v2[0], v1[1]+v2[1], v1[2]+v2[2]]
def minus(v1, v2):
    return [v1[0]-v2[0], v1[1]-v2[1], v1[2]-v2[2]]

def intersect(T, p1, p2):
    n = cross(T[1], T[2])
    v = [p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2]]
    d = - dot(T[0], n)

    if dot(v, n) == 0:
        return False

    t = (dot(n, p1) + d) / dot(n, v)
    t = -t

    if t < 0 or t > 1:
        return False

    P = [p1[0]+t*v[0], p1[1]+t*v[1], p1[2]+t*v[2]]
    P = minus(P, T[0])

    if (T[1][0]*T[2][1] - T[1][1] * T[2][0]) == 0:
        return False

    s = (P[0]*T[2][1] - P[1]*T[2][0]) / (T[1][0]*T[2][1] - T[1][1] * T[2][0])
    t = (P[1]*T[1][0] - P[0]*T[1][1]) / (T[1][0]*T[2][1] - T[1][1] * T[2][0])

    if s < 0 or s > 1 or t < 0 or t > 1 or s+t>1:
        return False


    return True

def TriangleLinked(T, T2):
    T1 = [T[0], minus(T[1], T[0]), minus(T[2], T[0])]
    cnt = 0
    cnt += intersect(T1, T2[0], T2[1])
    cnt += intersect(T1, T2[1], T2[2])
    cnt += intersect(T1, T2[2], T2[0])

    return cnt == 1

