int sum(int a, int b) {
    a += b;
    if (a >= mod)
        a -= mod;
    return a;
}

int sub(int a, int b) {
    a -= b;
    if (a < 0)
        a += mod;
    return a;
}

int mult(int a, int b) {
    return 1ll * a * b % mod;
}

int bp(int a, int b) {
    int res = 1;
    while (b) {
        if (b & 1)
            res = mult(res, a);
        a = mult(a, a);
        b >>= 1;
    }
    return res;
}

int inv(int x) {
    return bp(x, mod - 2);
}


int par[N], rnk[N];

void make_set(int u)
{
    par[u] = u;
    rnk[u] = 0;
}

int find_set(int u)
{
    if (par[u]==u) return u;
    return par[u] = find_set(par[u]);
}

void union_sets(int v, int u)
{
    v = find_set(v);
    u = find_set(u);
    if (v==u) return;
    if (rnk[v]<rnk[u]) swap(v,u);
    par[u] = v;
    if (rnk[u]==rnk[v]) rnk[v]++;
}

