struct SA{
    int n;
    string s;
    vector<int> sa, lcp, pos, resp;
    vector<vector<int> > rank_subs;

    vector<int> suffix_array(){
        s.push_back('$');
        int n = (int)s.size(), N = max(n, 260);
        vector<int> sa(n), rank(n);
        for(int i=0; i<n; i++) sa[i] = i, rank[i] = s[i];

        for(int k=0; k<n; k ? k*=2 : k++){
            vector<int> nsa(sa), nrank(n), cnt(N);

            for(int i=0; i<n; i++) nsa[i] = (nsa[i]-k+n)%n, cnt[rank[i]]++;
            for(int i=1; i<N; i++) cnt[i] += cnt[i-1];
            for(int i=n-1; i+1; i--) sa[--cnt[rank[nsa[i]]]] = nsa[i];

            for(int i=1, r = 0; i<n; i++) nrank[sa[i]] = r += rank[sa[i]] != rank[sa[i-1]] || rank[(sa[i]+k)%n] != rank[(sa[i-1]+k)%n];

            rank = nrank;
            if(rank[sa[n-1]]==n-1) break;
        }
        s.pop_back();
        return vector<int>(sa.begin()+1, sa.end());
    }

    vector<int> build_lcp(){
        int n = (int)s.size(), k = 0;
        vector<int> rank(n), lcp(n);
        for(int i=0; i<n; i++) rank[sa[i]] = i;

        for(int i=0; i<n; i++, k-=!!k){
            if(rank[i]==n-1) {k=0; continue;}
            int j = sa[rank[i]+1];
            while(i+k<n && j+k<n && s[i+k]==s[j+k]) k++;
            lcp[rank[i]]=k;
        }
        return lcp;
    }

    SA() {}

    SA(string &s) : s(s), n((int)s.size()), pos(n), resp(n) {
        sa = suffix_array();
        lcp = build_lcp();
    }

    void solve(){
        // cout << n/2 << endl;
        for(int i=0; i<n; i++){
            // cout << sa[i] << ' ';
            if(sa[i] < n/2 + 1){
                int l = i-1;
                if(l>=0 && sa[l] == sa[i] + n/2 + 1) l--;
                resp[sa[i]] = max(l>=0 ? lcp[l]:-1, lcp[i]);
            }
        }
        // cout << endl;
    }
};

