unordered_map<ll, int> pos;
vector<pair<char, int> > ops;
int dp[mxn], entrei[mxn];

int solve(ll x){
    if(!pos[x]) return 0;
    if(entrei[pos[x]]) return (int)1e4+5;
    entrei[pos[x]]=1;
    int &ans = dp[pos[x]];
    if(ans!=-1) return ans;
    int best = 1e4+5;
    for(auto [c, d]:ops){
        if(c == '+'){
            best = min(best, solve(x + d));
        }else if(c == '-'){
            if(x-d>=0) best = min(best, solve(x-d));
        }else if(c == '*'){
            best = min(best, solve(x * d));
        }else{
            best = min(best, solve(x/d));
        }
    }
    entrei[pos[x]]=0;
    return ans = min(best + 1, (int)1e4+5);
}

vector<int> ans;

void recap(ll x){
    int cont = 1;
    for(auto [c, d]:ops){
        if(c == '+'){
            if(!pos[x+d]){
                ans.push_back(cont);
                return;
            }
            if(dp[pos[x]] == 1 + dp[pos[x+d]]){
                ans.push_back(cont);
                recap(x+d);
                return;
            }
        }else if(c == '-'){
            if(x-d>=0){
                if(!pos[x-d]){
                    ans.push_back(cont);
                    return;
                }
                if(dp[pos[x]] == 1 + dp[pos[x-d]]){
                    ans.push_back(cont);
                    recap(x-d);
                    return;
                }
            }
        }else if(c == '*'){
            if(!pos[x*d]){
                ans.push_back(cont);
                return;
            }
            if(dp[pos[x]] == 1 + dp[pos[x*d]]){
                ans.push_back(cont);
                recap(x*d);
                return;
            }
        }else{
            if(!pos[x/d]){
                ans.push_back(cont);
                return;
            }
            if(dp[pos[x]] == 1 + dp[pos[x/d]]){
                ans.push_back(cont);
                recap(x/d);
                return;
            }
        }
        cont++;
    }
}

