struct SegmentTree {
    vector<ll> seg;
    int l0, ln;

    SegmentTree(int n) : ln{1} {
        while(ln < n) ln *= 2;
        seg = vector<ll>(2*ln - 1);
        l0 = seg.size()-ln;
    }

    void sum(int i, ll val) {
        i = l0+i;
        seg[i] += val;
        while(i > 0) {
            i = (i-1)/2;
            seg[i] += val;
        } 
    }

    ll query(int l, int r) {
        return query(l,r,0,ln-1,0);
    }

    ll query(int l, int r, int lx, int rx, int i) {
        if(rx < l || r < lx) return 0;
        if(l <= lx && rx <= r) return seg[i];
        int mid = (lx+rx)/2;
        return
            query(l,r,lx,mid,2*i+1) +
            query(l,r,mid+1,rx,2*i+2);
    }
};

