int clac(int x,int y) {
    int ret=0;
    for (int i=1;i<=s;i++) {
        for (int j=1;j<=r;j++) {
            int xx=x+i-1, yy=y+j-1;
            ret+=a[xx][yy]*b[i][j];
        }

    }
    return ret;
}
void flip() {
    int ss=s, rr=r;
    for (int i=1;i<=ss;i++) {
        for (int j=1;j<=rr;j++) {
            c[i][j]=b[i][j];
        }
    }
    for (int i=1;i<=s;i++) {
        for (int j=1;j<=r;j++) {
            b[j][s-i+1]=c[i][j];
        }
    }
    swap(s,r);
}
