#define int long long
#define N 300050
const int inf = 0x3f3f3f3f3f3f3f3f;
void solve()
{
    int n, k, d, s;
    cin >> n >> k >> d >> s;
    vector<int> a(n + n + 10), nxt(n + 10);
    for(int i = 1; i <= n; i++){
        cin >> a[i];
        a[i + n] = a[i];
        nxt[i] = (i + k - 1) % n + 1;
    }
    for(int i = 1; i <= n * 2; i++){
        a[i] += a[i - 1];
    }
    vector<int> vis(n + 1, -inf);
    for(int i = 1; i <= n - s + 1; i++){
        if(vis[i] != -inf) continue;
        int l = i, r = i + s - 1;
        if(l > r) r = r + n;
        int ll = l, rr = r;
        int sum = 0;
        if(k == 0 || k == n){
            sum += (a[r] - a[l - 1]) * d;
        }
        else{
            for(int j = 1; j <= d; j++){
                int x = a[r] - a[l - 1];
                sum += x;
                l = nxt[l];
                r = nxt[(r - 1) % n + 1];
                if(r < l) r += n;
            }
        }
        vis[i] = sum;
        int x = i;
        for(int p = 1; p <= inf; p++){
            x = nxt[x];
            if(vis[x] != -inf) break;
            sum -= a[rr] - a[ll - 1];
            sum += a[r] - a[l - 1];
            vis[x] = sum;
            ll = nxt[ll];
            rr = nxt[(rr - 1) % n + 1];
            if(ll > rr) rr += n;
            l = nxt[l];
            r = nxt[(r - 1) % n + 1];
            if(l > r) r += n;
        }
    }
    int ans = -inf;
    vector<int> viss(n + 1);
    int cnt = 0;
    for(int i = 1; i <= n - s + 1; i++){
        int x = i;
        for(int j = 1; j <= n - d + 1; j++){
            ans = max(ans, vis[x]);
            cnt++;
            viss[x] = 1;
            x = nxt[x];
            if(x > i && x <= n - s + 1) j = 0;
            if(viss[x]) break;
        }
    }
    cout << ans << endl;
}
signed main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T = 1;
    while (T--)
    {
        solve();
    }
}

