    cin >> n >> k;

    vector<basic_string<int>> g(n+1);
    
    vector<vector<int>> adj(n+1, vector<int>(n+1));

    for(int i = 1; i < n; i++){
        int a, b;
        cin >> a>> b;
        a--, b--;
        adj[a][b] = adj[b][a] = 1;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    n++;


    vector<int> block(n);
    block[n-1] = 1;

    auto can_max =[&](int sz, int last) -> bool {
        if(sz == 0) 
            return 1;
        
        int mx = 0;
        bool made = 0;
        for(int i = 0; i < n; i++){
            if(block[i])
                continue;
            made |= !adj[last][i];
            int cur = 0;
            for(int j : g[i])
                cur+=!block[j];

            mx = max(mx,cur);
        }
        return (sz == 1 || mx < sz-1) && made;
    };

    auto min_k =[&](int move, int last, int sz){
        // cerr << "mink " << move << ' ' << last << ' ' << sz << '\n';
        vector<int> check(n);
        vector<array<int,2>> dp(n);

        auto dfs =[&](int id, auto && dfs) -> void {
            check[id] = 1;
            vector<int> dif;

            int base = 0;
            for(int i : g[id]){
                if(block[i] || check[i])
                    continue;
                dfs(i,dfs);

                base+=dp[i][0];
                dif.push_back(dp[i][1]-dp[i][0]);
            }

            sort(all(dif));
            dif.push_back(INF);
            dif.push_back(INF);
            dp[id][1] = min(base, dif[0]+base);
            dp[id][0] = 1+min({base, dif[0]+base, dif[0]+dif[1]+base});
        };
        int resp = 0;
        dfs(move,dfs);
        resp+=dp[move][1];

        for(int i = 0; i < n; i++){
            if(!check[i] && !block[i]){
                dfs(i,dfs);
                resp+=dp[i][0];
            }
        }
        // cerr << resp << '\n';
        return resp;
    };

    auto is_valid =[&](int move, int last, int sz, int k)-> bool {
        k-=!adj[last][move];
        if(k >= sz || k < 0)
            return 0;
        if(k == sz-1){
            block[move] = 1;
            bool ok = can_max(sz-1, move);
            block[move] = 0;
            return ok;
        }
        return min_k(move,last,sz) <= k;
    };
    int last = n-1;
    int sz = n-1;
    k++;
    vector<int> resp;
    for(int i = 0; i < n-1; i++){
        bool ok = 0;
        for(int j = 0; !ok && j < n; j++){
            if(block[j])
                continue;

            if(is_valid(j,last,sz,k)){
                k-=!adj[last][j];
                last = j;
                block[j] = 1;
                resp.push_back(j+1);
                ok = 1;
                sz--;
                break;
            }
        }
        if(!ok){
            if(i == 0){
                cout << -1 << '\n';
                return 0;
            }
            break;
        }
    }

    for(int i : resp)
        cout << i << ' ';
    cout << '\n';
}

