int ccw(pair<int, int> a, pair<int, int> b){
	ll ret = (ll)a.first*b.second - (ll)a.second*b.first;
	if (ret > 0) return 1;
	if (ret < 0) return -1;
	return 0;
}

double dist(pair<int, int> a, int y){
	double lx = (double)a.first / (-a.second) * y;
	return sqrt(lx*lx + (double)y*y);
}

void NO(){
	printf("-1\n");
	exit(0);
}

int main(){
	int n;
	scanf("%d", &n);
	for (int i=1;i<=n;i++){
		scanf("%d %d %d %d", X+i, Y+i, L+i, R+i);
		I[i] = i;

		ansL[i] = {L[i] - X[i], -Y[i]};
		ansR[i] = {R[i] - X[i], -Y[i]};
	}

	sort(I+1, I+n+1, [&](int i, int j){return Y[i] > Y[j];});
	set<int> st;

	for (int _=1;_<=n;_++){
		int i = I[_];
		auto [it, __] = st.insert(i);

		if (it != st.begin()){
			auto pit = prev(it);
			auto cl = ansL[*pit];
			auto cr = ansR[*pit];
			pair<int, int> cx = {X[i] - X[*pit], Y[i] - Y[*pit]};

			if (ccw(cx, cl)==1) NO();
			if (ccw(cx, cr)==1) ansR[*pit] = cx;
		}

		if (next(it) != st.end()){
			auto nit = next(it);
			auto cl = ansL[*nit];
			auto cr = ansR[*nit];
			pair<int, int> cx = {X[i] - X[*nit], Y[i] - Y[*nit]};

			if (ccw(cr, cx)==1) NO();
			if (ccw(cl, cx)==1) ansL[*nit] = cx;
		}
	}

	double ans = 0;
	for (int i=1;i<=n;i++){
		if (ccw(ansL[i], pair<int, int>(0, -1)) >= 0 && ccw(pair<int, int>(0, -1), ansR[i]) >= 0) ans += Y[i];
		else ans += min(dist(ansL[i], Y[i]), dist(ansR[i], Y[i]));
	}

	printf("%.15f\n", ans);
}

