int reduce(int x){
    map<int,int> cnts;
    for(int i : primes){
        while(x%i==0){
            cnts[i]++;
            x/=i;
            if(x==1)break;
        }
    }
    int q = round(sqrt(x));
    if(q*q==x){
        cnts[q]+=2;
    }
    int ans = 1;
    for(auto p : cnts){
        int x = p.F;
        while(p.S>=2){
            ans*=x;
            p.S-=2;
        }
    }
    return ans;
}

