struct Mod {
    ll x;
    Mod(ll xx) : x(xx) {}
    Mod operator+(Mod b) {return Mod((x + b.x) % MOD); }
    Mod operator-(Mod b) {return Mod((x - b.x + MOD) % MOD); }
    Mod operator*(Mod b) {return Mod(((x * b.x) % MOD)); }
    friend Mod bpow(Mod a, ll e) {
        Mod ans = 1;
        for(; e; a = a * a, e /= 2)
            if(e & 1) ans = ans * a;
        return ans;
    }
    Mod operator/(Mod b) {return (*this) * bpow(b, MOD - 2); }
};

