		ll a,b,c; cin >> a >> b >> c; a--; b--;
		adj[a].pb({b,c});
		adj[b].pb({a,c});
	}

	vl deg(n);
	for(ll i=0;i<n;i++) deg[i] = sz(adj[i]);

	queue<ll> q;
	for(ll i=0;i<n;i++) if(sz(adj[i]) == 1) q.push(i);
	vl vis(n);

	vector<vl> dp(n, vl(1,0));
	while(sz(q)) {
		ll i = q.front(); q.pop();
		vis[i] = 1;
		sort(all(dp[i]), greater<>());
		for(auto [nx,nc] : adj[i]) if(!vis[nx]) {
			dp[nx].pb(dp[i][0]+nc);
			if(--deg[nx] == 1) q.push(nx);
		}
	}

	vl cyc, w, res;
	for(ll i=0;i<n;i++) if(!vis[i]) {
		if(sz(cyc) == 0) cyc.pb(i), vis[i] = 2;
		sort(all(dp[i]), greater<>());
	}

redo:
	for(auto [nx,nc] : adj[cyc.back()]) if(!vis[nx]) {
		vis[nx] = 2;
		cyc.pb(nx), w.pb(nc);
		goto redo;
	}

	for(auto [nx,nc] : adj[cyc.back()]) if(nx == cyc[0]) w.pb(nc);

	{
		res.resize(sz(cyc));
		ll n=sz(cyc), tot=accumulate(all(w),0LL);
		multiset<ll> slo,shi;
		ll phi=0,plo=0,whi=0,wlo=0,wcur=0;

		for(ll i=0;i<2*n;i++) {
			while(whi-wcur <= tot/2) {
				shi.insert(whi + dp[cyc[phi%n]][0]);
				whi += w[phi++ % n];
			}
			while(wcur-wlo > tot/2) {
				slo.erase(slo.find(-wlo + dp[cyc[plo%n]][0]));
				wlo += w[plo++ % n];
			}

			shi.erase(shi.find(wcur + dp[cyc[i%n]][0]));
			if(sz(shi)) res[i%n] = max(res[i%n], *shi.rbegin() - wcur);
			if(sz(slo)) res[i%n] = max(res[i%n], wcur + *slo.rbegin());
			slo.insert(-wcur + dp[cyc[i%n]][0]);
			wcur += w[i%n];
		}

		auto dfs = [&](auto &&dfs, ll i, ll ls, ll val)->void {
			for(auto [nx,c] : adj[i]) if(nx!=ls && vis[nx] == 1) {
				if(dp[nx][0]+c == dp[i][0]) dfs(dfs,nx,i,max(val,dp[i][1])+c);
				else dfs(dfs,nx,i,max(val,dp[i][0])+c);
			}

			dp[i][0] = max(dp[i][0], val);
		};

		for(ll i=0;i<n;i++) dfs(dfs,cyc[i],-1,res[i]);
	}

	for(ll i=0;i<n;i++) cout << dp[i][0] << ' ';
	cout << '\n';
}

