          if (v == s2){
            if (t == 0) nt = 0;
            else nt = t + 1;
          }
          T tmp = dp[i - 1][j][t];
          tmp.first += (u != v);
          add(dp[i][j + nt / 3][nt % 3], tmp); 
        }
      }
    }
  }

  T ans = inf;
  for (int t = 0; t <= 2; ++ t) 
    add(ans, dp[n][k][t]);

  cout << ans.first << ' ' << ans.second;
}

