// 定义导线结构体
struct Wire {
    long long r; // 范围可能很大，使用 long long
    int s;       // 信号类型
};

// 干扰矩阵：impacts[aggressor][victim]
// 如果 impacts[j][i] 为 true，表示类型 j 的信号会干扰类型 i
bool impacts[205][205]; 

int main() {
    // 优化输入输出速度
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<Wire> wires(N);
    for (int i = 0; i < N; ++i) {
        cin >> wires[i].r >> wires[i].s;
    }

    // 读取干扰矩阵
    // 输入描述：第 i 行描述哪些信号影响类型 i
    // 如果第 j 个字符是 '0'，则类型 j 影响类型 i
    for (int i = 1; i <= M; ++i) { // i 代表受害者 (Victim)
        string row;
        cin >> row;
        for (int j = 1; j <= M; ++j) { // j 代表干扰者 (Aggressor)
            char c = row[j-1]; // 字符串下标从0开始，对应类型 j
            if (c == '0') {
                impacts[j][i] = true;
            } else {
                impacts[j][i] = false;
            }
        }
    }

    // 存储每根导线的位置
    vector<long long> pos(N);
    
    // 第一根导线固定在位置 1
    pos[0] = 1;

    for (int i = 1; i < N; ++i) {
        // 基础约束：必须在上一根导线的右边，不能重叠
        pos[i] = pos[i-1] + 1;

        // 检查与左侧所有导线 j 的相互干扰情况
        for (int j = 0; j < i; ++j) {
            int type_i = wires[i].s;
            int type_j = wires[j].s;
            long long range_i = wires[i].r;
            long long range_j = wires[j].r;

            // 情况 1: 左边的 j 干扰 右边的 i
            // i 必须在 j 的范围之外：pos[i] > pos[j] + range_j
            // 即 pos[i] >= pos[j] + range_j + 1
            if (impacts[type_j][type_i]) {
                pos[i] = max(pos[i], pos[j] + range_j + 1);
            }

            // 情况 2: 右边的 i 干扰 左边的 j
            // j 必须在 i 的范围之外：pos[j] < pos[i] - range_i
            // 移项得：pos[i] > pos[j] + range_i
            // 即 pos[i] >= pos[j] + range_i + 1
            if (impacts[type_i][type_j]) {
                pos[i] = max(pos[i], pos[j] + range_i + 1);
            }
        }
    }

    // 输出最后一根导线的位置
    cout << pos[N-1] << endl;

    return 0;
}

