struct World{
	int lanes[20][2];
	queue<int> q[20];
	vector<Event> events[MAXN];

	void attempt(int t, int x){
		if(q[x].empty()) return;
		if(lanes[x][0]) return;
		if(!lanes[x][1]){
			lanes[x][1] = 1;
			auto u = q[x].front(); q[x].pop();
			events[t + f[u]].push_back({2, x, 1, u});
			ans[u] = t + f[u];
		}
		else{
			lanes[x][0] = 1;
			auto u = q[x].front(); q[x].pop();
			events[t + f[u]].push_back({2, x, 0, u});
			ans[u] = t + f[u];
		}
	}

	void run(int t){
		sort(events[t].begin(), events[t].end(), cmp);
		for(auto [type, lane, slot, car]: events[t]){
			if(type == 2){
				lanes[lane][slot] = 0;
				attempt(t, lane); attempt(t, lane);
			}
