        nmm[r]^=3;
	for(int i=l;i<r;i++)
	{
		if(nmm[i]!=nmm[i+1])
		{
			int nw=wkot(l,i,2^x&1)^wkot(i+2,r,x&2);
			if(se.find(nw)==se.end())se.insert(nw);
			nw=wkot(l,i-1,x&1)^wkot(i+1,r,1^x&2);
			if(se.find(nw)==se.end())se.insert(nw);
		}
	}
	int nw=0;
	for(set<int>::iterator ite=se.begin();ite!=se.end();ite++)
	{
		if(nw!=*ite)
		{
			return res[l][r][x]=nw;
		}
		nw++;
	}
	return res[l][r][x]=nw;
}
