        int x;
        cin >> x;
        arr.push_back(x);
    }
    sort(arr.begin(), arr.end());
    vector<int> moves;
    auto inr = [&](int l, int r) -> int {
        auto it1 = upper_bound(arr.begin(), arr.end(), r);
        auto it2 = lower_bound(arr.begin(), arr.end(), l);
        return (it1 - it2);
    };
    while (sz(arr)) {
        int curm = 0, val = 0;
        for (int i = sz(arr) - 1; i >= 0; i--) {
            int num = inr(arr[i] - 2 * radius, arr[i]);
            if (num >= curm) {
                curm = num;
                val = arr[i] - radius;
            }
        }
        moves.push_back(val);
        vector<int> narr;
        for (int i = 0; i < sz(arr); i++) {
            if (!(val - radius <= arr[i] && arr[i] <= val + radius)) {
                narr.push_back(arr[i]);
            }
        }
        arr = narr;
    }
    cout << sz(moves) << "\n";
    for (auto u : moves) {
        cout << u << " ";
    }
    cout << "\n";
}

