map<int,int> reduce(map<int,int> a){
    while(true){
        bool win=false;
        int x = 0;
        for(pi p : a){
            if(p.S >= 10){
                x=p.F;
                win=true;
            }
        }
        if(!win)break;
        a[x]-=10;
        a[x+1]++;
    }
    while(true){
        bool win=false;
        int x = 0;
        for(pi p : a){
            if(p.S == 0){
                x=p.F;
                win=true;
            }
        }
        if(!win)break;
        a.erase(x);
    }
    return a;
}

map<int,int> add(map<int,int> a, map<int,int> b){
    for(pi p : b){
        a[p.F]+=p.S;
    }
    return reduce(a);
}

map<int,int> mul(map<int,int> a, map<int,int> b){
    map<int,int> c;
    for(pi p : a){
        for(pi q : b){
            c[p.F+q.F]+=p.S*q.S;
        }
    }
    return reduce(c);
}

bool bigger(map<int,int> a, map<int,int> b){
    if(sz(a)==0)return false;
    if(sz(b)==0)return true;
    pi p = *(--a.end());
    pi q = *(--b.end());
    if(p > q)return true;
    if(q>p)return false;
    a.erase(p.F);
    b.erase(q.F);
    return bigger(a,b);
}

