int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    if (!(cin >> N)) return 0;
    vector<double>  x(N), y(N);
    for (int i = 0; i < N; ++i) cin >> x[i] >> y[i];

    vector<vector<double>> dist(N, vector<double>(N));
    for (int i = 0; i < N; ++i)
        for (int j = i + 1; j < N; ++j) {
            double d = hypot(x[i] - x[j], y[i] - y[j]);
            dist[i][j] = dist[j][i] = d;
        }

    const double INF = 1e100;
    double best = INF;

    for (int c = 0; c < N; ++c) {
        double max1 = 0, max2 = 0;
        for (int k = 0; k < N; ++k) {
            double d = dist[c][k];
            if (d > max1) { max2 = max1; max1 = d; }
            else if (d > max2) max2 = d;
        }
        best = min(best, max1 + max2);
    }

    const int ITER = 50;            
    for (int i = 0; i < N; ++i)
        for (int j = i + 1; j < N; ++j) {
            double dij = dist[i][j];
            if (dij == 0) continue;   

            double lo = 0.0, hi = 1.0;
            auto diameter = [&](double alpha) {
                double di = alpha * dij;
                double dj = (1.0 - alpha) * dij;
                double big1 = 0.0, big2 = 0.0;
                for (int k = 0; k < N; ++k) {
                    double val = min(di + dist[i][k], dj + dist[j][k]);
                    if (val > big1) { big2 = big1; big1 = val; }
                    else if (val > big2) big2 = val;
                }
                return big1 + big2;
            };

            for (int it = 0; it < ITER; ++it) {
                double a = (2 * lo + hi) / 3.0;
                double b = (lo + 2 * hi) / 3.0;
                if (diameter(a) < diameter(b)) hi = b;
                else lo = a;
            }
            best = min(best, diameter((lo + hi) / 2.0));
        }

    cout << fixed << setprecision(10) << best << '\n';
    return 0;
}

