int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
bool is_bad(int x,int y){
    return x < 0 || x >= n || y < 0 || y >= m || s[x][y] == '*';
}
bool is_blocked(int x,int y,int mask){
    if(s[x][y] == '#') return true;
    if('A' <= s[x][y] && s[x][y] <= 'D'){
        int pos = s[x][y] - 'A';
        return !((mask>>pos)&1);
    }
    if('a' <= s[x][y] && s[x][y] <= 'd'){
        int pos = s[x][y] - 'a';
        return (mask>>pos)&1;
    }
    return false;
}
int main(){
