            if(s[i][j] == 'S') st.push_back(i*m + j), s[i][j] = '.';
            if(s[i][j] == 'E') ed.push_back(i*m + j), s[i][j] = '.';
            //if(s[i][j] == 'A')
        }
    }
    d[st[0]][st[1]][0] = 0;
    queue<tuple<int,int,int>> q;
    q.emplace(st[0], st[1], 0);
    while(!q.empty()){
        auto [p1, p2, msk] = q.front();
        q.pop();
        if((p1 == ed[0] && p2 == ed[1]) || (p1 == ed[1] && p2 == ed[0])){
            cout<<d[p1][p2][msk]<<"\n";
            return 0;
        }
        int x1 = p1/m, y1 = p1%m;
        int x2 = p2/m, y2 = p2%m;
        for(int i=0;i<4;i++){
            int nx1 = x1  + dx[i], ny1 = y1 + dy[i];
            int nx2 = x2  + dx[i], ny2 = y2 + dy[i];
            if(is_bad(nx1, ny1)) continue;
            if(is_bad(nx2, ny2)) continue;
            bool blk1 = is_blocked(nx1, ny1, msk), blk2 = is_blocked(nx2, ny2, msk);
            if(blk1) nx1 = x1, ny1 = y1;
            if(blk2) nx2 = x2, ny2 = y2;
            if(nx1 == nx2 && ny1 == ny2) continue;
            int np1, np2, nmsk = msk;
            if(!blk1 && '1' <= s[nx1][ny1] && s[nx1][ny1] <= '4'){
