                int pos = s[nx2][ny2] - '1';
                nmsk ^= 1 << pos;
            }
            if(is_blocked(nx1, ny1, nmsk)) continue;
            if(is_blocked(nx2, ny2, nmsk)) continue;
            np1 = nx1*m + ny1;
            np2 = nx2*m + ny2;
            if(d[np1][np2][nmsk]==-1){
                d[np1][np2][nmsk] = d[p1][p2][msk] + 1;
                q.emplace(np1, np2, nmsk);
            }
        }
    }
    assert(false);
    return 0;
}

