typedef long long ll;
using pll=pair<ll,ll>;
int n;
ll S;
ll L,R;
vector<pll> A,B;
ll Solve(vector<pll> &a){
    ll o=LONG_LONG_MAX;
    sort(a.begin(),a.end(),[&](pll x,pll y){
        return x.second<y.second;
    });
    vector<ll> suf(a.size()+1);
    suf.back()=R;
    for(int i=(int)a.size()-1;i>=0;--i){
        //cerr<<" ?? "<<a[i].first<<" "<<a[i].second<<endl;
        suf[i]=min(suf[i+1],a[i].first);
    }
    for(int i=0;i<(int)a.size();++i){
        //cerr<<" .. "<<(a[i].second-S)*2<<" "<<S-L<<" "<<R-L<<" "<<R-suf[i+1]<<endl;
        o=min(o,(a[i].second-S)*2+(S-L)+(R-L)+(R-suf[i+1]));
    }
    //cerr<<" o: "<<o<<endl;
    sort(a.begin(),a.end());
    vector<pll> _a;
    for(auto [l,r]:a){
        if(_a.empty()||l>_a.back().second){
            _a.emplace_back(l,r);
        }
        else{
            _a.back().second=max(_a.back().second,r);
        }
    }
    a=_a;
    if(a.empty())return S-L+(R-L);
    ll tot=R-a[0].first;
    ll tmp=0;
    if(a[0].first<=S){
        tmp=(a[0].second-S)*2;
        a.erase(a.begin());
    }
    int m=a.size();
    vector<ll> s(m+1);
    for(int i=1;i<=m;++i){
        s[i]=s[i-1]+(a[i-1].second-a[i-1].first)*2;
    }
    tot=min(tot,s[m]+tmp);
    for(int i=m-1;i>=0;--i){
        tot=min(tot,s[i]+R-a[i].first+tmp);
    }
    tot+=S-L+(R-L);
    return min(tot,o);
}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin>>n>>S;
    L=S;
    R=S;
    
    for(int i=1;i<=n;++i){
        ll u,v;
        cin>>u>>v;
        L=min(L,min(u,v));
        R=max(R,max(u,v));
        if(u>S&&v<u){
            A.emplace_back(v,u);
        }
        if(u<S&&v>u){
            B.emplace_back(v,u);
        }
    }
    ll ans=Solve(A);
    S=-S;
    L=-L;
    R=-R;
    swap(L,R);
    for(auto &[u,v]:B){
        u=-u,v=-v;
    }
    ans=min(ans,Solve(B));
    cout<<ans<<'\n';
    return 0;
}

