		adj[v].pb(u);
		M[u][v]=M[v][u]=true;
	}
	
	VI C(n,-1);
	// returns mask were bit is set when color is available
	auto av_cols=[&](int v) -> int
	{
		int mask=0b000;
		for(auto to: adj[v])
		{
			if(C[to] != -1)
				mask |= (1<<C[to]);
		}
		return (~mask)&0b111;
	};
	
	auto get_col=[&](int mask) -> int{
		return 31 - __builtin_clz(mask);
	};
	
	FOR(num,0,pow(3,k))
	{
		fill(all(C), -1);
		int x=num;
		FOR(i,0,k)
		{
			C[i]=x%3;
			x/=3;
		}
		bool ok=true;
		FOR(i,0,k)
		{
			FOR(j,i+1,k)
			{
				if(M[i][j] && C[i] == C[j])
					ok=false;
			}
		}
		if(!ok)continue;
		set<int> S;
		FOR(v,k,n)S.insert(v);
		bool exists=true;
		while(!S.empty())
		{
			bool one=false;
			for(auto v: S)
			{
				int mask = av_cols(v);
				int pc=__popcount((unsigned)mask);
				if(pc==0)
				{
					exists=false;
					break;
				}
				else if(pc==1)
				{
					C[v]=get_col(mask);
					S.erase(v);
					one=true;
					break;
				}
			}
			if(!exists) break;

			if(!one)
			{
				for(auto v: S)
				{
					int mask = av_cols(v);
					int pc=__popcount((unsigned)mask);
					if(pc==0)
					{
						exists=false;
						break;
					}
					else
					{
						C[v]=get_col(mask);
						S.erase(v);
						break;
					}
				}
			}
			if(!exists) break;
		}
		
		if(exists)
		{
			cout<<"possible\n";
			for(auto c: C)
				cout<<c+1<<" ";
			cout<<'\n';
			return 0;
		}
	}

	cout<<"impossible\n";
	return 0;
}

