const int mod = (int)(1e9 + 7), MOD = mod;

struct Matrix {
    int n, m;
    vector<vector<int>> arr;

    Matrix(int _n, int _m) {
        n = _n;
        m = _m;
        arr.assign(n, vector<int>(m));
    }

    vector<int> & operator [] (int i) {
        return arr[i];
    }

    Matrix operator * (Matrix b) {
        Matrix ret(n, b.m);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < b.m; ++j){
                for (int k = 0; k < m; ++k) {
                    ret.arr[i][j] += arr[i][k] * b.arr[k][j] % MOD;
                    ret.arr[i][j] %= MOD;
                }
            }
        }
        return ret;
    }

    Matrix pow (int p) {
        Matrix ret(n, n), mul = *this;
        for (int i = 0; i < n; ++i) {
            ret.arr[i][i] = 1;
        }

        for ( ; p; p >>= 1) {
            if (p & 1) ret = ret * mul;
            mul = mul * mul;
        }
        return ret;
    }
};

