    for (int i = 1; i <= p; ++i) {
        int t; cin >> t;
        char g; cin >> g;
        int x, y, z; cin >> x >> y >> z;
        mp[t].push_back({(g - 'A'), x, y, z});
    }
    mp[n].push_back({0, s, c, s + c});
    Matrix mats(s + 1, s + 1), matc(c + 1, c + 1);
    for (int rev = 0; rev < 2; ++rev) {
        for (int i = 0; i <= s; ++i) {
            for (int j = 0; j <= s; ++j) if (abs(i - j) <= 1) {
                if (i < j) mats[i][j] = (s - i);
                else if (i > j) mats[i][j] = i;
                else mats[i][j] = 1;
            }
        }
        swap(s, c);
        swap(mats, matc);
    }
    auto cal = [&](int x, int y) {
        return x * (c + 1) + y;
    };
    vector<int> state(cal(s, c) + 1);
    state[cal(s, c)] = 1;
    int pre = 1;
    for (auto &[t, v] : mp) {
        int dif = t - pre;
        Matrix mats_pow = mats.pow(dif);
        Matrix matc_pow = matc.pow(dif);
        vector<int> nxt(state.size());
        for (int i = 0; i <= s; ++i) for (int j = 0; j <= c; ++j) for (int i2 = 0; i2 <= s; ++i2) for (int j2 = 0; j2 <= c; ++j2) {
            int mul = mats_pow[i][i2] * matc_pow[j][j2] % mod;
            nxt[cal(i2, j2)] += state[cal(i, j)] * mul;
            nxt[cal(i2, j2)] %= mod;
        }
        for (int i = 0; i <= s; ++i) for (int j = 0; j <= c; ++j) {
            bool good = true;
            for (auto &[g, x, y, z] : v) {
                if (g == 0 && (i < x || j < y || (i + j) < z)) good = false;
                if (g == 1 && ((s - i) < x || (c - j) < y || ((s - i) + (c - j)) < z)) good = false;
            }
            if (good == false) nxt[cal(i, j)] = 0;
        }
        state = nxt;
        pre = t;
    }
    cout << state[cal(s, c)] << '\n';
}

