			vis[i]=0; vis[fa[fa[i]]]=1;
			work(i,fa[i],i,1);
			fa[i]=1;
			return 1;
		}
		return 0;
	}
	void swp(int x,int y,int z){
		work(x,y,x,z);
		fa[y]=1; cir[y]=0; vis[y]=0;
		fa[z]=x; fa[x]=1; cir[x]=0; cir[z]=1; vis[x]=vis[z]=1;
	}
	int Ge(){
		for(int i=2;i<=n;i++) if(fa[i]==1&&G[i].size()==1) return i;
		return -1;
	}
	vector<node> sol(){
		dfs(1,-1);
		for(int i=1;i<=n;i++){
			for(int j:G[i]) if(d[j]<d[i]&&j^fa[i]&&j^fa[fa[i]]){
				work(i,j,i,fa[fa[i]]);
				break;
			}
		}
		for(int i=1;i<=n;i++){
			for(int j:G[i]) if(d[j]<d[i]&&j^fa[i]) cir[i]=1;
		}
		for(int i=1;i<=n;i++) if(cir[i]) vis[i]=vis[fa[i]]=1;
		for(int i=2;i<=n;i++) if(!vis[i]){
			work(i,fa[i],i,1);
			fa[i]=1;
		}
		while(Del()) ;
		while(1){
			int flag=0;
			for(int i=2;i<=n;i++) if(cir[i]&&fa[fa[i]]==1){
				if(G[i].size()>2){
					swp(fa[i],i,Ge());
					flag=1; break;
				}
				if(G[fa[i]].size()>2){
					swp(i,fa[i],Ge());
					flag=1; break;
				}
			}
			if(!flag) break;
			while(Del()) ;
		}
		for(int i=1;i<=m-(n-1);i++){
			int x=2*i;
			if(G[x].size()==1){
				for(int j=2*i;j<=n;j++) if(fa[fa[j]]==1){
					swp(j,fa[j],x);
					break;
				}
			}
			int z=2*i+1;
			if(G[z].size()==2){
				int p=G[z][0]^G[z][1]^1;
				swp(p,z,Ge());
			}
			int y=G[x][0]^G[x][1]^1;
			swp(x,y,z);
		}
		return ans;
	}
