#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
constexpr int N = 200005, TC = 4 * N;

int n, m;

#define L (z << 1)
#define R (z << 1 | 1)
LL a[TC], b[TC], totsum;
int v[TC], t[TC];
void tag(int z, int l, int c) {
	v[z] += c, a[z] += l * (LL)c, b[z] += l * (LL)c, t[z] += c;
}
void down(int z, int a, int b) {
	int &s = t[z];
	if (s) tag(L, a, s), tag(R, b, s), s = 0;
}
LL qA(int c, int l, int r, int z) {
	if (v[z] <= c) {
		return c * (r - l + 1ll);
	}
	if (l == r) {
		return max(c, v[z]);
	}
	int md = l + r >> 1;
	down(z, md - l + 1, r - md);
	if (c <= v[L]) {
		return qA(c, l, md, L) + a[z] - a[L];
	}
	return c * (md - l + 1ll) + qA(c, md + 1, r, R);
}
LL qB(int c, int l, int r, int z) {
	if (v[z] <= c) {
		return c * (r - l + 1ll);
	}
	if (l == r) {
		return max(c, v[z]);
	}
	int md = l + r >> 1;
	down(z, md - l + 1, r - md);
	if (c <= v[R]) {
		return qB(c, md + 1, r, R) + b[z] - b[R];
	}
	return qB(c, l, md, L) + c * (LL)(r - md);
}
void build(int l = 1, int r = n, int z = 1) {
	if (l == r) {
		cin >> v[z], a[z] = b[z] = v[z], totsum += v[z];
		return;
	}
	int md = l + r >> 1;
	build(l, md, L), build(md + 1, r, R);
	v[z] = max(v[L], v[R]);
	a[z] = a[L] + qA(v[L], md + 1, r, R);
	b[z] = b[R] + qB(v[R], l, md, L);
}
void A(int ql, int qr, int l = 1, int r = n, int z = 1) {
	if (l >= ql && r <= qr) {
		tag(z, r - l + 1, 1);
		return;
	}
	int md = l + r >> 1;
	down(z, md - l + 1, r - md);
	if (ql <= md) {
		A(ql, qr, l, md, L);
	}
	if (md < qr) {
		A(ql, qr, md + 1, r, R);
	}
	v[z] = max(v[L], v[R]);
	a[z] = a[L] + qA(v[L], md + 1, r, R);
	b[z] = b[R] + qB(v[R], l, md, L);
}
LL Ans() {
	return a[1] + b[1] - v[1] * (LL)n - totsum;
}

int main() {
	cin.tie(0)->sync_with_stdio(false);
	cin >> n >> m;
	build();
	cout << Ans() << "\n";
	while (m--) {
		int l, r;
		cin >> l >> r;
		A(l, r), totsum += r - l + 1;
		cout << Ans() << "\n";
	}
	return 0;
}

