	double operator*(vec a){
		return x*a.x+y*a.y;
	}
	double operator^(vec a){
		return x*a.y-y*a.x;
	}
	vec operator+(vec a){
		return {x+a.x,y+a.y};
	}
	vec operator-(vec a){
		return {x-a.x,y-a.y};
	}
	double len(){return sqrtl(x*x+y*y);}
	vec one(){return {x/len(),y/len()};};
	vec operator*(double d){return {x*d,y*d};}
	void print(){cerr<<x<<' '<<y<<'\n';}
};
const double eps=1e-10;
const double PI=acosl(-1);
void solve(){
	int n;double s;
	cin>>n>>s;
	s*=2;
	vector<vec> hull(n);
	for(int i=0;i<n;i++)	{
		cin>>hull[i].x>>hull[i].y;
	}
	for(int i=1;i<n;i++)	hull[i]=hull[i]-hull[0];
	hull[0]={0,0};
	double pans=0,sans=0;
	auto getsn=[&](vec a,vec b)->double {
		double v=abs((a^b)/a.len()/b.len());
		return v;
	};
	auto getmid=[&](vec st,vec ed)->vec {
		st=st.one();ed=ed.one();
		double v=(st*ed);
		if(v>1)	v=1;
		if(v<-1)	v=-1;
		vec mid=(st+ed).one();
		return mid*(2*sqrtl((1-v)/2));
	};
	for(int i=0;i<n;i++){
		vec mid=hull[i];
		vec pre=hull[(i+n-1)%n];
		vec seg=hull[(i+1)%n];
		sans+=getmid(mid-pre,seg-mid)^mid;
	}
	// cerr<<sans<<'\n';
	int r=1;
	vec sump=hull[1];int num=1;
	double area=0;
	auto nxt=[&](int x){return (x+1)%n;};
	auto pre=[&](int x){return (x+n-1)%n;};
	auto getarea=[&](int p,int l)->double {
		return abs((hull[p]-hull[l])^(hull[p]-hull[nxt(l)]));
	};
	while(area+getarea(0,r)<=s)	{area+=getarea(0,r);r=nxt(r);sump=sump+hull[r];num++;}
	auto get=[&](vec st,vec ml,vec mr,double s)->vec {
		double l=(ml-st).len();
		double sn=getsn(st-ml,mr-ml);
		double len=s/(l*sn);
		vec d=ml+(mr-ml).one()*len;
		return (d-st);
	};
	vec preO=get(hull[0],hull[r],hull[nxt(r)],s-area);
	auto  d=preO;
	for(int i=0;i<n;i++){
		area-=getarea(r,i);
		while(area+getarea(nxt(i),r)<=s)	{
			area+=getarea(nxt(i),r);
			vec nxtO=get(hull[nxt(r)],hull[nxt(i)],hull[i],s-area)*-1;
			pans+=(getmid(preO,nxtO)^(sump*((double)1.0/num)));
			// cerr<<pans<<'\n';
			preO=nxtO;
			r=nxt(r);num++;sump=sump+hull[r];
		}
		auto nxtO=get(hull[nxt(i)],hull[r],hull[nxt(r)],s-area);
		pans+=((getmid(preO,nxtO)^(sump*((double)1.0/num))));preO=nxtO;
		num--;sump=sump-hull[nxt(i)];
		// cerr<<pans<<'\n';

	}
	cout<<setprecision(12)<<abs(pans-sans)/(2*acosl(-1))<<'\n';

}

