				fa[v]=u;
				fe[v]=id;
				dfs(v);
				continue;
			}
			if(dfn[u]>dfn[v])
			{
				adde1(++n1,v,id);
				for(int i=u;i!=v;i=fa[i])
					adde1(n1,i,fe[i]);
			}
		}
}
void dfs1(int u,int fa=0)
{
	w[u]=u>n&&(e1[u].size()&1);
	for(auto [v,id]:e1[u]) if(v!=fa)
		dfs1(v,u),w[u]^=w[v];
}
void dfs2(int u,int fa=0,int fe=0,int x=1,int y=2)
{
	if(x>y) swap(x,y);
	if(u<=n)
	{
		if(y-x==1) x=y;
		for(auto [v,id]:e1[u])
			if(v!=fa&&w[v])
			{
				if(y-x==2) dfs2(v,u,id,x-1,y-1),x=y;
				else x+=2,y+=4,dfs2(v,u,id,x,y);
			}
		assert(x==y);
		for(auto [v,id]:e1[u])
			if(v!=fa&&!w[v])
				dfs2(v,u,id,x+1,x+2),x+=2;
	}
	else
	{
		z[fe]=x;
		int t=x;
		for(auto [v,id]:e1[u])
			if(v!=fa&&w[v])
			{
				if(t<y) t+=2,sgn[v]=1;
				else t-=2,sgn[v]=-1;
			}
		for(auto [v,id]:e1[u])
			if(v!=fa&&!w[v])
			{
				if(t<y) ++t,sgn[v]=1;
				else --t,sgn[v]=-1;
			}
		t=x;
		for(auto [v,id]:e1[u])
			if(v!=fa)
			{
				int t1=t+(w[v]?2:1)*sgn[v];
				dfs2(v,u,id,t,t1);
				z[id]=t=t1;
			}
		assert(t==y);
	}
}
