    return tuple(x-y for x,y in zip(p1,p2))
    
def dot(p1,p2):
    return sum(x*y for x,y in zip(p1,p2))

def rotO(R,p):
    return tuple(dot(row,p) for row in R)

def rot(R,c,p):
    return add(rotO(R,sub(p,c)),c)

