    x,y,z,t=p
    match alp:
        case 0:
            return x+s,y,z,t
        case 45:
            return x,y+s,z,t+s
        case 90:
            return x,y,z+s,t
        case 135:
            return x,y-s,z,t+s
        case 180:
            return x-s,y,z,t
        case 225:
            return x,y-s,z,t-s
        case 270:
            return x,y,z-s,t
        case 315:
            return x,y+s,z,t-s
