}e[200010];
void add_edge(int u,int v,int w){
    // cout<<u<<" "<<v<<" "<<w<<"\n";
    e[++o]=(edge){v,head[u],w},head[u]=o;
    e[++o]=(edge){u,head[v],0},head[v]=o;
}
void addedges(int l,int r,int cnt,int ty){
    if(l>r||!cnt) return;
    head[++tot]=0;
    if(ty) add_edge(tot,T,cnt);
    else add_edge(S,tot,cnt);
    for(int i=l;i<=r;i++){
        if(ty) add_edge(p[ty][i],tot,1),b[p[ty][i]]=tot;
        else add_edge(tot,p[ty][i],1),a[p[ty][i]]=tot;
    }
}
bool bfs(){
    for(int i=1;i<=tot;i++) dep[i]=0,cur[i]=head[i];
    queue<int>q;
    q.push(S),dep[S]=1;
    while(q.size()){
        int u=q.front();q.pop();
        for(int i=head[u],v;i;i=e[i].link) if(e[i].w&&!dep[v=e[i].to]){
            dep[v]=dep[u]+1;
            q.push(v);
        }
    }
    return dep[T]>0;
}
int dfs(int u,int in){
    if(u==T) return in;
    int out=0;
    for(int &i=cur[u],v;i;i=e[i].link) if(dep[v=e[i].to]==dep[u]+1&&e[i].w){
        int res=dfs(v,min(in,e[i].w));
        e[i].w-=res;
        e[i^1].w+=res;
        in-=res;
        out+=res;
        if(!in) break;
    }
    if(!out) cur[u]=0;
    return out;
}
bool vis[200010];
bool chk(int u,int t){
    if (u==t) return 1;
    vis[u]=1;
    for (int i=head[u];i;i=e[i].link) if (e[i].w&&!vis[e[i].to]) {
        if (chk(e[i].to,t)) return 1;
    }
    return 0;
}
