	for(int i=1;i<=N;i++) {
		scanf("%s",s+1);
		for(int j=1;s[j];j++) vq[i][s[j]-'A']++,vc[s[j]-'A']++;
	}
	for(int i=1;i<=N;i++) {
		int ans=0;
		for(int j=0;j<26;j++) {
			if(vc[j]==vq[i][j]) {
				if(vc[j]) ans=0x3f3f3f3f;
			}
			else {
				int s1=vq[i][j];
				int s2=vc[j]-vq[i][j];
				ans=std::max(ans,(s1+s2-1)/s2);
			}
