int T;
struct vec {
	ll x,y;
	int id;
	ll operator*(vec a){return x*a.x+y*a.y;}
	ll operator^(vec a){return x*a.y-y*a.x;}
	vec operator+(vec a){return {x+a.x,y+a.y};}
	vec operator-(vec a){return {x-a.x,y-a.y};}
	bool operator==(vec a) {return x==a.x&&y==a.y;}
	int core(){return (y==0&&x<0)||y<0;}
	void print(){cerr<<x<<' '<<y<<'\n';}
	bool operator<(vec a){if(core()!=a.core())	return core()==1;return ((*this)^a)>=0;}
};
vector<vec> convex(vector<vec> p){
	sort(p.begin(),p.end(),[&](vec a,vec b){if(a.x!=b.x)	return a.x<b.x;return a.y>b.y;});
	int n=p.size();
	int lo=0;
	vector<vec> res;
	for(int i=0;i<n;i++){
		while(lo>=2&&((res[lo-1]-res[lo-2])^(p[i]-res[lo-1]))<=0)	lo--,res.pop_back();
		res.push_back(p[i]);lo++;
	}
	int pre=lo;
	for(int i=n-2;i>=0;i--){
		while(lo>=pre+1&&((res[lo-1]-res[lo-2])^(p[i]-res[lo-1]))<=0)	lo--,res.pop_back();
		res.push_back(p[i]);lo++;
	}
	return res;
}
pair<int,int> get_pot_convex(vec v,vector<vec>& hull){
	if(hull.size()==3)	return {0,1};
	
	int sz=hull.size();
	int lo=0,ro=sz-2;
	int flag=((((hull[1]-v)^(hull[0]-v))>=0)?1:-1);
	while(lo<ro){
		int mid=(lo+ro+1)>>1;
		if((((hull[mid]-v)^(hull[0]-v))*flag)>=0)		lo=mid;
		else ro=mid-1;
	}
	pair<int,int> lcut={0,lo},rcut={lo+1,sz-1};
	pair<int,int> ans;
	if(flag==1)	swap(lcut,rcut);
	lo=lcut.first,ro=lcut.second;
	while(lo<ro){
		int mid=(lo+ro)>>1;
		if(((hull[mid+1]-hull[mid])^(v-hull[mid]))>=0)	lo=mid+1;
		else ro=mid;
	}
	ans.first=(lo==sz-1?0:lo);
	lo=rcut.first,ro=rcut.second;
	while(lo<ro){
		int mid=(lo+ro)>>1;
		if(((hull[mid+1]-hull[mid])^(hull[mid]-v))>=0)	lo=mid+1;
		else ro=mid;
	}
	ans.second=(lo==sz-1?0:lo);
	swap(ans.first,ans.second);
	return ans;
}
