int sgn(ll x){if(x>0)	return 1;if(x==0)	return 0;return -1;}
bool on(vec a,vec b,vec  c){
	if(((c-a)*(c-b))<=0&&((c-a)^(c-b))==0)	return true;
	return false;
}
bool inconvex(vec a,vector<vec>& hull){
	if(hull.size()==3)	return on(hull[0],hull[1],a);
	int o=0,lo=1,ro=(int)hull.size()-2;
	if(a==hull[o])		return true;
	if(!(((a-hull[o])^(hull[lo]-hull[o]))<=0&&((a-hull[o])^(hull[ro]-hull[o]))>=0))	return false;
	while(lo+1<ro){
		int mid=(lo+ro)>>1;
		if(((hull[mid]-hull[o])^(a-hull[o]))<0)	ro=mid;
		else lo=mid;
	}
	return ((hull[ro]-hull[lo])^(a-hull[lo]))>=0;
}
bool segment(vec a,vec b,vec c,vec d){
	if(on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b))	return true;
	return sgn((c-b)^(a-b))*sgn((d-b)^(a-b))<0&&sgn((a-d)^(c-d))*sgn((b-d)^(c-d))<0;
}

