void add(int x, int v) {
  for (; x <= n; x += x & -x) {
    bit[x] += v;
  }
}

int sum(int x) {
  int v = 0;
  for (; x; x -= x & -x) {
    v += bit[x];
  }
  return v;
}

int f[N], r[N];
Dis c[N];
ll clc(vector<Dis> &x, vector<Dis> &y, Dis p, Dis q) {
  int m = x.size() + y.size();
  ll res = 0;
  memset(bit, 0, sizeof(int) * (m + 1));
  for (int i = 0; i < x.size(); i++) {
    c[i] = x[i];
  }
  for (int i = 0; i < y.size(); i++) {
    c[i + x.size()] = y[i];
  }
  for (int i = 0; i < m; i++) {
    f[i] = i;
  }
  sort(f, f + m, [](int x, int y){
    ll v = Len(P, c[x]) * Len(P, c[y]);
    if (v == 0) {
      return x < y;
    }
    return v > 0;
  });
  for (int i = 0; i < m; i++) {
    r[f[i]] = i + 1;
  }
  sort(f, f + m, [](int x, int y){
    ll v = Len(Q, c[x]) * Len(Q, c[y]);
    if (v == 0) {
      return x < y;
    }
    return v > 0;
  });
  for (int i = 0; i < m; i++) {
    if (f[i] < x.size()) {
      add(r[f[i]], 1);
    } else {
      res += sum(r[f[i]]);
    }
  }
  return res;
}

