#include<bits/stdc++.h>
using namespace std;
const int maxn = 1000005, maxm = 1005;
int T, n, m, s, t;
char c[maxm][maxm], ch[maxm][maxm];
int id[maxm][maxm], cnt;
vector<int> a[maxn], b[maxn];
int cut[maxn], p[maxn], dfn[maxn], low[maxn], tot, tt;
int l[maxn], r[maxn], d1[maxm], d2[maxm], d3[maxm], dep[maxn];
stack<int> st;
int ans;
void add(int x, int y) {a[x].push_back(y), a[y].push_back(x);}
void addb(int x, int y) {b[x].push_back(y), b[y].push_back(x);}
void dfs1(int fa, int x) {
    dfn[x] = low[x] = ++tot; st.push(x);
    for (auto y : a[x]) {
        if (y == fa) continue;
        if (dfn[y]) low[x] = min(low[x], dfn[y]);
        else {
            dfs1(x, y); low[x] = min(low[x], low[y]);
            if (low[y] >= dfn[x]) {
                addb(++tt, x);
                while (!st.empty()) {
                    int u = st.top(); st.pop();
                    addb(tt, u);
                    if (u == y) break;
                }
            }
        }
    }
}
bool dfs2(int fa, int x) {
    if (x == t) return 1;
    int pp = 0;
    for (auto y : b[x]) {
        if (y == fa) continue;
        if (dfs2(x, y)) {pp = 1; break;}
    }
    if (!pp) return 0;
    if (x > cnt)
        for (auto y : b[x]) p[y] = 1;
    if (x != s) cut[x] = 1;
    return 1;
}
void dfs3(int fa, int x) {
    dep[x] = dep[fa] + 1;
    if (x > cnt)
        for (auto y : b[x])
            if (y != s && y != t && !cut[y]) dep[y] = dep[x];
    for (auto y : b[x])
        if (y != fa && (cut[y] || y == t)) dfs3(x, y);
}
bool chk(int l, int r, int ll, int rr) {
    int p1 = (d1[ll - 1] > d1[l - 1]), p2 = (d2[ll - 1] > d2[l - 1]);
    int q1 = (d1[r] > d1[rr]), q2 = (d2[r] > d2[rr]);
    if ((p1 && p2) || (q1 && q2)) return 0;
    if (!((p1 && q2) || (p2 && q1))) return 1;
    return d3[ll - 1] <= rr;
}
int check(int x) {
    for (int i = l[x] - 1; i <= r[x]; i++) d1[i] = d2[i] = d3[i] = 0;
    for (auto y : a[x]) {
        int ll = l[y], rr = r[y];
        if (rr < l[x]) rr++;
        if (ll > r[x]) ll--;
        ll = max(ll, l[x]); rr = min(rr, r[x]);
        if (!p[y]) {
            int jj = 0;
            for (auto i : b[y])
                for (auto j : b[x])
                    if (i == j) {jj = i; break;}
            l[jj] = min(l[jj], ll); r[jj] = max(r[jj], rr);
        }
        else if (dep[y] < dep[x]) d1[ll]++, d1[rr + 1]--;
        else d2[ll]++, d2[rr + 1]--;
    }
    for (auto y : b[x])
        if (!cut[y]) d3[l[y]] = max(d3[l[y]], r[y]);
    for (auto y : b[x]) l[y] = m + 1, r[y] = 0;
    for (int i = l[x]; i <= r[x]; i++) d3[i] = max(d3[i], d3[i - 1]), d1[i] += d1[i - 1], d2[i] += d2[i - 1];
    for (int i = l[x]; i <= r[x]; i++) d1[i] += d1[i - 1], d2[i] += d2[i - 1];
    int p = l[x], ans = 1e9;
    for (int i = l[x]; i <= r[x]; i++) {
        p = max(p, i);
        while (p <= r[x] && !chk(l[x], r[x], i, p)) p++;
        if (p > r[x]) break;
        ans = min(ans, p - i + 1);
    }
    return ans;
}
void solve() {
    cnt = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            if (c[i][j] == 's') s = id[i][j] = ++cnt;
            if (c[i][j] == 'f') t = id[i][j] = ++cnt;
            if (c[i][j] == '.') id[i][j] = (c[i][j - 1] == '.' ? id[i][j - 1] : ++cnt);
            if (c[i][j] == '#') id[i][j] = 0;
        }
    for (int i = 1; i <= 2 * cnt; i++) a[i].clear(), b[i].clear();
    for (int i = 1; i <= cnt; i++) l[i] = m, r[i] = 1;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (id[i][j]) l[id[i][j]] = min(l[id[i][j]], j), r[id[i][j]] = max(r[id[i][j]], j);
    for (int i = 1; i < n; i++)
        for (int j = 1; j <= m; j++)
            if (id[i][j] && id[i + 1][j] && (id[i][j - 1] != id[i][j] || id[i + 1][j - 1] != id[i + 1][j])) add(id[i][j], id[i + 1][j]);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < m; j++)
            if (id[i][j] && id[i][j + 1] && id[i][j] != id[i][j + 1]) add(id[i][j], id[i][j + 1]);
    for (int i = 1; i <= cnt * 2; i++) dfn[i] = low[i] = p[i] = cut[i] = 0;
    while (!st.empty()) st.pop();
    tot = 0; tt = cnt; dfs1(0, s);
    if (!dfs2(0, s)) {ans = 0; return;}
    dfs3(0, s);
    for (int i = cnt + 1; i <= tt; i++) l[i] = m + 1, r[i] = 0;
    for (int i = 1; i <= cnt; i++)
        if (cut[i]) ans = min(ans, check(i));
}
