#include <bits/stdc++.h>
using namespace std;
#define rep(i, a, b) for(int i = (a); i < (b); ++i)
#define all(x) (x).begin(), (x).end()

typedef long long ll;

const int N = 2e5+5;
int n;
ll x[N], y[N], r[N];

__int128_t abs(__int128_t x) { return x >= 0 ? x : (~x + 1); }

struct F {
  typedef __int128_t T;
  T a, b;
  void norm() {
    if(b < 0) a = -a, b = -b;
    T g = __gcd(abs(a), b);
    a /= g;
    b /= g;
  }
  F(T a=0, T b=1) : a(a), b(b) { norm(); }

  F operator+(const F f) const { return F(a*f.b + f.a*b, b*f.b); }
  F operator-(const F f) const { return F(a*f.b - f.a*b, b*f.b); }
  F operator*(const F f) const { return F(a*f.a, b*f.b); }

  bool operator<(const F f) const { return a*f.b < f.a*b; }
};

int sgn(const F f) { return (f.a > 0) - (f.a < 0); }

struct P {
  typedef F T;
  T x, y;
  explicit P(T x=T(), T y=T()) : x(x), y(y) {}

  P operator+(const P p) const { return P(x+p.x, y+p.y); }
  P operator-(const P p) const { return P(x-p.x, y-p.y); }
  P operator*(const T d) const { return P(x*d, y*d); }

  bool operator<(const P p) const { return tie(x, y) < tie(p.x, p.y); }

  int half() const {
    return sgn(y) == -1 || (sgn(y) == 0 && sgn(x) == -1);
  }
} c[N];

struct A {
  int i; bool top;

  bool contains(const A& a) const {
    return r[i] > r[a.i] // don't contain self
      && (x[i]-x[a.i])*(x[i]-x[a.i])+(y[i]-y[a.i])*(y[i]-y[a.i]) <= r[i]*r[i];
  }
  bool operator<(const A& a) const {
    if(contains(a)) return !top;
    if(a.contains(*this)) return a.top;
    return tie(y[i], x[i], top) < tie(y[a.i], x[a.i], a.top);
  }
};

pair<bool, P> inter(int i, int j) {
  if(i == j) return {0, P()};
  if((x[i]-x[j])*(x[i]-x[j])+(y[i]-y[j])*(y[i]-y[j]) == (r[i]+r[j])*(r[i]+r[j]))
    return {1, c[i] + (c[j]-c[i]) * F(r[i], r[i]+r[j])};
  if((x[i]-x[j])*(x[i]-x[j])+(y[i]-y[j])*(y[i]-y[j]) == (r[i]-r[j])*(r[i]-r[j]))
    return {1, c[i] + (c[j]-c[i]) * F(r[i], r[i]-r[j])};
  return {0, P()};
}

void solve() {
  int n; cin >> n;
  rep(i, 0, n) {
    cin >> x[i] >> y[i] >> r[i];
    c[i] = P(F(x[i]), F(y[i]));
  }

  typedef tuple<ll, int, int> E;
  vector<E> ev;
  rep(i, 0, n) {
    ev.emplace_back(x[i]-r[i], 0, i);
    ev.emplace_back(x[i]+r[i], 1, i);
  }
  sort(all(ev));

  set<A> s;
  vector<pair<int, int>> cand;
  for(auto [_, id, i] : ev) {
    vector<A> as = {A(i, 0), A(i, 1)};
    for(A& a : as) {
      if(id) {
        // remove
        auto it = s.find(a);
        if(it != s.begin() && next(it) != s.end())
          cand.emplace_back(prev(it)->i, next(it)->i);
        s.erase(it);
      } else {
        // add
        auto [it, added] = s.insert(a);
        assert(added);
        if(it != s.begin())
          cand.emplace_back(prev(it)->i, i);
        if(next(it) != s.end())
          cand.emplace_back(i, next(it)->i);
      }
    }
  }

  map<P, set<int>> mp;
  for(auto [i, j] : cand) {
    auto [is, p] = inter(i, j);
    if(!is) continue;
    mp[p].insert(i);
    mp[p].insert(j);
  }

  ll ans = 0;
  for(auto [p, is] : mp) {
    ll cnt[2] = {};
    for(auto i : is)
      cnt[(p-c[i]).half()]++;
    ans += cnt[0] * cnt[1];
  }
  cout << ans << endl;
}

int main() {
  int t; cin >> t;
  while(t--) solve();
}

