typedef long double db;

using namespace std;

const db eps=1e-15;

int sgn(db x){return x<-eps?-1:x>eps;}
struct vec
{
	db x,y;
	void read(){cin>>x>>y;}
	vec operator+(vec b)const{return {x+b.x,y+b.y};}
	vec operator-(vec b)const{return {x-b.x,y-b.y};}
	vec operator*(db k)const{return {k*x,k*y};}
	db operator^(vec b)const{return x*b.x+y*b.y;}
	db operator*(vec b)const{return x*b.y-y*b.x;}
	bool operator==(vec b)const{return !sgn(x-b.x)&&!sgn(y-b.y);}
	bool operator<(vec b)const{return sgn(x-b.x)?x<b.x:sgn(y-b.y)==-1;}
	vec rot90(int z){return {-y*z,x*z};}
	db d(){return sqrt(x*x+y*y);}
	db ata(){return atan2l(y,x);}
};
struct node
{
	db k;vec A;
	bool operator<(const node b)const
	{
		return sgn(k-b.k)?sgn(k-b.k)<0:A<b.A;
	}
};
struct dynamic_convex
{
	set<vec>u,d;
	set<node>ku,kd;
	bool chk(vec v)
	{
		if(u.empty())return 0;
		auto r=u.lower_bound(v);
		if(r==u.begin()&&*r==v)return 1;
		if(r==u.begin()||r==u.end()||sgn((*r-*prev(r))*(v-*prev(r)))>0)return 0;
		r=d.lower_bound(v);
		if(r==d.begin()&&*r==v)return 1;
		return !(r==d.begin()||r==d.end()||sgn((*r-*prev(r))*(v-*prev(r)))<0);
	}
	void ins(vec v)
	{
		if(chk(v))return;
		auto r=u.lower_bound(v);
		if(r==u.begin()||r==u.end()||sgn((*r-*prev(r))*(v-*prev(r)))>0)
		{
			if(r!=u.begin()&&r!=u.end())
				ku.erase({(*r-*prev(r)).ata(),*prev(r)});
			auto t=u.insert(v).first;
			while(r!=u.end()&&next(r)!=u.end()&&sgn(((*r)-v)*(*next(r)-*r))>=0)
			{
				ku.erase({(*next(r)-*r).ata(),*r});
				r=next(r);u.erase(prev(r));
			}
			if(t!=u.begin())
			{
				auto l=prev(t);
				while(l!=u.begin()&&sgn((*l-*prev(l))*(v-*l))>=0)
				{
					ku.erase({(*l-*prev(l)).ata(),*prev(l)});
					l=prev(l);u.erase(next(l));
				}
				ku.insert({(*next(l)-*l).ata(),*l});
			}
			if(r!=u.end())
				ku.insert({(*next(t)-*t).ata(),*t});
		}
		r=d.lower_bound(v);
		if(r==d.begin()||r==d.end()||sgn((*r-*prev(r))*(v-*prev(r)))<0)
		{
			if(r!=d.begin()&&r!=d.end())
				kd.erase({(*r-*prev(r)).ata(),*prev(r)});
			auto t=d.insert(v).first;
			while(r!=d.end()&&next(r)!=d.end()&&sgn(((*r)-v)*(*next(r)-*r))<=0)
			{
				kd.erase({(*next(r)-*r).ata(),*r});
				r=next(r);d.erase(prev(r));
			}
			if(t!=d.begin())
			{
				auto l=prev(t);
				while(l!=d.begin()&&sgn((*l-*prev(l))*(v-*l))<=0)
				{
					kd.erase({(*l-*prev(l)).ata(),*prev(l)});
					l=prev(l);d.erase(next(l));
				}
				kd.insert({(*next(l)-*l).ata(),*l});
			}
			if(r!=d.end())
				kd.insert({(*next(t)-*t).ata(),*t});
		}
	}
}A;

