	mi[x] = val[x];
	siz[x] = siz[ch[x][0]] + siz[ch[x][1]] + 1;
	if (ch[x][0] && mi[ch[x][0]] < mi[x]) mi[x] = mi[ch[x][0]];
	if (ch[x][1] && mi[ch[x][1]] < mi[x]) mi[x] = mi[ch[x][1]];
}
void pushdown(int x) {
	upd(ch[x][0], ad[x]);
	upd(ch[x][1], ad[x]);
	ad[x] = 0;
}
void rotate(int x) {
	int y = fa[x], z = fa[y], b = get(x);
	if (z) ch[z][get(y)] = x;
	ch[y][b] = ch[x][!b], ch[x][!b] = y;
	fa[ch[y][b]] = y, fa[y] = x, fa[x] = z;
	pushup(y);
}
void down(int x) {
	if (!x) return;
	down(fa[x]);pushdown(x);
}
void splay(int x, int k) {
	down(x);
	for (; fa[x] != k; rotate(x)) if (fa[fa[x]] != k)
		rotate((get(x) ^ get(fa[x])) ? x : fa[x]);
	pushup(x);
}

vector<int> S;

void dfs(int u) {
	if (!u || mi[u] > 0) return;
	pushdown(u);
	dfs(ch[u][0]);
	if (val[u] <= 0) S.push_back(u / 2);
	dfs(ch[u][1]);
}
int sub(int x) {
	splay(x, 0); val[x] --, pushup(x);
	if (val[x] <= 0) S.push_back(x / 2);
	int ans = 1 + siz[ch[x][1]];
	upd(ch[x][1], -1);
	dfs(ch[x][1]);
	return ans;
}

unordered_map<int, map<int, int> > mp[3];
int dead[N], r[N], c[N];
void merge(int a, int b) {
	if (a) {
		splay(a, 0);
		fa[ch[a][1]] = 0;
		ch[a][1] = 0;
		pushup(a);
	}
	if (b) {
		splay(b, 0);
		fa[ch[b][0]] = 0;
		ch[b][0] = 0;
		pushup(b);
	}
	if (a && b) {
		ch[a][1] = b;
		fa[b] = a;
		pushup(a);
	}
}
void ins(map<int, int> &m, int p, int v) {
	auto it = m.emplace(p, v).first;
	if (next(it) != m.end()) merge(v, next(it)->second ^ 1);
	if (it != m.begin()) merge(prev(it)->second, v ^ 1);
}
void del(map<int, int> &m, int p, int v) {
	auto it = m.find(p);
	int x = 0, y = 0;
	if (next(it) != m.end()) y = next(it)->second ^ 1;
	if (it != m.begin()) x = prev(it)->second;
	merge(x, y);
	m.erase(it);
}
void kill(int x) {
	dead[x] = 1;
	del(mp[1][r[x] + c[x]], -r[x] + c[x], x * 2);
	del(mp[2][-r[x] + c[x]], r[x] + c[x], x * 2 + 1);
}

