int dfsf(int k, int i, int j) {
  if (f[k][i][j] != -1) {
    return f[k][i][j];
  }
  if (k == 0) {
    f[k][i][j] = (a[i][j] == '.' && a[i][j + 1] == '.') || (a[i][j] == 'L' && a[i][j + 1] == 'R');
    return f[k][i][j];
  }

  int l = 1 << (k - 1);

  int v = 1ll * dfsh(k - 1, i, j + l) * dfsh(k - 1, i, j + 2 * l) % mod * dfsh(k - 1, i + l, j + l) % mod * dfsh(k - 1, i + l, j + 2 * l) % mod;

  f[k][i][j] = (1ll * dfsh(k, i, j) * dfsh(k, i, j + 2 * l) + (1ll * dfsf(k - 1, i, j + l) * dfsf(k - 1, i + l, j + l) + mod - v) % mod * dfsg(k - 1, i, j) % mod * dfsg(k - 1, i, j + 3 * l)) % mod;
  return f[k][i][j];
}

int dfsg(int k, int i, int j) {
  if (g[k][i][j] != -1) {
    return g[k][i][j];
  }
  if (k == 0) {
    g[k][i][j] = (a[i][j] == '.' && a[i + 1][j] == '.') || (a[i][j] == 'U' && a[i + 1][j] == 'D');
    return g[k][i][j];
  }

  int l = 1 << (k - 1);
  int v = 1ll * dfsh(k - 1, i + l, j) * dfsh(k - 1, i + 2 * l, j) % mod * dfsh(k - 1, i + l, j + l) % mod * dfsh(k - 1, i + 2 * l, j + l) % mod;
  g[k][i][j] = (1ll * dfsh(k, i, j) * dfsh(k, i + 2 * l, j) + (1ll * dfsg(k - 1, i + l, j) * dfsg(k - 1, i + l, j + l) + mod - v) % mod * dfsf(k - 1, i, j) % mod * dfsf(k - 1, i + 3 * l, j)) % mod;
  return g[k][i][j];
}

int dfsh(int k, int i, int j) {
  if (h[k][i][j] != -1) {
    return h[k][i][j];
  }

  if (k == 0) {
    return h[k][i][j] = 0;
  }

  int l = 1 << (k - 1);
  h[k][i][j] = (1ll * dfsf(k - 1, i, j) * dfsf(k - 1, i + l, j) + 1ll * dfsg(k - 1, i, j) * dfsg(k - 1, i, j + l)) % mod;
  int v = 1;
  for (int o0 : {0, 1}) {
    for (int o1 : {0, 1}) {
      v = 1ll * v * dfsh(k - 1, i + o0 * l, j + o1 * l) % mod;
    }
  }
  h[k][i][j] = (h[k][i][j] + mod - v) % mod;
  return h[k][i][j];
}

