  return lt = nw;
}

void dfs(int i) {
  for (int j : to[i]) {
    dfs(j);
    val[i] = 1ll * val[i] * val[j] % mod;
    pos[i] = pos[j];
  }

  ans = (ans + (mod + 1ll - val[i]) * (len[i] - len[fa[i]])) % mod;
}

void build() {
  for (int i = 2; i <= cnt; i++) {
    to[fa[i]].push_back(i);
  }

  dfs(1);
}
