	}
	int m=x.l+x.r>>1;
	if(l<m) upd(i*2,l,v);
	else upd(i*2+1,l,v);
	x.mi=min(nd[i*2].mi,nd[i*2+1].mi);
	for(int j=0;j<8;j++) dn[i].ts[j]=dn[i*2].ts[j]+dn[i*2+1].ts[j];
