using namespace std;

const int N = 2000005, mod = 998244353;
int fac[N], ifac[N];

int power(int a, int n) {
  int tp = 1;
  while (n) {
    if (n & 1) {
      tp = 1ll * tp * a % mod;
    }
    a = 1ll * a * a % mod, n >>= 1;
  }
  return tp;
}

void prep(int n = 2000000) {
  fac[0] = 1;
  for (int i = 1; i <= n; i++) {
    fac[i] = 1ll * fac[i - 1] * i % mod;
  }
  ifac[n] = power(fac[n], mod - 2);
  for (int i = n - 1; i != -1; i--) {
    ifac[i] = 1ll * ifac[i + 1] * (i + 1) % mod;
  }
}

int main() {
  // freopen("experiment.in", "r", stdin);
  // freopen("experiment.out", "w", stdout);
  ios::sync_with_stdio(0), cin.tie(0);

  prep();

  int t;
  cin >> t;
  while (t--) {
    int n, l, r, ans = 1;
    cin >> n >> l >> r;
    cout << 1ll * (n + 1) * (l + r) << ' ';
    for (int i = 1; i <= l + r; i++) {
      int x = i == 1 ? 1 : (n + 1) * (i - 1);
      if (x >= l && x >= r) {
        ans = 1ll * ans * fac[l + r - i + 1] % mod;
        break;
      } else {
        ans = 1ll * ans * (min(x, l) + min(x, r) - i + 1) % mod;
      }
    }

    cout << 1ll * power(ans, n - 1) * fac[l + r] % mod * ifac[l] % mod * ifac[r] % mod << '\n';
  }
}

