const int N=201000;
template<class T>
struct BIT {
	T c[N];
	int size;
	void init(int s) {
		size = s;
		for (int i = 1; i <= s; i++) c[i] = 0;
	}
	T query(int x) { // 1 ... x
		assert(x <= size);
		T s = 0;
		for (; x; x -= x & (-x)) {
			s += c[x];
		}
		return s;
	}

	void modify(int x, T s) { // a[x] += s
		assert(x != 0);
		for (; x <= size; x += x & (-x)) {
			c[x] += s;
		}
	} 
	int querykth(T y) {
		// min x, pref x> y
		int k=0;
		for (int j=31-__builtin_clz(size);j>=0;j--) {
			if (k+(1<<j)<=size&&c[k+(1<<j)]<=y) {
				k+=1<<j;
				y-=c[k];
			}
		}
		return k+1;
	}
};
const int T=50;

BIT<int> c;
db pi=acos(-1.);
int n,q;
int l[N];
db r[N],ser[T];

struct node {
	db coef[T];
}nd[4*N];
void upd(int p) {
	rep(i,0,T) nd[p].coef[i]=nd[p+p].coef[i]+nd[p+p+1].coef[i];
}
void build(int p,int l,int r) {
	if (l==r) {
		db rat=1./::r[l],pw=rat;
		rep(i,0,T) {
			nd[p].coef[i]=::l[l]*pw;
			pw=pw*rat*rat;
		}
	} else {
		int md=(l+r)>>1;
		build(p+p,l,md);
		build(p+p+1,md+1,r);
		upd(p);
	}
}

db cc[T];
void query(int p,int l,int r,int tl,int tr) {
	if (tl==l&&tr==r) {
		rep(j,0,T) cc[j]+=nd[p].coef[j];
	} else {
		int md=(l+r)>>1;
		if (tr<=md) return query(p+p,l,md,tl,tr);
		else if (tl>md) return query(p+p+1,md+1,r,tl,tr);
		else return query(p+p,l,md,tl,md),query(p+p+1,md+1,r,md+1,tr);
	}
}

void change(int p,int l,int r,int x) {
	if (l==r) {
		db rat=1/::r[x],pw=rat;
		rep(i,0,T) {
			nd[p].coef[i]=::l[x]*pw;
			pw=pw*rat*rat;
		}
	} else {
		int md=(l+r)>>1;
		if (x<=md) change(p+p,l,md,x);
		else change(p+p+1,md+1,r,x);
		upd(p);
	}
}


