			l[p1]=p2;
			r[p1]=1e-4*p3;
			change(1,1,n,p1);
		} else {
			scanf("%d%d",&p1,&p2);
			int y=c.querykth(p1);
			db x=r[y]*sin(p2/6.48e5*pi);
			db ret=(c.query(y)-p1)*x/sqrt(r[y]*r[y]-x*x);
			rep(j,0,T) cc[j]=0;
			if (y+1<=n) {
