			}
			db pw=x;
			///printf("%d %.10f %.10f\n",y,x,ret);
			rep(i,0,T) {
				//printf("!! %d %.10f %.10f\n",cc[i])
				ret+=pw*cc[i]*ser[i];
				pw=pw*x*x;
			}
			/*for (int j=y+1;j<=n;j++) {
				ret+=l[j]*(x/r[j])/sqrt(1-(x/r[j])*(x/r[j]));
