int n;
void genst(int x) {
	VI pos;
	rep(j,0,n) if (g[x][j]) pos.pb(j);
	int rem=n;
	//printf("%d %d\n",x,SZ(pos));
	static int tmp[N];
	function<void(int,int,int)> dfs=[&](int cur,int c,int tot) {
		if (rem==0) return;
		if (c==tot) {
			/*printf("edge %d : ",x);
			rep(i,0,c) printf(" %d",tmp[i]); puts("");
			*/
			eg.pb(mp(VI(tmp,tmp+c),x));
			--rem;
		} else {
			rep(j,cur,SZ(pos)) {
				tmp[c]=pos[j];
				dfs(j+1,c+1,tot);
			}
		}
	};
	for (int c=1;c<=SZ(pos);c++) if (rem) {
		dfs(0,0,c);
	}
}
bool dfs(int u) {
	for (auto v:e[u]) if (!vis[v]) {
		vis[v]=1;
		if (mate[v]==-1||dfs(mate[v])) { mate[v]=u; return 1;}
	}
	return 0;
}

