		scanf("%s",s);
		rep(j,i+1,n) g[i][j]=g[j][i]=s[j-i-1]-'0';
	}

	rep(i,0,n) {
		genst(i);
	}
	sort(all(eg),[&](pair<VI,int> &a,pair<VI,int> &b) {
		if (SZ(a.fi)!=SZ(b.fi)) return SZ(a.fi)<SZ(b.fi);
		return a<b;
	});
