#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 998244353;
const int G = 3; // 998244353 的原根

// 快速幂
long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

// 预处理位逆序和单位根以加速 NTT
vector<int> rev;
void init_ntt(int n) {
    int k = 0;
    while ((1 << k) < n) k++;
    rev.assign(n, 0);
    for (int i = 0; i < n; i++) {
        rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (k - 1));
    }
}

// NTT 模板
void ntt(vector<long long>& a, bool invert) {
    int n = a.size();
    for (int i = 0; i < n; i++) {
        if (i < rev[i]) swap(a[i], a[rev[i]]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        long long wlen = power(G, (MOD - 1) / len);
        if (invert) wlen = modInverse(wlen);
        for (int i = 0; i < n; i += len) {
            long long w = 1;
            for (int j = 0; j < len / 2; j++) {
                long long u = a[i + j], v = (a[i + j + len / 2] * w) % MOD;
                a[i + j] = (u + v < MOD ? u + v : u + v - MOD);
                a[i + j + len / 2] = (u - v >= 0 ? u - v : u - v + MOD);
                w = (w * wlen) % MOD;
            }
        }
    }
    if (invert) {
        long long n_inv = modInverse(n);
        for (long long& x : a) x = (x * n_inv) % MOD;
    }
}

// 多项式乘法
vector<long long> multiply(const vector<long long>& const_a, const vector<long long>& const_b) {
    if (const_a.empty() || const_b.empty()) return {};
    vector<long long> a = const_a, b = const_b;
    int n = 1, total_len = a.size() + b.size() - 1;
    while (n < total_len) n <<= 1;
    a.resize(n, 0);
    b.resize(n, 0);
    init_ntt(n);
    ntt(a, false);
    ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = (a[i] * b[i]) % MOD;
    ntt(a, true);
    a.resize(total_len);
    return a;
}

const int MAXN = 200005;
int col[MAXN];
int freq[MAXN]; // 记录某种颜色之前出现的次数
long long cnt[MAXN];  // 对应前文推导中的 cnt_i
vector<long long> tree_poly[MAXN * 4]; // 线段树维护区间多项式乘积
long long ans[MAXN];

// 预处理构建线段树，维护多项式前缀积
void build(int node, int L, int R) {
    if (L == R) {
        // P_i(x) = x + cnt_i  -> 多项式系数表示为 [cnt_i, 1]
        tree_poly[node] = {cnt[L], 1};
        return;
    }
    int mid = L + (R - L) / 2;
    build(node * 2, L, mid);
    build(node * 2 + 1, mid + 1, R);
    tree_poly[node] = multiply(tree_poly[node * 2], tree_poly[node * 2 + 1]);
}

// 分治求解答案
void solve(int node, int L, int R, const vector<long long>& F) {
    // 递归到底部，计算并保存答案
    if (L == R) {
        ans[L] = (F[1] * cnt[L] % MOD + F[0]) % MOD;
        return;
    }
    int mid = L + (R - L) / 2;
    int SL = mid - L + 1; // 左半区间长度
    int S = R - L + 1;    // 当前区间总长度

    // 处理左半边：直接截断获取需要的最高阶系数
    // F_left 是 F 的最后 (SL + 1) 项
    vector<long long> F_left(F.end() - (SL + 1), F.end());
    solve(node * 2, L, mid, F_left);

    // 处理右半边：需要当前累积的 F 乘以 左边区间的乘积多项式
    vector<long long> Prod = multiply(F, tree_poly[node * 2]);
    
    // F_right 截取 Prod 中的 [SL, S] 位置的系数
    int SR = R - mid; // 右边长度
    vector<long long> F_right(Prod.begin() + SL, Prod.begin() + S + 1);
    solve(node * 2 + 1, mid + 1, R, F_right);
}

int main() {
    // 优化 I/O 速度
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    for (int i = 1; i <= n; i++) {
        cin >> col[i];
        cnt[i] = freq[col[i]]++; // 统计出现次数作为 cnt_i
    }

    int m;
    cin >> m;
    
    // 初始化目标查询多项式 T(x)，度数为 n，即大小为 n+1
    // T(x) = \sum_{x \in M} x^{n - x_i}
    vector<long long> T(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int x;
        cin >> x;
        T[n - x] = 1; 
    }

    // 1. 构建线段树，获得所有区间的 P(x)
    build(1, 1, n);

    // 2. 自顶向下分治，截断式推导答案
    solve(1, 1, n, T);

    // 输出答案
    for (int i = 1; i <= n; i++) {
        cout << ans[i] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

