void color(int x)
{
	qwq[x] = 0;
	for(auto y: S[x])
		color(y);
}
void work(int x, int c)
{
	col[x] = c;
	for(auto y: S[x])
		work(y, c);
}
void upd(int x, int y)
{
	S[fa[x]].erase(x);
	S[fa[x] = y].insert(x);
}
void dfs(int x, int f)
{
	int v, w;
	vis[x] = 1;
	dep[x] = dep[f] + 1;
	for(auto y: e[x])
	{
		if(y == f)
			continue;
		if(!vis[y])
			dfs(y, x);
		else if(dep[y] > dep[x] && qwq[y])
		{
			v = y;
			while(v != x)
			{
				w = fa[v];
				upd(v, 0);
				if(v != y)
					color(v);
				v = w;
			}
			upd(y, x);
		}
	}
	if(S[x].size() & 1)
		color(x);
	else
		upd(x, f);
}
void solve()
{
	int n, m, i, u, v;
	scanf("%d%d", &n, &m);
	for(i = 0; i <= n; i++)
		S[i].clear();
	for(i = 1; i <= n; i++)
	{
		S[fa[i] = 0].insert(i);
		vis[i] = 0;
		qwq[i] = 1;
		e[i].clear();
	}
	for(i = 1; i <= m; i++)
	{
		scanf("%d%d", &u, &v);
		e[u].emplace_back(v);
		e[v].emplace_back(u);
	}
	if(n & 1)
	{
		printf("-1\n");
		return ;
	}
	dfs(1, 0);
	for(auto o: S[0])
		work(o, o);
	for(i = 1; i <= n; i++)
		printf("%d ", col[i]);
	printf("\n");
}

