struct LeftistTree {
	static const int S=N*230;
	int tot;
	struct Node {
		int val,ls,rs,ht,t;
	} s[S];
	inline int newx(int v) {
		int u=++tot;
		s[u]={v,0,0,1,0};
		return u;
	}
	inline void pushup(int u) {
		if(s[s[u].ls].ht>s[s[u].rs].ht) swap(s[u].ls,s[u].rs);
		s[u].ht=s[s[u].ls].ht+1;
	}
	inline int putT(int u,int k) {
		int v=++tot;
		s[v]=s[u];
		s[v].t+=k,s[v].val+=k;
		return v;
	}
	inline void pudown(int u) {
		if(!s[u].t) return ;
		if(s[u].ls) s[u].ls=putT(s[u].ls,s[u].t);
		if(s[u].rs) s[u].rs=putT(s[u].rs,s[u].t);
		s[u].t=0;
	}
	int merge(int u,int v) {
		if(!u||!v) return u|v;
		int w=++tot;
		if(s[u].val>s[v].val) s[w]=s[u],pudown(w),s[w].ls=merge(s[w].ls,v);
		else s[w]=s[v],pudown(w),s[w].ls=merge(s[w].ls,u);
		pushup(w);
		return w;
	}
	inline int pop(int u) {
		pudown(u);
		return merge(s[u].ls,s[u].rs);
	}
} T;
ll ans[N+2];
struct Val {
	int u;
	ll k;
	void deal(char c) {
		if(u) u=T.putT(u,1);
		if(c=='1') u=T.merge(u,T.newx(0));
		else if(u) {
			k+=T.s[u].val;
			u=T.merge(T.pop(u),T.newx(0));
		}
	}
} f[N+2],g[N+2],h[N+2];
Val operator+(const Val &a,const Val &b) {
	return {T.merge(a.u,b.u),a.k+b.k};
}
int id[N+2],pos[N+2];
void dfs(int u,int p) {
	f[u]={0,0};
	for(auto v : e[u]) if(v!=p) {
		dfs(v,u);
		f[u]=f[u]+f[v];
	}
	f[u].deal(s[u]);
}
void dfs2(int u,int p) {
	int cnt=0;
	for(auto v : e[u]) if(v!=p) {
		id[v]=++cnt;
		pos[cnt]=v;
	}
	h[cnt+1]={0,0};
	for(int i=cnt; i>=1; --i) h[i]=h[i+1]+f[pos[i]];
	Val cur=g[u];
	for(auto v : e[u]) if(v!=p) {
		g[v]=cur+h[id[v]+1];
		g[v].deal(s[u]);
		cur=cur+f[v];
	}
	cur.deal(s[u]);
	ans[u]=cur.k;
	for(auto v : e[u]) if(v!=p) dfs2(v,u);
}
