		}
		else st.insert(a[i].y);
	}
	int p=-inf,L=ql-1,R=qr+1;
	for(int i=qr;i>=ql;i--)
	{
		if(a[i].c>b[mid]&&a[i].y>p&&(!e[i]||e[i]<=p)) p=a[i].y;
		if(a[i].y<=p) c[++L]=a[i];
