struct poi { ll x,y; };
bool operator <(const poi&u,const poi&v) { return u.x^v.x?u.x<v.x:u.y>v.y; }
poi operator +(const poi&u,const poi&v) { return {u.x+v.x,u.y+v.y}; }
poi operator -(const poi&u,const poi&v) { return {u.x-v.x,u.y-v.y}; }
ll dt(const poi&u,const poi&v) { return u.x*v.x+u.y*v.y; }
ll cr(const poi&u,const poi&v) { return u.x*v.y-u.y*v.x; }
typedef basic_string<poi> vec;
void conv(vec&f) {
	int t=0; static poi g[MAXN];
	sort(f.begin(),f.end());
	for(auto x:f) {
		for(;t&&g[t].y<=x.y;--t);
		for(;t>1&&cr(x-g[t-1],g[t]-g[t-1])<=0;--t);
		g[++t]=x;
	}
	f=vec(g+1,g+t+1);
}
vec operator+(vec f,const vec&g) { return conv(f+=g),f; }
vec operator*(vec f,vec g) {
	vec h{f[0]+g[0]};
	for(int i=f.size()-1;i;--i) f[i]=f[i]-f[i-1];
	for(int i=g.size()-1;i;--i) g[i]=g[i]-g[i-1];
	auto i=f.begin()+1,j=g.begin()+1;
	for(;i!=f.end()||j!=g.end();) {
		if(j==g.end()||(i!=f.end()&&cr(*i,*j)<=0)) h+=h.back()+*i++;
		else h+=h.back()+*j++;
	}
	return h;
}
