poi a[MAXN];
vec f[MAXN],g[MAXN];
void init(int l=1,int r=n-1,int p=1) {
	if(l==r) {
		int k; cin>>a[l].x>>a[l].y>>k,f[p]={a[l]},g[p].resize(k);
		for(auto&o:g[p]) cin>>o.x>>o.y;
