ll ask(vec&h) {
	int x=h.size()-1;
	if(x) for(int k=1<<__lg(x);k;k>>=1) if(x>=k&&dt(h[x-k],q)>=dt(h[x-k+1],q)) x-=k;
	return dt(h[x],q);
