int exgcd(int a, int b, int &x, int &y) {
  if(b == 0) {
    x = 1; 
    y = 0;
    return a;
  } 
  int g = exgcd(b, a % b, y, x);
  y -= a / b * x;
  return g;
}  

pair <int, int> merge(int m1, int a1, int m2, int a2) {
  int x, y; 
  int g = exgcd(m1, m2, x, y);
  if((a1 - a2) % g != 0) return {0ll, 0ll};
  int v = (a2 - a1) / g;
  i128 m = (i128)m1 / g * m2;
  i128 a = ((i128)(x) * v % (m2 / g) * m1 + a1) % m;
  if(a < 0) a += m;
  m = min(m, (i128)(1e18) + 1); 
  a = min(a, (i128)(1e18));
  return {m, a};
} 
