		z=max(z,w[u][k]),u=fa[u][k];
	}
	if(u==v) return z;
	for(int k=19;~k;--k) if(fa[u][k]^fa[v][k]) {
		z=max({z,w[u][k],w[v][k]}),u=fa[u][k],v=fa[v][k];
