int access(int x){
	int y=0,lst[2]={0,0};
	for(;x;x=getf(y=T1::findtop(x))){
		T1::splay(x);
		int tr[2]={T1::rt[x][0],T1::rt[x][1]};
		int tsz[2]={T1::siz[T1::ch[x][0]][0]+(T1::tp[x]==0),T1::siz[T1::ch[x][0]][1]+(T1::tp[x]==1)};
		bool tf[2]={0,0};
		if(tsz[0]) tr[0]=T2::split(tr[0],tsz[0]);
		else tf[0]=1;
		if(tsz[1]) tr[1]=T2::split(tr[1],tsz[1]);
		else tf[1]=1;
		if(T1::ch[x][1]){
			int nxt=T1::ch[x][1]; T1::pushdown(nxt);
			while(T1::ch[nxt][0]) nxt=T1::ch[nxt][0],T1::pushdown(nxt);
			T2::sz[nxt]=getsiz(nxt);
			T1::splay(x);
			if(tr[0]) T2::splay(tr[0]);
			if(tr[1]) T2::splay(tr[1]);
			tr[T1::tp[x]]=T2::delrt(tr[T1::tp[x]]);
			bool fl=0;
			if(tr[T1::tp[x]]<0) fl=1,tr[T1::tp[x]]=-tr[T1::tp[x]]-1;
			if(tf[T1::tp[x]^1]) tr[T1::tp[x]^1]=T2::addrt1(tr[T1::tp[x]^1],nxt);
			else tr[T1::tp[x]^1]=T2::addrt(tr[T1::tp[x]^1],nxt);

			for(int i=0;i<2;i++){
				if(fl&&i==T1::tp[x]) T1::rt[T1::ch[x][1]][i]=tr[i],T2::lab[tr[i]]=T1::ch[x][1],tr[i]=0;
				else if(tr[i]){
					T1::rt[T1::ch[x][1]][i]=T2::ch[tr[i]][1];
					T2::lab[T2::ch[tr[i]][1]]=T1::ch[x][1];
					T2::fa[T2::ch[tr[i]][1]]=0,T2::ch[tr[i]][1]=0;
					T2::update(tr[i]);
				}
			}
			T1::rt[x][0]=tr[0],T1::rt[x][1]=tr[1];
		}
		T1::tp[x]^=1;
		if(y) T1::fa[y]=x;
		T1::fa[T1::ch[x][1]]=0;
		T1::ch[x][1]=y;
		T1::update(x);
		if(lst[0]){
			if(tr[0]) T2::ch[tr[0]][1]=lst[0],T2::fa[lst[0]]=tr[0],T2::update(tr[0]);
			else tr[0]=lst[0];
		}
		if(lst[1]){
			if(tr[1]) T2::ch[tr[1]][1]=lst[1],T2::fa[lst[1]]=tr[1],T2::update(tr[1]);
			else tr[1]=lst[1];
		}
		lst[0]=tr[0],lst[1]=tr[1];
	}
	T1::rt[y][0]=lst[0],T1::rt[y][1]=lst[1];
	T2::lab[lst[0]]=T2::lab[lst[1]]=y;
	T2::reverse(lst[0]);
	T2::totalrev(lst[0]);
	return T2::siz[lst[0]];
}

int findx(int x){
	int y=n-x-1;
	int u=root;
	while(1){
		T1::splay(u);
		int v=T1::rt[u][0];
		// cout<<"findx "<<u<<' '<<x<<' '<<y<<' '<<T2::sum[T1::rt[u][0]]<<' '<<T2::sum[T1::rt[u][1]]<<endl;
		if(T2::sum[v]==x) return T1::findrg(u);
		if(T2::sum[v]>x){
			int w=T2::findx(v,x);
			T2::splay(w);
			T2::checkrev(w);
			x-=T2::sum[T2::ch[w][0]];
			int rnk=T2::siz[T2::ch[w][0]]+1;
			int pt=T1::kth(u,rnk,0);
			T1::splay(pt);
			rnk=T1::siz[T1::ch[pt][0]][1];
			int tmp=rnk?T2::kth(T1::rt[u][1],rnk):0;
			if(tmp) T2::splay(tmp);
			y-=T2::sum[T2::ch[tmp][0]]+T2::sz[tmp];
			y-=getsiz(pt)-getsiz(w);
			u=w;
		}
		else{
			v=T1::rt[u][1];
			int w=T2::findx(v,y);
			T2::splay(w);
			T2::checkrev(w);
			y-=T2::sum[T2::ch[w][0]];
			int rnk=T2::siz[T2::ch[w][0]]+1;
			int pt=T1::kth(u,rnk,1);
			T1::splay(pt);
			rnk=T1::siz[T1::ch[pt][0]][0];
			int tmp=rnk?T2::kth(T1::rt[u][0],rnk):0;
			if(tmp) T2::splay(tmp);
			x-=T2::sum[T2::ch[tmp][0]]+T2::sz[tmp];
			x-=getsiz(pt)-getsiz(w);
			u=w;
		}
	}
}

