using fp = double;
using pt = array<fp, 2>;

auto operator-(auto a, auto b) -> decltype(array(a), array(b), pt{}) { return {a[0] - b[0], a[1] - b[1]}; }
auto operator+(auto a, auto b) -> decltype(array(a), array(b), pt{}) { return {a[0] + b[0], a[1] + b[1]}; }
auto operator&(auto a, auto b) -> decltype(array(a), array(b), fp{}) { return a[0] * b[0] + a[1] * b[1]; }
auto operator^(auto a, auto b) -> decltype(array(a), array(b), fp{}) { return a[0] * b[1] - a[1] * b[0]; }
auto operator*(fp a, auto b) -> decltype(array(b), pt{}) { return {a * b[0], a * b[1]}; }
auto rot90(auto a) -> decltype(array(a), pt{}) { return {a[1], -a[0]}; }

using circ = array<fp, 3>;
const fp err = abs(cos(3242234)) * 1e99;

array<pt, 2> tgb(circ a, circ b, fp intern = -1) {
  pt v = b - a;
  fp d = v & v, dr = a[2] - (b[2] *= intern), h = d - dr * dr;
  pt piv = dr / d * v, step = sqrt(max(h, {})) / d * rot90(v);
  return {b + b[2] * (piv - step), b + b[2] * (piv + step)};
}

bool s2c(pt a, pt b, circ c) {
  a = a - c, b = b - c; pt v = b - a;
  fp d = v & v, x = b & v, y = b ^ v;
  return (x > 0 && x < d? y * y / d: min(a & a, b & b)) < (c[2] - 1e-7) * (c[2] - 1e-7);
}

