		if(d==(1<<16))
			for(int i=0;i<L;i++)f[i]%=lpw;
	}
	int inv=qpow(L,lpw-2);
	for(int i=0;i<L;i++)a[i]=1ll*f[i]%lpw*(op?1:inv)%lpw;
