}
void add_lie(int x) {
    // printf("lie %d\n",x);
    ans.push_back(MP(2,x));
    char tmp=s[n-1][x];
    for (int i=n-1;i>=1;i--) s[i][x]=s[i-1][x];
    s[0][x]=tmp;
}
void hang(int x,int len) {
    len=(len%n+n)%n;
    for (int i=1;i<=len;i++) add_hang(x);
}
void lie(int x,int len) {
    len=(len%n+n)%n;
    for (int i=1;i<=len;i++) add_lie(x);
}
