    for (int i=0;i<n;i++) printf("%s\n",s[i]); puts("");
}
void r1(int a,int b,int x,int y) {
    hang(a,y-b);
    lie(y,a-x);
    hang(a,b-y);
    lie(y,x-a);
}
void r2(int a,int b,int x,int y) {
    lie(y,a-x);
    hang(a,y-b);
    lie(y,x-a);
    hang(a,b-y);
}
void add(int a,int b,int x,int y) {
    if (a!=x&&b!=y) {
        if (s[a][y]==s[a][b]) {
            r1(a,b,x,y);
        } else r2(a,b,x,y);
    } else if (a==x) {
        int z=(a+1)%n;
        if (s[z][y]==s[a][b]) r2(a,b,z,y);
        else r1(a,b,z,y);
    } else { // b=y
        int z=(b-1+n)%n;
        if (s[a][z]==s[x][y]) r1(a,z,x,b);
        else r2(a,z,x,b);
    }
}
