void swp(int y) {
	int x=pr[y],l=pr[x],r=sf[y];
	sf[l]=y,pr[y]=l,sf[y]=x,pr[x]=y,sf[x]=r,pr[r]=x;
	pw[y]=pw[l]+w[l],pw[x]=pw[y]+w[y],sw[x]=sw[r]+w[r],sw[y]=sw[x]+w[x];
}
int upd(int x,ll t) {
	if(ne[x]) {
		int y=ne[x];
		if((t-lst[x])&1) {
			swp(a[x]<a[y]?y:x),swap(a[x],a[y]);
			return lst[x]=lst[y]=t,y;
		} else return lst[x]=lst[y]=t,x;
	} else return a[x]+=dir[x]*(t-lst[x]),lst[x]=t,x;
}
void del(int x,int y) {
	dsu[y]=x,w[x]+=w[y],sw[x]-=w[y],sf[x]=sf[y],pr[sf[y]]=x;
}
