int rd(int x=0,char c=getchar()){int f=1;while(!isdigit(c))f=(c^'-'?1:-1),c=getchar();while(isdigit(c))x=x*10+(c^48),c=getchar();return x*f;}
const int N=2e5+6,M=19,Q=1e6+6;
int n,a[Q],b[Q],ta,tb;
int mn[N],F[N],fa[N][M],dep[N];
vector<pair<int,int>> E[N];
int getf(int x){while(F[x]^x)x=F[x]=F[F[x]];return x;}
int f[N],g[N],ca[Q],cb[Q];
void upd(int&x,int&y,int z){if(z<x)y=x,x=z;else y=min(y,z);}
void dfs1(int u){
	for(int i=1;i<M;i++)fa[u][i]=fa[fa[u][i-1]][i-1];
	f[u]=mn[u];g[u]=n+1;
	for(auto [v,w]:E[u])if(v^fa[u][0]){
		dep[v]=dep[u]+1;
		fa[v][0]=u;dfs1(v);
		upd(f[u],g[u],max(w,f[v]));
	}
}
void dfs2(int u){
	u>ta?cb[g[u]]++:ca[g[u]]++;
	for(auto [v,w]:E[u])if(v^fa[u][0]){
		if(f[u]==max(w,f[v]))upd(f[v],g[v],max(w,g[u]));
		else upd(f[v],g[v],max(w,f[u]));
		dfs2(v);
	}
}
int lca(int u,int v){
	if(dep[u]<dep[v])swap(u,v);
	for(int i=M-1;~i;i--)if(dep[fa[u][i]]>=dep[v])u=fa[u][i];
	if(u==v)return u;
	for(int i=M-1;~i;i--)if(fa[u][i]!=fa[v][i])u=fa[u][i],v=fa[v][i];
	return fa[u][0];
}
int dis(int u,int v){return dep[u]+dep[v]-dep[lca(u,v)]*2;}
struct dat{int x,y,dis;}tr[N];
dat operator+(dat a,dat b){
	dat s=a.dis>b.dis?a:b;
	int d;
	for(auto u:{a.x,a.y})for(auto v:{b.x,b.y})if((d=dis(u,v))>s.dis)s={u,v,d};
	return s;
}
int sa,sb,vis[N];
void upd(dat t,int x){
	if(t.dis%2==0)(t.x<=ta)^(t.dis%4==2)?sa+=x:sb+=x;
	else t.dis%4==1?sb+=x:sa+=x;
}
int main(){
	n=rd();
	for(int i=1;i<=n;i++)a[i]=rd(),b[i]=rd(),ta=max(ta,a[i]),tb=max(tb,b[i]);
	for(int i=1;i<=ta+tb;i++)mn[i]=n+1,F[i]=i;
	for(int i=1;i<=n;i++){
		b[i]+=ta;
		int x=getf(a[i]),y=getf(b[i]);
		if(x^y){
			E[a[i]].push_back({b[i],i});
			E[b[i]].push_back({a[i],i});
			F[x]=y;
		}else{
			mn[a[i]]=min(mn[a[i]],i);
			mn[b[i]]=min(mn[b[i]],i);
		}
	}
	for(int i=1;i<=ta+tb;i++)if(!f[i])dfs1(i),dfs2(i);
	for(int i=1;i<=ta+tb;i++)F[i]=i,tr[i]={i,i,0};
	for(int i=1;i<=n;i++){
		int x=getf(a[i]),y=getf(b[i]);
		if(x^y){
			if(!vis[x])upd(tr[x],1);
			if(!vis[y])upd(tr[y],1);
			if(!vis[x]&&!vis[y])tr[y]=tr[x]+tr[y],upd(tr[y],-1);
			else vis[y]=1;
			F[x]=y;
		}else{
			if(!vis[x])vis[x]=1,upd(tr[x],1);
		}
		sa-=ca[i];sb-=cb[i];
		printf("%d %d\n",sa,sb);
	}
	return 0;
}

