ll getd(int u,int v){return 1ll*d[u][v]*d[u][v];}
void dfs2(int u,int fa){
	g[u]=0;
	for(auto [v,w]:E[u])if(v!=fa)
		dfs2(v,u),g[u]+=f[v];
	f[u]=g[u];to[u]=0;
	for(auto [v,w]:E[u])if(v!=fa){
		ll w=g[u]-f[v]+g[v]+getd(u,p[u])+getd(v,p[v])-getd(u,p[v])-getd(v,p[u]);
		if(w>f[u])f[u]=w,to[u]=v;
	}
}
void dfs3(int u,int fa,int ga){
	for(auto [v,w]:E[u])if(v!=fa){
		if(v==ga){now.pb(w);swap(p[u],p[v]);dfs3(v,u,0);}
		else dfs3(v,u,to[v]);
	}
}
