#include <bits/stdc++.h>

#define N 200005
#define lson l,m,rt<<1
#define rson m+1,r,rt<<1|1
#define mod 1000000123

typedef long long ll;

using namespace std;

int a[N];
ll qpow(ll a,ll b){b=(b+mod-1)%(mod-1);ll ans=1;while(b){if(b&1)ans=ans*a%mod;a=a*a%mod;b>>=1;}return ans;}
struct segtree
{
	ll sm[N*4],tr[N*4],lzy[N*4],ml[N*4];
	void upd(int l,int r,int rt,ll x,ll y)
	{
		lzy[rt]+=x;
		ml[rt]=ml[rt]*y%mod;
		tr[rt]=tr[rt]*y%mod;
		sm[rt]+=1ll*(r-l+1)*x;
	}
	void up(int rt){tr[rt]=(tr[rt<<1]+tr[rt<<1|1])%mod;sm[rt]=sm[rt<<1]+sm[rt<<1|1];}
	void down(int l,int r,int rt){int m=(l+r)>>1;upd(lson,lzy[rt],ml[rt]);upd(rson,lzy[rt],ml[rt]);lzy[rt]=0;ml[rt]=1;}
	void add(int a,int b,ll c,int l,int r,int rt)
	{
		if(a<=l&&r<=b)
		{
			upd(l,r,rt,c,qpow(7,c));
			return;
		}
		down(l,r,rt);int m=(l+r)>>1;
		if(a<=m)add(a,b,c,lson);
		if(b>m)add(a,b,c,rson);
		up(rt);
	}
	ll que(int a,int b,int l,int r,int rt,ll* tr)
	{
		if(a<=l&&r<=b)return tr[rt];
		down(l,r,rt);int m=(l+r)>>1;ll ans=0;
		if(a<=m)ans=que(a,b,lson,tr);
		if(b>m)ans+=que(a,b,rson,tr);
		return ans;
	}
}A,B;

int main()
{
	int i,n,T;
	cin>>n>>T;
	for(i=0;i<N*4;++i)A.tr[i]=B.tr[i]=A.ml[i]=B.ml[i]=1;
	for(i=1;i<=n;++i){cin>>a[i];A.add(i,i,a[i],1,n,1);B.add(i,i,-a[i],1,n,1);}
	while(T--)
	{
		int ty,l,r,v;
		cin>>ty>>l>>r;
		if(ty==1)
		{
			cin>>v;
			A.add(l,r,v,1,n,1);B.add(l,r,-v,1,n,1);
		}
		else
		{
			ll s=A.que(l,r,1,n,1,A.sm);
			if(s%((r-l+1)/2)){puts("NO");continue;}
			ll m=s/((r-l+1)/2);
			puts(A.que(l,r,1,n,1,A.tr)%mod==B.que(l,r,1,n,1,B.tr)%mod*qpow(7,m)%mod?"YES":"NO");
		}
	}
	return 0;
}

