	if(x<=y) return ask(y)-ask(x);
	return ask(y)+ask(n)-ask(x);
}
void HitachiMako(){
	scanf("%d",&n);
	for(int i=0;i<n;i++) scanf("%d",a+i);
	for(int i=0;i<n;i++) upd(i,a[i]),q[a[i]].emplace_back(i);
	vector<int>p{0}; vector<ll>f{0},g; deque<int>Q;
