		if(q[v].empty()) continue;
		int s=q[v].size();
		vector<ll>nf(s,(ll)1e18);
		for(int i=0;i<(int)p.size();i++){ int x=p[i];
			int k=lower_bound(q[v].begin(),q[v].end(),x)-q[v].begin();
			if(k==s) k=0; nf[k]=min(nf[k],f[i]+dis(x,q[v][k]));
			k=(k-1+s)%s; nf[k]=min(nf[k],f[i]+dis(q[v][k],x));
		}
		f=move(nf),p=move(q[v]),nf.assign(s,(ll)1e18);
		for(int _=0;_<2;_++)
			for(int i=s-1;~i;i--){
				int j=(i-1+s)%s;
				f[j]=min(f[j],f[i]+dis(p[j],p[i]));
			}
		for(int i=0;i<s;i++){
			int j=(i-1+s)%s;
			nf[j]=min(nf[j],f[i]+dis(p[i],p[j])-(s-1)*v);
		}
		for(int _=0;_<2;_++)
			for(int i=0;i<s;i++){
				int j=(i+1)%s;
				f[j]=min(f[j],f[i]+dis(p[i]+1,p[j]));
			}
