		auto calc=[&](int i){ return f[i%s]+2*i*v-ask(p[i%s])-(i>=s?ask(n):0); };
		for(int i=0;i<s+s;i++){
			while(Q.size()&&calc(Q.back())>=calc(i)) Q.pop_back();
			Q.push_back(i); while(Q.size()&&i-s>=Q.front()) Q.pop_front();
			if(i>=s) g[i-s]=f[i-s]-calc(i)+calc(Q.front());
		}
		f=move(g);
		for(int i=0;i<s;i++){
			int j=(i+1)%s;
			nf[j]=min(nf[j],f[i]+dis(p[j],p[i]));
		}
		f=move(nf);
		for(int x:p) upd(x,-v);
	}
