void KMP(std::string &s, Arr<int> &kmp) {
	int m = (int)s.size();
	kmp.resize(m);
	kmp[0] = -1;
	For(i, 1, m) {
		for (kmp[i] = kmp[i - 1]; kmp[i] > -1 and s[i] != s[(kmp[i] + 1)]; kmp[i] = kmp[kmp[i]])
			;
		if (s[i] == s[kmp[i] + 1])
			++kmp[i];
	}
  int t = m - 1 - kmp[m - 1];
  if (m % t == 0)
    s.resize(t);
}

void Work(Arr<int> ps, int pos) {
  if (ps.size() < 3)
    return;
  Arr<int> by[3];
  int sum[3] = {};
  for (auto p : ps) {
    by[who[t[p][pos % t[p].size()]]].push_back(p);
    sum[who[t[p][pos % t[p].size()]]] += w[p];
  }
  ans += (LL)sum[0] * sum[1] * sum[2];
  For(i, 0, 3)
    Work(by[i], pos + 1);
}

