using P3 = array<double, 3>;
#define FOR(i, a, b) for (int i = (a); i < (int)(b); ++i)
int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  int n;
  cin >> n;
  vector<vector<double>> D(n, vector<double>(n));
  FOR(i, 0, n) FOR(j, 0, n) cin >> D[i][j];
  mt19937 rng(time(0));  // 随机数生成器
  uniform_real_distribution<double> r0(0.0, 1.0), r1(-1.0, 1.0);
  vector<P3> ps(n);
  FOR(i, 0, n) FOR(j, 0, 3) ps[i][j] = r0(rng);
  auto cal_err = [&]() {
    double md = 0;
    FOR(i, 0, n) FOR(j, i + 1, n) {
      double d = 0;
      FOR(k, 0, 3) d += (ps[i][k] - ps[j][k]) * (ps[i][k] - ps[j][k]);
      md = max(md, fabs(sqrt(d) - D[i][j]));
    }
    return md;
  };
  double err = cal_err(), step = 1.0, decay = 0.99995;
  for (int max_it = 2e5; step > 1e-6 and max_it--; step *= decay) {
    P3 &p = ps[rng() % n], p_bak = p;     // 随机移动该点
    FOR(i, 0, 3) p[i] += r1(rng) * step;  // 生成随机的移动步幅
    double ne = cal_err();                   // 新的误差
    if (ne < 0.1) break;
    if (ne < err)  // 如果找到了满足要求（误差<=0.1）的解，可以提前退出
      err = ne;
    else  // 撤销修改
      p = p_bak;
  }
  for (auto [x, y, z] : ps) printf("%.6f %.6f %.6f\n", x, y, z);
  return 0;
}
