int ask(int l,int r){int rec=0;for(int i=l;i<=r;i++)rec^=a[i];return rec;}
void chg(int u,int v,int w){
	while(top[u]^top[v]){
		if(dep[top[u]]<dep[top[v]])swap(u,v);
		add(dfn[top[u]],dfn[u],w);u=fa[top[u]];
	}if(dep[u]>dep[v])swap(u,v);
	add(dfn[u],dfn[v],w);
}
int query(int u,int v){
	int rec=0;
	while(top[u]^top[v]){
		if(dep[top[u]]<dep[top[v]])swap(u,v);
		rec^=ask(dfn[top[u]],dfn[u]);u=fa[top[u]];
	}if(dep[u]>dep[v])swap(u,v);
	rec^=ask(dfn[u],dfn[v]);
	return rec;
}
