int sgn(db x) {
    if (x < -eps) return -1;
    if (x > eps) return 1;
    return 0;
}
struct vec {
    db x, y;
    vec(db _x = 0, db _y = 0) {
        x = _x, y = _y;
    }
    friend vec operator+(const vec& a, const vec& b) {
        return vec(a.x + b.x, a.y + b.y);
    }
    friend vec operator-(const vec& a, const vec& b) {
        return vec(a.x - b.x, a.y - b.y);
    }
    friend vec operator*(const vec& a, const db& b) {
        return vec(a.x * b, a.y * b);
    }
    friend db operator^(const vec& a, const vec& b) {
        return a.x * b.x + a.y * b.y;
    }
    db len() {
        return sqrt(x * x + y * y);
    }
    vec rotate(db alpha) {
        return vec(x * cos(alpha) - y * sin(alpha), x * sin(alpha) + y * cos(alpha));
    }
};
db dot(vec a, vec b, vec c) {
    return (b - a) ^ (c - a);
}
