#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve() {
  int H, W, X, Y;
  cin >> H >> W >> X >> Y;
  int N = H * W;
  vector<char> grid(N);
  for (auto& c : grid) cin >> c;
  vector<int> cost(N);
  for (auto& x : cost) cin >> x;
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      if (grid[i * W + j] == '#') {
        if (i > 0) grid[(i - 1) * W + j] = '*';
        if (i < H - 1) grid[(i + 1) * W + j] = '*';
        if (j > 0) grid[i * W + (j - 1)] = '*';
        if (j < W - 1) grid[i * W + (j + 1)] = '*';
      }
    }
  }
  vector<array<ll, 2>> dist(N);
  for (auto& a : dist) a.fill(1ll << 60);
  struct State {
    int u, k;
    ll d;
    bool operator<(const State& s) const { return d > s.d; }
  };
  priority_queue<State> heap;
  const auto push = [&](int u, int k, ll d) {
    if (dist[u][k] > d) {
      dist[u][k] = d;
      heap.push(State{u, k, d});
    }
  };
  push(0, 0, 0);
  while (!heap.empty()) {
    const auto [u, k, d] = heap.top();
    heap.pop();
    const int i = u / W;
    const int j = u % W;
    for (int di = -1; di <= 1; ++di) {
      for (int dj = -1; dj <= 1; ++dj) {
        const int ni = i + di;
        const int nj = j + dj;
        if (!(0 <= ni && ni < H)) continue;
        if (!(0 <= nj && nj < W)) continue;
        const int nu = ni * W + nj;
        if (grid[nu] == '#') {
          push(nu, 0, d + (k ? Y : X));
          push(nu, 1, d + (k ? Y : X));
        } else if ((grid[u] == '#' && abs(di) + abs(dj) == 1) || grid[nu] != '*') {
          push(nu, k, d + k * cost[u]);
        }
      }
    }
  }
  cout << min(dist[N - 1][0], dist[N - 1][1]) << "\n";
}

int main() {
  cin.tie(nullptr)->sync_with_stdio(false);

  int T;
  cin >> T;
  while (T--) solve();

  return 0;
}

