#include <bits/stdc++.h>
using namespace std;
using Tf = long double;
 
const Tf EPS = 1e-6;
 
int dcmp(Tf x) {
    if (fabs(x) < EPS) return 0;
    return x < 0 ? -1 : 1;
}
 
struct Point {
    Tf x, y;
 
    Point operator+(Point p) {
        return Point{x + p.x, y + p.y};
    }
 
    Point operator-(Point p) {
        return Point{x - p.x, y - p.y};
    }
 
    Point operator*(Tf c) {
        return Point{x * c, y * c};
    }
 
    Tf len() {
        return hypot(x, y);
    }
};
 
Tf dot(Point p, Point q) {
    return p.x * q.x + p.y * q.y;
}
 
Tf cross(Point p, Point q) {
    return p.x * q.y - p.y * q.x;
}
 
int orient(Point p, Point q, Point r) {
    Tf v = cross(q - p, r - p);
    return dcmp(v);
}
 
using Polygon = vector<Point>;
 
Tf read() {
    int x;
    cin >> x;
    return x;
}
 
bool lexComp(Point a, Point b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}
 
Polygon minkowskiDiff(Polygon &P, Polygon &Q){
    for(auto &q : Q){
        q.x = -q.x;
        q.y = -q.y;
    }
 
    auto it1 = min_element(P.begin(), P.end(), lexComp);
    auto it2 = min_element(Q.begin(), Q.end(), lexComp);
 
    rotate(P.begin(), it1, P.end());
    rotate(Q.begin(), it2, Q.end());
 
    Polygon D;
    D.push_back(P[0] + Q[0]);
 
    int i = 0, j = 0;
    int n = P.size(), m = Q.size();
    while(i < n || j < m){
        Point d;
        if(i == n){
            d = Q[(j+1) % m] - Q[j];
            j++;
        }
        else if(j == m){
            d = P[(i+1) % n] - P[i];
            i++;
        }
        else{
            auto p = P[(i+1) % n] - P[i];
            auto q = Q[(j+1) % m] - Q[j];
            if(cross(p, q) >= 0){
                d = p;
                i++;
            }
            else{
                d = q;
                j++;
            }
        }
 
        D.push_back(D.back() + d);
    }
 
    D.pop_back();
    return D;
}
 
Polygon tangents(Polygon &P){
    int n = P.size();
    int i1 = 0, i2 = 0;
 
    Point O{0, 0};
 
    for(int i = 0; i<P.size(); i++){
        auto p = P[i];
        auto prev = P[(i-1+n)%n];
        auto next = P[(i+1)%n];
 
        auto v2 = orient(O, p, next);
        auto v1 = orient(O, p, prev);
 
        if(v2 >= 0 && v1 > 0){
            i2 = i;
        }
 
        if(v2 < 0 && v1 <= 0){
            i1 = i;
        }
    }
 
    Polygon T;
    for(int i = i1; ; i++){
        i %= n;
        T.push_back(P[i]);
        if(i == i2)
            break;
    }
 
    return T;
}
 
bool rayCircleIntersect(Point d, Point c, Tf r){
    if (dot(d, c) > 0){
        auto dperp = Point{-d.y, d.x};
        auto dist = abs(dot(dperp, c));
        __int128 x = __int128(dist) * __int128(dist);
        __int128 y = __int128(r) * __int128(r) * __int128(d.x * d.x + d.y * d.y);
        if(x > y) return false;
        return true;
    }
    else{
        auto y = r * r;
        auto x = c.x * c.x + c.y * c.y;
        if(x >= y) return false;
        return true;
    }
}
 
Tf touchCirlce(Point d, Point c, Tf r){
    auto dperp = Point{-d.y, d.x};
    auto dist = abs(dot(dperp, c));
    __int128 x = __int128(dist) * __int128(dist);
    __int128 y = __int128(r) * __int128(r) * __int128(d.x * d.x + d.y * d.y);
    if(x == y) return abs(dot(d, c)) / d.len();
    return -1;
}
 
bool pointInAngle(Point a, Point b, Point p){
    Point O{0, 0};
    return orient(O, a, p) < 0 && orient(O, b, p) > 0;
}
 
int getCrossingIndex(Polygon& P, Point a){
    int lo = 0, hi = (int)P.size() - 1;
    while(lo <= hi){
        int mid = (lo+hi)/2;
        if(cross(P[mid], a) <= 0){
            lo = mid+1;
        }
        else{
            hi = mid-1;
        }
    }
    return hi;
}
 
bool acrossRay(Point a, Point p){
    return dot(a, p) >= a.x * a.x + a.y * a.y;
}
 
Tf perpDistance(Point a, Point p){
    return abs(cross(a, p) / a.len());
}
 
Tf getSegmentDistance(Point a, Point b, Point c){
    auto v1 = dot(b-a, c-a);
    auto v2 = dot(b-a, b-a);
    if(v1 <= 0) return (c-a).len();
    if(v2 <= v1) return (c-b).len();
    return perpDistance(b-a, c-a);
}
 
Tf getPolylineDistance(Polygon &P, Point p){
    int lo = 0, hi = (int)P.size() - 3;
    while(lo <= hi){
        int mid = (lo+hi)/2;
        auto v1 = getSegmentDistance(P[mid], P[mid+1], p);
        auto v2 = getSegmentDistance(P[mid+1], P[mid+2], p);
        if(v1 <= v2){
            hi = mid-1;
        }
        else{
            lo = mid+1;
        }
    }
 
    return getSegmentDistance(P[lo], P[lo+1], p);
}
 
