		if(!p) p=++tot;
		if(l==r) return su[p]+=z,mn[p]=min(0,su[p]),void();
		int mid=(l+r)>>1;
		if(x<=mid) add(x,z,l,mid,ls[p]);
		else add(x,z,mid+1,r,rs[p]);
		psu(p);
	}
