			f[p][0][0]=0,f[p][1][0]=f[p][1][1]=f[p][0][1]=c[i];
			return ;
		}
		int mid=(l+r)>>1;
		if(i<=mid) upd(i,l,mid,p<<1);
		else upd(i,mid+1,r,p<<1|1);
		for(int u:{0,1}) for(int v:{0,1}) {
			f[p][u][v]=inf;
			for(int x:{0,1}) for(int y:{0,1}) {
				f[p][u][v]=min(f[p][u][v],f[p<<1][u][x]+f[p<<1|1][y][v]+(x||y?0:b[mid]));
			}
		}
	}
