struct poly
{
	vector<int> c;
	poly()
	{
		c.clear();
	}
	poly(vector<int> v)
	{
		c = v;
	}
	poly operator + (poly p)
	{
		int i;
		p.c.resize(max(p.c.size(), c.size()));
		for(i = 0; i < p.c.size(); i++)
			if(i < c.size())
				p.c[i] = (p.c[i] + c[i]) % mod;
		return p;
	}
	friend poly operator * (poly f, poly g)
	{
		if(f.c.empty() || g.c.empty())
			return poly();
		poly h;
		int i, l = 0;
		while((f.c.size() + g.c.size()) >> l)
			l++;
		memset(X, 0, 4 << l);
		memset(Y, 0, 4 << l);
		for(i = 0; i < f.c.size(); i++)
			X[i] = f.c[i];
		for(i = 0; i < g.c.size(); i++)
			Y[i] = g.c[i];
		ntt(X, l, 0);
		ntt(Y, l, 0);
		for(i = 0; i < (1 << l); i++)
			X[i] = (ll)X[i] * Y[i] % mod;
		ntt(X, l, 1);
		h.c.resize(f.c.size() + g.c.size() - 1);
		for(i = 0; i < h.c.size(); i++)
			h.c[i] = X[i];
		return h;
	}
};
int qwq(int x)
{
	return x > mod / 2 ? x - mod : x;
}
int a[N], b[N], c[N];
void work(int l, int r)
{
	int mid = (l + r) >> 1, i;
	if(l >= r)
		return ;
	poly f, g;
	for(i = l; i <= mid; i++)
		f.c.emplace_back(a[i]);
	for(i = mid + 1; i <= r; i++)
		g.c.emplace_back(b[i]);
	f = f * g;
	for(i = 0; i < f.c.size(); i++)
		c[i + l + mid + 1] = (c[i + l + mid + 1] + f.c[i]) % mod;
	work(l, mid);
	work(mid + 1, r);
	return ;
}

