{
	add(ls,tag[o]);
	add(rs,tag[o]);
	tag[o]=0;
}
void pushup(int o)
{
	maxx[o]=max(maxx[ls],maxx[rs]);
	cnt[o]=cnt[ls]+cnt[rs];
	sum[o]=sum[ls]+sum[rs];
}
void build(int o=1,int l=1,int r=n)
{
	tag[o]=0;
	if(l==r)
	{
		tag[o]+=b[l];
		if(tag[o]<0){cnt[o]=1;sum[o]=maxx[o]=tag[o];}
		else{cnt[o]=sum[o]=0;maxx[o]=-1e18;}
		return;
	}
	build(ls,l,mid);build(rs,mid+1,r);
	pushup(o);
}
void update(int lx,int rx,int k,int o=1,int l=1,int r=n)
{
	if(lx<=l&&r<=rx)
	{
		if(l==r)
		{
			tag[o]+=k;
			if(tag[o]<0){cnt[o]=1;sum[o]=maxx[o]=tag[o];}
			else{cnt[o]=sum[o]=0;maxx[o]=-1e18;}
			return;
		}
		if(maxx[o]+k<0)
		{
			add(o,k);
			return;
		}
	}
	pushdown(o);
	if(lx<=mid)update(lx,rx,k,ls,l,mid);
	if(rx>mid)update(lx,rx,k,rs,mid+1,r);
	pushup(o);
}
