    auto step = [&](int r) {
      int rr = r * (uint64_t)r % mod, rrr = rr * (uint64_t)r % mod;
      c = (c + (i + 1) * 1ull * (mod + rrr - lll) + a1 * 3ull * (mod + rr - ll) + a0 * 3ull * (mod + r - l)) % mod;
      l = r, ll = rr, lll = rrr;
