        ++k;
      }
      step(qs[i][j][0]);
      if (j + 1 < qs[i].size() && qs[i][j + 1] == ii{qs[i][j][0], qs[i][j][1] | 1}) {
        ans[qs[i][j][1] / 2] = ((i + 1ull) * ll + a1 * 2ull * l + a0) % mod, ++j;
      } else {
