		if (c[g[i + 1]] < c[i - 1]) g[i] = i - 1;
		else g[i] = g[i + 1];
	}
	if (h == 0) d++;
	long long int k = 0, l = 0;
	for (int i = 1; i <= n; i++) {
		if (k <= 0) {
