int root(vector<int> &uf, int u) {
  return (uf[u] < 0) ? u : (uf[u] = root(uf, uf[u]));
}
bool connect(vector<int> &uf, int u, int v) {
  u = root(uf, u);
  v = root(uf, v);
  if (u == v) return false;
  if (uf[u] > uf[v]) swap(u, v);
  uf[u] += uf[v];
  uf[v] = u;
  return true;
}


struct EarDecomp {
  int n;
  vector<vector<int>> graph;
  vector<int> par, dep;
  int zeit;
  vector<int> dis;
  vector<int> sid;
  vector<vector<int>> back;
  // ((s, t), u)
  //   s-u: back edge
  //   u-t: tree path
  //   dep[s] <= dep[t] <= dep[u]
  vector<pair<pair<int, int>, int>> ears;
  
  EarDecomp() {}
  EarDecomp(int n_) : n(n_), graph(n) {}
  void ae(int u, int v) {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }
  void build() {
    par.assign(n, -1);
    dep.assign(n, -1);
    zeit = 0;
    dis.assign(n, -1);
    sid.assign(n, -1);
    back.assign(n, {});
    for (int u = 0; u < n; ++u) if (!~dis[u]) dfs(u, -1);
    vector<int> vis(n, 0);
    ears.clear();
    for (int j = 0; j < n; ++j) {
      const int s = sid[j];
      vis[s] = 1;
      for (const int u : back[s]) {
        for (int t = u; ; t = par[t]) {
          if (vis[t]) {
            ears.emplace_back(make_pair(s, t), u);
            break;
          }
          vis[t] = 1;
        }
      }
    }
  }
  void dfs(int u, int p) {
    par[u] = p;
    dep[u] = (~p) ? (dep[p] + 1) : 0;
    dis[u] = zeit++;
    sid[dis[u]] = u;
    for (const int v : graph[u]) if (p != v) {
      if (~dis[v]) {
        if (dis[u] > dis[v]) back[v].push_back(u);
      } else {
        dfs(v, u);
      }
    }
  }
};


int N, M;
vector<int> A, B;

Int brute() {
  Int ans = 0;
  for (int u = 0; u < N; ++u) for (int v = u + 1; v < N; ++v) {
    bool cyc = false;
    vector<int> uf(N, -1);
    for (int i = 0; i < M; ++i) if (u != A[i] && u != B[i] && v != A[i] && v != B[i]) {
      if (!connect(uf, A[i], B[i])) cyc = true;
    }
    if (!cyc) {
      ++ans;
    }
  }
  return ans;
}

vector<pair<int, int>> sols;

// erase ban
void check1(int ban) {
  Biconnected bi(N);
  for (int i = 0; i < M; ++i) if (ban != A[i] && ban != B[i]) {
    bi.ae(A[i], B[i]);
  }
  bi.build();
  int numComps = 0;
  for (int u = 0; u < N; ++u) if (ban != u) if (!~bi.par[u]) ++numComps;
  for (int u = 0; u < N; ++u) if (ban != u) {
    const int n = N - 2;
    const int m = bi.m - (int)bi.g[u].size();
    const int c = numComps - 1 + (int)bi.gg[u].size();
    if (m == n - c) {
      sols.emplace_back(ban, u);
    }
  }
}

