#include<bits/stdc++.h>
#define ll long long
using namespace std;
const int MAXS=1<<17|5;
int _,p,z[7],f[7][7][7][7][7][7],h[7][7][7];
//f[n,x,m,y,u,v]: n=N_r x=D_l m=N_l y=D_r u=#[in deg>=p^l], v=#[out deg>=p^l+1]
//h[n,x,u]: edge between p^r groups to solve D_r
int g[MAXS],ng[MAXS];
void add(int &x,const int &y) { x=(x+y)%p; }
signed main() {
	ios::sync_with_stdio(false),cin.tie(0),cout.tie(0);
	cin>>_>>p;
	for(int i=z[0]=1;i<p;++i) z[i]=z[i-1]*p;
	for(int n=0;n<p;++n) for(int y=0;y<p;++y) {
		basic_string <int> tr; //state of p^l
		for(int s=0;s<(1<<n);++s) if(__builtin_popcount(s)==y) {
			int d=0;
			for(int i=0;i<n;++i) d+=z[i]*(s>>i&1);
			tr+=d;
		}
		memset(g,0,z[n]<<2),g[0]=1; //p^r deg from m p^l
		for(int m=0;m<p;++m) {
			for(int x=0;x<p;++x) for(int u=0;u<=n;++u) {
				for(int e=0;e<(1<<(n*2));++e) { //edge of p^l inside p^r
					int ok=1,v=0,s=0,o=1; //s: need deg from p^l
					for(int i=0;i<n;++i) {
						int c=e>>(i*2)&3;
						if(c>p/2) { ok=0; break; }
						int d=c*(p>2?2:1)+(i<u); //choose edge: C(p/2,c)
						if(p==5&&c==1) o*=2;
						if(p==7&&(c==1||c==2)) o*=3;
						if(d<=x) s+=z[i]*(x-d);
						else s+=z[i]*(x-d+p),++v; //carry bit
					}
					if(!ok) continue;
					add(f[n][x][m][y][u][v],o*g[s]);
				}
			}
			if(m==p-1||y>n) break;
			memset(ng,0,z[n]<<2);
			for(int s=0;s<z[n];++s) if(g[s]) for(auto&e:tr) add(ng[s+e],g[s]);
			memcpy(g,ng,z[n]<<2);
		}
	}
	for(int n=0;n<p;++n) {
		memset(g,0,z[n]<<2);
		basic_string <int> e;
		for(int i=0;i<n;++i) for(int j=i+1;j<n;++j) e+=(z[i]+z[j]);
		int k=e.size();
		for(int s=0;s<(1<<k);++s) { //graph of n p^r
			int o=0;
			for(int i=0;i<k;++i) o+=(s>>i&1)*e[i];
			add(g[o],1);
		}
		for(int x=0;x<p;++x) for(int u=0;u<=n;++u) {
			if(!x&&u) continue;
			int s=0;
			for(int i=0;i<n;++i) s+=z[i]*(x-(i<u));
			add(h[n][x][u],g[s]);
		}
	}
	for(ll N,D;_--;) {
		cin>>N>>D;
		basic_string <int> n,d;
		for(;N;N/=p,D/=p) n+=N%p,d+=D%p;
		int ans=1;
		for(int r=0;r<(int)n.size();++r) {
			array<int,7> dp,nx;
			dp.fill(0),dp[0]=1;
			for(int l=0;l<r;++l) {
				nx.fill(0);
				for(int u=0;u<=n[r];++u) if(dp[u]) for(int v=0;v<=n[r];++v) {
					add(nx[v],dp[u]*f[n[r]][d[l]][n[l]][d[r]][u][v]);
				}
				dp=nx;
			}
			int rs=0;
			for(int u=0;u<=n[r];++u) add(rs,dp[u]*h[n[r]][d[r]][u]);
			ans=ans*rs%p;
		}
		cout<<ans<<"\n";
	}
	return 0;
}

#include <bits/stdc++.h>

#define N 500005

using namespace std;

bool inq[N];
vector<int>g[N];
int fl,cnt,f[N],sz[N],dfn[N],low[N];

void dfs(int u,int fa)
{
	inq[u]=1;sz[u]=1;
	dfn[u]=low[u]=++cnt;
	int ct[3]={0};
	for(auto v:g[u])
		if(v!=fa)
		{
			if(!dfn[v])
			{
				dfs(v,u);
				low[u]=min(low[u],low[v]);
				sz[u]+=sz[v];
				if(low[v]>=dfn[u])
				{
					if(sz[v]%3==1)++ct[2];
				}
				else
					++ct[f[v]];
			}
			else if(inq[u])
				low[u]=min(low[u],dfn[v]);
		}
	if(sz[u]%3==2)fl=1;
	else if(sz[u]%3==1)
	{
		if(ct[1]>1)fl=1;
		f[u]=1;
	}
	else
	{
		if(ct[1])fl=1;
		f[u]=0;
	}
	inq[u]=0;
}

int main()
{
	int T;
	cin>>T;
	while(T--)
	{
		int i,n,m,u,v;
		cin>>n>>m;cnt=0;
		for(i=1;i<=n;++i){dfn[i]=0;g[i].clear();}
		for(i=1;i<=m;++i)
		{
			cin>>u>>v;
			g[u].push_back(v);
			g[v].push_back(u);
		}
		fl=0;
		vector<int>z;
		for(i=1;i<=n;++i)
			if(!dfn[i])
			{
				dfs(i,0);
				z.push_back(sz[i]);
			}
		if(z.size()>=3){puts("No");continue;}
		if(z.size()==2)
		{
			puts(z[0]%3==2?"Yes":"No");
			continue;
		}
		puts(fl?"Yes":"No");
	}
	return 0;
}

