using namespace std;
const int N=1e5+5;
int T,n,fa[N],v[N],d[N];
inline int ask(int x,int y){
	printf("? %d %d\n",x,y);ff;
	int z;scanf("%d",&z);return z;
}
int sol(bs g)
{
	if(g.size()==2) fa[g[1]]=g[0];
	if(g.size()<=2) return g[0];
	int mx=g.back();
	for(int w:g)
		if(w!=g[0]&&w!=mx) v[w]=(d[w]+d[mx]-ask(w,mx))/2;
		else v[w]=d[w];
	sort(g.begin(),g.end(),[](int x,int y){return v[x]==v[y]?d[x]<d[y]:v[x]<v[y];});
	for(int i=0,j,z=-1;i<g.size();i++)
	{
		for(j=i;j+1<g.size()&&v[g[i]]==v[g[j+1]];j++);
		bs id;for(int k=i;k<=j;k++) id+=g[k];
		int u=sol(id);(z!=-1)&&(fa[u]=z);z=u;i=j;
	}
	return g[0];
}
int main()
{
	scanf("%d",&T);
	while(T--)
	{
		scanf("%d",&n);bs g;
		for(int i=1;i<=n;i++) d[i]=(i==1?0:ask(1,i)),g+=i;
		sort(g.begin(),g.end(),[](int x,int y){return d[x]<d[y];});
		sol(g);printf("! ");
		for(int i=2;i<=n;i++)printf("%d %d %d ",fa[i],i,d[i]-d[fa[i]]);
		puts("");ff;
	}
	return 0;
}

