		}
		int l=v[i]*dp[i][i];
		for(int j=0;j<=k;j++) v[j]=(v[j]-dp[i][j]*l%3+3)%3;
	}
}
int query(vector<int> v){
	for(int i=0;i<=k;i++){
		if(v[i]==0) continue;
		if(dp[i].empty()) return 0;
		int l=v[i]*dp[i][i];
		for(int j=0;j<=k;j++) v[j]=(v[j]-dp[i][j]*l%3+3)%3;
	}
	for(int j=0;j<=k;j++){
		if(v[j]) return 0;
	}
	return 1;
}
