	for(int i=n;i;i--) sum[i]=sum[i+1]+(a[i]<<1);
	__int128 res=-((__int128)1<<120),sum1=0,sum2=sum[1];
	for(int i=1,la=0;i<=n;i++){
		if(sum1+(a[i]<<(t1?0:1))>d) res=max(res,sum2-(a[i]<<1)-(t2?a[i==n?la:n]:0));
		if(sum1+(a[i]<<1)<=d||sum1+sum[i+1]-(t1?a[n]:0)<=d) sum1+=a[i]<<1,sum2-=a[i]<<1;
		else la=i;
	}
	return res;
