template<typename T>
int dcmp(T x){
	if(is_same<T,ld>::value)
		return x<-eps?-1:(x>eps?1:0);
	else return (x>0)-(x<0);
}
struct pt{
	ld x,y;
	int id;
	pt(ld xx=0,ld yy=0,int i=-1){x=xx,y=yy,id=i;}
	bool operator <(const pt &a)const{return dcmp(y-a.y)?y<a.y:x<a.x;}
	pt &operator +=(const pt &b){x+=b.x,y+=b.y;return *this;}
	pt &operator -=(const pt &b){x-=b.x,y-=b.y;return *this;}
	friend istream &operator >>(istream &is,pt &a){return is>>a.x>>a.y;}
	friend ostream &operator <<(ostream &os,const pt &a){return os<<a.x<<' '<<a.y;}
}O(0,0);
pt operator -(const pt &a){return pt(-a.x,-a.y);}
pt operator +(const pt &a,const pt &b){return pt(a.x+b.x,a.y+b.y);}
pt operator -(const pt &a,const pt &b){return pt(a.x-b.x,a.y-b.y);}
pt operator *(const pt &a,const ld &b){return pt(a.x*b,a.y*b);}
pt operator *(const ld &b,const pt &a){return pt(a.x*b,a.y*b);}
pt operator /(const pt &a,const ld &b){return pt(a.x/b,a.y/b);}
ld operator *(const pt &a,const pt &b){return a.x*b.x+a.y*b.y;}
ld operator ^(const pt &a,const pt &b){return a.x*b.y-a.y*b.x;}
ld sqr(ld x){return x*x;}
ld len2(pt a){return a*a;}
ld len(pt a){return sqrt(a*a);}
ld atan2(pt a){return atan2(a.y,a.x);}
ld getang(pt a){ld t=atan2(a);return t<0?t+2*pi:t;}
int ccw(pt a,pt b,pt c){return dcmp((b-a)^(c-a));}
pt intersect(pt a,pt b,pt c,pt d){
	pt x=b-a,y=d-c,z=c-a;
	return a+x*((z^y)/(x^y));
}
struct line{
	pt p[3];
	ld ang;
	int box;
	line(){}
	line(pt a,pt b,int ibox=-1,ld k=inf){p[0]=a,p[1]=b,p[2]=a+b;box=ibox;ang=(k<inf/2?k:getang(b));}
	pt &operator [](int i){return p[i];}
	const pt &operator [](int i)const{return p[i];}
	bool operator <(const line &l)const{return dcmp(ang-l.ang)?ang<l.ang:ccw(p[0],p[2],l.p[0])<0;}
	bool operator ==(const line &l)const{return !dcmp(ang-l.ang);}
};
pt intersect(line a,line b){return intersect(a[0],a[2],b[0],b[2]);}
line rev(line a){return line(a[2],-a[1],a.box,a.ang+pi);}
bool left(line a,pt p){return dcmp(a[1]^(p-a[0]))>0;}
bool para(line a,line b){return !dcmp(a[1]^b[1]);}
ld dis(pt a,line o){
	if(((a-o[0])*o[1])<=0)return len(a-o[0]);
	if(((a-o[2])*o[1])>=0)return len(a-o[2]);
	return fabs((a-o[0])^o[1]/len(o[1]));
}
struct logop{int tp;line l;pt p;};
struct dq{
	segs q;
	poly p;
	vector<logop> st;
	vector<int> ps;
	void clear(){q.clear();p.clear();st.clear();ps.clear();}
	void add(line x){
		ps.pb(st.size());
		while(q.size()>=2&&!left(x,p.back())){
			st.pb({2,q.back(),p.back()});
			q.pop_back();p.pop_back();
		}
		if(!q.empty()){
			pt t=intersect(q.back(),x);
			p.pb(t);st.pb({1,line(),t});
		}
		q.pb(x);st.pb({0,x,pt()});
	}
	void del(){
		int t=ps.back();ps.pop_back();
		while((int)st.size()>t){
			logop o=st.back();st.pop_back();
			if(o.tp==0)q.pop_back();
			else if(o.tp==1)p.pop_back();
			else q.pb(o.l),p.pb(o.p);
		}
	}
};
struct ch{
	segs l;
	poly p;
	void clear(){l.clear();p.clear();}
	void add(line x){
		while(l.size()>=2&&!left(x,p.back()))l.pop_back(),p.pop_back();
		if(!l.empty())p.pb(intersect(l.back(),x));
		l.pb(x);
	}
};
segs canonical(segs v,int keep){
	segs z;
	for(auto x:v){
		if(!z.empty()&&para(z.back(),x)){
			ld c=z.back()[1]^(x[0]-z.back()[0]);
			if((keep&&dcmp(c)>0)||(!keep&&dcmp(c)<0))z.back()=x;
		}
		else z.pb(x);
	}
	return z;
}
ch mergeplane(const segs &a,const poly &pa,const segs &b,const poly &pb,int dir,line *cap,int cr){
	int na=a.size(),nb=b.size();
	vector<line> va,vb;
	int i=na-1,j=nb-1;
	while(i>=0&&j>=0){
		line x=a[i],y=b[j];
		int nx=i>0,ny=j>0;
		if(!nx&&!ny){va.pb(x);vb.pb(y);i--;j--;break;}
		int okx=nx&&left(y,pa[i-1]);
		int oky=ny&&left(x,pb[j-1]);
		if(!okx&&!oky){va.pb(x);vb.pb(y);i=-1;j=-1;break;}
		if(okx&&oky){
			if(dcmp(dir*(pa[i-1].y-pb[j-1].y))<=0)va.pb(x),i--;
			else vb.pb(y),j--;
		}
		else if(okx)va.pb(x),i--;
		else vb.pb(y),j--;
	}
	while(i>=0)va.pb(a[i--]);
	while(j>=0)vb.pb(b[j--]);
	ch c;
	for(auto x:va)c.add(x);
	if(cap)c.add(cr?rev(*cap):*cap);
	for(int k=vb.size()-1;k>=0;k--)c.add(vb[k]);
	return c;
}
ld linedis(line a,line b){
	if(dcmp(a[1]^b[1]))return 0;
	return fabs((b[0]-a[0])^a[1])/len(a[1]);
}
ld linepts(line a,poly &p){
	ld res=inf;
	for(auto x:p)res=min(res,fabs((x-a[0])^a[1])/len(a[1]));
	return res;
}
ld disray(pt p,pt s,pt d){
	ld t=max((ld)0,((p-s)*d)/len2(d));
	return len(p-s-d*t);
}
ld edis(pt p,ch &c,int i,int fl,int fr){
	int n=c.l.size(),m=c.p.size();
	if(i==0){
		pt d=c.l[0][1];
		if(!fl)d=-d;
		return disray(p,c.p[0],d);
	}
	if(i==n-1){
		pt d=c.l[n-1][1];
		if(!fr)d=-d;
		return disray(p,c.p[m-1],d);
	}
	return dis(p,line(c.p[i-1],c.p[i]-c.p[i-1]));
}
ld calc(ch &a,ch &b){
	int na=a.l.size(),nb=b.l.size(),ma=a.p.size(),mb=b.p.size();
	if(!na||!nb)return inf;
	if(!ma&&!mb)return linedis(a.l[0],b.l[0]);
	if(!ma)return linepts(a.l[0],b.p);
	if(!mb)return linepts(b.l[0],a.p);
	int af=dcmp(a.l[1][1]^a.l[0][1])>=0;
	int ar=dcmp(a.l[na-2][1]^a.l[na-1][1])>=0;
	int bf=dcmp(b.l[1][1]^b.l[0][1])>=0;
	int br=dcmp(b.l[nb-2][1]^b.l[nb-1][1])>=0;
	ld res=inf;
	int j=0;
	for(auto x:a.p){
		ld cur=edis(x,b,j,bf,br);
		while(j+1<nb){
			ld nxt=edis(x,b,j+1,bf,br);
			if(dcmp(nxt-cur)<=0)j++,cur=nxt;
			else break;
		}
		res=min(res,cur);
	}
	j=0;
	for(auto x:b.p){
		ld cur=edis(x,a,j,af,ar);
		while(j+1<na){
			ld nxt=edis(x,a,j+1,af,ar);
			if(dcmp(nxt-cur)<=0)j++,cur=nxt;
			else break;
		}
		res=min(res,cur);
	}
	return res;
}
int T,n;
segs rw;
ld ans;
ld calc(segs v){
	for(auto &x:v)if(x[2]<x[0])x=rev(x);
	sort(v.begin(),v.end(),[](line a,line b){
		ld c=a[1]^b[1];
		return dcmp(c)?dcmp(c)>0:dcmp(a[1]^(b[0]-a[0]))<0;
	});
	segs s;
	line *dn=0,*up=0;
	for(auto &x:v){
		if(!dcmp(x[1].y)){
			if(!dn||x[0]<(*dn)[0])dn=&x;
			if(!up||(*up)[0]<x[0])up=&x;
		}
		else s.pb(x);
	}
	if(s.empty())return (!dn||!up)?0:(*up)[0].y-(*dn)[0].y;
	segs L=canonical(s,1),R=canonical(s,0);
	dq pl,pr,sl,sr;
	for(int i=L.size()-1;~i;i--){
		sl.add(L[i]);
		sr.add(rev(R[i]));
	}
	ld res=inf;
	for(int i=0;i<=(int)L.size();i++){
		ch lo=mergeplane(pr.q,pr.p,sl.q,sl.p,1,dn,1);
		ch hi=mergeplane(sr.q,sr.p,pl.q,pl.p,-1,up,0);
		res=min(res,calc(lo,hi));
		if(i<(int)L.size()){
			pl.add(L[i]);
			pr.add(rev(R[i]));
			sl.del();
			sr.del();
		}
	}
	return res;
}
