int64_t lerpf(int64_t a, int64_t b, int64_t c, int64_t d, int64_t e) {
  if (c == a) return min(b, d);
  auto p = b * (c - e) + d * (e - a), q = c - a;
  return p / q - (p % q < 0);
}

