inline void ad(int &u,int v) {u+=v;(u>=mod&&(u-=mod));}
inline int pw(int x,int y) {
	int z=1;
	for(;y;y>>=1,x=x*1ll*x%mod) if(y&1) z=z*1ll*x%mod;
	return z;
}
inline void dfs(int x,int fa,int o) {
	f[x][1]=1;f[x][0]=0;sz[x]=1;
	for(int y:e[x]) if(y!=fa) {
		dfs(y,x,o);
		fr(i,1,sz[x]) fr(j,0,sz[y]) ad(tp[i+j],f[x][i]*1ll*f[y][j]%mod);
		sz[x]+=sz[y];
		fr(i,1,sz[x]) f[x][i]=tp[i],tp[i]=0;
	}
	fr(i,1,sz[x]) ad(f[x][0],f[x][i]),f[x][i]=f[x][i]*1ll*o%mod;
	return ;
}
inline void lag(int *a,int n) {
	fr(i,0,n) c[i]=h[i]=0;
	h[0]=1;fr(i,1,n+1) rp(j,i,0) h[j]=(h[j]*1ll*(mod-i)+(j?h[j-1]:0))%mod;
	fr(i,1,n+1) {
		int z=1,inv=pw(i,mod-2),l=0;
		fr(j,1,n+1) if(i!=j) z=z*1ll*(i-j)%mod;
		z=pw(z,mod-2)*1ll*a[i]%mod;
		fr(j,0,n) {
			l=(l-h[j])*1ll*inv%mod;
			c[j]+=l*1ll*z%mod;
		}
	}
	return ;
}
int main() {
	scanf("%d",&n);
	fac[0]=1;fr(i,1,n) fac[i]=fac[i-1]*1ll*i%mod;
	fr(i,0,n) fr(j,0,i) C[i][j]=j?(C[i-1][j-1]+C[i-1][j])%mod:1;
	fr(i,1,n) scanf("%d",q+i);
	fr(i,1,n-1) {int x,y;scanf("%d%d",&x,&y);e[x].push_back(y);e[y].push_back(x);}
	fr(i,1,n+1) {
		dfs(1,0,i);
		fr(j,1,n) fr(k,1,sz[j]) ad(g[j][i],f[j][k]*1ll*q[k]%mod);
	}
	fr(i,1,n) {
		lag(g[i],sz[i]);
		fr(j,1,n) ans[j]=0;
		fr(j,1,sz[i]) {
			c[j]=(c[j]%mod+mod)%mod;
			fr(k,j,n) ad(ans[k],c[j]*C[n-sz[i]][k-j]%mod);
		}
		fr(j,1,n) printf("%lld ",ans[j]*1ll*fac[j-1]%mod*fac[n-j]%mod);printf("\n");
	}
	return 0;
}

