using namespace std;
int n,dis[1000001],vis[1000001],mx_d[1000001],ans[2][1000001],f[1000001],zj,num,siz[1000001];
vector<int>g[1000001];
void dfs(int u,int fa){
	mx_d[u]=dis[u]=dis[fa]+1;f[u]=fa;
	for(int v:g[u])if(v^fa)dfs(v,u),mx_d[u]=max(mx_d[u],mx_d[v]);
}void work(int x,int k){
	queue<int>q,qq;q.push(x);int minn;
	for(int i=1;i<zj;i++){
		ans[k][i]=num;minn=1e9;
		while(!q.empty()){
			int u=q.front();siz[u]=0;qq.push(u);q.pop();
			for(int v:g[u])if(v!=f[u]&&mx_d[v]==zj)siz[u]++;
			minn=min(minn,siz[u]);
		}while(!qq.empty()){
			int u=qq.front();qq.pop();
			if(siz[u]==minn){
				for(int v:g[u])if(v!=f[u]&&mx_d[v]==zj)q.push(v);
			}
		}num+=minn;
	}ans[k][zj]=minn;
}
void solve(){
	cin>>n;for(int i=1;i<=n;i++)vis[i]=0,g[i].clear();
	for(int i=1,u,v;i<n;i++)cin>>u>>v,g[u].push_back(v),g[v].push_back(u);
	dfs(1,0);int maxx=0,l=1,r=1;num=0;
	for(int i=1;i<=n;i++)if(dis[i]>maxx)maxx=dis[i],l=i;maxx=0;
	dfs(l,0);for(int i=1;i<=n;i++)if(dis[i]>maxx)maxx=dis[i],r=i;
	for(int i=1;i<=n;i++)if(dis[i]==maxx)vis[i]=1;dfs(r,0);
	for(int i=1;i<=n;i++)if(dis[i]==maxx)vis[i]=1;
	for(int i=1;i<=n;i++)num+=vis[i];zj=maxx;work(r,0);
	num=0;for(int i=1;i<=n;i++)num+=vis[i];dfs(l,0);work(l,1);
	int w=2;for(int i=1;i<=maxx;i++){
		if(w>1){
			if(ans[0][i]>ans[1][i])w=1;
			if(ans[0][i]<ans[1][i])w=0;
		}
		cout<<ans[min(1,w)][i]<<" ";
	}cout<<"\n";
}
main(){
	int t;cin>>t;while(t--)solve();	
}

