using namespace std;using ll=long long;using vl=vector<ll>;
using ld=long double;using vd=vector<ld>;
const ll M=36*1e7,inf=1e18;const ld pi=acos(-1);
vl r;vector<pair<ll,ld>>ps;vector<vector<pair<ll,ll>>>Mix;vd Vr;vl Vp;
ld calc(int rid,ll ad)
{
    ll rA=r[rid-1],rB=r[rid];
    ld ang=pi*2*abs(ad)/M,dg=acos(ld(rA)/rB);
    if(ang>dg)return sqrt(rB*rB-rA*rA)+rA*(ang-dg);
    return sqrt(rA*rA+rB*rB-rA*rB*cos(ang)*2);
}
void qry(int rid,int cid,int pl,int pr)
{
    for(int i=pl,pos=Mix[rid][cid].first;i<=pr;i++)
    {
        auto&[a,r2]=ps[i];ld V=r2+calc(rid,pos-a);
        if(V<Vr[cid])Vr[cid]=V,Vp[cid]=i;
    }
}
void sol(int dep,int iL,int iR)
{
    if(iR-iL<2)return;int iM=iL+iR>>1;
    qry(dep,iM,Vp[iL],Vp[iR]);sol(dep,iL,iM);sol(dep,iM,iR);
}
int main()
{
    ios::sync_with_stdio(0),cin.tie(0);
    int n,q;cin>>n>>q;vd Res(q+1);r=vl(n+1);Mix.resize(n+1);
    for(int i=1,k;i<=n;i++)
    {
        cin>>r[i]>>k;Mix[i].resize(k);
        for(auto&[c,qid]:Mix[i])cin>>c,qid=0;
    }
    for(int i=1,pos,c;i<=q;i++)cin>>pos>>c,Mix[pos].push_back({c,i});
    for(int i=1,link=1;i<=n;i++)
    {
        sort(Mix[i].begin(),Mix[i].end());
        int La=ps.size(),Lb=Mix[i].size();Vr=vd(Lb,inf);Vp=vl(Lb,-1);

        if(i==1)Vr=vd(Lb,r[1]);else if(!La||!Lb||!link)link=0;
        else qry(i,0,0,La-1),qry(i,Lb-1,0,La-1),sol(i,0,Lb-1);
        
        ps.clear();auto vec=ps;
        for(int j=0;j<Lb;j++)
        {
            auto [c,qid]=Mix[i][j];
            if(qid)Res[qid]=Vr[j];
            else vec.push_back({c,Vr[j]});
        }
        for(int z:{-1,0,1})for(auto&[pos,dp]:vec)ps.push_back({pos+M*z,dp});
    }
    for(int i=1;i<=q;i++)
    {
        if(Res[i]>inf/2)cout<<"-1\n";
        else cout<<fixed<<setprecision(12)<<Res[i]<<'\n';
    }
}

