inline void solve(){
	for(int i=1;i<=n+1;i++) tg[i]=0;
	tp=1,st[tp]=n+1,sts[tp]=0,w[n+1]=1;
	for(int i=n,sm=0;i;i--){
		tg[a[i]]++,w[i]=tg[a[i]]/(n-i+1.0),sm+=c[i];
