	scanf("%d%d",&n,&K);
	m=max(n,K);
	inv[1]=1;
	for(int i=2;i<=m;i++)
		inv[i]=1ll*(mod-mod/i)*inv[mod%i]%mod;
	for(int i=0;i<=m;i++){
		C[i][0]=1;
		for(int j=1;j<=i;j++)
			C[i][j]=(C[i-1][j-1]+C[i-1][j])%mod;
	}
	for(int i=1;i<=m;i++){
		pw[i][0]=1;
		for(int j=1;j<=m;j++)
			pw[i][j]=1ll*pw[i][j-1]*inv[i]%mod;
	}
	int ans=0;
	for(int i=0;i<n;i++)
		ans=(ans+C[n-1][i])%mod;
	for(int i=0;i<=K;i++){
		int x=1;
		for(int j=1;j<=n;j++)
			x=1ll*x*((j<n)+pw[j][i])%mod;
		ans=(ans+1ll*((i&1)?1:-1)*C[K][i]*x)%mod;
	}
	ans=(ans+mod)%mod; 
	printf("%d",ans);
