}
using ll = long long;
using ull = unsigned long long;
const int N=1e5+10,M=N*6;
int n,m;
struct BIT{
  unsigned c[N];
  void add(int x,unsigned y){
    for(x++;x;x^=x&-x)c[x]+=y;
  }
  unsigned get(int x,unsigned y=0){
    for(x++;x<=n+1;x+=x&-x)y+=c[x];
    return y;
  }
  void update(int l,int r,unsigned x){
    add(r,x);
    add(l-1,-x);
  }
  void clr(int x){
    for(x++;x;x^=x&-x)c[x]=0;
  }
}A,B,C;
int n1,n2;
struct opts{
  int op,l,r;
  unsigned w;
  int id,tp;
}o1[M],o2[M],o[M];
int op[N];
unsigned ans[N];
void divide1(int l,int r){
  if(l==r)return;
  int mid=(l+r)>>1;
  divide1(l,mid);
  divide1(mid+1,r);
  int j=l;
  for(int i=mid+1;i<=r;i++){
    for(;j<=mid&&o[j].r<o[i].r;j++)if(o[j].op==1){
      A.update(0,o[j].l,o[j].w*(o[j].r-o[j].l)*(o[j].r-o[j].l));
      A.update(o[j].l+1,o[j].r,o[j].w*o[j].r*o[j].r);
      B.update(o[j].l+1,o[j].r,o[j].w*o[j].r);
      C.update(o[j].l+1,o[j].r,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(
        A.get(o[i].l)
        -B.get(o[i].l)*2*o[i].l
        +C.get(o[i].l)*o[i].l*o[i].l
      );
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    A.clr(o[j].l);
    A.clr(o[j].r);
    B.clr(o[j].l);
    B.clr(o[j].r);
    C.clr(o[j].l);
    C.clr(o[j].r);
  }
  inplace_merge(o+l,o+1+mid,o+1+r,[&](opts x,opts y){
    return x.r<y.r;
  });
}
void divide2(int l,int r){
  if(l==r)return;
  int mid=(l+r)>>1;
  divide2(l,mid);
  divide2(mid+1,r);
  int j=l;
  for(int i=mid+1;i<=r;i++){
    for(;j<=mid&&o[j].l<o[i].l;j++)if(o[j].op==1){
      C.update(o[j].l,o[j].r,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(C.get(o[i].r)*(o[i].r-o[i].l)*(o[i].r-o[i].l));
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    C.clr(o[j].l-1);
    C.clr(o[j].r);
  }
  j=mid;
  for(int i=r;i>mid;i--){
    for(;j>=l&&o[j].l>=o[i].l;j--)if(o[j].op==1){
      A.update(o[j].l,o[j].r,o[j].w*o[j].l*o[j].l);
      B.update(o[j].l,o[j].r,o[j].w*o[j].l);
      C.update(o[j].l,o[j].r,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(A.get(o[i].r)-B.get(o[i].r)*2*o[i].r+C.get(o[i].r)*o[i].r*o[i].r);
    }
  }
  for(;++j<=mid;)if(o[j].op==1){
    A.clr(o[j].l-1);
    A.clr(o[j].r);
    B.clr(o[j].l-1);
    B.clr(o[j].r);
    C.clr(o[j].l-1);
    C.clr(o[j].r);
  }
  inplace_merge(o+l,o+1+mid,o+1+r,[&](opts x,opts y){
    return x.l<y.l;
  });
}
void solve1(opts *oo){
  for(int i=1;i<=n1;i++)o[i]=oo[i];
  divide1(1,n1);
  for(int i=1;i<=n1;i++)o[i]=oo[i];
  divide2(1,n1);
}
BIT U[2],V[2],W[2];
void divide3(int l,int r){
  if(l==r)return;
  int mid=(l+r)>>1;
  divide3(l,mid);
  divide3(mid+1,r);
  int j=l;
  for(int i=mid+1;i<=r;i++){
    for(;j<=mid&&o[j].r<o[i].r;j++)if(o[j].op==1){
      U[o[j].tp].update(0,o[j].r-o[j].l,o[j].w*(o[j].r-o[j].l)*(o[j].r-o[j].l));
      V[o[j].tp].update(0,o[j].r-o[j].l,o[j].w*(o[j].r-o[j].l));
      W[o[j].tp].update(0,o[j].r-o[j].l,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(
        U[!o[i].tp].get(o[i].l)
        -V[!o[i].tp].get(o[i].l)*2*o[i].l
        +W[!o[i].tp].get(o[i].l)*o[i].l*o[i].l
      );
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    U[o[j].tp].clr(o[j].r-o[j].l);
    V[o[j].tp].clr(o[j].r-o[j].l);
    W[o[j].tp].clr(o[j].r-o[j].l);
  }
  j=mid;
