	}
	if(!flg)return 0;
	for(int i=2*l-2; i>=0; i--)nex[i]=min(nex[i],nex[i+1]);
	for(int i=0; i<2*l; i++)st[0][i]=nex[i];
	for(int i=1; i<=17; i++)for(int j=0; j<2*l; j++){
