const int mod = 998244353, g = 3, invg = (mod + 1) / 3;
int Power(int x, int y) {
	int r = 1;
	while (y) {
		if (y & 1) r = 1ll * r * x % mod;
		y >>= 1, x = 1ll * x * x % mod;
	}
	return r;
}
int ta[1200005], tb[1200005], wk[1200005];
int Add(int x, int y) {
	x += y;
	if (x >= mod) x -= mod;
	return x;
}
int Del(int x, int y) {
	x -= y;
	if (x < 0) x += mod;
	return x;
}
void DFT(int *a, int n) {
	for (int i = n >> 1; i; i >>= 1) {
		int w = Power(g, (mod - 1) / (i << 1));
		wk[0] = 1;
		for (int j = 1; j < i; j++) wk[j] = 1ll * wk[j - 1] * w % mod;
		for (int j = 0; j < n; j += (i << 1)) {
			for (int k = 0; k < i; k++) {
				int x = a[j + k], y = a[i + j + k], z = x;
				x += y, (x >= mod && (x -= mod)), a[j + k] = x;
				z -= y, (z < 0 && (z += mod)), a[i + j + k] = 1ll * z * wk[k] % mod;
			}
		}
	}
}
void IDFT(int *a, int n) {
	for (int i = 1; i < n; i <<= 1) {
		int w = Power(invg, (mod - 1) / (i << 1));
		wk[0] = 1;
		for (int j = 1; j < i; j++) wk[j] = 1ll * wk[j - 1] * w % mod;
		for (int j = 0; j < n; j += (i << 1)) {
			for (int k = 0; k < i; k++) {
				int x = a[j + k], y = 1ll * a[i + j + k] * wk[k] % mod, z = x;
				x += y, (x >= mod && (x -= mod)), a[j + k] = x;
				z -= y, (z < 0 && (z += mod)), a[i + j + k] = z;
			}
		}
	}
	for (int i = 0, inv = Power(n, mod - 2); i < n; i++) a[i] = 1ll * a[i] * inv % mod;
}
poly operator*(const poly &a, const poly &b) {
	int sa = a.size(), sb = b.size(), sr = sa + sb - 1;
	poly ret(sr);
	if (sr < 70) {
		for (int i = 0; i < sa; i++)
			for (int j = 0; j < sb; j++) ret[i + j] = (ret[i + j] + 1ll * a[i] * b[j]) % mod;
		return ret;
	}
	int len = 1;
	while (len < sr) len <<= 1;
	for (int i = 0; i < len; i++) ta[i] = tb[i] = 0;
	for (int i = 0; i < sa; i++) ta[i] = a[i];
