	return ret;
}
poly operator+(poly a, poly b) {
	int sa = a.size(), sb = b.size(), sr = max(sa, sb);
	a.resize(sr);
	for (int i = 0; i < sr; i++)
		if (i < sb) a[i] = Add(a[i], b[i]);
	return a;
}
poly operator-(poly a, poly b) {
	int sa = a.size(), sb = b.size(), sr = max(sa, sb);
	a.resize(sr);
