int P[200002];

struct Info { int i, u; };
Info Q[200002];

vector<int> L, R;

struct Node { int s, v; };
Node tr[1 << 21];

void add(int i, int x){
  i += (1 << 20) - 1;

  Node &o = tr[i];
  o.s += x; o.v = max(o.s, 0);

  while(i > 1){
    const Node &a = tr[i & -2], &b = tr[i | 1];
    i >>= 1;

    tr[i] = { a.s + b.s, max(a.v, a.s + b.v) };
  }
}

void push(int i, bool d = true){
  const int x = P[i];
  vector<int> &S = d ? R : L;

  const int n = S.size(); int s = 0;

  for(int e = n; s < e; ){
    const int m = (s + e + 1) / 2, y = P[S[m - 1]];

    if(d ? y > x : y < x) s = m; else e = m - 1;
  }

  if(s == n) S.push_back(0);
  else add(P[S[s]], d ? 1 : -1);

  Q[i] = { s, S[s] }; S[s] = i;

  add(x, d ? -1 : 1);
}

void pop(int i, bool d = true){
  add(P[i], d ? 1 : -1);
  vector<int> &S = d ? R : L;

  const Info &o = Q[i];

  if(o.u == 0) S.pop_back();
  else{ S[o.i] = o.u; add(P[o.u], d ? -1 : 1); }
}

int main(){
  int N, Q; scanf("%d%d", &N, &Q);

  for(int i = 1; i <= N; i++) scanf("%d", &P[i]);

  for(int i = N; i >= 1; i--) push(i);

  for(int i = 1; Q--; ){
    char c; scanf(" %c", &c);

    if(c == '>'){ pop(i); push(i++, false); continue; }
    if(c == '<'){ pop(--i, false); push(i); continue; }

    int x; scanf("%d", &x);

    pop(i); P[i] = x; push(i);

    printf("%lu\n", R.size() + tr[1].v);
  }

  return 0;
}

