int qpow(int x,int y=mod-2){
	int m=1;
	for(;y;y>>=1,x=1ll*x*x%mod)if(y&1)m=1ll*m*x%mod;
	return m;
}
int C(int n,int m){
	if(n<m||m<0)return 0;
	return 1ll*fac[n]*ifac[m]%mod*ifac[n-m]%mod;
}
void init(int n){
	fac[0]=1;
	for(int i=1;i<=n;i++)fac[i]=1ll*fac[i-1]*i%mod;
	ifac[n]=qpow(fac[n]);
	for(int i=n-1;i>=0;i--)ifac[i]=1ll*ifac[i+1]*(i+1)%mod;
}
const int G=3;
const int invG=qpow(G);
int tr[N<<1],tf;
void tpre(int n){
	if(tf==n)return;tf=n;
	for(int i=0;i<n;i++)tr[i]=(tr[i>>1]>>1)|((i&1)?n>>1:0);
}
int pwG[N],pwiG[N];
int Qpow(int op,int p){
	if(op){
		if(pwG[p])return pwG[p];
		return pwG[p]=qpow(G,(mod-1)/p/2);
	}
	if(pwiG[p])return pwiG[p];
	return pwiG[p]=qpow(invG,(mod-1)/p/2);
} 
void NTT(int *g,bool op,int n){
	static ull f[N<<1],w[N]={1};
	tpre(n);
	for (int i=0;i<n;i++)f[i]=(g[tr[i]]);
	for(int l=1;l<n;l<<=1){
		ull tG=Qpow(op,l);
		for (int i=1;i<l;i++)w[i]=w[i-1]*tG%mod;
		for(int k=0;k<n;k+=l+l)
			for(int p=0;p<l;p++){
				int tt=w[p]*f[k|l|p]%mod;
				f[k|l|p]=f[k|p]+mod-tt;
				f[k|p]+=tt;
			}      
		if (l==(1<<10))
			for (int i=0;i<n;i++)f[i]%=mod;
	}if (!op){
		ull invn=qpow(n);
		for(int i=0;i<n;++i)
			g[i]=f[i]%mod*invn%mod;
	}else for(int i=0;i<n;++i)g[i]=f[i]%mod;
}
