void times(int *f,int *g,int len,int lim){
//	puts("Times");
//	for(int i=0;i<len;i++)printf("%d ",f[i]);puts(""); 
//	for(int i=0;i<len;i++)printf("%d ",g[i]);puts(""); 
	int n=1;while(n<len+len)n<<=1;
	cpy(sav,g,n);clr(sav+len,n-len);
	NTT(f,1,n);NTT(sav,1,n);
	px(f,sav,n);NTT(f,0,n);
	clr(f+lim,n-lim);clr(sav,n);
//	for(int i=0;i<lim;i++)printf("%d ",f[i]);puts(""); 
}
void invp(int *f,int m){
	int n;for (n=1;n<m;n<<=1);
	static int w[N<<1],r[N<<1];
	w[0]=qpow(f[0]);
	for (int len=2;len<=n;len<<=1){
	for (int i=0;i<(len>>1);i++)r[i]=w[i];
	cpy(sav,f,len);NTT(sav,1,len);
	NTT(r,1,len);px(r,sav,len);
	NTT(r,0,len);clr(r,len>>1);
	cpy(sav,w,len);NTT(sav,1,len);
	NTT(r,1,len);px(r,sav,len);
	NTT(r,0,len);
	for (int i=len>>1;i<len;i++)
		w[i]=(w[i]*2ll-r[i]+mod)%mod;
	}cpy(f,w,m);clr(sav,n);clr(w,n);clr(r,n);
}
int f[N],g[N],h[N],ng[N],nh[N];
int u[N],v[N];
void div(int *u,int *v,int m){
	for(int i=0;i<m;i++)f[i]=u[i],g[i]=v[i];
	invp(g,m);
	times(f,g,m,m);
	for(int i=0;i<m;i++)u[i]=f[i];
	clr(f,m),clr(g,m);
}
#define U(i,j,n,m) u[(j)*(n)+(i)]
#define V(i,j,n,m) v[(j)*(n)+(i)]
void solve(int n,int m,int Lim){
	while(1){
		if(n==1)return div(u,v,m);
		for(int i=0;i<n;i++){
			for(int j=0;j<m;j++){
				f[j*n*2+i]=U(i,j,n,m);
				g[j*n*2+i]=V(i,j,n,m);
	//			if(i&1)h[j*n*2+i]=(mod-h[j*n*2+i])%mod;
			}
		}
		m<<=1;
		int lim=1;
		while(lim<n*m*2)lim<<=1;
	//	printf("Solve:%d %d\n",n,m); 
	//	for(int i=0;i<lim;i++)printf("%d ",f[i]);puts("");
	//	for(int i=0;i<lim;i++)printf("%d ",g[i]);puts("");
	//	for(int i=0;i<lim;i++)printf("%d ",h[i]);puts("");
		NTT(f,1,lim),NTT(g,1,lim);//,NTT(h,1,lim); 
		for(int i=0;i<(lim>>1);i++){
			h[i]=g[i+(lim>>1)];
			h[i+(lim>>1)]=g[i];
		}
	//	for(int i=0;i<lim;i++)printf("%d ",g[i]);puts("");
	//	for(int i=0;i<lim;i++)printf("%d ",h[i]);puts("");
		for(int i=0;i<lim;i++)f[i]=1ll*f[i]*h[i]%mod;
		for(int i=0;i<lim;i++)g[i]=1ll*g[i]*h[i]%mod;
		NTT(f,0,lim),NTT(g,0,lim);
		clr(u,n*m*2),clr(v,n*m*2);
		m=min(m,Lim);
		if(n&1){
			int n1=n+1>>1,n2=n*2; 
			for(int i=0;i<n;i+=2){
				int i1=i>>1;
				for(int j=0,p=i;j<m;j++,p+=n2){
					U(i1,j,n1,m)=f[p];
					V(i1,j,n1,m)=g[p];
				}
			}
		}else{
			int n1=n+1>>1,n2=n*2; 
			for(int i=0;i<n;i++){
				int i1=i>>1;
				if(i&1){
					for(int j=0,p=i;j<m;j++,p+=n2)U(i1,j,n1,m)=f[p];
				}else{
					for(int j=0,p=i;j<m;j++,p+=n2)V(i1,j,n1,m)=g[p];
				}
			}
		}
		clr(f,lim),clr(g,lim),clr(h,lim);
		n=n+1>>1;
	}
}
