using namespace std;
char pl[10005];
int fk[15]={0,11,10,9,8,7,6,5,4,3,1},tt=10;
#define ull unsigned long long
ull A=0,B=0;
int L[105],R[105];
inline void send(int b){
	printf("send %d\n",b);fflush(stdout);
}
inline int rcv(){
	printf("receive\n");fflush(stdout);
	int b;scanf("%d",&b);
	return b;
}
int main(){
	scanf("%s",pl+1);
	int he=0;
	for(int i=1;i<=tt;++i){
		R[i]=63-he,L[i]=63-he-fk[i]+1;
		he+=fk[i];
	}
	if(pl[1]=='A'){
		scanf("%llu",&A);
		int fl=0;
		for(int i=1;i<=tt;++i){
			if(fl){
				for(int j=R[i];j>=L[i];--j)send(A>>j&1);
				continue;
			}
			for(int j=R[i];j>=L[i];--j){
				int b=rcv();
				B|=(ull)b<<j;
			}
			if(B>A){
				send(0);fl=1;
				for(int j=R[i];j>=L[i];--j)send(A>>j&1);
			}else send(1);
		}
	}else{
		scanf("%llu",&B);
		int fl=0;
		for(int i=1;i<=tt;++i){
			if(fl){
				for(int j=R[i];j>=L[i];--j)A|=(ull)rcv()<<j;
				continue;
			}
			for(int j=R[i];j>=L[i];--j){
				send(B>>j&1);
			}
			if(rcv()){
				for(int j=R[i];j>=L[i];--j)A|=(ull)(B>>j&1)<<j;
				continue;
			}
			fl=1;
			for(int j=R[i];j>=L[i];--j)A|=(ull)rcv()<<j;
		}
	}
	printf("answer %llu\n",min(A,B));fflush(stdout);
	return 0;
}

