struct vec
{
	int x,y;
	int quadrant()const{return !x?(y<0?3:1):!y?(x<0?2:0):((y<0)*3)^(x<0);}
	ll norm2()const{return (ll)x*x+(ll)y*y;}
	friend vec operator+(const vec &a,const vec &b){return {a.x+b.x,a.y+b.y};}
	friend vec operator-(const vec &a,const vec &b){return {a.x-b.x,a.y-b.y};}
	friend bool operator<(const vec &a,const vec &b){return a.y!=b.y?a.y<b.y:a.x<b.x;}
};
ll cross(const vec &a,const vec &b)
{
	return (ll)a.x*b.y-(ll)a.y*b.x;
}
void hull(vector<vec> &a)
{
	for(vec &i:a)if(i<a.front())swap(i,a.front());
	vec p=a.front();
	for(vec &i:a)i=i-p;
	sort(a.begin()+1,a.end(),[](const vec &u,const vec &v)
	{
		ll cr=cross(u,v);
		return cr?cr>0:u.norm2()>v.norm2();
	});
	int t=1;
	a[0]={0,0};
	F(i,1,(int)a.size())
	{
		if(t>1&&!cross(a[t-1],a[i]))continue;
		while(t>1&&cross(a[t-1]-a[t-2],a[i]-a[t-1])<0)--t;
		a[t++]=a[i];
	}
	a.resize(t);
	for(vec &i:a)i=i+p;
}
vector<vec> diff(const vector<vec> &a,const vector<vec> &b)
{
	static vector<vec> q[4];
	F(i,0,4)q[i].clear();
	auto add=[](const vec &u){q[u.quadrant()].emplace_back(u);};
	F(i,1,(int)a.size())add(a[i]-a[i-1]);
	if(a.size()>1)add(a[0]-a.back());
	int mid[4];
	F(i,0,4)mid[i]=(int)q[i].size();
	F(i,1,(int)b.size())add(b[i-1]-b[i]);
	if(b.size()>1)add(b.back()-b[0]);
	vec mb=b[0];
	F(i,1,(int)b.size())if(mb<b[i])mb=b[i];
	vec p=a[0]-mb;
	vector<vec> c;
	c.reserve(a.size()+b.size());
	F(i,0,4)
	{
		inplace_merge(q[i].begin(),q[i].begin()+mid[i],q[i].end(),[](const vec &u,const vec &v){return cross(u,v)>0;});
		for(const vec &j:q[i])c.emplace_back(p),p=p+j;
	}
	if(c.empty())c.emplace_back(p);
	return c;
}
ll cross(const vector<vec> &a,const vector<vec> &b)
{
	int p=0,sgn=1,m=(int)b.size();
	ll r,ans=0;
	auto pre=[&](int x){return x?x-1:m-1;};
	auto nex=[&](int x){return x!=m-1?x+1:0;};
	auto adjust=[&](const vec &ai)
	{
		ll q=0;
		if((q=sgn*cross(ai,b[pre(p)]))>r)do r=q,p=pre(p);while((q=sgn*cross(ai,b[pre(p)]))>r);
		else while((q=sgn*cross(ai,b[nex(p)]))>r)r=q,p=nex(p);
	};
	F(i,0,(int)a.size())
	{
		r=sgn*cross(a[i],b[p]);
		adjust(a[i]);
		ans=max(ans,r);
	}
	sgn=-1;
	F(i,0,(int)a.size())
	{
		r=sgn*cross(a[i],b[p]);
		adjust(a[i]);
		ans=max(ans,r);
	}
	return ans;
}
