		for(int j=k;j>=0;j--)
			for(int c=0;c*x<=a[i]&&c<=j;c++)
				f[j]=max(f[j],(int)(f[j-c]+(a[i]-c*x)/y+eps));
	return f[k]>=k;
}
bool check(double S)
{
	int c=0;double x=sqrt(S);
	for(int i=1;i<=n;i++) c+=a[i]/x+eps;
	if(c>=2*k) return 1;
	for(int i=1;i<=n;i++)
		for(int p=0;p<=k;p++)
			for(int q=!p;q<=k;q++)
			{
				if(!p) 
