void calc(){
	for(int i=2,j=0;i<=n1;i++){
		while(j&&a1[j+1]!=a1[i])j=nxt[j];
		if(a1[j+1]==a1[i])nxt[i]=++j;
		else nxt[i]=0;
	}
	int j=0;
	for(int i=1;i<=n2;i++){
		while(j&&a1[j+1]!=a2[i])j=nxt[j];
		if(a1[j+1]==a2[i])j++;
		if(j==n1)break;
	}
	
	for(int i=1;i<=n3+1;i++)cnt2[i]=cnt1[i];
	for(int i=1;i<=n2;i++)if(--cnt2[a2[i]]<0)return;
	int lim=n1;
	while(lim){
		if(--cnt2[a1[lim]]<0)break;
		lim--;
	}
	
	vector<int> v1,v2;
	for(int i=1;i<=n1;i++)v1.push_back(a1[i]);
	for(int i=1;i<=n2;i++)v2.push_back(a2[i]);
	if(lim==0)calc2(v1,v2);
	if(j==n1){
		calc1(v2);
		return;
	}
	while(j&&j>=lim){
		vector<int> v3=v2;
		for(int i=j+1;i<=n1;i++)v3.push_back(a1[i]);
		calc1(v3);
		if(nxt[j]*2<j)j=nxt[j];
		else if(lim<=(j-1)%(j-nxt[j])+1)j=(j-1)%(j-nxt[j])+1;
		else {
			j=nxt[j];
			while(nxt[j]>=lim)j=nxt[j];
		}
	}
}

