    X.resize(N);
    for (INT n = 0; n < N; ++n) X[n] = inInt128();
    
    vector<INT> ns0, ns1;
    vector<RAT> cs0, cs1;
    // lower bound: convex
    ns0.push_back(N - 1);
    for (INT n = N - 1; --n >= 0; ) {
      for (; ; ) {
        const RAT c(X[ns0.back()] - X[n], ns0.back() - n);
        if (!cs0.size() || cs0.back() < c) {
          ns0.push_back(n);
          cs0.push_back(c);
          break;
        }
        ns0.pop_back();
        cs0.pop_back();
      }
    }
    // upper bound: concave
    ns1.push_back(0);
    for (INT n = 1; n < N; ++n) {
      for (; ; ) {
        const RAT c(X[n] - X[ns1.back()], n - ns1.back());
        if (!cs1.size() || cs1.back() < c) {
          ns1.push_back(n);
          cs1.push_back(c);
