		while(m--){
			int x,y;scanf("%d%d",&x,&y);
			if(x>1)jia(a[x-1],a[x],-1);
			if(x<n)jia(a[x],a[x+1],-1);
			if(!(--b[a[x]])){
				if(a[x]>1)gai(a[x]-1);
				if(a[x]<n)gai(a[x]);
			}
			a[x]=y;
			if(!(b[a[x]]++)){
				if(a[x]>1)gai(a[x]-1);
				if(a[x]<n)gai(a[x]);
			}
			if(x>1)jia(a[x-1],a[x],1);
			if(x<n)jia(a[x],a[x+1],1);
			output();
		}
		for(int i=1;i<=n;++i)b[i]=0;
	}
	return 0;
}

