int a[MAXN],b[MAXN];
// 1st, 2nd
int mxb[MAXN<<2],mxx[MAXN<<2];
void psu(int id){
	mxb[id]=max(mxb[id<<1],mxb[id<<1|1]);
	mxx[id]=mxb[id<<1]<mxx[id<<1|1]?mxx[id<<1|1]:mxx[id<<1];
}
void build(int id=1,int l=0,int r=n+1){
	if(l==r){
		a[l]=b[l]=n+1;mxb[id]=n+1;mxx[id]=0;
		return;
	}
	int mid=(l+r)>>1;
	build(id<<1,l,mid);build(id<<1|1,mid+1,r);
	psu(id);
}
void apply(int x,int t,int id=1,int l=0,int r=n+1){
	if(l==r){
		b[l]=a[l];a[l]=t;
		mxb[id]=b[l];mxx[id]=(a[l]==b[l]?0:b[l]);
		return;
	}
	int mid=(l+r)>>1;
	if(x<=mid) apply(x,t,id<<1,l,mid);
	else apply(x,t,id<<1|1,mid+1,r);
	psu(id);
}
int query(int x=0,int id=1,int l=0,int r=n+1){
	if(x>=mxx[id]) return n+1;
	if(l==r) return max(x,a[l]);
	int mid=(l+r)>>1;
	if(x<mxx[id<<1]) return query(x,id<<1,l,mid);
	return query(max(x,mxb[id<<1]),id<<1|1,mid+1,r);
}
