namespace Main
{
    const int mod = 998244353;
    struct mdint
    {
        int value;
        mdint() : value(0) {}
        mdint(int x) : value((x % mod + mod) % mod) {}
        mdint& operator+=(const mdint& b) { value = value + b.value; value >= mod ? value -= mod : 0; return *this; }
        mdint& operator-=(const mdint& b) { value = value - b.value; value < 0 ? value += mod : 0; return *this; }
        mdint& operator*=(const mdint& b) { value = 1ll * value * b.value % mod; return *this; }
        friend mdint operator+(mdint a, const mdint& b) { a += b; return a;}
        friend mdint operator-(mdint a, const mdint& b) { a -= b; return a;}
        friend mdint operator*(mdint a, const mdint& b) { a *= b; return a;}
        friend ostream& operator<<(ostream& os, const mdint& x) {return os << x.value; }
        friend istream& operator>>(istream& is, mdint& x) { int v; is >> v; x.value = (v % mod + mod) % mod; return is; }
    };
    mdint qpow(mdint a, int k)
    {
        mdint res = 1;
        while(k)
        {
            if(k & 1) res *= a;
            k >>= 1;
            a *= a;
        }
        return res;
    }
    mdint C(int n, int m)
    {
        if(m < 0 || m > n) return 0;
        m = min(m, n - m);
        mdint res = 1;
        up(n - m + 1, n, i) res *= i;
        up(1, m, i) res *= qpow(i, mod - 2);
        return res;
    }

    mdint ask0(int s)
    {
        if(s < 0) return 0;
        mdint c3 = C(s + 3 - 1, 2), c2 = s / 2 + 1, c1 = s % 3 == 0;
        mdint res = c3 + 3 * c2 + 2 * c1;
        return res * qpow(6, mod - 2);
    }

    mdint ask1(int cnt, int sum)
    {
        if(cnt < 0 || cnt > sum) return 0;
        int s = sum - cnt;
        mdint c3 = 0;
        up(0, 3, i)
        {
            int S = s - i * (cnt + 1);
            if(S < 0) continue;
            mdint x = C(S + 3 - 1, 2) * C(3, i);
            if(i % 2 == 0) c3 += x;
            else c3 -= x;
        }
        mdint c2 = 0;
        int L = max(s - cnt, 0), R = min(s, cnt * 2);
        if(L <= R) 
        {
            c2 = R / 2 + 1;
            if(L) c2 -= (L - 1) / 2 + 1;
        }
        mdint c1 = (s % 3 == 0 && s / 3 <= cnt);
        mdint res = c3 + 3 * c2 + 2 * c1;
        return res * qpow(6, mod - 2);
    }

    mdint ask(int t1, int t2, int t3, int t4, int cnt, int sum)
    {
        if(cnt < 0 || cnt > sum) return 0;
        mdint res = 0;
        up(0, (1 << 4) - 1, S)
        {
            int c = cnt, s = sum;
            if(S & 1) c -= (t1 + 1), s -= 1 * (t1 + 1);
            if(S & 2) c -= (t2 + 1), s -= 2 * (t2 + 1);
            if(S & 4) c -= (t3 + 1), s -= 3 * (t3 + 1);
            if(S & 8) c -= (t4 + 1), s -= 4 * (t4 + 1);
            if(c >= 0 && s >= 0) 
            {
                if(__builtin_popcount(S) % 2 == 0) res += ask1(c, s);
                else res -= ask1(c, s);
            }
        }
        return res;
    }

    void solve()
    {
        int n, k, x, t1, t2, t3, t4;
        cin >> n >> k >> x >> t1 >> t2 >> t3 >> t4;
        if(n == k) return cout << (t1 * 1 + t2 * 2 + t3 * 3 + t4 * 4 <= x) << endl, void();
        mdint ans = 0;
        ans += ask(t1, t2, t3, t4, k, x);
        k -= t1, x -= t1 * 1;
        ans += ask(0, t2, t3, t4, k, x - 1);
        k -= t2, x -= t2 * 2;
        ans += ask(0, 0, t3, t4, k, x - 2);
        k -= t3, x -= t3 * 3;
        ans += ask(0, 0, 0, t4, k, x - 3);

        cout << ans << endl;
    }
    void main()
    {
        ios::sync_with_stdio(0);
        cin.tie(0);cout.tie(0);
        int _;cin>>_;while(_--)solve();
    }
};

