void cdq(int l,int r) {
	if(l==r) return ;
	int mid=(l+r)>>1;
	cdq(l,mid);
	for(int i=l;i<=mid;++i) a[i-l]=1ll*(MOD-f[i])*ifac[i-1]%MOD;
	for(int i=0;i<=r-l;++i) b[i]=1ll*g[i]*ifac[i]%MOD;
	poly_mul(a,b,c,mid-l+1,r-l+1);
	for(int i=mid+1;i<=r;++i) f[i]=(f[i]+1ll*c[i-l]*fac[i-1])%MOD;
	cdq(mid+1,r);
