	top=0;
	for(int i=1;i<=r-mid;i++){
		while(top&&cmp(st[top]-st[top-1],sum[mid+st[top]]-sum[mid+st[top-1]],i-st[top],sum[mid+i]-sum[mid+st[top]])) top--;
