		for(int i=1;i<8;i+=2){
			if(!f[i].fi)continue;
			else D.merge(i-1,i),D.merge(i,(i+1)&7);
		}
		for(int i=0;i<8&&(!b[x][y]);i++){
			if(!f[i].fi)continue;
			for(int j=i+1;j<8;j++){
				if(f[i]==f[j]&&D.find(i)!=D.find(j))b[x][y]=1;
			}
		}
	}
	ans+=b[x][y];
}
