void merge(int x1,int y1,int x2,int y2){
	tie(x1,y1)=find(x1,y1);tie(x2,y2)=find(x2,y2);
	if(sz[x1][y1]<sz[x2][y2])swap(x1,x2),swap(y1,y2);
	if(x1!=x2||y1!=y2){
		fa[x2][y2]=mp(x1,y1);sz[x1][y1]+=sz[x2][y2];
		for(auto [x,y]:g[x2][y2])check(x,y),g[x1][y1].pb(mp(x,y));
	}
}
