int n,m,t,a[300005],wz[300005],q[300005];
void exgcd(int a,int b,int& x,int& y){
	if(!b){
		x=1,y=0;return;
	}
	exgcd(b,a%b,x,y);
	int z=x;x=y,y=z-a/b*y;
}
int niyuan(int a,int b){
	int x=0,y=0;
	exgcd(a,b,x,y);
	return (x%b+b)%b;
}
int jie(int a,int b,int c,int d){
	int ga=__gcd(a,m),gc=__gcd(c,m);
	if(b%ga||d%gc)return -1;
	a/=ga,b/=ga,c/=gc,d/=gc;
	int ma=m/ga,mc=m/gc;
	int xa=1ll*niyuan(a,ma)*b%ma;
	int xc=1ll*niyuan(c,mc)*d%mc;
	int g=__gcd(ma,mc);
	if(xa%g!=xc%g)return -1;
	ma/=g,mc/=g;
	int r=xa%g;xa/=g,xc/=g;
	//r+g*min
	int s=(1ll*(xc-xa)*niyuan(ma,mc)%mc+mc)%mc;
	return r+g*(xa+s*ma);
}
