constexpr int M = 2000005, mod = 1000333;
constexpr int inv(int x, int k = mod - 2) {
	int r = 1;
	for (; k; k >>= 1, x = x * (LL)x % mod) if (k & 1) r = x * (LL)r % mod;
	return r;
}

int p[M], n, m;
bool xr[M];

int fd(int x) {
	if (x == p[x]) return x;
	int r = fd(p[x]);
	xr[x] ^= xr[p[x]];
	return p[x] = r;
}
void mg(int x, int y, bool op) {
	int fx = fd(x), fy = fd(y);
	if (fx != fy) {
		p[fx] = fy, xr[fx] = xr[x] ^ xr[y] ^ op;
	} else {
		assert((xr[x] ^ xr[y]) == op);
	}
}

int rId(int i, int j) { return 1 + i * (m - 1) + j; }
int cId(int i, int j) { return 1 + n * (m - 1) + i * m + j; }
int $(int i, int j, int d) {
	if (d == 0) return i ? cId(i - 1, j) : 0;
	if (d == 1) return j + 1 < m ? rId(i, j) : 0;
	if (d == 2) return i + 1 < n ? cId(i, j) : 0;
	return j ? rId(i, j - 1) : 0;
}

