void l(int u,int v) {
	to[++k]=v;nxt[k]=hd[u];hd[u]=k;
}
void dfs(int n,int f) {
	dep[n]=dep[f]+1;
	for(int i=hd[n];i;i=nxt[i]) {
		if(to[i]==f) continue;
		dfs(to[i],n);
	}
}
void qv(int n,int f) {
	int ss=0;
	for(int i=hd[n];i;i=nxt[i]) {
		if(to[i]==f) continue;
		qv(to[i],n);
		ss+=dp[to[i]];
	}	
	su[n]=dp[n]=ss;
	for(int i=0;i<t2[n].size();i++) {
		int p=t2[n][i],as=1;
		for(int j=1;j<t[p].size();j++) as-=dp[t[p][j]];
		for(int j=0;j<t[p].size();j++) as+=su[t[p][j]];
		dp[n]=std::max(dp[n],as);
		va[p]=as;
	}
}
void dt(int n,int f) {
	ok[n]+=la[f];
	if(ok[n]) {
		if(dp[n]==su[n]) {
			for(int i=hd[n];i;i=nxt[i]) {
				if(to[i]==f) continue;
				ok[to[i]]++;
			}
		}
		for(int i=0;i<t2[n].size();i++) {
			int p=t2[n][i];
			if(dp[n]==va[p]) {
				for(int j=1;j<t[p].size();j++) ok[t[p][j]]--;
				for(int j=0;j<t[p].size();j++) la[t[p][j]]++;
			}
		}
	}
	for(int i=hd[n];i;i=nxt[i]) {
		if(to[i]==f) continue;
		dt(to[i],n);
	}
}
