#define Me(x,y) memset(x,y,sizeof x)
const int N=1e6+5; const ll INF=1e18+7;
int n,m,q;ll A[N],C[N];
struct edge{
    int x,y; ll w;
}e[N];
int fa[N];
int GF(int x){return fa[x]^x?fa[x]=GF(fa[x]):x;}
vector<int> S[N]; ll w[N];

int bg[N],en[N],bh;
ll sum[N],mi[N];
void dfs(int x,int La){
    bg[x]=++bh;
    if(x<=n){
        sum[x]=A[x];
        mi[x]=C[x];
    }else{
        sum[x]=0;
        mi[x]=INF;
    }
    for(int u:S[x]) if(u^La){
        dfs(u,x);
        sum[x]+=sum[u];
        mi[x]=min(mi[x],mi[u]);
    } 
    en[x]=bh;
}
int to[N];
bool chkin(int x,int y){
    return bg[x]<=bg[y]&&bg[y]<=en[x];
}
int jp1[N][21]; ll val1[N][21];
int jump1(int x,ll w){
    for(int i=20;~i;i--) if(jp1[x][i]&&val1[x][i]<=w) x=jp1[x][i];
    return x;
}
int jp2[N][21]; 
ll val2[N];
void dfs2(int x,int La){
    Me(jp1[x],0);
    jp1[x][0]=to[x]; val1[x][0]=w[to[x]]-sum[x];
    for(int i=1;jp1[x][i-1];i++){
        jp1[x][i]=jp1[jp1[x][i-1]][i-1];
        val1[x][i]=max(val1[x][i-1],val1[jp1[x][i-1]][i-1]);
    }
    Me(jp2[x],0);
    int y=jp2[x][0]=jump1(to[x],w[to[x]]-sum[x]);
    val2[x]=(w[to[y]]-(w[to[x]]-sum[x]+sum[y]))*mi[y]+val2[y];
    for(int i=1;jp2[x][i-1];i++){
        jp2[x][i]=jp2[jp2[x][i-1]][i-1];
    }
    for(int i:S[x]) if(i^La) dfs2(i,x);
}
void Solve(){
    scanf("%d%d%d",&n,&m,&q);
    fill(w+1,w+n+1,0); fill(to+1,to+2*n+1,0);
    for(int i=1;i<=2*n;i++) S[i].clear();
    for(int i=1;i<=n;i++) scanf("%lld",&A[i]);
    for(int i=1;i<=n;i++) scanf("%lld",&C[i]);
    for(int i=1;i<=m;i++) scanf("%d%d%lld",&e[i].x,&e[i].y,&e[i].w);
    sort(e+1,e+m+1,[](edge x,edge y){return x.w<y.w;});
    iota(fa+1,fa+2*n+1,1);
    int cnt=n;
    for(int i=1;i<=m;i++){
        int x=GF(e[i].x),y=GF(e[i].y);
        if(x^y){
            w[++cnt]=e[i].w;
            to[x]=to[y]=cnt;
            fa[x]=fa[y]=cnt;
            S[cnt].push_back(x); S[cnt].push_back(y);
        }
    }
    bh=0; for(int i=1;i<2*n;i++) if(fa[i]==i) dfs(i,0);
    for(int i=1;i<2*n;i++) if(fa[i]==i) dfs2(i,0);
    while(q--){
        int x,y;ll z;
        scanf("%d%d%lld",&x,&y,&z);
        if(GF(x)^GF(y)){
            puts("-1");
            continue;
        }
        x=jump1(x,z);
        if(chkin(x,y)){
            puts("0");
            continue;
        }
        ll ans=(w[to[x]]-(z+sum[x]))*mi[x];
        for(int i=20;~i;i--) if(jp2[x][i]&&!chkin(jp2[x][i],y)){
            ans+=val2[x]-val2[jp2[x][i]];
            x=jp2[x][i];
        }
        // while(!chkin(x,y)){
        //     ans+=(w[to[x]]-z-sum[x])*mi[x];
        //     z+=(w[to[x]]-z-sum[x]);
        //     x=to[x];
        //     x=jump1(x,z);
        // }
        printf("%lld\n",ans);
    }
}
int main(){
	int t=1;
	scanf("%d",&t);
	while(t--) Solve();
}

#include<bits/stdc++.h>
#define N 100009
#define pii pair<int,int>
#define fi first
#define se second
#define mp make_pair
using namespace std;
int L[N],R[N],a[N],f[N],g[N],n,q;
int lsf[N],lsg[N];
int pre[N][20],nxt[N][20];
struct DSU{
	int fa[N],cnt;
	pii sta[N];int top;
	void init(int n){
		top=0;cnt=n;
		memset(fa,-1,sizeof(int)*(n+5));
	}
	int find(int x){
		if(fa[x]<0)return x;
		return find(fa[x]);
	}
	void merge(int x,int y){
		x=find(x),y=find(y);
		if(fa[x]>fa[y])swap(x,y);
		if(x^y){
			--cnt;
			sta[++top]=mp(y,fa[y]);
			fa[x]+=fa[y];fa[y]=x;
		}
	}
	void undo(int lim){
		while(top>lim){
			int y=sta[top].fi,z=sta[top].se;
			int x=fa[y];
			fa[y]=z;fa[x]-=fa[y];
			--top;++cnt;
		}
	}
} D;
int ans[N];
struct SGT{
	#define ls (rt<<1)
	#define rs (rt<<1|1)
	basic_string<pii> tr[N<<2];
	void upd(int rt,int l,int r,int ul,int ur,pii v){
//		if(ul<=ur)cout<<v.fi<<" "<<v.se<<"\n";
		if(ul>r||ur<l)return;
		else if(ul<=l&&ur>=r)tr[rt]+=v;
		else{
			int mid=l+r>>1;
			upd(ls,l,mid,ul,ur,v);
			upd(rs,mid+1,r,ul,ur,v);
		}
	}
	void solve(int rt,int l,int r){
		int tmp=D.top;
		for(pii t:tr[rt])D.merge(t.fi,t.se);
		tr[rt].clear();
		if(l==r)ans[l]=D.cnt;
		else{
			int mid=l+r>>1;
			solve(ls,l,mid);
			solve(rs,mid+1,r);
		}
		D.undo(tmp);
	}
	#undef ls
	#undef rs
} T;
set<int> st[20];
string tmp;
int now;
void updf(int x){
	if(x<0||x>n)return;
	int tmp=f[x];f[x]=0;
	for(int i=0;i<20;i++){
		if(a[x]>>i&1)f[x]=max(f[x],pre[x][i]);
	}
	if(tmp==f[x])return;
	if(tmp&&L[x])T.upd(1,0,q,lsf[x],now-1,mp(tmp,x));
	lsf[x]=now;
}
void updg(int x){
	if(x<0||x>n)return;
	int tmp=g[x];g[x]=n+1;
	for(int i=0;i<20;i++){
		if(a[x]>>i&1)g[x]=min(g[x],nxt[x][i]);
	}
	if(tmp==g[x])return;
	if(tmp<=n&&R[x])T.upd(1,0,q,lsg[x],now-1,mp(tmp,x));
	lsg[x]=now;
}
void upda(int x,int y){
	basic_string<int> todo;
	for(int i=0;i<20;i++){
		if(!((a[x]^y)>>i&1))continue;
		if(a[x]>>i&1){
			st[i].erase(x);
			int u=pre[x][i],v=nxt[x][i];
			pre[x][i]=nxt[x][i]=0;
			nxt[u][i]=v;pre[v][i]=u;
			todo+=u;todo+=v;
		}
		else{
			auto it=st[i].insert(x).fi;
			--it;int u=*it;
			++it;++it;int v=*it;
			nxt[u][i]=x;pre[v][i]=x;
			pre[x][i]=u;nxt[x][i]=v;
			todo+=u;todo+=v;
		}
	}
	todo+=x;a[x]=y;
	for(int t:todo){
		updf(t);updg(t);
	}
}
void updl(int x,int y){
	if(L[x]==y)return;
	if(f[x]>=1&&L[x]){
		T.upd(1,0,q,lsf[x],now-1,mp(f[x],x));
	}
	L[x]=y;lsf[x]=now;
}
void updr(int x,int y){
	if(R[x]==y)return;
	if(g[x]<=n&&R[x]){
		T.upd(1,0,q,lsg[x],now-1,mp(x,g[x]));
	}
	R[x]=y;lsg[x]=now;
}
void solve(){
	cin>>n>>q;D.init(n);now=0;
	for(int i=1;i<=n;i++){
		a[i]=L[i]=R[i]=0,f[i]=0,g[i]=n+1,lsf[i]=lsg[i]=0;
		for(int j=0;j<20;j++){
			pre[i][j]=0;nxt[i][j]=n+1;
		}
	}
	for(int i=0;i<20;i++)st[i].clear(),st[i].insert(0),st[i].insert(n+1);
	for(int i=1,x;i<=n;i++){cin>>x;upda(i,x);}
	cin>>tmp;for(int i=1;i<=n;i++)updl(i,tmp[i-1]-'0');
	cin>>tmp;for(int i=1;i<=n;i++)updr(i,tmp[i-1]-'0');
	for(int i=1;i<=q;i++){
		char c;int x,y;
		cin>>c>>x>>y;now=i;
		if(c=='A')upda(x,y);
		else if(c=='L')updl(x,y);
		else updr(x,y);
	}
	for(int i=1;i<=n;i++){
		if(f[i]>=1&&L[i])T.upd(1,0,q,lsf[i],q,mp(f[i],i));
		if(g[i]<=n&&R[i])T.upd(1,0,q,lsg[i],q,mp(i,g[i]));
	}
	T.solve(1,0,q);
	for(int i=0;i<=q;i++)cout<<ans[i]<<"\n";
}
int main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int T;cin>>T;while(T--)solve();return 0;
}

