using namespace std;
using db = double;
const db inf = 1e18;
struct Line {
	mutable db k, m, p;
	bool operator<(const Line& o) const { return k < o.k; }
	bool operator<(db x) const { return p < x; }
};
struct LineContainer : multiset<Line, less<>> {
	// (for doubles, use inf = 1/.0, div(a,b) = a/b)
	db div(db a, db b) { // floored division
		return a / b; }
	bool isect(iterator x, iterator y) {
		if (y == end()) return x->p = inf, 0;
		if (x->k == y->k) x->p = x->m > y->m ? inf : -inf;
		else x->p = div(y->m - x->m, x->k - y->k);
		return x->p >= y->p;
	}
	void add(db k, db m) {
		auto z = insert({k, m, 0}), y = z++, x = y;
		while (isect(y, z)) z = erase(z);
		if (x != begin() && isect(--x, y)) isect(x, y = erase(y));
		while ((y = x) != begin() && (--x)->p >= y->p)
			isect(x, erase(y));
	}
	db query(db x) {
		assert(!empty());
		auto l = *lower_bound(x);
		return l.k * x + l.m;
	}
} f[10];
int N, M;
void solve() {
	cin >> N >> M;
	for (int i = 1; i <= M; i++) {
		f[i].clear();
	};
	db A = 0, B = 0;
	for (int z = 1; z <= N; z++) {
		int s, g, t; cin >> s >> g >> t;
		f[t].add(s, -1LL * s * g);
		A += 1LL * s * g, B += s;
		if (z < 2 * M) {
			continue;
		}
		db lo = 0, hi = 1e10;
		while ((hi - lo) / hi > 1e-6) {
			db mid = (lo + hi) / 2, sum = A - B * mid;
			for (int i = 1; i <= M; i++) {
				db v = f[i].query(mid);
				sum += max(0., v);
			}
			if (sum >= 0) lo = mid;
			else hi = mid;
		}
		cout << lo << '\n';
	}
}
int main() {
	ios::sync_with_stdio(false), cin.tie(nullptr);
	cout.precision(10), cout << fixed;
	int T; cin >> T;
	while (T--) solve();
	return 0;
}

