i64 calc(i64 l, i64 r) {
	// xor [l, r)
	auto pre = [&](i64 n) {
		i64 ans = 0;
		while (n%4 != 0) ans ^= --n;
		return ans;
	};
	return pre(r) ^ pre(l);
}
