	int cv[1<<24], ch[1<<24][2], cnt = 0; pair<i64,i64> f[1<<24];
	pair<i64,i64> get(int x, i64 l, i64 r) { return x ? f[x] : pair{i64(r-l), calc(l,r)}; }
	void pull(int x, i64 l, i64 r) {
		if (cv[x]) f[x] = {0, 0};
		else {
			i64 m = (l + r) / 2; int a = ch[x][0], b = ch[x][1];
			f[x] = get(a,l,m) + get(b,m,r);
		}
	}
	void app(int x, i64 l, i64 r, int v) { cv[x] += v, pull(x, l, r); }
	void upd(int& x, i64 l, i64 r, i64 ql, i64 qr, int v) {
		if (qr <= l || r <= ql || ql >= qr) return;
		if (!x) x = ++cnt;
		// cerr << "upd " << x << ' ' << l << ' ' << r << ' ' << ql << ' ' << qr << ' ' << v << '\n';
		if (ql <= l && r <= qr) return app(x, l, r, v);
		i64 m = (l + r) / 2;
		upd(ch[x][0], l, m, ql, qr, v), upd(ch[x][1], m, r, ql, qr, v), pull(x, l, r);
	}
