	if (j-i >= N) return;
	i64 l = (N-i%N)%N, r = l + (N-(j-i)%N)%N;
	T.upd(rt, 0, N, l, min(r,N), v);
	if (r > N) T.upd(rt, 0, N, 0, r-N, v);
}
void del(int i) {
	auto& pos = mp[A[i]];
	auto it = pos.find(i);
	assert(it != pos.end());
	if (it != pos.begin()) {
		auto j = *prev(it);
		ins(j, i, -1);
	}
	if (next(it) != pos.end()) {
		auto j = *next(it);
		ins(i, j, -1);
	}
	if (it != pos.begin() && next(it) != pos.end()) {
		ins(*prev(it), *next(it), 1);
	}
	pos.erase(it);
}
void ins(int i) {
	auto& pos = mp[A[i]];
	auto [it, _] = pos.insert(i);
	assert(_);
	if (it != pos.begin()) {
		auto j = *prev(it);
		ins(j, i, 1);
	}
	if (next(it) != pos.end()) {
		auto j = *next(it);
		ins(i, j, 1);
	}
	if (it != pos.begin() && next(it) != pos.end()) {
		ins(*prev(it), *next(it), -1);
	}
}
