poly up(int n){
	if(n==0)return {1};
	if(n&1)return multi({up(n-1),{n-1,1}});
	int nn=n/2;
	poly a=up(nn);
	poly a1,a2;
	for(int i=0;i<=nn;++i)
		a1.emplace_back(1ll*di[i]*a[i]%mod);
	int cj=powdv(nn,nn),cc=powdv(nn);
	for(int i=0;i<=nn;++i)
		a2.emplace_back(1ll*cj*id[nn-i]%mod),cj=1ll*cj*cc%mod;
	poly c=multi({a1,a2}),cp;
	for(int i=nn;i<=nn+nn;++i)cp.emplace_back(1ll*c[i]*id[i-nn]%mod);
	return multi({a,cp});
}
poly dn(int n){
	poly pp=up(n);
	for(int i=0;i<=n;++i)if((n-i)%2)pp[i]=(mod-pp[i])%mod;
	return pp;
}
int C(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*di[n]*id[m]%mod*id[n-m]%mod;
}
