using namespace std;
struct apple{
	int N;set<int>se;
	multiset<int>ms;
	int ans;
	void init(int n){
		N=n;se.emplace(0);se.emplace(N);
		ms.emplace(N);ans=N;
	}
	void cut(int x){
		auto it=se.emplace(x).first;
		int L=*(--it);++it;
		int R=*(++it);--it;
		ms.erase(ms.find(R-L));
		ms.emplace(x-L);ms.emplace(R-x);
		ans=*(ms.rbegin());
	}
}a,b;
int main(){
	int n,m,q;scanf("%d%d%d",&n,&m,&q);
	a.init(n);b.init(m);
	while(q--){
		int op,x;scanf("%d%d",&op,&x);
		if(op==1)a.cut(x);
		else b.cut(x);
		printf("%lld\n",1ll*a.ans*b.ans);
	}
	return 0;
}

