    pre[i][0] = suf[i][0] = 0;
    ull pw = 1;
    for (int j = 1; j <= len[i]; j++) {
      pre[i][j] = (pre[i][j - 1] + (u128)pw * s[i][j]) % mod;
      suf[i][j] = (s[i][len[i] + 1 - j] + (u128)P * suf[i][j - 1]) % mod;
      pw = (u128)pw * P % mod;
    }
    for (int j = 1; j <= len[i]; j++)
      ans += mp1[suf[i][j]];
    for (int j = 1; j <= len[i]; j++)
