#include <bits/stdc++.h>
int N,dp[1000009],a[1000009],iv[500009],p[500009],ll[500009],rr[500009],sg[500009];
#define lb(x) ((x)&(-(x)))
void up(int n,int v) {
    while(n<=N) {
        sg[n]=std::max(sg[n],v);
        n+=lb(n);
    }
}
int qr(int n) {
    int as=0;
    while(n) {
        as=std::max(as,sg[n]);
        n-=lb(n);
    }
    return as;
}
bool cmp(int x,int y) {
    if(ll[x]/10000==ll[y]/10000) return rr[x]<rr[y];
    return ll[x]<ll[y];
}
signed main(void) {
    scanf("%d",&N);
    for(int i=1;i<=2*N;i++) {
        scanf("%d",&a[i]);
        if(ll[a[i]]==0) ll[a[i]]=i;
        else rr[a[i]]=i;
    }
    for(int i=1;i<=N;i++) {
        p[i]=i;
    }
    std::sort(p+1,p+N+1,cmp);
    for(int i=1;i<=N;i++) {
       // iv[i]=p[i];
         iv[p[i]]=i;
    }
    for(int i=1;i<=2*N;i++) {
        dp[i]=qr(N-iv[a[i]]+1)+1;
        up(N-iv[a[i]]+1,dp[i]);
        printf("%d ",dp[i]);
    }
}
